const n=[{id:"mlg_museo_picasso",categoryId:"cultura",city:"malaga",name:"Museo Picasso Málaga",tagline:"O Picasso essencial no palácio renascentista",description:"A coleção permanente reúne mais de 200 obras doadas pela família do artista, cobrindo oito décadas de criação. Ocupa o Palacio de Buenavista, joia do século XVI com pátio andaluz e vestígios fenícios no subsolo. É o museu-âncora da cidade que Picasso viu nascer.",whatToDo:["Percorra a coleção em ordem cronológica, do cubismo às cerâmicas finais","Desça à cripta arqueológica com restos fenícios e romanos","Reserve tempo para a exposição temporária e a loja"],kingTip:"Compre ingresso online com hora marcada; entrada gratuita nas últimas duas horas de domingo.",priceLevel:"~€13 (est.)",lat:36.72135,lng:-4.41895,durationLabel:"1h30–2h",fit:"INDOOR",hours:{openHour:10,closeHour:19,note:"Aberto todos os dias; verifique horário estendido no verão."},mapQuery:"Museo Picasso Málaga, Calle San Agustín 8, Málaga",history:"A doação de Christine e Bernard Ruiz-Picasso tornou realidade um desejo antigo do próprio artista: ter um museu na sua cidade natal. Inaugurado em 2003, ocupa um palácio que já foi residência dos condes de Buenavista.",links:[{label:"Site oficial",url:"https://www.museopicassomalaga.org/"},{label:"Ingressos",url:"https://www.museopicassomalaga.org/en/plan-your-visit/tickets"}],image:"mlg_museo_picasso.jpg"},{id:"mlg_casa_natal_picasso",categoryId:"cultura",city:"malaga",name:"Casa Natal de Picasso",tagline:"Onde o gênio nasceu, na Plaza de la Merced",description:"A casa onde Pablo Picasso nasceu em 1881 hoje é museu e fundação, com objetos da família, cadernos e obras gráficas do artista. O prédio recria o ambiente doméstico do fim do século XIX. Pequeno e íntimo, complementa a visita ao Museo Picasso.",whatToDo:["Veja objetos pessoais da família Ruiz-Picasso","Aprecie a coleção de gravuras e cerâmicas","Descanse na arborizada Plaza de la Merced ao sair"],kingTip:"Combine com o Museo Picasso no mesmo dia; ficam a cinco minutos a pé.",priceLevel:"~€4 (est.)",lat:36.72555,lng:-4.41787,durationLabel:"45min–1h",fit:"INDOOR",hours:{openHour:9,closeHour:20,note:"Aberto todos os dias; consulte fechamento em feriados."},mapQuery:"Casa Natal de Picasso, Plaza de la Merced 15, Málaga",links:[{label:"Site oficial",url:"https://fundacionpicasso.malaga.eu/"}],image:"mlg_casa_natal_picasso.jpg"},{id:"mlg_carmen_thyssen",categoryId:"cultura",city:"malaga",name:"Museo Carmen Thyssen Málaga",tagline:"A grande pintura andaluza do século XIX",description:"Instalado no palacete renascentista de Villalón, reúne a coleção de Carmen Thyssen dedicada à pintura espanhola, com forte presença do costumbrismo andaluz e do paisagismo. Salas luminosas mostram Zuloaga, Sorolla e os mestres românticos. Um mergulho na Andaluzia idealizada dos pintores.",whatToDo:["Concentre-se nas salas de pintura andaluza e paisagem","Visite o pátio e o palacete restaurado","Confira a mostra temporária, que costuma ser forte"],kingTip:"Domingo à tarde a coleção permanente costuma ter entrada gratuita.",priceLevel:"~€10 (est.)",lat:36.72073,lng:-4.42222,durationLabel:"1h–1h30",fit:"INDOOR",hours:{openDays:[2,3,4,5,6,7],openHour:10,closeHour:20,note:"Fecha às segundas."},mapQuery:"Museo Carmen Thyssen Málaga, Calle Compañía 10, Málaga",links:[{label:"Site oficial",url:"https://www.carmenthyssenmalaga.org/"},{label:"Ingressos",url:"https://www.carmenthyssenmalaga.org/en/visit"}],image:"mlg_carmen_thyssen.jpg"},{id:"mlg_centre_pompidou",categoryId:"cultura",city:"malaga",name:"Centre Pompidou Málaga",tagline:"Arte do século XX sob o cubo colorido",description:"A primeira sede do Pompidou fora da França, num edifício subterrâneo à beira do porto coroado por 'El Cubo', o cubo de vidro multicolor de Daniel Buren. A seleção semipermanente traz Picasso, Frida Kahlo, Bacon e Magritte, entre outros. O acordo com Málaga foi renovado até 2035.",whatToDo:["Percorra a mostra semipermanente de arte moderna e contemporânea","Fotografe 'El Cubo' de fora, no Muelle Uno","Aproveite a passagem à beira-mar antes ou depois"],kingTip:"Fica no Muelle Uno: encaixe a visita entre o porto e La Malagueta.",priceLevel:"~€9 (est.)",lat:36.71558,lng:-4.41548,durationLabel:"1h–1h30",fit:"INDOOR",hours:{openDays:[3,4,5,6,7,1],openHour:9,closeHour:20,note:"Fecha às terças."},mapQuery:"Centre Pompidou Málaga, Pasaje Doctor Carrillo Casaux, Muelle Uno, Málaga",links:[{label:"Site oficial",url:"https://centrepompidou-malaga.eu/"},{label:"Ingressos",url:"https://centrepompidou-malaga.eu/entradas/"}],image:"mlg_centre_pompidou.jpg"},{id:"mlg_coleccion_museo_ruso",categoryId:"cultura",city:"malaga",name:"Colección del Museo Ruso",tagline:"Arte russa na antiga Tabacalera",description:"Sede do Museo Estatal Ruso de São Petersburgo instalada na monumental Tabacalera de Málaga, com ícones, vanguarda e realismo social russos. Ocupa amplas salas do antigo edifício da fábrica de tabaco. Segue aberto em 2026, com programação temporária que se renova.",whatToDo:["Veja a mostra semipermanente de arte russa dos séculos XV ao XX","Explore a arquitetura industrial restaurada da Tabacalera","Combine com o Museo Automovilístico, no mesmo complexo"],kingTip:"Fica a oeste do centro; venha de táxi ou combine com a Tabacalera inteira.",priceLevel:"~€8 (est.)",lat:36.69048,lng:-4.44228,durationLabel:"1h–1h30",fit:"INDOOR",hours:{openDays:[2,3,4,5,6,7],openHour:9,closeHour:20,note:"Ter–Dom 9h30–20h; fecha às segundas."},mapQuery:"Colección del Museo Ruso, Avenida Sor Teresa Prat 15, Tabacalera, Málaga",links:[{label:"Site oficial",url:"https://www.coleccionmuseoruso.es/"}],image:"mlg_coleccion_museo_ruso.jpg"},{id:"mlg_cac_malaga",categoryId:"cultura",city:"malaga",name:"CAC Málaga",tagline:"Arte contemporânea grátis à beira do Guadalmedina",description:"O Centro de Arte Contemporáneo ocupa o antigo mercado de atacado, um marco racionalista dos anos 1930. Exibe arte internacional das últimas décadas e nomes como Louise Bourgeois, Julian Opie e Art&Language. A entrada é gratuita, o que o torna parada certa nas horas de calor.",whatToDo:["Veja a coleção permanente e as mostras temporárias rotativas","Observe o edifício racionalista em forma de estrela","Passe pelo Soho e seus murais ao redor"],kingTip:"Entrada gratuita; ótimo refúgio climatizado no meio da tarde.",priceLevel:"Grátis",lat:36.71258,lng:-4.42663,durationLabel:"1h",fit:"INDOOR",hours:{openDays:[2,3,4,5,6,7],openHour:9,closeHour:20,note:"Fecha às segundas; horário reduzido no verão à tarde."},mapQuery:"CAC Málaga, Calle Alemania, Málaga",links:[{label:"Site oficial",url:"https://cacmalaga.eu/"}],image:"mlg_cac_malaga.jpg"},{id:"mlg_museo_de_malaga",categoryId:"cultura",city:"malaga",name:"Museo de Málaga",tagline:"Belas Artes e Arqueologia no Palacio de la Aduana",description:"O maior museu da Andaluzia reúne mais de 15 mil peças entre belas artes e arqueologia, do mundo fenício e romano à pintura málaga do século XIX. Ocupa o imponente Palacio de la Aduana, aos pés da Alcazaba. As salas são vastas, frescas e pouco lotadas.",whatToDo:["Suba à cobertura para ver a Alcazaba e o porto","Percorra a seção arqueológica e o mosaico romano","Aprecie a pintura málaga do XIX na pinacoteca"],kingTip:"Entrada gratuita para cidadãos da UE; leve passaporte para conferência.",priceLevel:"~€1,50 (est.); grátis p/ UE",lat:36.72033,lng:-4.41596,durationLabel:"1h30–2h",fit:"INDOOR",hours:{openDays:[2,3,4,5,6,7],openHour:9,closeHour:21,note:"Fecha às segundas; horário varia no verão."},mapQuery:"Museo de Málaga, Palacio de la Aduana, Plaza de la Aduana, Málaga",links:[{label:"Site oficial",url:"https://www.museosdeandalucia.es/web/museodemalaga"}],image:"mlg_museo_de_malaga.jpg"},{id:"mlg_museo_automovilistico_moda",categoryId:"cultura",city:"malaga",name:"Museo Automovilístico y de la Moda",tagline:"Carros clássicos e alta-costura lado a lado",description:"Um dos museus mais originais da cidade, cruza cerca de cem automóveis de coleção com peças de alta-costura e obras de arte. Ocupa uma ala restaurada da Tabacalera, com cenografia impecável. Agrada tanto a curiosos de design quanto a apaixonados por carros.",whatToDo:["Veja os automóveis art déco e os motores a energia alternativa","Aprecie os vestidos de grandes casas de moda","Combine com o Museo Ruso, no mesmo edifício"],kingTip:"Fica na Tabacalera, a oeste do centro; reserve táxi para a volta.",priceLevel:"~€10 (est.)",lat:36.69006,lng:-4.44299,durationLabel:"1h–1h30",fit:"INDOOR",hours:{openHour:10,closeHour:19,note:"Aberto todos os dias; confira fechamento sazonal."},mapQuery:"Museo Automovilístico y de la Moda, Avenida Sor Teresa Prat 15, Málaga",links:[{label:"Site oficial",url:"https://www.museoautomovilmalaga.com/"}],image:"mlg_museo_automovilistico_moda.jpg"},{id:"mlg_museo_del_vino",categoryId:"cultura",city:"malaga",name:"Museo del Vino Málaga",tagline:"A história dos vinhos da Denominação Málaga",description:"No palacete de Biedmas, o museu conta a tradição vinícola de Málaga e da Sierras de Málaga por meio de rótulos, cartazes litográficos e utensílios. A visita costuma incluir degustação de dois vinhos da denominação de origem. Cultura e prova numa parada curta e fresca.",whatToDo:["Percorra a coleção de cartazes e rótulos históricos","Faça a degustação de vinhos doces e secos incluída","Compre garrafas da D.O. na loja"],kingTip:"O ingresso já inclui duas taças; ótimo fim de tarde antes das tapas.",priceLevel:"~€6 (est.), com degustação",lat:36.72547,lng:-4.42675,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:[1,2,3,4,5],openHour:10,closeHour:17,note:"Seg–Sex; sábado só manhã; fecha domingos."},mapQuery:"Museo del Vino Málaga, Plaza de los Viñeros 1, Málaga",links:[{label:"Site oficial",url:"https://museovinomalaga.com/"}],image:"mlg_museo_del_vino.jpg"},{id:"rnd_museo_lara",categoryId:"cultura",city:"ronda",name:"Museo Lara",tagline:"O gabinete de curiosidades de Ronda",description:"Coleção reunida por Juan Antonio Lara ao longo da vida, num palacete do bairro histórico. Relógios, armas, instrumentos científicos e objetos do cotidiano andaluz enchem as salas. Inclui seções sobre bruxaria e Inquisição no subsolo, curiosas e temáticas.",whatToDo:["Veja a coleção de relógios e instrumentos antigos","Desça às salas de bruxaria e Inquisição","Aprecie o palacete e o jardim interno"],kingTip:"Fica na Calle Armiñán, a caminho do bairro velho; ótimo escape do sol.",priceLevel:"~€4 (est.)",lat:36.74078,lng:-4.92679,durationLabel:"45min–1h",fit:"INDOOR",hours:{openHour:11,closeHour:19,note:"Aberto todos os dias; horário reduzido no inverno."},mapQuery:"Museo Lara, Calle Armiñán 29, Ronda",links:[{label:"Site oficial",url:"https://www.museolara.org/"}],image:"rnd_museo_lara.jpg"},{id:"rnd_museo_bandolero",categoryId:"cultura",city:"ronda",name:"Museo del Bandolero",tagline:"A lenda dos bandoleiros da serrania",description:"Único museu da Espanha dedicado ao bandoleirismo andaluz, o fenômeno romântico dos foras-da-lei da serrania de Ronda no século XIX. Reúne armas, documentos, trajes e histórias de figuras como El Tempranillo. Pequeno, temático e muito ligado à identidade local.",whatToDo:["Conheça a história dos bandoleiros mais famosos da serra","Veja armas, cartazes de recompensa e trajes de época","Combine com um passeio pelo casco antiguo de Ronda"],kingTip:"A poucos passos do Museo Lara; dá para ver os dois na mesma manhã.",priceLevel:"~€3,75 (est.)",lat:36.73953,lng:-4.92707,durationLabel:"30–45min",fit:"INDOOR",hours:{openHour:10,closeHour:19,note:"Aberto todos os dias; confira horário sazonal."},mapQuery:"Museo del Bandolero, Calle Armiñán 65, Ronda",links:[{label:"Site oficial",url:"https://www.museobandolero.com/"}]},{id:"mlg_mia_coffee",categoryId:"cafe",city:"malaga",name:"Mia Coffee",tagline:"Café de especialidade na fachada amarela",description:"Cafeteria minúscula e cultuada de fachada amarela viva, no centro histórico, tocada por uma família de origem venezuelana. Trabalha com micro-torrefadores espanhóis e domina o espresso, o flat white e os métodos filtrados. Um dos endereços de referência do café de especialidade em Málaga.",lat:36.72223,lng:-4.42274,durationLabel:"20–40 min",fit:"ANY",mapQuery:"Mía Coffee Shop, Plaza de los Mártires, Málaga",whatToDo:"Peça um flat white e um dos bolos caseiros na barra estreita, ou leve o café para caminhar pelo centro.",kingTip:"O espaço é pequeníssimo e enche rápido; vá em horário de baixa ou peça para viagem.",priceLevel:"€€"},{id:"mlg_next_level_coffee",categoryId:"cafe",city:"malaga",name:"Next Level Specialty Coffee",tagline:"Espresso de especialidade na Calle San Juan",description:"Cafeteria de especialidade moderna e luminosa na movimentada Calle San Juan, popular entre nômades digitais e amantes do bom grão. Cartas de espresso e filtrados bem executadas, com brunch leve e opções vegetais. Ambiente descontraído e Wi-Fi para uma pausa produtiva.",lat:36.71965,lng:-4.42336,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Next Level Specialty Coffee, Calle San Juan 27, Málaga",whatToDo:"Prove um filtrado do lote em destaque acompanhado de um pedaço de bolo de cenoura ou torrada de abacate.",kingTip:"Tem mais de um endereço no centro; o da Calle San Juan é o mais central para juntar com o Mercado de Atarazanas.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"08:00",closeHour:"17:00",note:"Fecha no fim da tarde; foco em cafés da manhã e brunch."}},{id:"mlg_el_ultimo_mono",categoryId:"cafe",city:"malaga",name:"El Último Mono Juice & Coffee",tagline:"Sucos naturais e brunch com café de origem",description:"Cafeteria de bairro descolada perto da catedral, especializada em sucos prensados a frio e café de especialidade. Brunch generoso com torradas, ovos e bolos caseiros, muitas opções veganas e vegetarianas. Parada favorita para começar o dia sem pressa no centro histórico.",lat:36.72113,lng:-4.42105,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"El Último Mono Juice & Coffee, Calle Santa María 9, Málaga",whatToDo:"Combine um suco verde prensado na hora com uma torrada de brunch e um cortado de especialidade.",kingTip:"Nos fins de semana o brunch enche; chegue antes das 11h para pegar mesa.",priceLevel:"€€"},{id:"mlg_julia_bakery",categoryId:"cafe",city:"malaga",name:"Julia Bakery",tagline:"Padaria-cafeteria de inspiração anglo-saxã",description:"Padaria, confeitaria e cafeteria na Calle Carretería, especializada em produtos de inspiração britânica e americana. Vitrines com napolitanas de framboesa, mais de dez tipos de cheesecake, cookies e pães de fermentação natural. Doçaria farta e reconfortante para um lanche no centro.",lat:36.72294,lng:-4.42397,durationLabel:"20–40 min",fit:"ANY",mapQuery:"Julia Bakery, Calle Carretería 44, Málaga",whatToDo:"Prove uma fatia de cheesecake e leve um pão de fermentação natural ou uma napolitana quentinha.",kingTip:"A carta de cheesecakes muda; pergunte pelas fatias do dia recém-saídas do forno.",priceLevel:"€€"},{id:"mlg_eccolo_gelato",categoryId:"cafe",city:"malaga",name:"Eccolo Gelato",tagline:"Gelato italiano premiado na Calle San Juan",description:"Gelateria artesanal na Calle San Juan que produz o sorvete diariamente no próprio obrador, com ingredientes frescos e naturais. Seus gelati e sorbetti já foram escolhidos entre os melhores da Itália, com ampla linha sem glúten. Cremosidade de nível italiano no coração de Málaga.",lat:36.71982,lng:-4.42345,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Eccolo Gelato, Calle San Juan 32, Málaga",whatToDo:"Peça uma casquinha com pistache siciliano e um sorbetto de fruta da estação para o calor de julho.",kingTip:"Nos dias mais quentes, o sorbetto de limão ou de morango refresca mais que os cremes.",priceLevel:"€€"},{id:"mlg_levi_angelo_gelato",categoryId:"cafe",city:"malaga",name:"Levi Angelo Gelato",tagline:"Gelato artesanal cremoso no bairro Soho",description:"Gelateria artesanal muito bem avaliada perto do bairro Soho, entre a Alameda e o porto. Sabores clássicos italianos e criações autorais, com textura sedosa feita em pequenas fornadas. Uma das paradas geladas mais elogiadas da cidade para os dias de calor.",lat:36.71651,lng:-4.42312,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Levi Angelo Gelato, Calle Vendeja, Málaga",whatToDo:"Escolha duas bolas contrastantes, um creme e um sorbetto, e coma à sombra a caminho do Muelle Uno.",kingTip:"Fica a poucos passos do porto; ótimo fecho depois de um passeio à beira-mar ao entardecer.",priceLevel:"€€"},{id:"grn_gran_cafe_bib_rambla",categoryId:"cafe",city:"granada",name:"Gran Café Bib-Rambla",tagline:"Churros com chocolate na praça, desde 1907",description:"Café histórico de 1907 na animada Plaza Bib-Rambla, entre a catedral e a Alcaicería. Famoso pelos churros e pelo chocolate espesso servidos nas mesas ao ar livre, além de tapas e doces clássicos. Cenário clássico para o café da manhã granadino ao pé da praça.",lat:37.17477,lng:-3.5999,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Gran Café Bib-Rambla, Plaza Bib-Rambla 3, Granada",whatToDo:"Sente-se na esplanada da praça e peça churros ou porras com uma xícara de chocolate quente para mergulhar.",kingTip:"As mesas da praça são disputadas de manhã; no calor, prefira o café da tarde à sombra dos toldos.",priceLevel:"€€",links:[{label:"Site oficial",url:"https://cafebibrambla.com"}]},{id:"grn_los_italianos",categoryId:"cafe",city:"granada",name:"Heladería Los Italianos",tagline:"Sorvetes e cassata italiana desde 1936",description:"Heladería lendária na Gran Vía de Colón, fundada em 1936 por uma família de imigrantes italianos e frequentada por gerações de granadinos. Famosa pela cassata, pelos tartufos e pelo sorvete cremoso servido no balcão sempre cheio. Instituição da cidade, aberta na temporada de calor.",lat:37.17619,lng:-3.5976,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Heladería Los Italianos, Gran Vía de Colón 4, Granada",whatToDo:"Peça uma fatia de cassata ou um cucurucho de sorvete e coma a caminho da catedral.",kingTip:"Abre de março a outubro; em julho fica lotada à tarde, então vá no fim da manhã.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"01:00",note:"Temporada de março a outubro; horário estendido nas noites de verão."},links:[{label:"Site oficial",url:"https://www.lositalianos.es"}],history:"Fundada em 1936 por uma família de imigrantes italianos, tornou-se uma das heladerías mais queridas de Granada."},{id:"rnd_confiteria_daver",categoryId:"cafe",city:"ronda",name:"Confitería Daver",tagline:"Yemas del Tajo e doçaria típica de Ronda",description:"Confeitaria e pastelaria tradicional de Ronda, referência nas yemas del Tajo, docinhos de gema e açúcar típicos da cidade. Vitrines com doces artesanais, folhados e bolos que atravessaram gerações da serrania. Parada certa para provar e levar a doçaria local.",lat:36.74232,lng:-5.16536,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Confitería Daver, Calle Virgen de los Remedios 6, Ronda",whatToDo:"Prove as yemas del Tajo no balcão e leve uma caixinha como lembrança doce da serrania.",kingTip:"As yemas viajam bem fechadas; peça a embalagem para presente antes de seguir viagem.",priceLevel:"€",links:[{label:"Site oficial",url:"https://confiteriadaver.es"}]},{id:"ant_la_antequerana",categoryId:"cafe",city:"antequera",name:"Cafetería-Obrador La Antequerana",tagline:"Mantecados e bienmesabe no obrador local",description:"Cafeteria e obrador histórico no centro de Antequera, especializado na doçaria artesanal da cidade feita de modo tradicional. Vitrines com mantecados, polvorones e o célebre bienmesabe antequerano, além de café para acompanhar. Parada ideal para provar os doces típicos na origem.",lat:37.021,lng:-4.56156,durationLabel:"20–40 min",fit:"ANY",mapQuery:"La Antequerana, Calle Merecillas 16, Antequera",whatToDo:"Peça um café com uma porção de bienmesabe e leve uma caixa de mantecados artesanais.",kingTip:"O bienmesabe local não é o do sul: aqui é um doce de amêndoa e abóbora; peça para provar antes de comprar.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"08:30",closeHour:"21:00",note:"Fecha à tarde entre turnos nos dias de semana; fins de semana horário contínuo."}},{id:"cor_the_coffee_club",categoryId:"cafe",city:"cordoba",name:"The Coffee Club",tagline:"Café de especialidade no coração da Judería",description:"Pequena cafeteria de especialidade no coração da Judería de Córdoba, a poucos passos da Mesquita-Catedral. Trabalha com café 100% arábica de torra artesanal andaluza, além de matcha, smoothies e bolos caseiros. Espaço enxuto, voltado sobretudo ao café para viagem enquanto se explora o bairro antigo.",lat:37.8806,lng:-4.78032,durationLabel:"15–30 min",fit:"ANY",mapQuery:"The Coffee Club, Calle Céspedes 2, Córdoba",whatToDo:"Peça um flat white de torra andaluza e um brownie morno para levar rumo à Mesquita-Catedral.",kingTip:"Poucos lugares para sentar; pegue o café para viagem e beba passeando pelas ruelas da Judería.",priceLevel:"€€"},{id:"mrb_kafein_coffee",categoryId:"cafe",city:"marbella",name:"Kafein Coffee & Kitchen",tagline:"Café e croissants no casco antiguo",description:"Cafeteria acolhedora nas ruelas do casco antiguo de Marbella, de gestão italiana e muito bem avaliada. Café de qualidade, croissants espetaculares e bolos sempre frescos, com bom brunch de ingredientes selecionados. Refúgio charmoso entre as fachadas caiadas do centro histórico.",lat:36.50981,lng:-4.88613,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Kafein Coffee & Kitchen, Calle Pedraza 3, Marbella",whatToDo:"Peça um cappuccino com um croissant recheado e sente-se na ruela do casco antiguo para ver o vaivém.",kingTip:"É pequena e concorrida; chegue cedo de manhã para garantir uma das poucas mesas na rua.",priceLevel:"€€"},{id:"mlg_mercado_salamanca",categoryId:"compras",city:"malaga",name:"Mercado de Salamanca",tagline:"Mercado neoárabe de 1925 no Molinillo",description:"Segundo mercado mais visitado de Málaga, ergue-se num edifício neoárabe de tijolo declarado Bem de Interesse Cultural, longe do burburinho turístico de Atarazanas. As bancas guardam o ritmo de bairro: peixe da lota, frutas da vega, azeitonas, queijos e especiarias entre vizinhos que fazem a compra do dia. Uma janela autêntica sobre o comércio de mesa malaguenho.",lat:36.7274,lng:-4.4231,durationLabel:"30–45 min",fit:"INDOOR",mapQuery:"Mercado de Salamanca, Calle San Bartolomé, Málaga",whatToDo:"Percorra as bancas de peixe e frutas e prove azeitonas aliñadas e queijos de cabra da serra malaguenha.",kingTip:"Vá pela manhã, entre 9h e 13h; aos domingos fecha e o movimento local é mais genuíno em dias de semana.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"08:00",closeHour:"15:00",note:"Domingos fechado."},links:[{label:"Mercados de Málaga",url:"https://mercados.malagacomercio.es/mercados/mercado-de-salamanca/"}],history:"Projetado pelo arquiteto Daniel Rubio Sánchez e construído entre 1922 e 1925, no bairro do Molinillo."},{id:"mlg_mercado_merced",categoryId:"compras",city:"malaga",name:"Mercado de la Merced",tagline:"Mercado gourmet ao lado da casa de Picasso",description:"A poucos passos da praça onde nasceu Picasso, este mercado foi reconvertido em 2015 num espaço gastronômico coberto com cerca de vinte bancas. Ostras, presunto ibérico, sushi, queijos, doces e vinhos convivem em balcões de degustação onde se compra e se prova no mesmo gesto. Um ponto de encontro descontraído no coração do centro histórico.",lat:36.7245,lng:-4.4178,durationLabel:"45 min–1 h",fit:"INDOOR",mapQuery:"Mercado de la Merced, Calle Merced 1, Málaga",whatToDo:"Monte um percurso de bancas: uma dúzia de ostras num balcão, presunto cortado à faca noutro e uma taça de vinho de Ronda para fechar.",kingTip:"Ao contrário dos mercados tradicionais, funciona até à noite, com ambiente animado a partir do fim da tarde.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"08:00",closeHour:"24:00",note:"Bancas gastronômicas prolongam-se até tarde; domingos com horário reduzido."},links:[{label:"Mercados de Málaga",url:"https://mercados.malagacomercio.es/mercados/mercado-de-la-merced/"}]},{id:"mlg_libreria_luces",categoryId:"compras",city:"malaga",name:"Librería Luces",tagline:"Livraria independente na Alameda Principal",description:"Referência cultural de Málaga desde 2003, ocupa um belo espaço na Alameda Principal com um catálogo vastíssimo e forte presença de literatura, ensaio e edições sobre Andaluzia. É palco frequente de apresentações e sessões de autógrafos, um lugar caro aos leitores da cidade. Ótima parada para um livro sobre o sul da Espanha ou uma edição ilustrada de recordação.",lat:36.7178,lng:-4.4231,durationLabel:"20–40 min",fit:"ANY",mapQuery:"Librería Luces, Alameda Principal 16, Málaga",whatToDo:"Procure a seção de temas andaluzes e guias locais; peça uma recomendação de literatura espanhola contemporânea traduzida.",kingTip:"Fica na Alameda, a caminho do porto e de Soho; combine com um passeio pelos murais do bairro das artes.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"21:00",note:"Domingos fechado."},links:[{label:"Site oficial",url:"https://www.librerialuces.com/"}]},{id:"mlg_la_mallorquina",categoryId:"compras",city:"malaga",name:"La Mallorquina",tagline:"Ultramarinos histórico de frutos secos",description:"Ancorada na Plaza de Félix Sáenz há gerações, é uma das casas de ultramarinos mais queridas de Málaga, com fachada clássica e balcões repletos de frutos secos, especiarias, conservas, doces e vinhos. O aroma de amêndoas torradas e o atendimento à moda antiga fazem parte da experiência. Ideal para levar produtos andaluzes de qualidade para casa.",lat:36.7192,lng:-4.4233,durationLabel:"20–30 min",fit:"ANY",mapQuery:"La Mallorquina, Plaza de Félix Sáenz 7, Málaga",whatToDo:"Compre amêndoas marcona, pimentão doce (pimentón), açafrão e um doce local para presente.",kingTip:"Peça para embalar os frutos secos a vácuo; viajam melhor e mantêm o frescor até o Brasil.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"09:30",closeHour:"20:30",note:"Domingos fechado; pausa ao meio-dia possível fora da temporada alta."}},{id:"grn_ceramica_fajalauza",categoryId:"compras",city:"granada",name:"Cerámica Fajalauza",tagline:"Cerâmica granadina desde 1517 no Albaicín",description:"No alto do Albaicín, junto à antiga Porta de Fajalauza, sobrevive a olaria que dá nome à cerâmica mais tradicional de Granada, com raízes que remontam a 1517. O barro vidriado em branco decorado a azul e verde, com romãs e pássaros, é assinatura da casa da família Morales. Loja e fábrica onde se compra direto da fonte.",lat:37.1866,lng:-3.5933,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Cerámica Fajalauza, Carretera de Murcia 166, Granada",whatToDo:"Escolha pratos e tigelas com o clássico decoro azul e verde; peça peças com o motivo da romã, símbolo de Granada.",kingTip:"Fica na parte alta do Albaicín; combine com o passeio até o Mirador de San Nicolás e leve peças menores, mais fáceis de transportar.",priceLevel:"€€",hours:{openDays:"Seg–Sex",openHour:"09:00",closeHour:"18:00",note:"Confirme horário de sábado por telefone; domingos fechado."},links:[{label:"Site oficial",url:"https://fajalauza.es/"}],history:"Tradição oleira ligada à família Morales desde o início do século XVI, no bairro do Albaicín."},{id:"grn_mercado_san_agustin",categoryId:"compras",city:"granada",name:"Mercado de San Agustín",tagline:"Mercado gourmet de 1881 junto à catedral",description:"Único mercado de abastecimento no centro histórico de Granada, funciona desde 1881 a poucos metros da catedral e da Gran Vía. Reúne mais de vinte estabelecimentos com peixe, carne, frutas e uma seção gourmet de ostras, presuntos, queijos, azeites e vinhos, com mesas para degustar como tapas. Compra tradicional e prova de qualidade sob o mesmo teto.",lat:37.1778,lng:-3.5994,durationLabel:"40 min–1 h",fit:"INDOOR",mapQuery:"Mercado de San Agustín, Plaza de San Agustín 2, Granada",whatToDo:"Compre presunto e queijo nas bancas e sente-se num balcão gourmet para provar ostras ou uma tábua com vinho da terra.",kingTip:"A zona gourmet fica animada ao almoço; para a compra de mercado, chegue de manhã, quando o peixe está mais fresco.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"09:00",closeHour:"15:00",note:"A seção gourmet estende-se à tarde e à noite; bancas de fresco fecham ao início da tarde."}},{id:"grn_casa_ferrer",categoryId:"compras",city:"granada",name:"Guitarrería Casa Ferrer",tagline:"Luthier de guitarras desde 1875",description:"Na emblemática Cuesta de Gomérez, a subida que leva à Alhambra, esta oficina de luthiers soma quatro gerações e cerca de século e meio de ofício. Constrói à mão guitarras clássicas e flamencas, de estudo a instrumentos de concerto, num aroma de madeira e verniz que é história viva de Granada. Visita imperdível para amantes de música e artesanato fino.",lat:37.1759,lng:-3.5944,durationLabel:"20–40 min",fit:"ANY",mapQuery:"Guitarrería Casa Ferrer, Cuesta de Gomérez 26, Granada",whatToDo:"Observe o ateliê de construção e experimente uma guitarra flamenca; peça para conhecer as diferenças entre madeiras.",kingTip:"Fica no caminho a pé até a Alhambra; passe na ida, quando a loja está mais tranquila. Sábados costuma fechar.",priceLevel:"€€€",hours:{openDays:"Seg–Sex",openHour:"10:00",closeHour:"20:00",note:"Pausa aproximada das 13h30 às 17h; sábados fechado."},links:[{label:"Site oficial",url:"https://guitarreriacasaferrer.com/"}]},{id:"grn_bib_rambla_flores",categoryId:"compras",city:"granada",name:"Flores de Bib-Rambla",tagline:"Bancas de flores na praça mais alegre",description:"A Plaza Bib-Rambla, no coração de Granada, foi por gerações conhecida como Praça das Flores pelos quiosques que a coloriam. Ainda hoje, entre cafés e a fonte dos Gigantones, resistem bancas de flores e postos de artesanato e recordações. Um dos recantos mais fotogênicos da cidade para uma pausa e uma compra despretensiosa.",lat:37.1752,lng:-3.5998,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Plaza Bib-Rambla, Granada",whatToDo:"Compre um ramo de flores nas bancas históricas ou artesanato local nos quiosques e faça uma pausa num café da praça.",kingTip:"Fica coladinha à Alcaicería e à catedral; encadeie as três num só passeio de compras pelo centro.",priceLevel:"€"},{id:"grn_laguna_taracea",categoryId:"compras",city:"granada",name:"Laguna Taller de Taracea",tagline:"Marchetaria nazari desde 1877",description:"Dentro do recinto da Alhambra, na Calle Real, esta oficina familiar mantém desde 1877 a arte da taracea, a marchetaria de origem árabe que embute madeiras nobres, osso e madrepérola em padrões geométricos. Produz desde porta-copos e caixas a mesas e tabuleiros de xadrez, tudo feito à mão. Uma das compras mais autênticas e duradouras de Granada.",lat:37.176,lng:-3.5889,durationLabel:"20–40 min",fit:"ANY",mapQuery:"Laguna Taller de Taracea, Calle Real de la Alhambra 30, Granada",whatToDo:"Veja a demonstração da marchetaria e escolha uma caixa ou tabuleiro embutido; peça para diferenciar a taracea artesanal da industrial.",kingTip:"Está dentro da Alhambra, então aproveite a visita ao monumento para passar; peças pequenas viajam bem na bagagem de mão.",priceLevel:"€€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"19:00",note:"Acompanha o horário de visitação da Alhambra."},links:[{label:"Site oficial",url:"https://www.lagunataracea.com/"}],history:"Oficina de taracea em funcionamento contínuo desde 1877, herdeira da tradição nazari granadina."},{id:"mrb_la_canada",categoryId:"compras",city:"marbella",name:"La Cañada Shopping",tagline:"Maior centro comercial da Costa del Sol",description:"Aos pés da estrada de Ojén, é o grande centro comercial de Marbella, com arquitetura moderna, mais de uma centena de lojas, restauração, cinema e hipermercado. Reúne moda, esporte, tecnologia, decoração e beleza num só lugar climatizado, alternativa prática às boutiques da Milla de Oro. Ideal para compras variadas e para um dia de calor ou chuva.",lat:36.522,lng:-4.874,durationLabel:"1–2 h",fit:"INDOOR",mapQuery:"Centro Comercial La Cañada, Carretera de Ojén, Marbella",whatToDo:"Circule pelas lojas de moda e complementos, faça compras no hipermercado Alcampo e reserve tempo para o cinema ou a praça de alimentação.",kingTip:"Costuma fechar aos domingos, exceto em datas especiais e no verão; planeje as compras para dias de semana ou sábado.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"22:00",note:"Domingos fechado, salvo aberturas especiais (Natal, verão)."},links:[{label:"Site oficial",url:"https://lacanadashopping.com/"}]},{id:"cor_zoco_artesania",categoryId:"compras",city:"cordoba",name:"Zoco Municipal de la Artesanía",tagline:"Pátio de oficinas artesanais na Judería",description:"No coração da Judería, a passos da Mesquita-Catedral, este zoco ocupa uma casa senhorial de pátio típico cordovês onde trabalham artesãos de prata, couro, cerâmica e joalheria. Além de comprar direto de quem produz, é possível ver os ofícios em atividade nas oficinas ao redor do pátio. Vitrine viva do artesanato cordovês.",lat:37.8796,lng:-4.7831,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Zoco Municipal de la Artesanía, Calle Judíos, Córdoba",whatToDo:"Percorra as oficinas do pátio e compre uma peça de prata cordovesa ou de couro trabalhado direto do artesão.",kingTip:"Tem entradas pela Calle Judíos e pela Calle Averroes; entre pela primeira, junto à Sinagoga, e combine com a Calleja de las Flores.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"20:00",note:"Horário pode reduzir no verão pelo calor da tarde."}},{id:"cor_meryan",categoryId:"compras",city:"cordoba",name:"Meryan",tagline:"Couro cordovão e guadamecí desde 1958",description:"Na pitoresca Calleja de las Flores, esta oficina familiar preserva desde 1958 as técnicas dos célebres Couros de Córdoba: o cordovão e o guadamecí, couro repuxado, gravado a faca e decorado à mão, por vezes com folha de prata. Do painel decorativo a bolsas, baús e pequenos objetos, cada peça é única. Um dos ofícios mais nobres e antigos da cidade.",lat:37.8804,lng:-4.7796,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Meryan, Calleja de las Flores 2, Córdoba",whatToDo:"Desça ao taller para ver o couro sendo repuxado e gravado, e escolha uma peça de guadamecí ou um objeto menor de cordovão.",kingTip:"Fica na fotogênica Calleja de las Flores, com a torre da Mesquita ao fundo; chegue cedo para evitar o aperto de visitantes.",priceLevel:"€€€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"20:00",note:"Pausa possível ao meio-dia; domingos com horário reduzido."},links:[{label:"Site oficial",url:"https://meryancor.com/"}],history:"Fundada em 1958 por Ángel López-Obrero e Mercedes Miarons, dedicada às técnicas históricas dos Couros de Córdoba."},{id:"rnd_bodega_la_sangre",categoryId:"compras",city:"ronda",name:"Antigua Bodega La Sangre",tagline:"Vinhos da DO Ronda junto a Santa María",description:"No centro histórico de Ronda, ao lado da igreja de Santa María la Mayor, este espaço reúne e comercializa vinhos da jovem e premiada Denominação de Origem Ronda, cravada na serra a mais de 700 metros de altitude. Além de comprar garrafas de pequenas bodegas locais, é possível provar tintos e brancos da região. Compra ideal para quem quer levar o vinho da serrania para casa.",lat:36.7377,lng:-5.1645,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Antigua Bodega La Sangre, Calle Gómez 2, Ronda",whatToDo:"Prove uma seleção de tintos da DO Ronda e leve garrafas de produtores pequenos que raramente chegam ao Brasil.",kingTip:"Fica coladinha à Plaza Duquesa de Parcent e à igreja de Santa María; combine a compra com a visita ao centro monumental.",priceLevel:"€€",links:[{label:"Site oficial",url:"https://bodegaronda.com/"}]},{id:"mlg_revello_de_toro",categoryId:"cultura",city:"malaga",name:"Museo Revello de Toro",tagline:"Retratos na casa do escultor Pedro de Mena",description:"Reúne mais de cem obras do pintor malaguenho Félix Revello de Toro, mestre do retrato e da figura feminina, com desenhos e estudos preparatórios. O museu ocupa a casa-oficina onde viveu no século XVII o grande escultor barroco Pedro de Mena. Pequeno, luminoso e climatizado, é uma pausa serena a poucos passos do Museo Picasso.",whatToDo:["Acompanhe a evolução do retrato, dos esboços às telas finais","Observe os vestígios da antiga casa de Pedro de Mena","Combine com o Museo Picasso, que fica ao lado"],kingTip:"Fica a dois minutos do Museo Picasso; encaixe os dois no mesmo período para fugir do sol do meio-dia.",priceLevel:"~€4 (est.)",lat:36.720336,lng:-4.418324,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Ter–Sáb; Dom e feriados 10h–14h",openHour:10,closeHour:20,note:"Terça a sábado 10h–20h; domingos e feriados 10h–14h. Fecha às segundas."},mapQuery:"Museo Revello de Toro, Calle Afligidos 5, Málaga",links:[{label:"Site oficial",url:"https://www.museorevellodetoro.net/"}]},{id:"mlg_vidrio_y_cristal",categoryId:"cultura",city:"malaga",name:"Museo del Vidrio y Cristal",tagline:"Vidro e cristal num casarão do século XVIII",description:"Coleção privada de cerca de três mil peças de vidro e cristal de várias épocas e culturas, exibida em ambientes decorados com móveis, pinturas e vitrais. Ocupa um casarão restaurado de 1761 no bairro de San Felipe Neri, longe do burburinho turístico. A visita é sempre guiada e revela também a história doméstica da casa.",whatToDo:["Faça a visita guiada, incluída no ingresso, pelos salões ambientados","Repare nos vitrais e na coleção de vidro romano e fenício","Aprecie a fachada barroca e a placeta diante da igreja de San Felipe Neri"],kingTip:"As visitas são guiadas e com horário; ligue ou confira o site no mesmo dia para garantir o próximo turno.",priceLevel:"~€6 (est.)",lat:36.725706,lng:-4.421487,durationLabel:"1h–1h15",fit:"INDOOR",hours:{openDays:"Ter–Dom",openHour:11,closeHour:19,note:"Terça a domingo 11h–19h. Acesso apenas por visita guiada (aprox. 1h). Fecha às segundas."},mapQuery:"Museo del Vidrio y Cristal, Plazuela Santísimo Cristo de la Sangre 2, Málaga",links:[{label:"Site oficial",url:"https://www.museovidrioycristalmalaga.com/"}]},{id:"mlg_museo_jorge_rando",categoryId:"cultura",city:"malaga",name:"Museo Jorge Rando",tagline:"Expressionismo intenso, entrada gratuita",description:"Primeiro museu da Espanha dedicado ao expressionismo, centrado na obra vigorosa do pintor e escultor malaguenho Jorge Rando, com mostras temporárias de outros artistas do movimento. Ocupa um edifício claro e amplo no bairro do Molinillo, com ateliê visível. A entrada e as visitas guiadas são gratuitas.",whatToDo:["Percorra as grandes telas expressionistas de Jorge Rando","Veja a mostra temporária, que costuma trazer nomes internacionais","Aproveite a visita guiada gratuita, se houver turno disponível"],kingTip:"Entrada sempre gratuita. Fecha aos domingos e faz pausa ao meio-dia no inverno; vá pela manhã ou no fim da tarde.",priceLevel:"Grátis",lat:36.726725,lng:-4.423693,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Seg–Sáb (fecha Dom)",openHour:10,closeHour:20,note:"Seg a sex 10h–14h e 16h–20h (verão 17h–21h); sáb 10h–14h. Fecha aos domingos."},mapQuery:"Museo Jorge Rando, Calle Cruz del Molinillo 12, Málaga",links:[{label:"Site oficial",url:"https://www.museojorgerando.org/"}]},{id:"grn_centro_garcia_lorca",categoryId:"cultura",city:"granada",name:"Centro Federico García Lorca",tagline:"O legado vivo de Federico García Lorca",description:"Instituição cultural moderna que guarda o legado literário do poeta granadino, com manuscritos, desenhos e cartas do arquivo da família. O edifício contemporâneo, na Plaza de la Romanilla junto à Catedral, abriga exposições, biblioteca e auditório. Um contraponto sereno e climatizado à Granada monumental.",whatToDo:["Veja as exposições sobre a vida e a obra de Lorca","Confira a programação de recitais e atividades no auditório","Descanse na praça diante da Catedral ao sair"],kingTip:"As exposições costumam ter entrada gratuita. Fica coladinho à Catedral, ótimo para intercalar com o centro.",priceLevel:"Grátis (exposições)",lat:37.176634,lng:-3.600694,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:11,closeHour:20,note:"Ter a sáb 11h–14h e 17h/18h–20h/21h; dom e feriados 11h–14h. Fecha às segundas."},mapQuery:"Centro Federico García Lorca, Plaza de la Romanilla, Granada",links:[{label:"Site oficial",url:"https://www.centrofedericogarcialorca.es/"}]},{id:"grn_corral_del_carbon",categoryId:"cultura",city:"granada",name:"Corral del Carbón",tagline:"A única alhóndiga nazari da Península",description:"Antiga alhóndiga (albergue e armazém de mercadores) construída por volta de 1336, é a única de origem nazari conservada íntegra na Península Ibérica. Impressiona pela portada em arco de ferradura e pelo pátio de três andares de galerias em torno de uma fonte. Visita rápida e gratuita, no coração comercial de Granada.",whatToDo:["Entre pelo grande arco de ferradura decorado com laçarias","Contemple o pátio sombreado com suas galerias de tijolo","Siga para a vizinha Alcaicería e a Catedral"],kingTip:"Entrada gratuita e visita de dez minutos. O pátio é sombreado, ideal para uma pausa no calor entre as compras da Alcaicería.",priceLevel:"Grátis",lat:37.17451,lng:-3.59869,durationLabel:"15–20min",fit:"ANY",hours:{openDays:"Todos os dias",openHour:9,closeHour:19,note:"Seg a sex 9h–19h; sáb e dom 10h–14h. Entrada gratuita."},mapQuery:"Corral del Carbón, Calle Mariana Pineda, Granada",history:"Erguido no reinado de Yusuf I, servia de hospedaria e armazém para comerciantes. Após a conquista cristã foi teatro de comédias e, mais tarde, depósito de carvão, daí o nome atual.",links:[{label:"Turismo de Granada",url:"https://turismo.granada.org/es/corral-del-carbon"}]},{id:"grn_palacio_madraza",categoryId:"cultura",city:"granada",name:"Palacio de la Madraza",tagline:"A 1ª universidade nazari e seu oratório dourado",description:"Fundada por Yusuf I em 1349 como escola corânica, foi a primeira universidade de Granada, hoje sede cultural da Universidade. Conserva um deslumbrante oratório nazari com mihrab de estuques dourados e policromados, sob uma fachada barroca posterior. Fica na Calle Oficios, de frente para a Capilla Real.",whatToDo:["Admire o oratório nazari com o mihrab de estuques dourados","Veja o salão de colunas e as exposições temporárias da Universidade","Atravesse até a Capilla Real e a Catedral, em frente"],kingTip:"Fecha em agosto, aos domingos e feriados; em julho, visite de manhã. A entrada costuma ser simbólica.",priceLevel:"~€2 (est.)",lat:37.17632,lng:-3.59866,durationLabel:"30–45min",fit:"INDOOR",hours:{openDays:"Seg–Sex; Sáb com exposição",openHour:9,closeHour:21,note:"Seg a sex 9h–21h; sáb 11h–14h e 17h30–20h30 apenas com exposição. Fecha domingos, feriados e todo o mês de agosto."},mapQuery:"Palacio de la Madraza, Calle Oficios 14, Granada",links:[{label:"Site oficial (La Madraza – UGR)",url:"https://lamadraza.ugr.es/"}]},{id:"crd_sinagoga",categoryId:"cultura",city:"cordoba",name:"Sinagoga de Córdoba",tagline:"Rara sinagoga medieval no bairro judeu",description:"Pequena sinagoga mudéjar de 1315, uma das únicas três sinagogas medievais conservadas na Espanha e a única da Andaluzia. Encanta pelos estuques finíssimos com atauriques e inscrições hebraicas na sala de oração. Fica no coração da Judería, a poucos passos da Mezquita.",whatToDo:["Observe os estuques mudéjares e as inscrições hebraicas nas paredes","Localize a galeria alta reservada às mulheres","Perca-se depois pelas vielas caiadas da Judería"],kingTip:"Entrada gratuita e visita curta. Combine com a Mezquita e a Calleja de las Flores, tudo à sombra das ruas estreitas.",priceLevel:"Grátis",lat:37.87981,lng:-4.78338,durationLabel:"15–20min",fit:"INDOOR",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:9,closeHour:15,note:"Terça a domingo 9h–15h. Fecha às segundas (salvo feriados). Entrada gratuita."},mapQuery:"Sinagoga de Córdoba, Calle Judíos 20, Córdoba",links:[{label:"Enclave Monumental (Junta de Andalucía)",url:"https://www.juntadeandalucia.es/cultura/enclaves/enclave-monumental-sinagoga-de-cordoba"}]},{id:"crd_templo_romano",categoryId:"cultura",city:"cordoba",name:"Templo Romano",tagline:"Colunas de um templo romano do século I",description:"Conjunto de altas colunas coríntias que reconstroem um templo romano do século I, ligado ao fórum provincial da Córdoba imperial, ao lado da Câmara Municipal. Reaberto após restauro, pode ser visitado por dentro em visitas guiadas gratuitas. É um marco arqueológico surpreendente no centro moderno.",whatToDo:["Suba pela plataforma até a base das colunas na visita guiada","Entenda a relação do templo com o fórum romano de Corduba","Fotografe o conjunto iluminado ao entardecer"],kingTip:"É um recinto a céu aberto e sem sombra: reserve o primeiro turno da manhã (10h/11h) para evitar o sol forte de julho. Visitas guiadas gratuitas por ordem de chegada.",priceLevel:"Grátis",lat:37.88458,lng:-4.77601,durationLabel:"30–45min",fit:"ANY",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:10,closeHour:13,note:"Visitas guiadas gratuitas: ter–sex 10h/11h/12h; sáb, dom e feriados também às 13h. Fecha às segundas. Acesso pela Calle Claudio Marcelo."},mapQuery:"Templo Romano, Calle Capitulares, Córdoba",links:[{label:"Turismo de Córdoba",url:"https://www.turismodecordoba.org/templo-romano-de-cordoba"}]},{id:"crd_bellas_artes",categoryId:"cultura",city:"cordoba",name:"Museo de Bellas Artes de Córdoba",tagline:"Pintura andaluza na Plaza del Potro cervantina",description:"Instalado no antigo Hospital de la Caridad, reúne pintura e escultura andaluzas do gótico ao século XX, com destaque para os mestres cordobeses. Abre-se para a pitoresca Plaza del Potro, citada por Cervantes no Quixote. Salas frescas e um pátio ajardinado tornam a visita agradável mesmo no calor.",whatToDo:["Percorra as salas de pintura barroca e dos pintores cordobeses","Descanse no pátio ajardinado do antigo hospital","Espie a Posada del Potro cervantina, na mesma praça"],kingTip:"Gratuito para cidadãos da UE (leve documento). O pátio e as salas são um refúgio fresco perto da Ribeira do Guadalquivir.",priceLevel:"Grátis (UE)",lat:37.88125,lng:-4.77478,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:9,closeHour:21,note:"Inverno: ter–sáb 9h–21h, dom e feriados 9h–15h. Verão (16/jun–15/set): ter–dom 9h–15h. Fecha às segundas."},mapQuery:"Museo de Bellas Artes de Córdoba, Plaza del Potro 1, Córdoba",links:[{label:"Site oficial (Museos de Andalucía)",url:"https://www.museosdeandalucia.es/web/museodebellasartesdecordoba"}]},{id:"ant_museo_ciudad_najera",categoryId:"cultura",city:"antequera",name:"Museo de la Ciudad de Antequera (MVCA)",tagline:"O Efebo romano no Palácio de Nájera",description:"Um dos museus municipais mais ricos da Andaluzia, percorre a história de Antequera da pré-história aos dias de hoje em cerca de vinte salas. Sua estrela é o Efebo de Antequera, bronze romano do século I considerado uma das mais belas peças antigas da Península. Ocupa o barroco Palácio de Nájera, do século XVIII.",whatToDo:["Admire o Efebo de Antequera, o bronze romano que dá fama ao museu","Suba à torre-mirante do palácio para ver a cidade","Passeie pelo pátio de colunas de mármore vermelho de El Torcal"],kingTip:"Combine com os dolmens de Antequera (Patrimônio Mundial) numa parada a caminho de Granada ou Córdoba. Fecha às segundas.",priceLevel:"~€3 (est.)",lat:37.01626,lng:-4.55815,durationLabel:"1h–1h30",fit:"INDOOR",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:10,closeHour:18,note:"Verão (14/jun–17/set): ter–dom 9h–14h. Inverno: ter–sex 10h–14h e 16h30–18h30, sáb 9h30–14h e 16h30–18h30, dom 9h30–14h. Fecha às segundas."},mapQuery:"Museo de la Ciudad de Antequera, Plaza del Coso Viejo, Antequera",links:[{label:"Site oficial",url:"https://museoantequera.es/"}]},{id:"mrb_sollo",categoryId:"gastronomia",city:"marbella",name:"Sollo",tagline:"Estrela verde do chef do caviar",description:'Uma estrela Michelin e Estrela Verde do chef brasileiro-espanhol Diego Gallegos, o "chef do caviar", no resort Reserva del Higuerón, sobre a costa de Fuengirola. Alta cozinha sustentável de aquaponia: cerca de 90% dos ingredientes, incluindo peixes de água doce e caviar, são cultivados na própria casa. Menu-degustação Caminho, criativo e de raiz mediterrânea com sotaque sul-americano, servido com vista para o mar.',lat:36.5796,lng:-4.5951,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Sollo Restaurante, Reserva del Higuerón, Avenida del Higuerón 48, Fuengirola",whatToDo:"Vá de menu-degustação completo; peça mesa junto às janelas para a costa e deixe a harmonização por conta da casa.",kingTip:"Prove o caviar de produção própria, a assinatura de Gallegos. Cozinha de destino com pouca capacidade: RESERVE COM MESES DE ANTECEDÊNCIA para julho.",priceLevel:"~€145/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias e temporada podem variar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://www.sollo.es/en/"},{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/fuengirola/restaurant/sollo"}],history:"Diego Gallegos, nascido no Brasil e criado na Espanha, apostou na aquaponia e no caviar de esturjão para construir um dos projetos mais sustentáveis da Costa del Sol, distinguido também com a Estrela Verde Michelin."},{id:"mrb_kava",categoryId:"gastronomia",city:"marbella",name:"Kava",tagline:"Cinco mesas de alta cozinha pessoal",description:"Casa recomendada pela Michelin do chef Fernando Alcalá, junto ao centro de Marbella. Apenas cinco mesas para uma alta cozinha muito pessoal, que cruza o produto andaluz de proximidade com claras influências asiáticas. Menus-degustação Amatxo e Lord Fer, que evoluem com a estação.",lat:36.5081,lng:-4.8875,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Kava, Avenida Antonio Belón 4, Marbella",whatToDo:"Escolha um dos dois menus-degustação; a sala minúscula favorece a conversa com o chef e a explicação prato a prato.",kingTip:"Só cinco mesas: das reservas mais difíceis de Marbella. Reserve com semanas a meses de antecedência para o verão.",priceLevel:"~€90/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://www.kavamarbella.com/"},{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/marbella/restaurant/kava"}],history:"Aberto em 2015, Fernando Alcalá foi consolidando o Kava como um dos endereços de autor mais pessoais da cidade, com fusão andaluza e asiática."},{id:"mrb_bibo",categoryId:"gastronomia",city:"marbella",name:"BiBo Marbella by Dani García",tagline:"A brasserie andaluza descontraída de Dani García",description:"A casa mais informal do chef Dani García (ex-três estrelas Michelin), na exclusiva Plaza del Puente Romano. Brasserie andaluza vibrante e cosmopolita, com tapas de autor, arrozes e clássicos que fizeram fama do grupo. A porta de entrada divertida ao universo gastronômico de Dani García, sem menu-degustação.",lat:36.4999,lng:-4.918,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"BiBo Marbella by Dani García, Puente Romano, Bulevar Príncipe Alfonso de Hohenlohe, Marbella",whatToDo:"Peça várias tapas de autor para partilhar e um arroz; ambiente animado, ideal para uma noite descontraída na Milla de Oro.",kingTip:"Prove o tomate nitro e a hambúrguer de rabo de touro, assinaturas da casa. Muito procurado no verão: reserve com antecedência.",priceLevel:"€€€",hours:{openDays:"Seg-Dom",openHour:"13:00",closeHour:"00:00",note:"Aberto todos os dias em temporada; confirme"},links:[{label:"Site oficial e reserva",url:"https://grupodanigarcia.com/en/marbella/"}],history:"BiBo nasceu como o conceito mais canalha e acessível de Dani García e se espalhou por Madri e Londres, mas foi na Marbella do Puente Romano que ganhou seu ambiente mais icônico."},{id:"mrb_tragabuches",categoryId:"gastronomia",city:"marbella",name:"Tragabuches Marbella by Dani García",tagline:"A taberna honesta que voltou de Ronda",description:"A taberna de cozinha tradicional andaluza de Dani García, que ressuscita em Marbella o nome do histórico Tragabuches de Ronda. Receituário de raiz sem firulas, com produto de proximidade e preço sensato. O contraponto caseiro aos formatos de luxo do grupo.",lat:36.4834,lng:-4.9724,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"Tragabuches Marbella, Calle Ana de Austria 2, Marbella",whatToDo:"Peça a ensaladilla, as croquetes e a lendária tarta de queso; cozinha de partilha, ótima para grupos.",kingTip:"A tarta de queso é obrigatória para fechar. Casa muito popular: reserve com antecedência, sobretudo aos fins de semana de julho.",priceLevel:"~€55/pessoa (est.)",hours:{openDays:"Seg-Dom",openHour:"13:00",closeHour:"23:30",note:"Horários variam por temporada; confirme"},links:[{label:"Site oficial e reserva",url:"https://tragabuchesrestaurants.com/es/marbella/"}],history:"O Tragabuches original brilhou em Ronda e chegou a ter estrela Michelin; Dani García recuperou o nome em 2022 como tributo às suas origens e à cozinha tradicional andaluza."},{id:"nrj_sollun",categoryId:"gastronomia",city:"axarquia",name:"Sollun",tagline:"Mediterrâneo contemporâneo no centro de Nerja",description:"Restaurante recomendado pela Guia Michelin, do chef Juan Quintanilla, numa rua central de Nerja. Cozinha mediterrânea contemporânea, cuidada e sazonal, com técnica apurada em formação por casas estreladas. A melhor mesa de autor da Axarquía, com menus-degustação e harmonização.",lat:36.7501,lng:-3.8765,durationLabel:"jantar 2h",fit:"ANY",mapQuery:"Sollun Restaurante, Calle Pintada 9, Nerja",whatToDo:"Opte pelo menu-degustação com harmonização de vinhos; combine com um passeio pelo Balcón de Europa, a poucos minutos.",kingTip:"Sala reduzida numa vila que lota em julho: reserve com antecedência, sobretudo para o jantar.",priceLevel:"€€€",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/nerja/restaurant/sollun"}],history:"Aberto em 2006 por Juan Quintanilla, o Sollun tornou-se referência da cozinha de autor na costa da Axarquía, a leste de Málaga."},{id:"nrj_chiringuito_ayo",categoryId:"gastronomia",city:"axarquia",name:"El Chiringuito de Ayo",tagline:"A paella na lenha da Praia de Burriana",description:"Chiringuito lendário na Praia de Burriana, em Nerja, servindo paella cozida em fogo de lenha desde 1969. Instituição familiar e cenário da série espanhola Verano Azul, com os pés quase na areia. O clássico icônico e acessível da Axarquía, com peixe fresco, espetos e a paella à vontade.",lat:36.7388,lng:-3.8607,durationLabel:"almoço 1h30",fit:"CLEAR_SKY",mapQuery:"Chiringuito de Ayo, Playa de Burriana, Nerja",whatToDo:"Peça a paella cozida na barca de lenha, que se pode repetir; sente-se na esplanada de frente para o mar em dia de sol.",kingTip:"A paella na lenha é o motivo da visita e costuma ter repetição inclusa. Não reserva mesa: chegue cedo no almoço de verão para pegar a esplanada.",priceLevel:"€",hours:{openDays:"Seg-Dom",openHour:"11:00",closeHour:"19:00",note:"Só de dia, sazonal; a paella é servida ao almoço"},links:[{label:"Site oficial",url:"https://ayonerja.com/"}],history:"Ayo, personagem popular de Nerja, montou o chiringuito nos anos 1960 na Praia de Burriana, que ganhou fama nacional com as gravações da série Verano Azul nos anos 1980."},{id:"mlg_el_refectorium",categoryId:"gastronomia",city:"malaga",name:"El Refectorium Malagueta",tagline:"O clássico malaguenho junto à Malagueta",description:"Clássico da cidade de Málaga, fundado em 1973, no bairro da Malagueta, junto à praça de touros. Cozinha mediterrânea e malaguenha de solera, com destaque para peixes, frituras, guisos e a célebre ensaladilla rusa. Casa de sempre para provar a Málaga tradicional, com salão amplo e terraço soalheiro.",lat:36.7196,lng:-4.41,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"El Refectorium Malagueta, Calle Cervantes 8, Málaga",whatToDo:"Peça peixe fresco frito e a ensaladilla rusa da casa; ótima parada antes ou depois de um jogo ou evento na Malagueta.",kingTip:"A ensaladilla rusa é lendária na cidade. Muito frequentado por malaguenhos nos fins de semana: reserve para o almoço de domingo.",priceLevel:"€€€",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"23:30",note:"Fecha domingo à noite e segunda; confirme"},links:[{label:"Site oficial",url:"https://elrefectorium.es/"}],history:"Fundado por Francisco Ramírez em 1973, o Refectorium mantém-se em família com várias unidades na cidade, sendo a da Malagueta a de maior solera."},{id:"mlg_meson_astorga",categoryId:"gastronomia",city:"malaga",name:"Mesón Astorga",tagline:"Cozinha tradicional malaguenha de família",description:"Restaurante familiar de Málaga desde 1990, referência da cozinha tradicional, castelhana e andaluza. Guisos, carnes e pratos autóctones como o chivo malaguenho e o pastel de cebola, com uma adega de mais de 300 rótulos. Mesa honesta e caseira para conhecer os sabores de raiz da província.",lat:36.7142,lng:-4.4373,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"Mesón Astorga, Calle Gerona 11, Málaga",whatToDo:"Peça o chivo malaguenho e o pastel de cebola, especialidades da casa; peça sugestão de vinho da adega ao garçom.",kingTip:"O chivo (cabrito) malaguenho é o prato-assinatura. Casa procurada por locais: reserve para almoços de fim de semana.",priceLevel:"€€",hours:{openDays:"Seg-Sáb",openHour:"13:00",closeHour:"23:00",note:"Costuma fechar domingo; confirme"},links:[{label:"Site oficial",url:"https://mesonastorga.com/"}],history:"Aberto em 1990, o Mesón Astorga firmou-se como um dos guardiões da cozinha tradicional malaguenha na cidade."},{id:"rnd_almocabar",categoryId:"gastronomia",city:"ronda",name:"Almocábar",tagline:"Cozinha de raiz no bairro de San Francisco",description:"Casa de referência com mais de quatro décadas, sob a direção do chef Antonio Domínguez, no bairro antigo de San Francisco, em Ronda. Cozinha tradicional e inovadora com produto da serra, famosa pelas saladas e pelos pratos de caça e cordeiro. Esplanada agradável na praça, ambiente onde comem os próprios rondenhos.",lat:36.7339,lng:-5.1646,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"Restaurante Almocábar, Plaza Ruedo Alameda 5, Ronda",whatToDo:"Peça as saladas da casa e um prato de carne da serra; em dia de sol, sente-se na esplanada da Plaza Ruedo Alameda.",kingTip:"Alternativa acessível e local aos estrelados de Ronda. Casa pequena e muito procurada: reserve com antecedência.",priceLevel:"€€",hours:{openDays:"Qua-Seg",openHour:"12:30",closeHour:"23:00",note:"Costuma fechar terça; confirme"},history:'Instalado junto à muralha e à Puerta de Almocábar, o restaurante leva o nome árabe ("cemitério") da antiga porta da cidade e é um clássico do bairro de San Francisco.'},{id:"grn_damasqueros",categoryId:"gastronomia",city:"granada",name:"Damasqueros",tagline:"A essência granadina de Lola Marín",description:"Restaurante de autor da chef Lola Marín (um Sol Repsol), no coração do Realejo, o antigo bairro judeu de Granada. Cozinha granadina contemporânea num menu-degustação semanal que segue rigorosamente a estação e o mercado. Sala acolhedora e luminosa, referência da alta cozinha acessível da cidade.",lat:37.1745,lng:-3.5941,durationLabel:"almoço/jantar 2h",fit:"ANY",mapQuery:"Damasqueros, Calle Damasqueros 3, Granada",whatToDo:"Vá de menu-degustação semanal, que muda com o produto de mercado; combine com um passeio pelo Realejo.",kingTip:"Menu único que troca a cada semana: cada visita é diferente. Reserve com antecedência, sobretudo para o jantar de verão.",priceLevel:"~€55/pessoa (est.)",hours:{openDays:"Ter-Dom",openHour:"13:30",closeHour:"22:30",note:"Costuma fechar segunda; confirme na reserva"},links:[{label:"Site oficial",url:"https://damasqueros.com/"},{label:"Reserva",url:"https://damasqueros.com/reservas/"}],history:"Lola Marín consolidou o Damasqueros como um dos endereços de autor mais respeitados de Granada, defendendo o receituário local com produto de temporada."},{id:"grn_atelier_casa_comidas",categoryId:"gastronomia",city:"granada",name:"Atelier Casa de Comidas",tagline:"Alta cozinha a bom preço fora do centro",description:"Casa de comidas recomendada pela Michelin, do chef Raúl Sierra, perto do Palacio de Congresos de Granada. Gastronomia contemporânea de sabores andaluzes e técnica moderna, a preço sensato, com cozinha aberta. Famosa por clássicos como o croissant recheado de rabo de touro e as suas patatas bravas com molho de kimchi.",lat:37.1666,lng:-3.595,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"Atelier Casa de Comidas, Calle Sos del Rey Católico 7, Granada",whatToDo:"Peça as patatas bravas de kimchi e o croissant de rabo de touro; combine à la carte com o menu-degustação sazonal.",kingTip:"As patatas bravas com emulsão de kimchi são a assinatura da casa. Vale o desvio para fora do centro: reserve com antecedência.",priceLevel:"~€55/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://ateliercasadecomidas.com/en/home/"}],history:"Raúl Sierra regressou a Granada em 2017 para abrir o Atelier, que cresceu de espaço e virou um dos favoritos da crítica pela relação qualidade-preço."},{id:"crd_recomiendo",categoryId:"gastronomia",city:"cordoba",name:"ReComiendo",tagline:"A nova estrela Michelin de Periko Ortega",description:"Uma estrela Michelin conquistada em 2026 pelo chef Periko Ortega, num bairro residencial ao norte do centro de Córdoba. Cozinha de autor com raízes tradicionais e memória, técnica forte e sentido de humor, servida em barra e sala de design contemporâneo. Menus-degustação (Recuerdos, Memoria, Nostalgia) que percorrem a história pessoal do chef.",lat:37.9078,lng:-4.7759,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"ReComiendo, Calle Mirto 7, Córdoba",whatToDo:"Comece pelos petiscos na barra e siga para o menu-degustação na sala; deixe a harmonização por conta da casa.",kingTip:"Estrela recém-conquistada e sala reduzida fora do centro: RESERVE COM MESES DE ANTECEDÊNCIA para julho.",priceLevel:"~€95/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha domingo e segunda; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://www.recomiendopower.com/"},{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/cordoba/restaurant/recomiendo"}],history:"Periko Ortega abriu o ReComiendo em 2014 e mudou-se em 2018 para a Calle Mirto, onde a casa alcançou em 2026 a sua primeira estrela Michelin."},{id:"crd_el_envero",categoryId:"gastronomia",city:"cordoba",name:"El Envero",tagline:"Bib Gourmand de mercado em Córdoba",description:"Restaurante com Bib Gourmand da Guia Michelin em Córdoba, de cozinha moderna e sazonal com produto local. Pratos de temporada centrados em hortas de proximidade e diferentes atuns, com boa relação qualidade-preço e ampla seleção de vinhos. Uma das melhores opções da cidade fora do circuito estrelado.",lat:37.8985,lng:-4.7886,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"Restaurante El Envero, Calle Teruel 21, Córdoba",whatToDo:"Pergunte pelos pratos de atum e pela sugestão de mercado do dia; peça harmonização por taça da adega.",kingTip:"Bib Gourmand: cozinha cuidada a preço justo. Muito procurado pelos cordoveses: reserve para almoços de fim de semana.",priceLevel:"€€€",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"23:00",note:"Dias podem variar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://elenvero.com/"},{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/cordoba/restaurant/el-envero"}],history:"O El Envero firmou-se como uma referência de cozinha de mercado em Córdoba, renovando ano após ano o Bib Gourmand da Guia Michelin."},{id:"grn_palacio_dar_al_horra",categoryId:"granada",city:"granada",name:"Palacio de Dar al-Horra",tagline:"O palácio nazarí escondido no Albaicín",description:"No alto do Albaicín, este palácio nazarí do século XV sobrevive quase intacto, com pátio central, alberca e miradouros de gelosia sobre a cidade. Foi residência de Aixa, a rainha-mãe de Boabdil, o último sultão de Granada. Uma joia íntima e pouco visitada, com vista privilegiada da Alhambra.",lat:37.1847,lng:-3.5968,durationLabel:"30–40 min",fit:"INDOOR",mapQuery:"Palacio de Dar al-Horra, Granada",kingTip:"Está incluído no combo de monumentos 'Dobla de Oro' junto com a Alhambra — vale conferir esse bilhete conjunto. Os miradouros do andar superior dão uma das vistas mais limpas da Alhambra sem multidão.",priceLevel:"€ (~5 €, estimativa; incluso na Dobla de Oro)",hours:{openDays:"Todos os dias (verão)",openHour:"09:30",closeHour:"20:30",note:"Horário de verão (1 mai–14 set): 09:30–14:30 e 17:00–20:30."},links:[{label:"Turismo de Granada",url:"https://turismo.granada.org/es/palacio-dar-al-horra"}],history:"Construído no século XV sobre um palácio zirí do século XI, foi a casa de Aixa, mãe de Boabdil; após 1492 os Reis Católicos cederam-no ao mosteiro de Santa Isabel la Real."},{id:"grn_abadia_sacromonte",categoryId:"granada",city:"granada",name:"Abadía del Sacromonte",tagline:"Catacumbas e vistas no alto do vale",description:"No ponto mais alto do Sacromonte, esta abadia do século XVII guarda as Santas Cuevas — catacumbas onde, segundo a tradição, foi martirizado São Cecílio, padroeiro de Granada, e onde apareceram os célebres Libros Plúmbeos. O conjunto reúne igreja, claustros e um miradouro com vistas amplas sobre a cidade e a serra.",lat:37.1928,lng:-3.576,durationLabel:"1 h (visita guiada)",fit:"INDOOR",mapQuery:"Abadia del Sacromonte, Granada",kingTip:"Fica bem afastada, no fim da estrada do Sacromonte — vá de táxi ou do ônibus C34. As catacumbas são frescas mesmo no auge de julho. Aos domingos não se visita a igreja durante a missa das 12h.",priceLevel:"€ (~5 €, estimativa)",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"19:00",note:"Verão: 10:00–14:00 e 15:30–19:00; bilheteria fecha antes."},links:[{label:"Site oficial",url:"https://abadiasacromonte.org"}],history:"Erguida a partir de 1600 pelo arcebispo Pedro de Castro em torno das catacumbas onde surgiram as relíquias e os Libros Plúmbeos, achados que moldaram a identidade cristã de Granada."},{id:"grn_basilica_san_juan_de_dios",categoryId:"granada",city:"granada",name:"Basílica de San Juan de Dios",tagline:"Uma explosão de ouro barroco",description:"Considerada uma das igrejas mais douradas da Espanha, sua nave transborda talha coberta de ouro, espelhos, mármores e afrescos numa profusão barroca que ofusca. Guarda a urna de prata com os restos de São João de Deus, fundador da ordem hospitaleira. Pouco turística e de tirar o fôlego por dentro.",lat:37.17877,lng:-3.60258,durationLabel:"30–45 min",fit:"INDOOR",mapQuery:"Basilica de San Juan de Dios, Granada",kingTip:"Suba ao camarín atrás do altar-mor (bilhete inclui) para ver de perto o exagero dourado e as relíquias. Refúgio fresco e deslumbrante longe das filas da Alhambra.",priceLevel:"€ (~5 €, estimativa)",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"19:00",note:"Fecha em horários de culto; confira no local."},links:[{label:"Basílica San Juan de Dios",url:"https://basilicasanjuandedios.es"}],history:"Construída entre 1737 e 1759 em pleno auge do barroco granadino, é o templo da Ordem Hospitaleira fundada por João de Deus, canonizado em 1690."},{id:"grn_paseo_de_los_tristes",categoryId:"granada",city:"granada",name:"Paseo de los Tristes",tagline:"O passeio à beira do Darro sob a Alhambra",description:"Oficialmente Paseo del Padre Manjón, este trecho ribeirinho ao pé do rio Darro é o cenário mais romântico de Granada: pontes de pedra, esplanadas e a Alhambra suspensa logo acima. É o coração da Carrera del Darro, considerada uma das ruas mais bonitas da Espanha, ligando a Plaza Nueva ao Sacromonte.",lat:37.1796,lng:-3.5907,durationLabel:"30–45 min a pé",fit:"CLEAR_SKY",mapQuery:"Paseo de los Tristes, Granada",kingTip:"Ao entardecer, sente-se numa esplanada com a Alhambra iluminada por cima — a foto clássica é a partir da ponte. O nome vem de ser o antigo caminho dos cortejos fúnebres rumo ao cemitério.",priceLevel:"Gratuito (consumo à parte)",history:"Trecho final da Carrera del Darro, de traçado medieval; recebeu o apelido de 'dos Tristes' por ser a rota histórica dos cortejos fúnebres que subiam ao cemitério da cidade."},{id:"crd_medina_azahara",categoryId:"cordoba",city:"cordoba",name:"Medina Azahara",tagline:"A cidade-palácio do califa, Patrimônio Mundial",description:"A oito quilômetros de Córdoba, as ruínas da cidade palatina de Abderramão III (século X) escalam a encosta da Serra Morena em terraços de arcos vermelhos e brancos. Foi a esplêndida capital do califado, saqueada e esquecida poucas décadas depois. Um museu premiado e a Casa de Ya'far transportam ao apogeu do al-Andalus. Patrimônio da Humanidade desde 2018.",lat:37.8883,lng:-4.8666,durationLabel:"2–2,5 h (com museu)",fit:"ANY",mapQuery:"Conjunto Arqueologico Medina Azahara, Cordoba",whatToDo:"Comece pelo museu no sopé, pegue o ônibus-lançadeira até as ruínas e percorra o Salão Rico e a Casa de Ya'far no alto.",kingTip:"Não se chega de carro às ruínas: estacione no museu e use o ônibus-lançadeira oficial (bilhete à parte). Vá logo na abertura, às 9h — a encosta não tem sombra e ferve no julho cordobês. Entrada gratuita para cidadãos da UE.",priceLevel:"Museu gratuito (UE); lançadeira ~3 € (estimativa)",hours:{openDays:"Ter a dom (fecha segunda)",openHour:"09:00",closeHour:"15:00",note:"Verão (16 jun–15 set): ter–dom 09:00–15:00; consulte antes de ir."},links:[{label:"Site oficial",url:"https://www.medinaazahara.org"}],history:"Mandada erguer por Abderramão III a partir de 936 como sede do califado de Córdoba, foi destruída na guerra civil (fitna) por volta de 1010 e permaneceu soterrada até as escavações do século XX."},{id:"crd_banos_alcazar_califal",categoryId:"cordoba",city:"cordoba",name:"Baños del Alcázar Califal",tagline:"As termas árabes do palácio califal",description:"Sob o Campo Santo de los Mártires, estes banhos do século X serviam ao antigo alcácer dos califas omíadas. Ao estilo das termas romanas, sucedem-se salas fria, morna e quente sob abóbadas rasgadas por claraboias em forma de estrela. A cenografia e a projeção multimídia explicam o ritual do banho no al-Andalus.",lat:37.877,lng:-4.7827,durationLabel:"30–45 min",fit:"INDOOR",mapQuery:"Banos del Alcazar Califal, Cordoba",kingTip:"Subterrâneos e frescos — perfeitos para as horas mais quentes da tarde. Ficam bem ao lado do Alcázar de los Reyes Cristianos; dá para encadear as duas visitas.",priceLevel:"€ (~3 €, estimativa)",hours:{openDays:"Ter a dom (fecha segunda)",openHour:"08:15",closeHour:"14:15",note:"Verão (16 jun–15 set): ter–dom 08:15–14:15."},links:[{label:"Museos de Córdoba",url:"https://banosdelalcazarcalifal.cordoba.es"}],history:"Termas do século X ligadas ao Alcácer Califal omíada, ampliadas nos períodos almorávida e almóada; escavadas e abertas ao público como espaço museológico da cidade."},{id:"crd_plaza_del_potro",categoryId:"cordoba",city:"cordoba",name:"Plaza del Potro",tagline:"A praça imortalizada por Cervantes",description:"Um recanto cheio de história perto do Guadalquivir, com uma fonte renascentista coroada por um potro e a antiga Posada del Potro, estalagem do século XV citada no Dom Quixote. Cervantes chamou-a de covil de gente de má fama; hoje é um largo tranquilo ladeado por museus e casas caiadas.",lat:37.8817,lng:-4.7713,durationLabel:"20–30 min",fit:"ANY",mapQuery:"Plaza del Potro, Cordoba",kingTip:"Espie o pátio da Posada del Potro, uma das poucas estalagens medievais que sobrevivem — hoje abriga o Centro Flamenco Fosforito, de entrada gratuita. Ótima parada a caminho da ribeira.",priceLevel:"Gratuito",history:"Documentada desde o século XV, deve o nome à fonte com a figura de um potro; a Posada del Potro que a ladeia foi mencionada por Cervantes em Dom Quixote como refúgio de pícaros."},{id:"crd_torre_malmuerta",categoryId:"cordoba",city:"cordoba",name:"Torre de la Malmuerta",tagline:"A torre octogonal da lenda sombria",description:"Uma imponente torre-fortaleza do início do século XV, ligada à antiga muralha por um arco sobre a via. Seu nome — 'a mal-morta' — remete à lenda de uma dama assassinada pelo marido enganado por falsas suspeitas. Ergue-se isolada num largo ao norte do centro, marco do perímetro histórico da cidade.",lat:37.8895,lng:-4.7768,durationLabel:"15–20 min (exterior)",fit:"CLEAR_SKY",mapQuery:"Torre de la Malmuerta, Cordoba",kingTip:"Costuma ser vista só por fora — visitas ao interior são pontuais e mediante reserva municipal. Combine com uma caminhada até a vizinha Plaza de Colón e o Palacio de la Merced.",priceLevel:"Gratuito (exterior)",history:"Erguida por volta de 1406-1408 sob Henrique III como torre albarrã de defesa e ponto de vigia; a lenda do feminicídio deu-lhe o nome, embora historiadores o liguem a 'mal murada' (mal fortificada)."},{id:"crd_caballerizas_reales",categoryId:"cordoba",city:"cordoba",name:"Caballerizas Reales",tagline:"Berço do cavalo andaluz e palco equestre",description:"Fundadas por Filipe II em 1570 para criar o puro-sangue espanhol, estas cavalariças reais de naves abobadadas são um monumento vivo. À noite, sob a arena coberta, o espetáculo 'Pasión y Duende del Caballo Andaluz' reúne alta escola, doma vaquera e flamenco ao vivo num show de tirar o fôlego.",lat:37.876,lng:-4.7834,durationLabel:"Espetáculo ~60–70 min",fit:"INDOOR",mapQuery:"Caballerizas Reales de Cordoba",whatToDo:"Visite as naves e o pátio de dia; à noite, assista ao espetáculo equestre com música e flamenco ao vivo.",kingTip:"O espetáculo é às quartas, quintas, sextas e sábados — em julho começa às 21h, quando o calor já cedeu. Reserve com antecedência pelo site da Córdoba Ecuestre; fica coladinho ao Alcázar.",priceLevel:"€€€ (espetáculo ~24 €, estimativa; visita diurna à parte)",hours:{openDays:"Espetáculo: qua, qui, sex, sáb",openHour:"21:00",closeHour:"22:10",note:"Horário do show varia por temporada; visita diurna em outros horários."},links:[{label:"Córdoba Ecuestre — ingressos",url:"https://www.cordobaecuestre.com"}],history:"Criadas por decreto de Filipe II em 1570 sob o cavalariço Diego López de Haro para fixar a raça do Cavalo Andaluz (Pura Raza Española), permanecem como referência mundial da criação equestre."},{id:"mlg_montes_de_malaga",categoryId:"natureza",city:"malaga",name:"Parque Natural Montes de Málaga",tagline:"Bosque e miradouros a 15 min de Málaga",description:"Manto de pinheiros que recobre as colinas logo acima da cidade, resultado de um reflorestamento centenário para conter as cheias do Guadalmedina. Trilhas sinalizadas partem da área recreativa de Torrijos, onde um antigo lagar de vinho virou ecomuseu com restaurante rural. Miradouros abertos revelam a baía inteira, do porto às montanhas.",lat:36.8353,lng:-4.3453,durationLabel:"2–4 h",fit:"CLEAR_SKY",mapQuery:"Lagar de Torrijos, Parque Natural Montes de Málaga",kingTip:"A poucos graus mais fresco que a cidade pela altitude e pela sombra dos pinheiros; ainda assim vá pela manhã, leve água e prove o plato de los montes no restaurante de Torrijos.",priceLevel:"€",links:[{label:"Visita Málaga",url:"https://visita.malaga.eu"}]},{id:"mlg_senda_litoral",categoryId:"natureza",city:"malaga",name:"Senda Litoral de Málaga",tagline:"Passadiço à beira-mar pela orla de Málaga",description:"Passeio contínuo de passadiços de madeira e calçadão que costura as praias da cidade rente ao Mediterrâneo, ligando os antigos Baños del Carmen aos espigões do leste. Plano e acessível, cruza chiringuitos, palmeiras e barcos de espeto fincados na areia. Trecho urbano de uma senda que um dia percorrerá todo o litoral da província.",lat:36.71776,lng:-4.38286,durationLabel:"1–3 h",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Baños del Carmen, Málaga",kingTip:"Sem sombra ao longo do passadiço: caminhe ao amanhecer ou no fim da tarde e emende com um banho de mar e sardinhas assadas num chiringuito.",priceLevel:"€"},{id:"mlg_catamaran_delfines",categoryId:"natureza",city:"malaga",name:"Catamarã e golfinhos no porto de Málaga",tagline:"Catamarã e golfinhos saindo do porto",description:"Saídas de catamarã à vela do Muelle Uno, no coração do porto, para navegar a baía e procurar os golfinhos-comuns que seguem os barcos no verão. Roteiros de uma a duas horas incluem banho em mar aberto e vista do skyline de Málaga a partir da água. Maio a outubro é a melhor janela para o avistamento.",lat:36.7146,lng:-4.4166,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Muelle Uno, Puerto de Málaga",kingTip:"O avistamento não é garantido; reserve a primeira saída da manhã, com mar mais calmo, e leve boné, protetor e uma muda para o banho a bordo.",priceLevel:"€€€",links:[{label:"Mundo Marino",url:"https://mundomarino.es"}],image:"mlg_catamaran_delfines.jpg"},{id:"ant_fuente_de_piedra",categoryId:"natureza",city:"antequera",name:"Laguna de Fuente de Piedra",tagline:"Flamingos na maior laguna da Andaluzia",description:"A maior laguna natural da Andaluzia e a principal colônia de flamingos-comuns da Península, com milhares de aves rosadas espelhadas na água salobra. Passarelas e observatórios partem do Centro de Visitantes José Antonio Valverde, dedicado ao pai da anilhagem de aves na Espanha. Um dos maiores espetáculos ornitológicos da Europa.",lat:37.1218,lng:-4.7472,durationLabel:"1–2 h",fit:"CLEAR_SKY",mapQuery:"Centro de Visitantes Laguna de Fuente de Piedra, Fuente de Piedra",kingTip:"Em julho a laguna pode secar em parte e concentrar os flamingos ao longe; leve binóculos, vá cedo pela luz e confirme antes se ainda há água e aves na temporada.",priceLevel:"€",links:[{label:"Fuente de Piedra",url:"https://www.fuentedepiedra.es"}]},{id:"ant_lobo_park",categoryId:"natureza",city:"antequera",name:"Lobo Park",tagline:"Santuário de lobos ibéricos e árticos",description:"Santuário de 40 hectares a poucos quilômetros de Antequera onde vivem, em grandes recintos naturais, alcateias de lobo-ibérico, europeu, da tundra do Alasca e do timber. A visita é sempre guiada, por caminhos de terra entre encinas, com biólogos explicando o comportamento de cada matilha. Nas noites de lua cheia há sessões especiais de uivos.",lat:36.9867,lng:-4.6233,durationLabel:"1,5 h (visita guiada)",fit:"CLEAR_SKY",mapQuery:"Lobo Park, Ctra. Antequera-Álora A-343 km 16",kingTip:"O acesso é só nos horários da visita guiada (por volta de 11h, 13h, 15h e 16h30); reserve a das 11h para pegar os lobos ativos antes do calor e confira no site se há tour noturno de lua cheia.",priceLevel:"€€",hours:{openDays:"Ter–Dom",openHour:"10:00",closeHour:"17:00",note:"Entrada só em visitas guiadas com horário marcado; confirme os turnos e feche reserva."},links:[{label:"Site oficial",url:"https://www.lobopark.com"}]},{id:"axq_rio_chillar",categoryId:"natureza",city:"axarquia",name:"Río Chíllar",tagline:"Caminhada dentro do rio, água até os joelhos",description:"Caminhada aquática lendária em que se avança rio acima, com os pés dentro da água fria da Sierra de Almijara, saindo de Nerja. O leito estreita nos Cahorros, um cânion de paredes verticais a poucos metros uma da outra, com poças e pequenas cascatas. Refresco natural perfeito para o verão andaluz.",lat:36.76445,lng:-3.87313,durationLabel:"4–6 h",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Aparcamiento Río Chíllar, Nerja",kingTip:"O trajeto é dentro d'água quase todo: use tênis ou sapatilha aquática que possa molhar, comece cedo (o parking de 1€ lota) e nunca entre com previsão de chuva ou tempestade na serra, pelo risco de enxurrada.",priceLevel:"€",links:[{label:"Visita Nerja",url:"https://visita.nerja.es"}]},{id:"axq_kayak_maro",categoryId:"natureza",city:"axarquia",name:"Caiaque nos Acantilados de Maro-Cerro Gordo",tagline:"Caiaque entre falésias e grutas marinhas",description:"Passeio de caiaque pelo paraje natural das falésias de Maro-Cerro Gordo, remando ao pé de paredões de até 70 metros entre Nerja e La Herradura. O trajeto revela enseadas escondidas, uma cachoeira que cai direto no mar e grutas onde só se entra pela água. Fundo marinho protegido, ideal para mergulho de snorkel nas paradas.",lat:36.75375,lng:-3.83396,durationLabel:"2–3 h",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de Maro, Nerja",kingTip:"Reserve a saída da manhã, quando o mar está de espelho; o vento da tarde levanta ondulação e cancela passeios. Leve protetor, câmera à prova d'água e sapatilha para as paradas nas calas.",priceLevel:"€€€"},{id:"axq_acueducto_aguila",categoryId:"natureza",city:"axarquia",name:"Acueducto del Águila",tagline:"Aqueduto de 36 arcos escondido em Maro",description:"Aqueduto do século XIX escondido num barranco verdejante a oeste das Cuevas de Nerja, com quatro níveis sobrepostos e 36 arcos em ferradura. No alto, um pavilhão coroado por um cata-vento de águia bicéfala, que batiza a obra, ainda leva água aos antigos engenhos de açúcar de Maro. Uma joia de tijolo emoldurada pela vegetação.",lat:36.7573,lng:-3.8324,durationLabel:"20–40 min",fit:"CLEAR_SKY",mapQuery:"Acueducto del Águila, Maro, Nerja",kingTip:"Há um recuo na antiga N-340 para parar e fotografar de frente; combine com as Cuevas de Nerja e a Playa de Maro, tudo a poucos minutos, e vá no fim da tarde pela melhor luz.",priceLevel:"€"},{id:"rnd_sierra_nieves",categoryId:"natureza",city:"ronda",name:"Parque Nacional Sierra de las Nieves",tagline:"Teto da província: pinsapos e o Torrecilla",description:"O parque nacional mais jovem da Espanha, declarado em 2021, guarda um dos maiores bosques de pinsapo, o raro abeto-espanhol relicto da era glacial. Do trailhead de Los Quejigales sobe-se ao Torrecilla, com 1.919 metros o teto da província de Málaga e vistas de duas costas. Altas montanhas selvagens a menos de uma hora de Ronda.",lat:36.68993,lng:-5.0458,durationLabel:"6–7 h (ida e volta)",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Área Recreativa Los Quejigales, Ronda",kingTip:"Atenção: por risco de incêndio, a estrada de acesso a Los Quejigales costuma fechar de meados de junho a meados de outubro, bem no verão. Antes de julho, confirme a abertura com o parque; se fechado, opte pelos miradouros e pelo pinsapar acessível pelo lado de Yunquera.",priceLevel:"€",links:[{label:"Sierra de las Nieves",url:"https://www.i-sierradelasnieves.com"}]},{id:"rnd_cueva_gato",categoryId:"natureza",city:"ronda",name:"Cueva del Gato",tagline:"Nascente esmeralda para um banho serrano",description:"Ponto onde o rio subterrâneo do complexo Hundidero-Gato, com mais de 10 km de galerias, ressurge à luz por uma boca escura em forma de focinho de gato. Sob ela forma-se uma poça de água esmeralda e gelada, cercada de rochedos, junto a Benaoján. Monumento natural e piscina serrana das mais fotogênicas da Serranía de Ronda.",lat:36.7223,lng:-5.236,durationLabel:"1–2 h",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Cueva del Gato, Benaoján",kingTip:"A água é cortante mesmo em julho e a poça fica funda perto da boca; o banho é só na parte externa, pois a caverna é fechada à visita. Chegue cedo, o pequeno mirador e o parking lotam nos dias quentes.",priceLevel:"€"},{id:"rnd_cueva_pileta",categoryId:"natureza",city:"ronda",name:"Cueva de la Pileta",tagline:"Arte rupestre paleolítica à luz de lampião",description:"Caverna nas montanhas de Benaoján que guarda pinturas rupestres de até 20 mil anos, com cavalos, peixes e sinais traçados em ocre e carvão. A visita, guiada e à luz de lampiões a gás pela família que descobriu o sítio em 1905, mantém a atmosfera de outro tempo. Uma das grandes joias do Paleolítico andaluz, longe das multidões.",lat:36.6925,lng:-5.2687,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Cueva de la Pileta, Benaoján",kingTip:"A gruta é fresca e coberta, ótimo refúgio no calor, mas os grupos são de até 25 pessoas e não há venda online: ligue antes para reservar e chegue com folga pela estrada estreita de acesso.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"18:00",note:"Sessões guiadas às 10h–13h e à tarde; último grupo às 18h no verão. Reserva por telefone."},links:[{label:"Site oficial",url:"https://cuevadelapileta.com"}]},{id:"rnd_acinipo",categoryId:"natureza",city:"ronda",name:"Acinipo (Ronda la Vieja)",tagline:"Teatro romano solitário sobre a serra",description:"Cidade romana em ruínas sobre um planalto a quase 1.000 metros, a uns 20 km de Ronda, com um dos teatros mais bem conservados da Hispânia. O graderío escavado na rocha viva emoldura um horizonte que alcança três províncias, sem multidões nem cercas. História e paisagem cársica num sítio quase secreto da Serranía.",lat:36.8869,lng:-5.2606,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Yacimiento de Acinipo, Ronda la Vieja",kingTip:"Planalto totalmente exposto ao sol e ao vento; visite de manhã com chapéu e água. A visita livre é gratuita, mas o sítio abre poucos dias por semana, então confirme o horário antes de subir.",priceLevel:"€",hours:{openDays:"Qua–Dom",openHour:"09:00",closeHour:"14:30",note:"Entrada gratuita; fecha seg e ter. Horário pode variar no verão, confirme antes."}},{id:"mrb_la_concha",categoryId:"natureza",city:"marbella",name:"Subida a La Concha desde Juanar",tagline:"Cume de 1.215 m com vista de 360° do mar",description:"Ascensão ao pico La Concha, a silhueta em forma de concha que domina o horizonte de Marbella, partindo do Refugio de Juanar em Ojén. O caminho cruza olivais e pinheiros até um trecho final estreito e rochoso, aéreo, com o mar de um lado e a Sierra Blanca do outro. Do cume, panorama de 360° que em dias limpos alcança o Rif marroquino.",lat:36.5583,lng:-4.8944,durationLabel:"4–5 h (ida e volta)",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Refugio de Juanar, Ojén",kingTip:"O trecho final tem passos expostos e vira perigoso com vento forte ou neblina; não é para quem sofre de vertigem. Saia ao nascer do sol para evitar o calor da encosta e leve ao menos 2 L de água por pessoa.",priceLevel:"€"},{id:"mrb_charco_canalon",categoryId:"natureza",city:"marbella",name:"Charco del Canalón (Río Verde, Istán)",tagline:"Poça turquesa no desfiladeiro do Río Verde",description:"Poça funda de água turquesa encaixada entre paredes de calcário no vale do Río Verde, junto a Istán, a menos de meia hora de Marbella. Um canal de irrigação despeja no alto uma cascata que alimenta a piscina natural, sombreada por sobreiros e adelfas. Refúgio aquático dos mais bonitos da Sierra de las Nieves.",lat:36.6083,lng:-4.9603,durationLabel:"3–4 h (ida e volta)",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Charco del Canalón, Istán",kingTip:"A poça é funda e escorregadia, só para quem nada bem; as pedras do leito têm algas traiçoeiras, use calçado aquático. Vá cedo por vaga no Vado de Bornoque e nunca com previsão de chuva na serra.",priceLevel:"€",links:[{label:"Istán",url:"https://www.istan.es"}]},{id:"grn_hoya_de_la_mora",categoryId:"natureza",city:"granada",name:"Hoya de la Mora, Sierra Nevada",tagline:"Neve eterna e ar puro a 2.500 m no verão",description:"Portal de alta montanha de Sierra Nevada a cerca de 2.500 metros, fim da estrada asfaltada mais alta da Espanha e base das caminhadas de verão rumo ao Veleta. Ar rarefeito e fresco, restos de neve nos barrancos e vistas que descem até Granada e o Mediterrâneo. Contraste absoluto com o calor do vale, a uma hora da cidade.",lat:37.0975,lng:-3.3878,durationLabel:"meio dia",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Hoya de la Mora, Sierra Nevada",kingTip:"No verão é o antídoto perfeito ao calor: pode fazer 15°C e ventar. Leve casaco, protetor forte (o sol da altitude queima rápido) e suba devagar por conta da altitude; no verão às vezes funciona o telecabina desde Pradollano.",priceLevel:"€",links:[{label:"Sierra Nevada",url:"https://sierranevada.es"}]},{id:"mlg_el_palo",categoryId:"praias",city:"malaga",name:"Playa de El Palo",tagline:"Espeto de sardinha na praia de bairro",description:"A praia mais castiça de Málaga, no antigo bairro de pescadores a leste da cidade. É aqui que os espetos de sardinha assam na areia sobre barcas cheias de brasa, num ambiente de família e de vida local, longe do turismo. Areia escura, águas calmas e um passeio marítimo cheio de chiringuitos históricos.",lat:36.7191,lng:-4.3548,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de El Palo, Málaga",kingTip:"Chegue com fome ao meio-dia: o espeto de sardinha, seis peixes num espeto de cana, é servido só na hora e é a alma deste pedaço de Málaga.",whereToEat:"El Tintero, o chiringuito clássico onde os garçons leiloam os pratos aos gritos entre as mesas."},{id:"mlg_misericordia",categoryId:"praias",city:"malaga",name:"Playa de la Misericordia",tagline:"Areia escura e pôr do sol operário",description:"Praia extensa e desafogada no bairro popular de Sacaba, a oeste do centro. Voltada para o poente, oferece um dos melhores pores do sol urbanos de Málaga, com a antiga chaminé da térmica ao fundo. Frequentada quase só por malaguenhos, tem chiringuitos honestos e muito espaço mesmo em agosto.",lat:36.689,lng:-4.452,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de la Misericordia, Málaga"},{id:"mlg_guadalmar",categoryId:"praias",city:"malaga",name:"Playa de Guadalmar",tagline:"Praia tranquila junto ao estuário",description:"No extremo oeste da cidade, colada à reserva natural da Desembocadura del Guadalhorce, é a praia mais sossegada de Málaga. O ambiente é natural e amplo, ideal para caminhar e observar aves no estuário vizinho. O trecho mais ao sul é tradicionalmente naturista.",lat:36.665,lng:-4.49,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de Guadalmar, Málaga",kingTip:"Combine a praia com uma volta pelos observatórios da reserva do Guadalhorce, ali ao lado: flamingos e aves aquáticas a poucos minutos da areia."},{id:"mlg_penon_cuervo",categoryId:"praias",city:"malaga",name:"Peñón del Cuervo",tagline:"Rochedo partindo a areia ao meio",description:"Enseada de areia escura no leste da cidade, marcada por um grande rochedo que divide a praia em duas metades e lhe dá nome. Rodeada por um parque florestal, tem um ar mais bravio e menos urbano que as praias do centro. É palco tradicional das moragas, as noitadas malaguenhas com fogueira, comida e amigos na areia.",lat:36.713,lng:-4.335,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa del Peñón del Cuervo, Málaga",links:[{label:"Ficha oficial de turismo de Málaga",url:"https://visita.malaga.eu/en/what-to-see-and-do/beaches/penon-del-cuervo-beach-p103834"}]},{id:"mlg_san_andres",categoryId:"praias",city:"malaga",name:"Playa de San Andrés",tagline:"Praia urbana com chiringuitos de sempre",description:"Praia central no bairro de Huelin, a um passo do porto e do centro. Popular entre os malaguenhos, é prática para um banho rápido sem sair da cidade, com chiringuitos tradicionais e passeio marítimo animado. Areia escura e serviços completos ao longo de toda a orla.",lat:36.704,lng:-4.435,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de San Andrés, Málaga"},{id:"nrj_torrecilla",categoryId:"praias",city:"axarquia",name:"Playa de la Torrecilla",tagline:"Bandeira Azul a passos do centro de Nerja",description:"A praia mais bem equipada de Nerja, a oeste do casco antigo e reconhecida com Bandeira Azul e o selo Q de Qualidade. Deve o nome aos restos de uma torre vigia que a acompanha, e reúne areia limpa, água calma e todos os serviços a poucos minutos a pé do centro. Tem até serviço de biblioteca de praia com livros em vários idiomas.",lat:36.7442,lng:-3.8835,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de la Torrecilla, Nerja",links:[{label:"Guia de praias de Nerja",url:"https://esnerja.com/playas/playa-torrecilla/"}]},{id:"nrj_carabeo",categoryId:"praias",city:"axarquia",name:"Playa de Carabeo",tagline:"Cala escondida sob as falésias",description:"Pequena cala íntima abraçada por falésias, que se alcança descendo uma escadaria ao fim da Calle Carabeo. Recolhida e de águas transparentes, recompensa quem procura sossego longe das praias mais movimentadas de Nerja. As vistas do alto do caminho, junto aos jardins do Carabeo, são espetaculares.",lat:36.7452,lng:-3.8738,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Carabeo, Nerja",kingTip:"Leve o essencial: a descida é por escadas e não há grande estrutura na areia, o que é justamente o que mantém a cala tão tranquila."},{id:"nrj_el_salon",categoryId:"praias",city:"axarquia",name:"Playa El Salón",tagline:"Enseada urbana escondida no centro",description:"Cala aconchegante escondida logo abaixo do Balcón de Europa, a poucos passos do coração de Nerja. Apesar de central, passa despercebida por ficar num recanto que se acessa por uma ladeira, o que lhe garante águas calmas e abrigadas. Perfeita para um mergulho entre uma volta e outra pelo casco antigo.",lat:36.7448,lng:-3.8785,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa El Salón, Nerja"},{id:"mrb_cabopino",categoryId:"praias",city:"marbella",name:"Playa de Cabopino",tagline:"Dunas naturais e torre vigia do século XV",description:"Uma das praias mais virgens da Costa del Sol, no leste de Marbella, junto ao Monumento Natural das Dunas de Artola. Mais de um quilômetro de areia fina e clara sob dunas protegidas e a imponente Torre de los Ladrones, a mais alta torre vigia da costa malaguenha. Metade da praia é tradicionalmente naturista, mas o ambiente é tranquilo e familiar.",lat:36.4877,lng:-4.7418,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de Cabopino, Marbella",kingTip:"Estacione junto à marina de Cabopino e faça a passarela de madeira sobre as dunas: é o jeito de atravessar sem pisar a vegetação protegida.",whereToEat:"Chiringuitos junto ao Puerto Deportivo de Cabopino, ao lado da praia."},{id:"mrb_nagueles",categoryId:"praias",city:"marbella",name:"Playa de Nagüeles",tagline:"Milha de Ouro com beach clubs de luxo",description:"Praia da célebre Milla de Oro de Marbella, entre o centro e Puerto Banús, cercada por hotéis e beach clubs de referência. Areia dourada e ampla, com serviço impecável e o ambiente sofisticado que fez a fama da cidade. É aqui que se alinham alguns dos endereços mais exclusivos da orla.",lat:36.5045,lng:-4.9175,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Nagüeles, Marbella",whereToEat:"Beach clubs da Milla de Oro à beira da areia, do casual ao alta gastronomia."},{id:"mrb_estrella_mar",categoryId:"praias",city:"marbella",name:"Estrella del Mar Beach Club",tagline:"Beach club tranquilo na Marbella leste",description:"Beach club elegante e sereno na zona de Las Chapas/Elviria, integrado ao hotel Vincci Selección Estrella del Mar. Piscina infinita de frente para o mar, spa e cozinha mediterrânea fazem dele a escolha de quem quer um dia de praia calmo e confortável, ideal para casais e famílias. Menos festa e mais requinte que os beach clubs de Puerto Banús.",lat:36.4832,lng:-4.7825,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Beach Club Estrella del Mar, Marbella",priceLevel:"~€30 mín. consumo (est.)"},{id:"mlg_meson_cervantes",categoryId:"tapas",city:"malaga",name:"El Mesón de Cervantes",tagline:"Tapas de autor junto à Plaza de la Merced",description:"Casa querida do centro histórico, a passos do Teatro Cervantes e da praça onde nasceu Picasso. A cozinha do chef argentino-malaguenho cruza o receituário andaluz com pinceladas de fora, em porções pequenas de execução caprichada e uma carta de vinhos bem escolhida. Ambiente descontraído e sempre cheio, ideal para uma noite de tapeo com calma.",lat:36.72438,lng:-4.41876,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"El Mesón de Cervantes, Calle Álamos 11, Málaga",kingTip:"Peça as mollejas (moelas de vitela) grelhadas com chimichurri, a tapa-assinatura que fundiu Buenos Aires e Málaga.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"19:30",closeHour:"23:30",note:"Foco no jantar; confirme o dia de descanso semanal na alta temporada."},links:[{label:"Site oficial",url:"https://elmesondecervantes.com"}]},{id:"mlg_uvedoble",categoryId:"tapas",city:"malaga",name:"Uvedoble Taberna",tagline:"Cozinha andaluza reinventada no Teatro Romano",description:"Taberna de referência do chef Willie Orellana, encravada na Calle Alcazabilla, entre o Teatro Romano e a Alcazaba. Releitura contemporânea da cozinha malaguenha em tapas de apresentação cuidada, servidas num salão estreito e vibrante de balcão animado. A escolha certa para quem quer tapas modernas sem perder a raiz local.",lat:36.72186,lng:-4.41694,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Uvedoble Taberna, Calle Alcazabilla 1, Málaga",kingTip:"Prove o célebre ovo com batata palha e trufa, a tapa que virou marca registrada da casa.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"12:30",closeHour:"00:00",note:"Domingos fechado; reserva recomendada à noite."},links:[{label:"Site oficial",url:"https://www.uvedobletaberna.com"}]},{id:"mlg_tapeo_cervantes",categoryId:"tapas",city:"malaga",name:"El Tapeo de Cervantes",tagline:"Petiscos criativos junto ao Teatro Cervantes",description:"Bistrô de tapas minúsculo e acolhedor na Calle Cárcer, colado ao Teatro Cervantes. Poucas mesas e um balcão apertado servem pequenas porções criativas de raiz andaluza, com destaque para carnes de cocção lenta e produtos de mercado. Íntimo e concorrido, pede reserva antecipada.",lat:36.72384,lng:-4.41946,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"El Tapeo de Cervantes, Calle Cárcer 8, Málaga",kingTip:"Peça o solomillo (filé) ao Pedro Ximénez, a tapa de assinatura regada ao vinho doce de Málaga.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"23:30",note:"Espaço pequeno; reserve com antecedência, sobretudo nos fins de semana."},links:[{label:"Site oficial",url:"https://eltapeodecervantes.com"}]},{id:"mlg_lo_gueno",categoryId:"tapas",city:"malaga",name:"Mesón Lo Güeno",tagline:"Taberna clássica de tapas desde 1967",description:"Referência do tapeo tradicional malaguenho, na Calle Marín García desde 1967, a poucos metros da Calle Larios. Balcão farto de tapas, salão de vigas de madeira e presuntos pendurados servem clássicos andaluzes com generosidade. Casa de sempre para sentir a Málaga de outrora.",lat:36.71872,lng:-4.41985,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Mesón Lo Güeno, Calle Marín García 9, Málaga",kingTip:"Peça as berinjelas fritas com mel de cana, a tapa doce-salgada emblemática da casa.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Enche na hora do aperitivo e no jantar; há uma segunda casa na Calle Strachan."},links:[{label:"Site oficial",url:"https://logueno.com"}]},{id:"grn_los_diamantes",categoryId:"tapas",city:"granada",name:"Los Diamantes (Plaza Nueva)",tagline:"Pescaíto frito e tapa grátis desde 1942",description:"Instituição granadina fundada em 1942, na animada Plaza Nueva, fiel à tradição da tapa gratuita a cada bebida. Frituras de peixe impecáveis, mariscos e um ambiente ruidoso de mesas comunais e balcão lotado captam a essência do sul. Não aceitam reserva e vive cheio, parte do encanto.",lat:37.17655,lng:-3.5981,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Los Diamantes, Plaza Nueva 13, Granada",kingTip:"Em Granada a tapa é grátis com a bebida; aqui peça o pescaíto frito variado, o carro-chefe da casa.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Não aceitam reserva; costuma lotar, com clientes em pé no balcão."}},{id:"rnd_bodega_san_francisco",categoryId:"tapas",city:"ronda",name:"Bodega San Francisco",tagline:"Tapas serranas junto à muralha de Ronda",description:"Taberna do bairro San Francisco, ao pé da muralha e da Puerta de Almocábar, no sul da cidade velha. Carta enorme de tapas e porções de cozinha caseira serrana, servidas dentro ou num grande terraço à sombra. Muito frequentada por locais, com preços honestos e porções fartas.",lat:36.73758,lng:-5.16558,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Bodega San Francisco, Plaza Ruedo Alameda 32, Ronda",kingTip:"Peça o rabo de toro guisado, a tapa serrana mais pedida da casa, com um tinto da Serranía de Ronda.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Terraço amplo; enche no almoço e à noite na alta temporada."},links:[{label:"Site oficial",url:"https://bodegasanfrancisco.com"}]},{id:"cor_taberna_salinas",categoryId:"tapas",city:"cordoba",name:"Taberna Salinas",tagline:"Taberna cordovesa de 1924 com pátio",description:"Taberna histórica fundada em 1924, perto da Plaza de las Tendillas, com botas de vinho no balcão e um belo pátio de colunas envidraçado e veladores de mármore. Cozinha cordovesa tradicional de receitas centenárias, tocada por gerações da mesma família. Uma das tabernas mais autênticas da cidade.",lat:37.8853,lng:-4.7769,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Taberna Salinas, Calle Tundidores 3, Córdoba",kingTip:"Peça as naranjas picadas com bacalhau e azeite, a tapa doce-salgada típica cordovesa que virou assinatura da casa.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"12:30",closeHour:"23:00",note:"Fecha à tarde entre serviços (16h–20h) e aos domingos."},links:[{label:"Site oficial",url:"http://www.tabernasalinas.com"}]},{id:"cor_casa_pepe_juderia",categoryId:"tapas",city:"cordoba",name:"Casa Pepe de la Judería",tagline:"Terraço com vista da Mesquita na Judería",description:"Taberna histórica no labirinto da Judería, a poucos passos da Mesquita-Catedral, sob a chancela municipal de Taberna Histórica. Pátios frescos, salões e um terraço panorâmico com vista para os minaretes tornam a refeição memorável. Cozinha cordovesa clássica servida com esmero.",lat:37.87975,lng:-4.7813,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Casa Pepe de la Judería, Calle Romero 1, Córdoba",kingTip:"Suba ao terraço ao entardecer e peça o salmorejo cordovês e o rabo de toro, os dois pratos-símbolo da casa.",priceLevel:"€€€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"23:30",note:"Terraço com vista muito disputado; reserve para garantir mesa lá em cima."}},{id:"cor_taberna_san_miguel",categoryId:"tapas",city:"cordoba",name:'Taberna San Miguel "El Pisto"',tagline:"Montilla-Moriles numa taberna centenária",description:"Taberna clássica na recolhida Plaza de San Miguel, com azulejos, cartazes de touros e barris de fino Montilla-Moriles ao fundo. Tocada pela mesma família desde 1974, mantém viva a alma da taberna cordovesa de sempre. Ambiente caloroso e preços amáveis, longe das rotas mais turísticas.",lat:37.88755,lng:-4.77895,durationLabel:"45 min–1,5 h",fit:"ANY",mapQuery:"Taberna San Miguel El Pisto, Plaza San Miguel 1, Córdoba",kingTip:"Peça o pisto cordovês que dá apelido à casa, acompanhado de um fino Montilla-Moriles do barril.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"12:00",closeHour:"16:00",note:"Reabre à noite (20h–24h); fecha aos domingos e em agosto costuma reduzir horário."},links:[{label:"Site oficial",url:"https://tabernacordoba.es"}]},{id:"cor_bodegas_campos",categoryId:"tapas",city:"cordoba",name:"Bodegas Campos",tagline:"Pátios cordoveses e bodega histórica",description:"Conjunto de casas e pátios andaluzes entre a Igreja de San Pedro e a Plaza del Potro, com uma bodega de tonéis assinados por personalidades. Reúne uma taberna de balcão para petiscar e um restaurante mais tranquilo, ambos de cozinha cordovesa refinada. Uma das mesas de mais solera da cidade.",lat:37.88248,lng:-4.7733,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Bodegas Campos, Calle Lineros 32, Córdoba",kingTip:"Fique na zona de taberna e peça um fino da casa com o salmorejo, a dupla que resume Córdoba no copo e no prato.",priceLevel:"€€€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"23:30",note:"Estacionamento privativo para clientes; domingos costuma servir só ao almoço."},links:[{label:"Site oficial",url:"https://bodegascampos.com"}]},{id:"grn_om_kalsum",categoryId:"tapas",city:"granada",name:"Om Kalsum",tagline:"Tapas árabes e vegetarianas em Granada",description:"Bar diferente na Calle Jardines, no centro de Granada, que troca a fritura andaluza por tapas marroquinas e do Oriente Médio. Fiel ao costume local, cada bebida vem com uma tapa gratuita, aqui em versão de cuscuz, tajine e legumes especiados. Barato, saboroso e um dos favoritos vegetarianos da cidade.",lat:37.1768,lng:-3.6005,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Om Kalsum, Calle Jardines 17, Granada",kingTip:"A tapa vem grátis com a bebida; segure a mão nas primeiras rodadas para receber o cuscuz de legumes e as berinjelas com mel.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"00:00",note:"Fecha à tarde entre serviços; espaço pequeno e muito procurado à noite."}},{id:"grn_bodega_la_mancha",categoryId:"tapas",city:"granada",name:"Bodega La Mancha",tagline:"Vermute de torneira e embutidos desde 1956",description:"Bodega emblemática aberta em 1956, a passos da Plaza Isabel la Católica, com paredes forradas de garrafas e presuntos pendurados sobre o balcão. Vermute de torneira, montaditos e tábuas de embutidos mantêm viva a tapa gratuita de Granada. Estreita, ruidosa e deliciosamente autêntica.",lat:37.17492,lng:-3.59772,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bodega La Mancha, Calle Joaquín Costa 10, Granada",kingTip:"Peça o vermute de torneira com um montadito de presunto, o combo que os granadinos repetem à tarde.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Bar pequeno; a maioria bebe em pé no balcão ou na calçada."}},{id:"mrb_casa_curro",categoryId:"tapas",city:"marbella",name:"Taberna Casa Curro",tagline:"Ibéricos e gambas de Huelva no casco antigo",description:"Taberna acolhedora escondida no casco antigo de Marbella, aberta em 2008 na estreita Calle Pantaleón, perto da Plaza de los Naranjos. Foco em ibéricos, queijos artesanais e produto do mar, com bons vinhos andaluzes por taça. Cantinho autêntico em meio ao charme caiado da cidade velha.",lat:36.51022,lng:-4.88503,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Taberna Casa Curro, Calle Pantaleón 7, Marbella",kingTip:"Peça as gambas blancas de Huelva e o lomo en orza, as duas tapas que definem a casa.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:30",note:"Fecha à tarde entre serviços (16h–19h30); não aceita reserva, chegue cedo."},links:[{label:"Site oficial",url:"https://grupocasacurro.com"}]},{id:"mrb_bar_el_estrecho",categoryId:"tapas",city:"marbella",name:"Bar El Estrecho",tagline:"Bar de tapas de 1954 num beco do casco antigo",description:"Bar minúsculo e cultuado, aberto em 1954, escondido numa ruela estreita do casco antigo de Marbella. Familiar e sempre movimentado, brilha nas frituras de peixe, boquerones e numa ensaladilla russa de fama local. Autêntico e despretensioso, longe do glamour da marina.",lat:36.51068,lng:-4.88494,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bar El Estrecho, Calle San Lázaro 12, Marbella",kingTip:"Peça a ensaladilla russa, tida como uma das melhores da cidade, com uns boquerones en vinagre.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"12:30",closeHour:"00:00",note:"Espaço apertado; nos fins de semana lota rápido, chegue cedo."},links:[{label:"Site oficial",url:"https://www.barelestrecho.com"}]},{id:"axq_la_puntilla_nerja",categoryId:"tapas",city:"axarquia",name:"La Puntilla",tagline:"Pescado fresco e tapa grátis em Nerja",description:"Bar de tapas e casa de peixe no casco urbano de Nerja, pertinho da Playa Torrecilla. Mantém o costume da tapa gratuita a cada bebida e capricha no pescado fresco frito na hora, a preço justo. Ambiente local e franco, com um restaurante vizinho que homenageia o produto do mar.",lat:36.74522,lng:-3.87918,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"La Puntilla, Calle Bolivia 1, Nerja",kingTip:"A tapa vem grátis com a bebida; peça o pescaíto frito do dia, sempre fresco do balcão de peixe.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"23:30",note:"Muito procurado no verão; a barra de tapas costuma encher no fim da tarde."},links:[{label:"Site oficial",url:"https://www.lapuntillanerja.es"}]},{id:"ant_arte_de_cozina",categoryId:"tapas",city:"antequera",name:"Arte de Cozina",tagline:"Cozinha antequerana de raiz e receitas locais",description:"Casa de comidas num edifício do século XVII no centro histórico de Antequera, que reúne restaurante, bar de tapas e pequena hospedaria. Resgata receitas locais e hortaliças de sequeiro numa carta de mais de trinta tapas premiadas em feiras gastronômicas. Um mergulho fundo na despensa antequerana.",lat:37.01865,lng:-4.56178,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Arte de Cozina, Calle Calzada 25, Antequera",kingTip:"Peça a porra antequerana, gaspacho espesso local coroado com ovo cozido e presunto, o prato que a casa consagrou.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"23:00",note:"Fecha à tarde entre serviços; confirme o dia de descanso na baixa temporada."},links:[{label:"Site oficial",url:"https://www.artedecozina.com"}]},{id:"ant_arco_de_los_gigantes",categoryId:"antequera",city:"antequera",name:"Arco de los Gigantes",tagline:"Pórtico renascentista da Antequera romana",description:"Portal monumental erguido em 1585 para substituir uma entrada em cotovelo da muralha muçulmana, evocando os arcos de triunfo clássicos. Nos seus dois metros de espessura foram encravadas lápides e inscrições latinas da Antikaria romana e das cidades vizinhas, além de um brasão de Filipe II. Emoldura, ao fundo, a Colegiata e a Alcazaba.",lat:37.01522,lng:-4.55694,durationLabel:"15–20 min",fit:"CLEAR_SKY",mapQuery:"Arco de los Gigantes, Antequera",kingTip:"Atravesse o arco e vire-se: o vão de meio-ponto enquadra a torre da Colegiata numa das fotos mais clássicas de Antequera.",priceLevel:"Gratuito",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/arco-de-los-gigantes/"}]},{id:"ant_iglesia_del_carmen",categoryId:"antequera",city:"antequera",name:"Iglesia del Carmen",tagline:"Retábulos barrocos sob teto mudéjar",description:"Antiga igreja dos carmelitas descalços, construída entre os séculos XVI e XVII em estilo mudéjar, com magnífico artesoado de madeira. Guarda um dos conjuntos de retábulos barrocos mais importantes da província: o retábulo-mor, anterior a 1747, dispensa o dourado e exibe a cor natural da madeira, com colunas, nichos e mais de cinquenta imagens. Peça única da Andaluzia.",lat:37.01607,lng:-4.5535,durationLabel:"20–30 min",fit:"INDOOR",mapQuery:"Iglesia del Carmen, Antequera",kingTip:"Fica no ponto mais alto do casco: combine a visita com a subida à Alcazaba e ao Arco, todos a poucos passos.",priceLevel:"€2",hours:"Ter–Sex 11:00–13:30 e 16:30–17:45; Sáb–Dom 11:00–14:00",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/iglesia-del-carmen/"}]},{id:"ant_termas_romanas_santa_maria",categoryId:"antequera",city:"antequera",name:"Termas Romanas de Santa María",tagline:"Os banhos da Antikaria sob a Colegiata",description:"Termas romanas descobertas por acaso em 1988 aos pés da Real Colegiata de Santa María, a primeira prova conclusiva da cidade de Antikaria sob o casco atual. Estiveram em uso da segunda metade do século I até o século V, e conservam a sequência clássica de salas frias, mornas e quentes — frigidarium, tepidarium e caldarium. Painéis recriam em 3D o estado original.",lat:37.0185,lng:-4.5581,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"Termas Romanas de Santa María, Antequera",kingTip:"Estão coladas à Colegiata e ao Arco dos Gigantes: encadeie os três num único passeio pela parte alta.",priceLevel:"Gratuito",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/termas-romanas/"}]},{id:"ant_mirador_almenillas",categoryId:"antequera",city:"antequera",name:"Mirador de las Almenillas",tagline:"As torres de Antequera num só olhar",description:"Balcão panorâmico junto ao Arco de los Gigantes e às muralhas da Alcazaba. De costas para a fortaleza, abre-se uma das vistas mais emblemáticas da vila, com o rosário de igrejas, torres, campanários e palácios erguidos ao longo de quatro séculos. Em dias limpos, a Peña de los Enamorados recorta-se no horizonte.",lat:37.0153,lng:-4.5575,durationLabel:"10–15 min",fit:"CLEAR_SKY",mapQuery:"Mirador de las Almenillas, Antequera",kingTip:"Venha ao entardecer: a luz rasante acende os campanários de tijolo e dá o melhor recorte da Peña de los Enamorados ao fundo.",priceLevel:"Gratuito",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/mirador-almenillas/"}]},{id:"ant_plaza_de_san_sebastian",categoryId:"antequera",city:"antequera",name:"Plaza de San Sebastián",tagline:"Fonte renascentista no coração da vila",description:"Um dos conjuntos urbanos mais belos de Antequera, com origem em 1508. No centro está a fonte renascentista lavrada por Baltasar de Godros em 1545, coroada por um anjo. Preside a praça a Real Colegiata de San Sebastián, com fachada plateresca de 1548 e um esbelto campanário barroco de tijolo rematado por veleta, ponto de encontro da cidade.",lat:37.01646,lng:-4.56144,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"Plaza de San Sebastián, Antequera",kingTip:"É o marco-zero para caminhar a rua Infante Don Fernando: comece aqui e deixe a praça se abrir das mesas dos cafés ao campanário.",priceLevel:"Gratuito",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/plaza-de-san-sebastian/"}]},{id:"ant_iglesia_de_los_remedios",categoryId:"antequera",city:"antequera",name:"Iglesia de Nuestra Señora de los Remedios",tagline:"A padroeira sob colunas salomônicas",description:"Antigo convento franciscano na rua Infante Don Fernando, iniciado em 1628 e declarado Monumento Histórico-Artístico Nacional. Abriga a Virgen de los Remedios, padroeira de Antequera desde 1546. O altar-mor é dominado por um enorme retábulo barroco de colunas salomônicas douradas, um dos mais teatrais da cidade.",lat:37.0196,lng:-4.56282,durationLabel:"20–30 min",fit:"INDOOR",mapQuery:"Iglesia de los Remedios, Antequera",kingTip:"Fica sobre a artéria principal da vila: entre para um respiro do calor e admire o dourado do retábulo antes de seguir a pé.",priceLevel:"Gratuito",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/iglesia-de-nuestra-senora-de-los-remedios/"}]},{id:"ant_dolmen_del_romeral",categoryId:"antequera",city:"antequera",name:"Dolmen del Romeral (Tholos de El Romeral)",tagline:"O tholos megalítico da Idade do Bronze",description:"O terceiro grande megálito de Antequera, a cerca de 2,5 km do centro e distinto de Menga e Viera. Construído por volta de 1800 a.C., é um sepulcro de falsa cúpula do tipo tholos: um longo corredor de lajes conduz a uma câmara funerária circular coberta por aproximação de fiadas. Integra, com os outros dolmens, o conjunto Patrimônio Mundial da UNESCO desde 2016.",lat:37.03444,lng:-4.53556,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Tholos de El Romeral, Antequera",kingTip:"Fica fora do centro de visitantes principal e exige carro: some 15 min ao trajeto de Menga e feche a trilogia megalítica no mesmo dia.",priceLevel:"Gratuito",hours:"Ter–Sáb (horário varia por estação); dom e feriados 09:00–15:00; seg fechado",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/tholos-de-el-romeral/"}]},{id:"ant_plaza_ochavada_archidona",categoryId:"antequera",city:"antequera",name:"Plaza Ochavada (Archidona)",tagline:"A praça octogonal do barroco andaluz",description:"Joia do urbanismo barroco andaluz na vizinha Archidona, construída entre 1780 e 1789 sobre uma zona insalubre. De planta octogonal, cada uma das oito fachadas recebeu decoração distinta em alvenaria de tijolo e cal, obra dos alarifes González Sevillano e Astorga Frías. Foi centro administrativo e palco de touradas, e é hoje um dos cartões-postais da província.",lat:37.09456,lng:-4.39053,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"Plaza Ochavada, Archidona",kingTip:"Archidona fica a ~20 min de carro de Antequera: combine a praça com a subida ao castelo e à ermita da Virgen de Gracia.",priceLevel:"Gratuito",links:[{label:"La Provincia — Diputación de Málaga",url:"https://www.malaga.es/en/laprovincia/patrimonio/lis_cd-5079/plaza-ochavada-octagonal-square"}]},{id:"ant_ermita_virgen_de_gracia_archidona",categoryId:"antequera",city:"antequera",name:"Castillo y Ermita de la Virgen de Gracia (Archidona)",tagline:"Mesquita mourisca no alto do castelo",description:"No ponto mais alto de Archidona, dentro do antigo castelo árabe, ergue-se uma das duas únicas mesquitas conservadas na província, de origem almóada, consagrada como igreja no século XV. Guarda arcos em ferradura, um antigo minarete convertido em campanário e cúpula setecentista. Do recinto — com torre de menagem, cisterna e a Puerta del Sol — abre-se o mirante mais espetacular sobre a vila.",lat:37.1001,lng:-4.3861,durationLabel:"45–60 min",fit:"ANY",mapQuery:"Ermita de la Virgen de Gracia, Archidona",kingTip:"A subida à sierra se faz de carro ou a pé; guarde a chegada ao mirante para o fim da tarde, quando a planície de Archidona ganha luz dourada.",priceLevel:"Gratuito",links:[{label:"Andalucía.org",url:"https://www.andalucia.org/es/archidona-turismo-cultural-mezquita-ermita-de-la-virgen-de-gracia"}]},{id:"nrj_torre_de_maro",categoryId:"axarquia",city:"axarquia",name:"Torre Vigía de Maro",tagline:"Atalaia do século XVI sobre a falésia",description:"Torre de vigia costeira do século XVI, também chamada Torre de Calaturcos, plantada num rochedo à beira do penhasco a leste de Maro. Fazia parte da rede de atalaias que avistava os corsários berberes e acendia fogueiras de alarme ao longo da costa. Hoje é um miradouro solitário sobre o mar aberto e o Parque Natural de Maro-Cerro Gordo.",lat:36.7537,lng:-3.8299,durationLabel:"30–45 min (com caminhada)",fit:"CLEAR_SKY",mapQuery:"Torre de Maro, Nerja",kingTip:"Chega-se por uma trilha de terra de cerca de 600 m a partir da N-340; leve água e vá calçado, o final é exposto ao sol.",priceLevel:"Gratuito"},{id:"axq_competa_pueblo",categoryId:"axarquia",city:"axarquia",name:"Cómpeta",tagline:"A vila branca do vinho da Almijara",description:"Povoado branco pendurado nas encostas da Serra de Almijara, capital histórica do vinho doce da Axarquía. As ruas íngremes convergem para a Plaza Almijara, dominada pela torre da igreja de la Asunción, entre adegas artesanais e varandas floridas. Ao redor, socalcos de uva moscatel descem até o vale com o mar ao fundo.",lat:36.833,lng:-3.9749,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Plaza Almijara, Cómpeta",kingTip:"Prove o vino de Cómpeta direto numa adega da praça; a noche del Vino, em meados de agosto, enche as ruas de dança e degustação gratuita.",priceLevel:"Gratuito (a vila)"},{id:"axq_torrox_pueblo",categoryId:"axarquia",city:"axarquia",name:"Torrox Pueblo",tagline:"Labirinto mouro sobre o vale do rio",description:"O núcleo histórico de Torrox, terra adentro, conserva a trama de becos brancos de origem andalusí que rende o slogan local do melhor clima da Europa. A Plaza de la Constitución, com a estátua de Almanzor, é o coração da vila, cercada de casas caiadas e da igreja de Nuestra Señora de la Encarnación. Distinto e mais autêntico que a movimentada Torrox Costa.",lat:36.758,lng:-3.952,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Plaza de la Constitución, Torrox",kingTip:"Domingo de manhã a vila enche de vida no mercado; estacione na entrada e desça a pé, os becos não comportam carro.",priceLevel:"Gratuito"},{id:"axq_velez_fortaleza",categoryId:"axarquia",city:"axarquia",name:"La Fortaleza de Vélez-Málaga",tagline:"Alcáçova nasrida sobre a capital da Axarquía",description:"Fortaleza de origem no século X, ampliada pelos nasridas, que coroa o morro sobre o casco antigo de Vélez-Málaga, a maior cidade da comarca. Da Torre del Homenaje reconstruída, de 16 metros, abre-se um panorama de 360º sobre o bairro branco da Villa, o vale e a linha do mar. Foi uma das praças-fortes mais importantes do reino de Granada até a conquista de 1487.",lat:36.7822,lng:-4.0983,durationLabel:"45 min – 1 h",fit:"CLEAR_SKY",mapQuery:"La Fortaleza, Vélez-Málaga",kingTip:"Suba a pé pelo bairro histórico da Villa até a fortaleza; a subida pelas ruas caiadas já é metade do passeio e rende as melhores vistas ao entardecer.",priceLevel:"Gratuito"},{id:"axq_archez_alminar",categoryId:"axarquia",city:"axarquia",name:"Alminar Mudéjar de Árchez",tagline:"Minarete almóada de tijolo do século XIV",description:"Numa das menores vilas da Axarquía, ergue-se um dos melhores minaretes almóadas conservados na Espanha, hoje campanário da igreja de Nuestra Señora de la Encarnación. A torre de tijolo vermelho, de 15 metros, exibe painéis geométricos em losango que contrastam com o branco das casas ao redor. É a joia da Ruta del Mudéjar da comarca.",lat:36.8323,lng:-3.966,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Alminar Mudéjar, Árchez",kingTip:"Combine com Salares e Sedella no mesmo dia: as três vilas mudéjares ficam a poucos quilômetros pela mesma estrada de vale.",priceLevel:"Gratuito (exterior)"},{id:"axq_salares_alminar",categoryId:"axarquia",city:"axarquia",name:"Salares e seu Alminar",tagline:"Vila mudéjar sem carros ao pé da serra",description:"Salares é um dos povoados mais bem preservados da rota mudéjar, de becos estreitos onde os carros nem entram. Seu minarete almóada dos séculos XIII–XIV, de tijolo com decoração em sebka, é hoje a torre da igreja de Santa Ana e um Monumento Histórico Nacional. Ao redor, hortas, uma ponte medieval e o silêncio da Sierra de Almijara.",lat:36.8548,lng:-4.0158,durationLabel:"45 min – 1 h",fit:"ANY",mapQuery:"Alminar de Salares, Salares",kingTip:"Deixe o carro no estacionamento da entrada e caminhe: o casco é intransponível de carro e a graça está em se perder pelos becos.",priceLevel:"Gratuito"},{id:"axq_sayalonga_cementerio_redondo",categoryId:"axarquia",city:"axarquia",name:"Cemitério Redondo de Sayalonga",tagline:"O único camposanto octogonal da Espanha",description:"Curiosidade da vila de Sayalonga, este cemitério da primeira metade do século XIX tem planta octogonal, caso único na Espanha, e por isso ficou conhecido como o cemitério redondo. Nichos abobadados dispostos em anel guardam figuras e símbolos que renderam mil lendas locais. Fica na saída norte da vila, na estrada para Cómpeta, com vista sobre o vale.",lat:36.8395,lng:-3.9948,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Cementerio Redondo, Sayalonga",kingTip:"Passe antes pela Plaza de la Rosa, no casco, e prove os nísperos de Sayalonga, fruta símbolo da vila na primavera.",priceLevel:"Gratuito"},{id:"axq_sedella_pueblo",categoryId:"axarquia",city:"axarquia",name:"Sedella",tagline:"Vila branca aos pés da Tejeda",description:"Povoado branco encravado nas encostas da Sierra de Tejeda, de origem mourisca e traçado íngreme de becos e arcos. Destacam-se a Casa Torreón, com sua fachada mudéjar renascentista, e a igreja de San Andrés. É um dos pontos de partida para a subida ao pico La Maroma, o mais alto da província, e mira ampla sobre o vale.",lat:36.868,lng:-4.029,durationLabel:"45 min – 1 h",fit:"ANY",mapQuery:"Sedella, Málaga",kingTip:"Combine com a Fábrica de la Luz, área de piquenique com nascentes a poucos quilômetros acima da vila, ideal no calor do verão.",priceLevel:"Gratuito"},{id:"mlg_cementerio_ingles",categoryId:"malaga",city:"malaga",name:"Cementerio Inglés (English Cemetery)",tagline:"O jardim romântico dos que aqui morreram",description:"O primeiro cemitério protestante da Espanha, aberto em 1831 numa encosta ajardinada sobre o mar, na Avenida de Pries. Antes disso, os não católicos eram enterrados na areia da praia à noite; aqui ganharam um jardim de ciprestes, buganvílias e lápides cobertas de conchas. É um recanto silencioso e cheio de histórias, com túmulos de poetas, cônsules e marinheiros náufragos.",lat:36.7212,lng:-4.4071,durationLabel:"45min",fit:"ANY",mapQuery:"Cementerio Inglés de Málaga, Spain",whatToDo:["Ver o túmulo do poeta Jorge Guillén e as sepulturas em concha","Passear pela alameda de ciprestes até a pequena capela de St. George","Ler as histórias de cônsules, viajantes e vítimas de naufrágios"],kingTip:"Fica a dez minutos a pé da Malagueta, subindo a Avenida de Pries; combine com a praça de touros e o Paseo. É sombreado e fresco, bom refúgio do sol do meio-dia, e o donativo de entrada ajuda na conservação.",priceLevel:"~€4 (donativo, est.)",links:[{label:"Fundación Cementerio Inglés",url:"https://cementerioinglesmalaga.org/"}],history:"Fundado em 1831 pelo cônsul britânico William Mark, pôs fim ao costume macabro de enterrar protestantes de pé na areia da praia, à mercê da maré e dos cães.",image:"mlg_cementerio_ingles.jpg"},{id:"mlg_plaza_constitucion_chinitas",categoryId:"malaga",city:"malaga",name:"Plaza de la Constitución e Pasaje de Chinitas",tagline:"O coração histórico e seu beco lendário",description:"A praça maior de Málaga desde a Reconquista, presidida pela Fuente de Génova de mármore do século XVI, é o ponto onde desemboca a Calle Larios. Dali parte o Pasaje de Chinitas, uma travessa cruciforme de casas caiadas que abrigava o célebre café-cantante imortalizado por García Lorca. Juntos condensam a alma do centro antigo.",lat:36.7197,lng:-4.4206,durationLabel:"30min",fit:"ANY",mapQuery:"Plaza de la Constitución, Málaga, Spain",whatToDo:["Ver a Fuente de Génova, no centro da praça pedonal","Entrar pelo arco do Pasaje de Chinitas e sentir o beco flamenco","Usar a praça como marco zero para explorar o centro histórico"],kingTip:"Entre no Pasaje de Chinitas pela porta ao lado do número 13 da praça: é curto mas guarda o espírito do velho café-cantante que Lorca celebrou. À noite a praça ganha esplanadas e músicos de rua.",priceLevel:"Grátis (praça)",history:"Chamada Plaza Mayor e depois Plaza de las Cuatro Calles, recebeu o nome atual em 1812, com a primeira constituição espanhola; o pasaje deve o nome ao ator Chinitas, que trabalhou num café ali dentro."},{id:"mlg_iglesia_santiago",categoryId:"malaga",city:"malaga",name:"Iglesia de Santiago Apóstol",tagline:"A igreja mais antiga, onde Picasso foi batizado",description:"Fundada em 1490, logo após a Reconquista, é a paróquia mais antiga de Málaga, erguida sobre uma antiga mesquita. Destaca-se a esbelta torre mudéjar de tijolo e azulejos, um dos raros vestígios daquele estilo na cidade, e o interior barroco. Foi aqui que, em 10 de novembro de 1881, batizaram Pablo Ruiz Picasso.",lat:36.7223,lng:-4.4175,durationLabel:"20-30min",fit:"INDOOR",mapQuery:"Iglesia de Santiago Apóstol, Calle Granada, Málaga, Spain",whatToDo:["Admirar a torre mudéjar em tijolo, único vestígio do estilo no centro","Ver a pia batismal ligada a Picasso e o interior barroco","Combinar com um passeio pela senhorial Calle Granada"],kingTip:"Fica na Calle Granada, no caminho entre a Catedral e a Plaza de la Merced, onde nasceu Picasso; encaixe na rota picassiana. Respeite os horários de missa, quando a visita turística é desencorajada.",priceLevel:"Grátis",links:[{label:"Visita Málaga (oficial)",url:"https://visita.malaga.eu/en/what-to-see-and-do/culture/historic-monuments/monuments/santiago-church-p103578"}],history:"Ordenada pelos Reis Católicos em 1490 sobre uma mesquita, fundiu naves góticas com a torre mudéjar; nela se casaram os avós e os pais de Picasso antes de o pintor ser ali batizado."},{id:"mlg_basilica_victoria",categoryId:"malaga",city:"malaga",name:"Basílica de Santa María de la Victoria",tagline:"O santuário barroco da padroeira",description:"Santuário barroco erguido no lugar onde os Reis Católicos acamparam durante o cerco de 1487, abriga a imagem de Santa María de la Victoria, padroeira de Málaga. O interior surpreende pelo camarín dourado e, sobretudo, pela cripta funerária dos condes de Buenavista, um teatro macabro de estuques negros com esqueletos e caveiras. Fica um pouco fora do circuito, o que preserva o silêncio.",lat:36.7293,lng:-4.4129,durationLabel:"30-45min",fit:"INDOOR",mapQuery:"Basílica de Santa María de la Victoria, Málaga, Spain",whatToDo:["Ver o camarín barroco dourado atrás do altar-mor","Descer à cripta dos condes de Buenavista, com decoração de caveiras","Apreciar a torre-mausoléu, incomum entre as igrejas espanholas"],kingTip:"Vale a caminhada de dez minutos subindo do centro; a cripta negra com esqueletos é uma das visitas mais insólitas e pouco concorridas de Málaga. Confira o horário, pois fecha ao meio-dia para a sesta.",priceLevel:"Grátis (basílica) | ~€4 (est.) camarín, cripta e museu",hours:{openDays:[1,2,3,4,5,6,7],openHour:9,closeHour:20,note:"Fecha no meio do dia (aprox. 13h-18h30). Confirme horários de missa."},links:[{label:"Museos de Málaga",url:"https://www.museosdemalaga.com/museos/basilica-santa-maria-de-la-victoria/"}],history:"Erguido a partir de 1487 no acampamento real do cerco a Málaga e reconstruído no século XVII pelos condes de Buenavista, que acrescentaram o camarín e a cripta funerária da família.",image:"mlg_basilica_victoria.jpg"},{id:"mlg_paseo_del_parque",categoryId:"malaga",city:"malaga",name:"Paseo del Parque",tagline:"A selva subtropical no meio da cidade",description:"Alameda ajardinada criada no início do século XX sobre terrenos ganhos ao mar, é considerada um dos jardins botânicos urbanos mais ricos da Europa. Ao longo de quase um quilômetro, entre a Alcazaba e o porto, crescem ficus centenários, palmeiras, jacarandás e plantas tropicais, entremeados de fontes e esculturas. Uma travessia sombreada e perfumada que liga o centro ao mar.",lat:36.7188,lng:-4.4168,durationLabel:"45min-1h",fit:"ANY",mapQuery:"Paseo del Parque, Málaga, Spain",whatToDo:["Caminhar sob os ficus gigantes entre a Alcazaba e a Praça da Marinha","Achar as fontes e as pequenas esculturas escondidas na vegetação","Ler as placas botânicas das espécies tropicais raras"],kingTip:"É o corredor sombreado ideal para atravessar a cidade a pé no calor de julho, ligando o centro à Malagueta e ao porto sem pegar sol. Aos domingos costuma haver bandas tocando no coreto.",priceLevel:"Grátis (passeio)",history:"Projetado no fim do século XIX sobre aterros do porto e plantado com espécies trazidas de todo o mundo tropical, tornou-se um jardim de aclimatação que hoje soma centenas de espécies."},{id:"mlg_jardines_pedro_luis_alonso",categoryId:"malaga",city:"malaga",name:"Jardines de Pedro Luis Alonso",tagline:"O roseiral de estilo latino ao lado do Ayuntamiento",description:"Pequeno jardim formal de 1945, encaixado entre o Ayuntamiento e o sopé do monte Gibralfaro, com traçado geométrico de influência hispano-árabe e francesa. Reúne uma das maiores coleções de roseiras da Espanha, com mais de setenta variedades, além de laranjeiras e ciprestes recortados. É o remate ajardinado do Paseo del Parque, com a fachada do Ayuntamiento como pano de fundo.",lat:36.7185,lng:-4.4177,durationLabel:"20-30min",fit:"CLEAR_SKY",mapQuery:"Jardines de Pedro Luis Alonso, Málaga, Spain",whatToDo:["Passear entre as roseiras e os canteiros geométricos de buxo","Fotografar a fachada barroca do Ayuntamiento de Málaga ao fundo","Espiar os Jardines de Puerta Oscura, na encosta ao lado"],kingTip:"As roseiras estão no auge na primavera, mas em julho o jardim ainda perfuma no fim da tarde, quando a luz dourada bate na fachada do Ayuntamiento. Fica colado ao Paseo del Parque, junte os dois.",priceLevel:"Grátis",history:"Desenhado em 1945 pelo arquiteto Fernando Guerrero-Strachan Rosado e batizado em homenagem ao primeiro prefeito de Málaga do pós-guerra, em estilo de jardim latino."},{id:"mlg_plaza_toros_malagueta",categoryId:"malaga",city:"malaga",name:"Plaza de Toros de La Malagueta",tagline:"O hexágono de tijolo à beira-mar",description:"Inaugurada em 1876, a praça de touros de Málaga é um imponente edifício neomudéjar de planta hexagonal em tijolo vermelho, junto ao mar e ao pé de Gibralfaro. Mesmo sem interesse pela tauromaquia, vale contemplar o volume geométrico do exterior e vê-lo de cima, do castelo, onde a arena vira uma moldura perfeita. É um dos cartões-postais arquitetônicos da cidade.",lat:36.7203,lng:-4.4108,durationLabel:"20-30min",fit:"CLEAR_SKY",mapQuery:"Plaza de Toros de La Malagueta, Málaga, Spain",whatToDo:["Dar a volta ao exterior hexagonal de tijolo neomudéjar","Ver a arena de cima, do Mirador de Gibralfaro, como um alvo perfeito","Combinar com o passeio pela orla e pela praça de touros a caminho da praia"],kingTip:"A imagem mais icônica não é lá de baixo, mas do alto de Gibralfaro, de onde a arena aparece redonda e completa; guarde para quando subir ao castelo. Há um museu taurino na porta 10 para quem quiser entrar.",priceLevel:"Grátis (exterior)",links:[{label:"La Malagueta (oficial)",url:"https://www.la-malagueta.es/"}],history:"Projetada por Joaquín Rucoba e inaugurada em 1876, é obra-prima do estilo neomudéjar; sua forma hexagonal e a posição à beira-mar tornaram-na símbolo do bairro que leva o mesmo nome."},{id:"mlg_teatro_cervantes",categoryId:"malaga",city:"malaga",name:"Teatro Cervantes",tagline:"O teatro oitocentista de teto pintado",description:"Inaugurado em 1870, é o principal teatro histórico de Málaga, num edifício elegante escondido numa ruela ao norte da Plaza de la Merced. O grande tesouro é o teto da plateia, com a alegoria 'A indústria, o comércio e as artes em Málaga', pintada por Bernardo Ferrándiz. Palco de ópera, dança e do festival de cinema da cidade, é uma joia para ver por dentro em dia de espetáculo ou visita guiada.",lat:36.7247,lng:-4.4186,durationLabel:"20-30min",fit:"ANY",mapQuery:"Teatro Cervantes, Málaga, Spain",whatToDo:["Ver a fachada e a ruela recolhida atrás da Plaza de la Merced","Se houver espetáculo, admirar o teto pintado por Ferrándiz","Conferir a programação de ópera, dança e do Festival de Málaga"],kingTip:"O interior só se vê em dia de função ou em visita guiada pontual; consulte a programação antes de ir. Fica a poucos passos da Plaza de la Merced, então encaixe na rota de Picasso e Lagunillas.",priceLevel:"Varia por espetáculo | fachada grátis",links:[{label:"Teatro Cervantes (oficial)",url:"https://www.teatrocervantes.com/"}],history:"Aberto em 1870 sobre um antigo pátio de comédias, salvou-se da demolição no século XX e foi restaurado pela prefeitura em 1987, recuperando o teto alegórico de Bernardo Ferrándiz."},{id:"mlg_mirador_gibralfaro",categoryId:"malaga",city:"malaga",name:"Mirador de Gibralfaro",tagline:"A vista de cartão-postal da cidade inteira",description:"Terraço panorâmico a meio caminho da subida ao castelo, no Camino de Gibralfaro, a cerca de 130 metros de altura. Daqui se abre a vista mais fotografada de Málaga: a praça de touros da Malagueta como um anel perfeito, o porto, a Catedral e a mancha branca da cidade descendo até o mar. Acesso livre, sem precisar entrar no castelo.",lat:36.7219,lng:-4.4128,durationLabel:"20min",fit:"CLEAR_SKY",mapQuery:"Mirador de Gibralfaro, Málaga, Spain",whatToDo:["Fotografar a praça de touros hexagonal vista de cima, como um alvo","Abarcar num só olhar porto, Catedral e a baía até a Malagueta","Aproveitar como parada na subida ou descida a pé do castelo"],kingTip:"Não precisa pagar entrada do castelo para chegar ao mirante, ele fica no caminho, um pouco antes. Venha ao fim da tarde para a luz dourada e evite o miolo do dia, quando a subida a pé não tem sombra.",priceLevel:"Grátis",history:"O mirante ocupa uma curva do antigo caminho militar que ligava a cidade ao castelo de Gibralfaro, hoje transformado em passeio panorâmico entre pinheiros."},{id:"mlg_perchel_trinidad",categoryId:"malaga",city:"malaga",name:"Barrios del Perchel e La Trinidad",tagline:"A Málaga popular do outro lado do rio",description:"Do outro lado do leito seco do rio Guadalmedina ficam El Perchel e La Trinidad, dois dos bairros mais antigos e castiços de Málaga. De ruas estreitas e casas de pátio, os chamados corralones, guardam a alma operária e flamenca da cidade, longe do roteiro turístico. É onde a Semana Santa e o cante jondo ainda pulsam com autenticidade.",lat:36.7188,lng:-4.4268,durationLabel:"45min",fit:"ANY",mapQuery:"Barrio del Perchel, Málaga, Spain",whatToDo:["Espiar os corralones, os pátios de vizinhança tradicionais","Cruzar o rio Guadalmedina pela Ponte da Aurora, rumo à outra Málaga","Sentir o ambiente flamenco e popular longe das multidões do centro"],kingTip:"É um passeio para quem já conhece o essencial e quer a cidade dos malaguenhos; alguns corralones só abrem na Fiesta de los Patios, na primavera. Prefira a manhã e ande com o bom senso de qualquer bairro popular.",priceLevel:"Grátis",history:"Nascidos como arrabaldes de pescadores e curtidores fora das muralhas, deram à cidade parte de sua tradição flamenca e o fervor da Semana Santa, apesar das demolições do século XX.",image:"mlg_perchel_trinidad.jpg"},{id:"mrb_mijas_pueblo",categoryId:"marbella",city:"marbella",name:"Mijas Pueblo",tagline:"A vila branca dos burro-táxis",description:"O pueblo blanco mais famoso da Costa del Sol ocidental, agarrado à serra a 428 m de altura, com ruas caiadas, vasos azuis e varandas floridas. Da praça central saem os históricos burro-táxis e abrem-se miradouros com o Mediterrâneo lá embaixo. É a fuga clássica de meia diária a partir da costa.",lat:36.5958,lng:-4.6376,durationLabel:"2–3 h",fit:"CLEAR_SKY",mapQuery:"Mijas Pueblo, Málaga",whatToDo:"Perca-se pelas vielas caiadas, encoste nos miradouros da muralha e prove um doce nas confeitarias da praça.",kingTip:"Estacione no parque subterrâneo da Avenida del Compás e suba a pé: as ruas do casco são estreitas e é ali que começa o encanto.",priceLevel:"Gratuito (passeio)"},{id:"mrb_plaza_toros_mijas",categoryId:"marbella",city:"marbella",name:"Plaza de Toros de Mijas",tagline:"A rara arena oval de 1900",description:"Uma das praças de touros mais singulares da Espanha: em vez do círculo habitual, tem planta oval, encaixada nos Jardines de la Muralla ao lado da Igreja da Imaculada Conceição. Hoje abriga um pequeno museu taurino e serve, sobretudo, de terraço-mirante sobre a costa. Vale a subida pela vista e pela raridade arquitetônica.",lat:36.5966,lng:-4.6362,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Plaza de Toros de Mijas",kingTip:"Suba ao anel superior da arena: dali se abre o melhor panorama de Mijas sobre o mar, melhor até que os miradouros da praça.",priceLevel:"≈ €3",hours:{note:"Sáb, dom e feriados ~10:30–18:30; verão (jul–ago) até mais tarde"},links:[{label:"Turismo de Mijas – Plaza de Toros",url:"https://turismo.mijas.es/es/cultura/monumentos/plaza-de-toros"}]},{id:"mrb_ermita_pena_mijas",categoryId:"marbella",city:"marbella",name:"Ermita de la Virgen de la Peña",tagline:"A capela escavada na rocha",description:"Santuário do século XVII cavado à mão na rocha por um frade, guardião da padroeira de Mijas. O interior minúsculo e úmido contrasta com o jardim panorâmico à frente, debruçado sobre a costa. É uma parada de poucos minutos, sombreada e tranquila, no caminho para os miradouros da vila.",lat:36.5952,lng:-4.6382,durationLabel:"15–20 min",fit:"ANY",mapQuery:"Ermita de la Virgen de la Peña, Mijas",priceLevel:"Gratuito"},{id:"mrb_ojen",categoryId:"marbella",city:"marbella",name:"Ojén",tagline:"O pueblo branco logo acima de Marbella",description:"Vila serrana de ruas íngremes e casas caiadas a poucos minutos subindo de Marbella, aos pés de Sierra Blanca. Quase sem turismo de massa, mantém o ritmo andaluz autêntico, com a Igreja da Encarnação a dominar a praça e fontes de água da serra pelas esquinas. Boa porta de entrada para trilhas do parque natural.",lat:36.5658,lng:-4.8556,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Ojén, Málaga",kingTip:"Combine a visita com o Mirador de Ojén, na subida da estrada A-355, para a foto do casario branco encaixado na serra.",priceLevel:"Gratuito"},{id:"mrb_istan",categoryId:"marbella",city:"marbella",name:"Istán",tagline:"O manancial da Costa del Sol",description:'Conhecida como o "manancial da Costa del Sol", esta vila branca sobre o reservatório de La Concepción é atravessada por canais e fontes de água corrente, herança da engenharia andalusí. Ruas estreitas, cal imaculada e a Torre del Reloj no centro compõem um casco antigo mudéjar bem preservado. O silêncio e o verde da serra contrastam com o glamour da costa a 15 km.',lat:36.583,lng:-4.95,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Istán, Málaga",kingTip:"Siga a Ruta del Agua, um percurso curto e sombreado pelas nascentes e antigos moinhos que cruzam a vila.",priceLevel:"Gratuito"},{id:"mrb_benahavis",categoryId:"marbella",city:"marbella",name:"Benahavís",tagline:"A vila gastronômica da serra",description:'Encravada num desfiladeiro entre Marbella, Estepona e Ronda, Benahavís tem fama de ter a maior concentração de bons restaurantes da região, o que lhe rendeu o apelido de "comedor de la Costa del Sol". O casco antigo de ruelas floridas e paredes brancas convida a caminhar antes ou depois da mesa. Ao redor, o desfiladeiro do rio Guadalmina abre trilhas e poços naturais.',lat:36.519,lng:-5.0454,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",mapQuery:"Benahavís, Málaga",kingTip:"Reserve o almoço com antecedência: as mesas boas da vila lotam nos fins de semana, sobretudo as com vista para o desfiladeiro.",priceLevel:"Passeio gratuito; refeições €€–€€€"},{id:"mrb_basilica_vega_del_mar",categoryId:"marbella",city:"marbella",name:"Basílica Paleocristã de Vega del Mar",tagline:"Ruínas cristãs do século IV à beira-mar",description:"Sítio arqueológico de uma das mais antigas basílicas paleocristãs da Península, dos séculos IV–VI, junto à foz do rio Guadalmina em San Pedro de Alcántara. Restam as plantas dos muros e cerca de duzentas sepulturas visigóticas espalhadas por um bosque de eucaliptos, a poucos metros do mar. Visita rápida, à sombra e de raro valor histórico.",lat:36.472,lng:-4.9902,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Basílica Vega del Mar, San Pedro de Alcántara",kingTip:"O sítio abre poucos dias por semana: confirme antes, porque fora do horário só se vê o gradil por fora.",priceLevel:"Gratuito",hours:{note:"Geralmente sex, sáb, dom e feriados ~11:15–14:00; confirmar"},links:[{label:"Ayuntamiento de Marbella – Vega del Mar",url:"https://www.marbella.es/web/cultura/patrimonio/arqueologia/basilica-paleocristiana-de-vega-del-mar.html"}]},{id:"mrb_bulevar_san_pedro",categoryId:"marbella",city:"marbella",name:"Bulevar de San Pedro de Alcántara",tagline:"O parque suspenso sobre a autopista",description:"Um dos projetos urbanos mais ambiciosos da costa: a autopista A-7 foi enterrada num túnel e, por cima, criou-se um bulevar-parque de mais de um quilômetro com jardins, pérgulas, fontes e áreas de lazer. É o novo coração de San Pedro de Alcántara, ligando o casco antigo ao mar sem o barulho do tráfego. Ótimo para um passeio relaxado ao entardecer.",lat:36.487,lng:-4.9975,durationLabel:"40–60 min",fit:"CLEAR_SKY",mapQuery:"Bulevar de San Pedro Alcántara",priceLevel:"Gratuito"},{id:"mrb_estepona_casco_flores",categoryId:"marbella",city:"marbella",name:"Casco Antiguo de Estepona",tagline:"O jardim urbano da Plaza de las Flores",description:"Um dos cascos antigos mais floridos da Andaluzia: ruas caiadas onde cada esquina exibe vasos coloridos e trepadeiras, convergindo para a Plaza de las Flores, rodeada de laranjeiras e com uma fonte de 1845. O ambiente é limpo, vivo e pedonal, cheio de bares de tapas e pátios. Modelo de reabilitação urbana premiada, é feito para caminhar sem pressa.",lat:36.4266,lng:-5.1466,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",mapQuery:"Plaza de las Flores, Estepona",kingTip:"Vá ao fim da tarde: a luz suave nas paredes brancas e os vasos coloridos rendem as melhores fotos, e as tapas ficam mais animadas.",priceLevel:"Gratuito (passeio)"},{id:"mrb_estepona_murales",categoryId:"marbella",city:"marbella",name:"Ruta de los Murales de Estepona",tagline:"Um museu de arte a céu aberto",description:"Mais de 60 murais monumentais espalhados pelas fachadas de Estepona transformam a cidade numa galeria a céu aberto. As obras, muitas gigantescas, dialogam com temas de natureza, memória e vida local, e podem ser seguidas por um roteiro numerado que parte da Plaza de las Flores. Passeio gratuito, ao ar livre e a qualquer hora.",lat:36.427,lng:-5.146,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",mapQuery:"Ruta de los Murales, Estepona",kingTip:"Pegue o mapa do roteiro na oficina de turismo da Plaza de las Flores; os murais mais impressionantes ficam concentrados no casco antigo.",priceLevel:"Gratuito"},{id:"mrb_orquidario_estepona",categoryId:"marbella",city:"marbella",name:"Orquidario de Estepona",tagline:"A cúpula tropical de mil orquídeas",description:"Parque botânico coberto por três domos de vidro que abrigam mais de 1.500 espécies de orquídeas, palmeiras e uma cascata interna de 17 metros, o ponto mais alto acessível por uma torre panorâmica. É um refúgio tropical no coração do casco antigo, à prova de qualquer clima. Visita curta e sensorial, ótima para dias de calor ou chuva.",lat:36.4268,lng:-5.1493,durationLabel:"45–60 min",fit:"ANY",mapQuery:"Orquidario de Estepona",priceLevel:"≈ €5 (adulto)",hours:{note:"Ter–Sáb 10:00–13:30 e 15:00–18:00; dom/feriados 10:00–14:00; seg fechado"},links:[{label:"Turismo de Estepona – Orquidario",url:"https://turismo.estepona.es/lugares/parque-botanico-orquidario/"}]},{id:"mrb_milla_de_oro",categoryId:"marbella",city:"marbella",name:"Milla de Oro de Marbella",tagline:"A avenida do luxo entre a cidade e Banús",description:"O trecho mais cobiçado da Costa del Sol: cerca de 6 km entre Marbella e Puerto Banús onde se enfileiram hotéis históricos como o Marbella Club e o Puente Romano, mansões, palmeiras e boutiques de grife. Não é ponto turístico clássico, mas um retrato do glamour da região, ideal para percorrer de carro ou a pé pelo passeio arborizado. Endereço mais caro da Andaluzia.",lat:36.5015,lng:-4.925,durationLabel:"30–60 min",fit:"CLEAR_SKY",mapQuery:"Milla de Oro, Marbella",priceLevel:"Gratuito (passeio)"},{id:"mrb_nueva_andalucia",categoryId:"marbella",city:"marbella",name:"Nueva Andalucía",tagline:"O vale do golfe atrás de Puerto Banús",description:'O anfiteatro verde logo acima de Puerto Banús, apelidado de "Vale do Golfe" pela concentração de campos como Aloha e Las Brañas. Bairro residencial elegante e tranquilo, tem como âncora social o mercadillo de sábado, um dos maiores mercados de rua da costa. Combina bem com uma volta por Banús: aqui o ambiente é mais local e pé no chão.',lat:36.494,lng:-4.956,durationLabel:"1–2 h",fit:"CLEAR_SKY",mapQuery:"Nueva Andalucía, Marbella",kingTip:"Vá num sábado de manhã pelo mercadillo (feira): é o melhor momento para sentir a vida do bairro e caçar pechinchas.",priceLevel:"Gratuito"},{id:"rnd_santa_maria_la_mayor",categoryId:"ronda",city:"ronda",name:"Iglesia de Santa María la Mayor",tagline:"A igreja maior sobre a antiga mesquita",description:"Templo principal de Ronda, erguido a partir de 1485 sobre a mesquita aljama, na tranquila Plaza Duquesa de Parcent. Reúne gótico tardío nos pés e cabeceira maneirista reconstruída após o terremoto de 1580, além de um arco de ferradura mourisco preservado como testemunho do passado islâmico. Interior de três naves com coro entalhado e retábulos barrocos.",lat:36.7376,lng:-5.1654,durationLabel:"30–45 min",fit:"INDOOR",mapQuery:"Iglesia de Santa María la Mayor, Ronda",kingTip:"Procure, junto à entrada, o arco de ferradura remanescente do mihrab da antiga mesquita: um raro vestígio islâmico embutido no templo cristão.",priceLevel:"€ (ingresso ~€4,50, estimativa)",hours:"Aberta diariamente; conferir horário de missas e verão no local",history:"Consagrada logo após a conquista cristã de 1485, sua construção se estendeu por mais de dois séculos, misturando gótico, mudéjar e maneirismo após o sismo de 1580."},{id:"rnd_puerta_almocabar",categoryId:"ronda",city:"ronda",name:"Puerta de Almocábar & Murallas",tagline:"O portão nasrida no flanco sul da muralha",description:"Principal porta da Ronda islâmica, do século XIII, com três portas sucessivas flanqueadas por duas torres semicirculares — um dos sistemas defensivos medievais mais bem conservados da Andaluzia. Ao lado ergue-se o arco de Carlos V, aberto no século XVI. Daqui parte o trecho sul das muralhas, o mais íntegro da cidade.",lat:36.7365,lng:-5.165,durationLabel:"20–30 min",fit:"ANY",mapQuery:"Puerta de Almocábar, Ronda",kingTip:"Entre pela Almocábar como faziam os viajantes antigos e siga a pé até a Plaza del Campillo, de onde a muralha desce sobre o vale.",priceLevel:"Gratuito",history:"O nome vem do árabe 'al-maqabir' (cemitério), pela necrópole muçulmana vizinha; a porta foi reestruturada no reinado de Carlos I, no século XVI."},{id:"rnd_iglesia_espiritu_santo",categoryId:"ronda",city:"ronda",name:"Iglesia del Espíritu Santo",tagline:"A igreja-fortaleza junto à Almocábar",description:"Templo gótico-tardío mandado erguer pelos Reis Católicos após a tomada de Ronda em 1485, junto à Puerta de Almocábar. De volumes sóbrios e ar defensivo, quase de fortaleza, tem nave única coberta por abóbadas de cruzaria e um retábulo barroco. Um dos primeiros templos cristãos da cidade reconquistada.",lat:36.7369,lng:-5.1655,durationLabel:"15–25 min",fit:"INDOOR",mapQuery:"Iglesia del Espíritu Santo, Ronda",priceLevel:"€ (ingresso ~€2, estimativa)",history:"Fundada por ordem de Fernando e Isabel logo após 1485, teria sido concluída por volta de 1505 no local onde se rendeu a guarnição nasrida."},{id:"rnd_puente_viejo",categoryId:"ronda",city:"ronda",name:"Puente Viejo",tagline:"A ponte antiga sobre o Guadalevín",description:"Ponte de arco único que cruza o rio Guadalevín no ponto onde a garganta se abre, ligando a cidade velha ao bairro do Padre Jesús. Reconstruída no início do século XVII sobre traçado anterior, oferece uma perspectiva serena do Tajo e da Casa del Rey Moro no alto. Ponto ideal para ver a garganta de baixo, longe das multidões.",lat:36.7401,lng:-5.1628,durationLabel:"15–25 min",fit:"CLEAR_SKY",mapQuery:"Puente Viejo, Ronda",kingTip:"Combine com os Baños Árabes, a poucos metros: dá para descer ao leito do rio e fotografar a ponte e o paredão do Tajo de um ângulo que quase ninguém procura.",priceLevel:"Gratuito",history:"Erguida em 1616 sobre uma passagem medieval anterior, foi durante séculos o principal acesso à cidade velha antes da conclusão do Puente Nuevo."},{id:"rnd_casa_don_bosco",categoryId:"ronda",city:"ronda",name:"Casa Don Bosco",tagline:"O jardim-mirante debruçado no Tajo",description:"Casa senhorial modernista do início do século XX, hoje casa-museu, no coração do centro histórico. Seu maior encanto é o jardim de azulejos suspenso na borda do Tajo, com um terraço que abre para o vale do Guadalevín, a Serra de Grazalema e um perfil raro do Puente Nuevo. Um dos miradouros mais recolhidos e elegantes de Ronda.",lat:36.7397,lng:-5.1653,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"Casa Don Bosco, Ronda",kingTip:"Peça para ir direto ao terraço dos fundos: o banco de azulejos na beira do penhasco é o canto mais fotogênico e quase sempre vazio da casa.",priceLevel:"€ (ingresso ~€2, estimativa)",hours:"Aberta diariamente, horário reduzido; conferir no local",links:[{label:"Casa Museo Don Bosco",url:"https://casamuseodonbosco.com/"}],history:"Construída em 1850 e reformada em estilo modernista em 1900, foi doada à congregação salesiana, que mantém a casa e o jardim abertos à visita."},{id:"rnd_setenil_de_las_bodegas",categoryId:"ronda",city:"ronda",name:"Setenil de las Bodegas",tagline:"As casas encaixadas sob a rocha",description:"Um dos povoados brancos mais surpreendentes da Andaluzia, encravado no desfiladeiro do rio Trejo, onde a rocha forma o teto de ruas inteiras. As célebres Cuevas del Sol e Cuevas de la Sombra alinham casas caiadas sob um beiral de pedra maciça, com bares e terraços à sombra da falésia. A cerca de 20 km de Ronda.",lat:36.8625,lng:-5.1814,durationLabel:"1,5–2,5 h",fit:"ANY",mapQuery:"Cuevas del Sol, Setenil de las Bodegas",whatToDo:"Percorra a pé as ruas Cuevas del Sol e Cuevas de la Sombra sob a rocha e suba ao Mirador del Carmen e às ruínas do castelo para ver os telhados encaixados no barranco.",kingTip:"A rua Cuevas de la Sombra fica na penumbra o dia todo; para a foto com luz nas fachadas, vá à Cuevas del Sol no meio da manhã.",priceLevel:"Gratuito (o povoado)",history:"O nome 'Setenil' remete à resistência muçulmana a sete cercos cristãos; 'de las Bodegas' vem das antigas adegas escavadas na rocha, hoje bares e casas."},{id:"rnd_juzcar_pueblo_azul",categoryId:"ronda",city:"ronda",name:"Júzcar (o Pueblo Azul)",tagline:"O vilarejo pintado de azul dos Smurfs",description:"Antigo povoado branco do Valle del Genal que em 2011 foi inteiramente pintado de azul — casas, igreja e até o cemitério — como cenário do filme dos Smurfs. O que seria temporário virou definitivo por votação dos moradores, e hoje é uma vila lúdica e fotogênica na Serranía de Ronda, cercada de castanheiros. A cerca de 22 km de Ronda.",lat:36.6256,lng:-5.1709,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Júzcar, Málaga",whatToDo:"Passeie pelas vielas azuis procurando os murais de personagens espalhados pelas fachadas e admire o Valle del Genal a partir das bordas da vila.",kingTip:"Estenda o passeio pelo Valle del Genal: no outono, os castanheiros ao redor de Júzcar viram um mar cobre-avermelhado que contrasta com o azul das casas.",priceLevel:"Gratuito",history:"Em 2011 a Sony pintou a vila de azul com cerca de 4.000 litros de tinta para estrear o filme dos Smurfs; um referendo local decidiu manter a cor."},{id:"rnd_zahara_de_la_sierra",categoryId:"ronda",city:"ronda",name:"Zahara de la Sierra",tagline:"A vila-fortaleza sobre o esmeralda do reservatório",description:"Povoado branco pendurado na encosta da Sierra del Jaral, coroado por uma torre nasrida do século XIII e debruçado sobre as águas verdes do reservatório de Zahara-El Gastor. Antigo bastião do reino de Granada, é um dos cenários mais dramáticos da Ruta de los Pueblos Blancos. A menos de uma hora de Ronda.",lat:36.8398,lng:-5.3928,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",mapQuery:"Zahara de la Sierra, Cádiz",whatToDo:"Suba a pé até a Torre del Homenaje do castelo para a vista aérea da vila e do reservatório, e circule pelo casco branco em torno da igreja de Santa María de la Mesa.",kingTip:"A luz do fim da tarde acende o branco das casas contra o verde do lago; do castelo, a panorâmica sobre a água é a imagem definitiva do lugar.",priceLevel:"Gratuito (a vila)",links:[{label:"Ayuntamiento de Zahara de la Sierra",url:"https://www.zaharadelasierra.es/"}],history:"A conquista de Zahara pelos nasridas em 1481 desencadeou a guerra final de Granada; a torre do castelo domina a vila desde o século XIII."},{id:"rnd_grazalema",categoryId:"ronda",city:"ronda",name:"Grazalema",tagline:"A vila branca de manta e telha ocre",description:"Um dos povoados brancos mais bonitos da Andaluzia, a 812 m de altitude, com becos íngremes, praças floridas e o contraste do branco da cal com a telha ocre e a serra ao fundo. Berço de uma antiga tradição têxtil de mantas de lã, mantém oficinas artesanais ativas. A cerca de 45 min de Ronda pela estrada da serra.",lat:36.7601,lng:-5.3664,durationLabel:"1,5–2 h",fit:"ANY",mapQuery:"Grazalema, Cádiz",whatToDo:"Perca-se pelas ruas em torno da Plaza de España e da igreja da Aurora, visite uma oficina de mantas de lã e alcance um mirador de borda para a serra.",kingTip:"Leve um casaco leve mesmo no verão: por estar no ponto mais chuvoso e alto da região, Grazalema costuma amanhecer bem mais fresca que Ronda.",priceLevel:"Gratuito (a vila)",history:"De origem romana e depois andalusí, Grazalema prosperou nos séculos XVIII e XIX com a manufatura de tecidos e mantas de lã, ofício que ainda resiste."},{id:"rnd_gaucin",categoryId:"ronda",city:"ronda",name:"Gaucín & Castillo del Águila",tagline:"O balcão da serrania com vista ao mar",description:"Vila branca empoleirada na Sierra del Hacho, dominada pelo Castillo del Águila, de origem romana e ampliado pelos árabes. Dos seus miradouros, em dias claros a vista alcança o Estreito de Gibraltar, o Rochedo e a costa africana. Refúgio de artistas, é uma das varandas panorâmicas mais espetaculares da Serranía de Ronda.",lat:36.5182,lng:-5.3175,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",mapQuery:"Castillo del Águila, Gaucín",whatToDo:"Suba ao Castillo del Águila para a panorâmica da serra até o mar e caminhe pelo casco branco entre casas de artistas e pequenas galerias.",kingTip:"Escolha um dia limpo de vento: só então o Rochedo de Gibraltar e a silhueta do Marrocos aparecem no horizonte a partir do castelo.",priceLevel:"Gratuito (a vila e o castelo)",links:[{label:"Castillo del Águila de Gaucín",url:"https://castillodelaguila.es/"}],history:"O castelo, de raízes romanas e reforço nasrida, foi ponto estratégico por séculos; ali morreu, em 1309, o cavaleiro Guzmán el Bueno em combate."},{id:"rnd_montejaque",categoryId:"ronda",city:"ronda",name:"Montejaque",tagline:"A vila branca no coração da serra",description:"Pequeno povoado branco encaixado entre paredões calcários da Serranía de Ronda, com traçado de origem mourisca em torno da Plaza de la Constitución e da igreja de Santiago el Mayor. Ruas íngremes e caiadas, ar autêntico e pouco turismo fazem dele um contraponto tranquilo aos vilarejos mais visitados. A cerca de 20 min de Ronda.",lat:36.7387,lng:-5.2497,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Montejaque, Málaga",whatToDo:"Circule pela Plaza de la Constitución sombreada, visite a igreja de Santiago e suba às bordas da vila para ver o anfiteatro de rochas ao redor.",kingTip:"É parada de tapas honesta e barata: as varandas em torno da praça servem petiscos serranos com muito menos gente que em Ronda.",priceLevel:"Gratuito (a vila)",history:"De nome derivado do árabe 'Montexaquez' (monte perdido), conserva o traçado andalusí e foi doado após a Reconquista aos senhores de Benaoján."},{id:"mlg_syra_coffee",categoryId:"cafe",city:"malaga",name:"Syra Coffee",tagline:"Torra catalã de especialidade na Calle Mártires",description:"Filial malaguenha da microtorrefação barcelonesa Syra, uma barra minúscula e clean na Calle Mártires, a poucos passos da Plaza de la Constitución. Trabalha só com café de especialidade ético e sustentável, com espresso preciso e filtrados que trocam de origem a cada lote. Abre cedo, ideal para o primeiro café antes de o centro acordar.",lat:36.72192,lng:-4.42294,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Syra Coffee, Calle Mártires 13, Málaga",whatToDo:"Peça um cortado ou um filtrado do lote do dia na barra e leve para caminhar até a Plaza de la Constitución.",kingTip:"Abre às 8h, quando quase tudo no centro ainda está fechado; é a melhor aposta para café de especialidade logo cedo.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"08:00",closeHour:"19:00",note:"Espaço pequeno, voltado sobretudo ao café para viagem."},links:[{label:"Site oficial",url:"https://syra.coffee"}]},{id:"mlg_cafe_con_libros",categoryId:"cafe",city:"malaga",name:"Café con Libros",tagline:"Café literário e boêmio na Plaza de la Merced",description:"Café histórico e bohemio na Plaza de la Merced, aberto desde 1998 e tomado por estantes de livros que convidam a ficar. Serve cafés, sucos, sanduíches, saladas, bolos e crepes num ambiente familiar, com música ao vivo, micro-teatro e exposições ao longo da semana. Uma parada tranquila para ler sem pressa a poucos metros da casa natal de Picasso.",lat:36.72364,lng:-4.4171,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Café con Libros, Plaza de la Merced 19, Málaga",whatToDo:"Pegue um livro da estante, peça um café com um pedaço de bolo caseiro e sente-se na esplanada de frente para a praça.",kingTip:"Confira a programação: em muitas noites há música ao vivo ou micro-teatro no salão interno.",priceLevel:"€€",image:"mlg_cafe_con_libros.jpg"},{id:"mlg_recyclo_bike_cafe",categoryId:"cafe",city:"malaga",name:"Recyclo Bike Café",tagline:"Café, oficina e aluguel de bikes num só lugar",description:"Café-oficina descontraído na Plaza Enrique García-Herrera, que junta cafeteria, loja e taller de bicicletas no mesmo espaço. Serve cafés da manhã, almoços leves, café e bebidas num ambiente descolado e cheio de bikes penduradas. Ponto natural para quem quer alugar uma bicicleta e explorar Málaga sobre duas rodas.",lat:36.71979,lng:-4.42436,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Recyclo Bike Café, Plaza Enrique García-Herrera 16, Málaga",whatToDo:"Tome um café da manhã na esplanada e aproveite para alugar uma bike para pedalar até a praia da Malagueta.",kingTip:"Fecha aos domingos e cedo aos sábados; para juntar café e aluguel de bike, vá num dia de semana pela manhã.",priceLevel:"€€",hours:{openDays:"Segunda a sábado",openHour:"09:00",closeHour:"17:00",note:"Sábado até 14h; fecha aos domingos."},links:[{label:"Site oficial",url:"https://www.recyclobike.com"}]},{id:"mlg_la_bella_julieta",categoryId:"cafe",city:"malaga",name:"La Bella Julieta",tagline:"Brunch criativo e fotogênico na Puerta del Mar",description:"Cafeteria chique e moderna na Calle Puerta del Mar, popular pelos cafés da manhã e brunches caprichados e muito instagramáveis. Cardápio variado com pan con tomate, waffles, bolos caseiros, smoothie bowls e boas opções veganas. Ambiente jovem e descontraído no coração do centro histórico.",lat:36.71794,lng:-4.42286,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"La Bella Julieta, Calle Puerta del Mar 20, Málaga",whatToDo:"Peça um smoothie bowl ou um waffle com um café especial e aproveite a decoração colorida para as fotos.",kingTip:"Tem várias unidades pela cidade; a da Puerta del Mar é a mais central para juntar com o Mercado de Atarazanas.",priceLevel:"€€"},{id:"mlg_freskitto",categoryId:"cafe",city:"malaga",name:"Heladería Freskitto",tagline:"Sorvete artesanal desde 1999, ao lado do Picasso",description:"Heladería artesanal fundada em Málaga em 1999 pelo maestro heladero José Romero, com uma loja na Calle Granada, pertíssimo do Museu Picasso. Produz o sorvete diariamente no próprio obrador, com ingredientes naturais e sem aditivos. Parada certeira e refrescante entre uma visita e outra pelo centro histórico.",lat:36.72199,lng:-4.41806,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Heladería Freskitto, Calle Granada 55, Málaga",whatToDo:"Escolha um creme e um sorbetto de fruta da estação e coma a caminho do Museu Picasso ou da catedral.",kingTip:"Fica na Calle Granada, rota natural entre a catedral e a Plaza de la Merced; ótimo para o calor de julho.",priceLevel:"€",links:[{label:"Site oficial",url:"https://www.heladeriafreskitto.com"}]},{id:"grn_cafeteria_lisboa",categoryId:"cafe",city:"granada",name:"Cafetería Lisboa",tagline:"Café clássico com torra própria junto à Plaza Nueva",description:"Cafeteria clássica de Granada na esquina da Calle Reyes Católicos com a Plaza Nueva, com torrefação própria de café 100% arábica. Serve cafés da manhã, churros e um enxuto cardápio de almoço num salão sempre movimentado. Localização imbatível para começar o dia antes de subir ao Albaicín ou à Alhambra.",lat:37.1764,lng:-3.5972,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Cafetería Lisboa, Calle Reyes Católicos, Plaza Nueva, Granada",whatToDo:"Peça churros com um café da casa e tome numa das mesas de frente para a Plaza Nueva.",kingTip:"Fica no ponto de partida das subidas ao Albaicín e à Alhambra; ideal para o café da manhã antes da caminhada.",priceLevel:"€€"},{id:"grn_cafe_futbol",categoryId:"cafe",city:"granada",name:"Café Fútbol",tagline:"Churros com chocolate na Plaza Mariana Pineda, desde 1903",description:"Café emblemático de Granada aberto em 1903 na Plaza Mariana Pineda, hoje na quarta geração da mesma família. Referência absoluta em churros e porras com chocolate espesso e no leite espumoso da casa, servidos numa ampla esplanada. Instituição centenária para o clássico café da manhã doce granadino.",lat:37.17201,lng:-3.59679,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Café Fútbol, Plaza de Mariana Pineda 6, Granada",whatToDo:"Sente-se na esplanada da praça e peça churros ou porras com uma xícara de chocolate quente para mergulhar.",kingTip:"O chocolate com churros sai na parte da manhã e de novo à noite; à tarde nem sempre está disponível.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"08:00",closeHour:"00:00",note:"Churros com chocolate servidos por volta de 6h–13h30 e 18h–00h."},links:[{label:"Site oficial",url:"https://cafefutbol.com"}],history:"Fundado em 1903 por D. Antonio Suárez Martín, é um dos cafés mais antigos da Espanha, mantido por quatro gerações da mesma família."},{id:"grn_la_finca_coffee",categoryId:"cafe",city:"granada",name:"La Finca Coffee",tagline:"Microtorrefação de especialidade no centro",description:"Microtorrefação de café de especialidade com casas no centro de Granada, referência para quem busca grão bem tostado e ambiente acolhedor. Trabalha só com especialidade e acompanha o café com bolos e folhados frescos, como o croissant de pistache e o danish de cheesecake. Parada moderna e tranquila a poucos passos da catedral.",lat:37.17621,lng:-3.60014,durationLabel:"20–40 min",fit:"ANY",mapQuery:"La Finca Coffee, Calle Colegio Catalino 3, Granada",whatToDo:"Prove um filtrado da torra da casa com um croissant de pistache e observe o vaivém do centro.",kingTip:"Eles torram o próprio café; pergunte pela origem em destaque e leve um pacote de grãos como lembrança.",priceLevel:"€€",links:[{label:"Site oficial",url:"https://lafincaroaster.com"}]},{id:"rnd_teteria_al_zahra",categoryId:"cafe",city:"ronda",name:"Tetería Al-Zahra",tagline:"Chás, doces árabes e crepes em clima andalusí",description:"Tetería de charme na Calle las Tiendas, no centro histórico de Ronda, dedicada ao mundo do chá em puro estilo árabe. Longa carta de infusões, batidos e sucos naturais, além de pastelaria árabe e crepes, num ambiente de almofadas, tapetes e luz baixa. Refúgio aconchegante para uma pausa diferente entre os mirantes da cidade.",lat:36.74232,lng:-5.16446,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Tetería Al-Zahra, Calle las Tiendas 19, Ronda",whatToDo:"Escolha um chá aromático da carta com um doce árabe ou um crepe e relaxe no ambiente com almofadas.",kingTip:"É uma ótima pausa à sombra no calor de julho, quando os mirantes ao sol de Ronda ficam intensos.",priceLevel:"€€"},{id:"mrb_gioelia_fuengirola",categoryId:"cafe",city:"marbella",name:"GIOELIA Cremeria",tagline:"Gelato italiano à beira-mar em Los Boliches",description:"Cremeria de gelato artesanal de estilo italiano no Paseo Marítimo Rey de España, no trecho de Los Boliches, em Fuengirola. Uma das heladerías mais bem avaliadas da Costa del Sol central, com texturas cremosas e sabores feitos em pequenas fornadas. Parada perfeita para um gelato de frente para o mar num passeio pela praia.",lat:36.538,lng:-4.6095,durationLabel:"15–30 min",fit:"ANY",mapQuery:"GIOELIA Cremeria, Paseo Marítimo Rey de España 62, Fuengirola",whatToDo:"Peça uma casquinha com dois sabores e coma caminhando pelo paseo marítimo de Los Boliches à beira-mar.",kingTip:"Fica no calçadão de Los Boliches; combine com um mergulho na praia e o pôr do sol sobre o mar.",priceLevel:"€€",links:[{label:"Site oficial",url:"https://gioelia.com"}]},{id:"mrb_darbini_torremolinos",categoryId:"cafe",city:"marbella",name:"Heladería D'Arbini",tagline:"Sorvete 100% artesanal na praia da Carihuela",description:"Heladería 100% artesanal no paseo marítimo da Carihuela, o antigo bairro de pescadores de Torremolinos. Uma das mais bem avaliadas da cidade, com sorvete cremoso feito no obrador e opções de tortas geladas. Ótimo fecho doce depois de um dia de praia ou de um passeio pelas ruelas caiadas da Carihuela.",lat:36.6072,lng:-4.5049,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Heladería D'Arbini, Paseo Marítimo La Carihuela 24, Torremolinos",whatToDo:"Escolha um creme e um sorbetto e coma no calçadão da Carihuela, de frente para o mar.",kingTip:"A Carihuela é o trecho mais gostoso de Torremolinos para caminhar à beira-mar; deixe o gelato para o entardecer.",priceLevel:"€€"},{id:"mlg_corte_ingles_centro",categoryId:"compras",city:"malaga",name:"El Corte Inglés Málaga",tagline:"Grande armazém junto ao centro histórico",description:"O grande armazém mais emblemático de Málaga ergue-se na Avenida de Andalucía, a poucos passos do centro histórico e do rio Guadalmedina. Reúne sob o mesmo teto moda de marcas nacionais e internacionais, perfumaria, eletrônica, casa e uma extensa seção Gourmet com azeites, vinhos e presuntos andaluzes. Prático para resolver compras variadas em ambiente climatizado e com devolução de IVA para turistas.",lat:36.7154,lng:-4.4283,durationLabel:"1–2 h",fit:"INDOOR",mapQuery:"El Corte Inglés, Avenida de Andalucía 4, Málaga",whatToDo:"Percorra os andares de moda e desça ao supermercado Gourmet para levar azeite virgem extra, pimentón e vinhos de Málaga.",kingTip:"Peça o formulário de Tax Free na loja: compras acima de certo valor dão direito a reembolso do IVA no aeroporto antes de voltar ao Brasil.",priceLevel:"€€€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"22:00",note:"Aberturas pontuais aos domingos e feriados; supermercado com horário próprio."},links:[{label:"Site oficial",url:"https://www.elcorteingles.es/centroscomerciales/es/eci/centros/centro-comercial-malaga"}]},{id:"mlg_la_recova",categoryId:"compras",city:"malaga",name:"La Recova",tagline:"Artesanato espanhol e café junto a San Juan",description:"Num beco tranquilo do centro histórico, ao lado da igreja de San Juan, La Recova reúne o melhor do artesanato espanhol feito à mão longe do circuito de souvenires. Cerâmica tradicional, esparto, cestaria, jarapas, bijuteria, vidros e cosméticos convivem com um cantinho de café e produtos gastronômicos malaguenhos. Um lugar de alma para levar uma peça com história.",lat:36.7196,lng:-4.4219,durationLabel:"30–45 min",fit:"INDOOR",mapQuery:"La Recova artesanía, Pasaje Niño de Guevara, Málaga",whatToDo:"Garimpe cerâmica de pequenas olarias e têxteis tipo jarapa, e faça uma pausa no café interno entre as compras.",kingTip:"Fica escondida numa travessa junto à igreja de San Juan; entre mesmo que a fachada pareça discreta, o interior surpreende.",priceLevel:"€€"},{id:"mlg_pasaje_chinitas",categoryId:"compras",city:"malaga",name:"Pasaje de Chinitas",tagline:"Passagem histórica de lojas junto à praça",description:"Esta estreita passagem em forma de cruz nasce na Plaza de la Constitución e é um dos recantos mais boêmios e queridos do centro de Málaga. Erguida no século XIX sobre um antigo convento, ficou famosa pelo Café de Chinitas, imortalizado num poema de Federico García Lorca. Hoje guarda pequenas lojas, ateliês e esplanadas num pátio central cheio de duende.",lat:36.7202,lng:-4.4206,durationLabel:"20–30 min",fit:"ANY",mapQuery:"Pasaje de Chinitas, Málaga",whatToDo:"Passeie entre as lojinhas e ateliês da passagem e procure o painel de azulejos que recorda o verso de Lorca sobre o Café de Chinitas.",kingTip:"Abre direto na Plaza de la Constitución; combine com a Calle Larios e o Pasaje continua até a Calle Fresca, poucos metros à frente.",priceLevel:"€€"},{id:"mlg_mercadillo_cortijo_torres",categoryId:"compras",city:"malaga",name:"Mercadillo de Cortijo de Torres",tagline:"Rastro dominical com 300+ bancas",description:"O maior mercadillo ambulante de Málaga arma-se todos os domingos no recinto ferial de Cortijo de Torres, com mais de 300 bancas divididas em duas zonas. Uma reúne roupa, calçado, artesanato, cerâmica e produtos frescos novos; a outra é um autêntico rastro de antiguidades, moedas, discos e peças de coleção. Manhã ideal para garimpar preços e sentir o pulso popular da cidade.",lat:36.6866,lng:-4.4577,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Recinto Ferial Cortijo de Torres, Málaga",whatToDo:"Reserve tempo para a zona de antiguidades e coleção, onde aparecem azulejos antigos, moedas e discos; pechinche com respeito, faz parte do jogo.",kingTip:"Só funciona aos domingos de manhã, das 9h às 15h; chegue cedo, leve dinheiro em espécie e calce sapato confortável para o chão de terra.",priceLevel:"€",hours:{openDays:"Domingo",openHour:"09:00",closeHour:"15:00",note:"Apenas aos domingos; encerra ao início da tarde."}},{id:"mrb_mercadillo_fuengirola",categoryId:"compras",city:"marbella",name:"Mercadillo de Fuengirola",tagline:"Mercadillo de terça, o maior da costa",description:"Todas as terças-feiras o recinto ferial de Los Boliches, em Fuengirola, recebe um dos maiores mercadillos ao ar livre da Costa del Sol, com quase 500 bancas. Roupa, calçado, complementos, couro, têxteis de casa, ervas e alimentos espalham-se numa maré de cores e sotaques internacionais. Parada obrigatória para quem gosta de garimpo e preços de rua na costa central.",lat:36.5352,lng:-4.6167,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Recinto Ferial de Fuengirola, Avenida Jesús Cautivo, Fuengirola",whatToDo:"Procure as bancas de couro e de têxteis e negocie; ao lado costuma haver postos de azeitonas, frutos secos e ervas para prova.",kingTip:"Só às terças, das 9h às 14h; vá de trem de cercanías (linha C1, estação Los Boliches) para fugir do estacionamento lotado.",priceLevel:"€",hours:{openDays:"Terça",openHour:"09:00",closeHour:"14:00",note:"Semanal às terças, exceto Natal, Ano Novo e Reis."}},{id:"mlg_designer_outlet_plaza_mayor",categoryId:"compras",city:"malaga",name:"McArthurGlen Designer Outlet Málaga",tagline:"Outlet de grifes com até 70% off",description:"Junto ao complexo Plaza Mayor, a caminho do aeroporto, este outlet a céu aberto reúne mais de cem marcas com descontos permanentes que chegam a 70%. Adidas, Nike, Tommy Hilfiger, Hugo Boss, Lacoste e Polo Ralph Lauren dividem ruas ao ar livre com zona de restauração e área infantil. A melhor opção da região para moda de marca a preço de ponta de estoque.",lat:36.6716,lng:-4.4995,durationLabel:"1,5–2,5 h",fit:"ANY",mapQuery:"McArthurGlen Designer Outlet Málaga, Plaza Mayor, Málaga",whatToDo:"Circule pelas lojas de esporte e moda internacional comparando descontos; muitas marcas somam Tax Free ao preço já rebaixado.",kingTip:"Fica a três paradas de trem do centro (estação Plaza Mayor, linha C1); combine com o vizinho centro comercial Plaza Mayor no mesmo passeio.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"22:00",note:"Abre em domingos e feriados selecionados; confirme no site."},links:[{label:"Site oficial",url:"https://www.mcarthurglen.com/en/outlets/es/designer-outlet-malaga/"}]},{id:"mrb_puerto_marina_benalmadena",categoryId:"compras",city:"marbella",name:"Puerto Marina de Benalmádena",tagline:"Compras e lojas na marina premiada",description:"Eleita várias vezes a melhor marina do mundo, o Puerto Marina de Benalmádena mistura arquitetura de ilhas artificiais, iates e uma animada zona comercial no Dique de Levante. Entre lojas de moda, souvenires, complementos e supermercados, aos sábados monta-se o Marina Market, com mais de sessenta bancas de artesanato, antiguidades e gourmet. Passeio de compras com vista para o mar.",lat:36.5955,lng:-4.5165,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Puerto Marina, Benalmádena",whatToDo:"Percorra as lojas do Dique de Levante e, se for sábado, garimpe o Marina Market de artesanato e antiguidades entre 10h e 16h.",kingTip:"Aos sábados vale o Marina Market; nas outras noites o porto é ponto de fim de tarde, ótimo para souvenires depois da praia.",priceLevel:"€€",links:[{label:"Puerto Marina Shopping",url:"https://puertomarinashopping.es/en/"}]},{id:"mrb_calle_san_miguel_torremolinos",categoryId:"compras",city:"marbella",name:"Calle San Miguel (Torremolinos)",tagline:"Rua-comércio peatonal de Torremolinos",description:"A artéria comercial de Torremolinos é uma das ruas pedonais mais movimentadas da Europa, com meio quilômetro de lojas ininterruptas. Ao longo do calçadão convivem souvenires, moda, joalherias, perfumarias e padarias típicas, entre esplanadas e o burburinho de tantos idiomas. No fim da rua espreitam a torre nazari e a igreja de San Miguel, do século XVIII.",lat:36.6215,lng:-4.4997,durationLabel:"45 min–1,5 h",fit:"ANY",mapQuery:"Calle San Miguel, Torremolinos",whatToDo:"Desça a rua toda comparando preços de complementos e perfumes, e ramifique pelas travessas Cauce e Casablanca para lojas menos turísticas.",kingTip:"Ligue a compra ao Balcón de Europa no topo e à descida da Cuesta del Tajo rumo à praia da Carihuela, no mesmo eixo pedonal.",priceLevel:"€€"},{id:"mrb_miramar_fuengirola",categoryId:"compras",city:"marbella",name:"Centro Comercial Miramar",tagline:"Shopping coberto à beira-mar",description:"À entrada de Fuengirola, junto à saída da autovia, o Miramar é o grande centro comercial coberto da zona sul da Costa del Sol. Reúne moda, esporte, tecnologia, hipermercado, cinema e uma ampla praça de alimentação em ambiente climatizado. Refúgio prático em dias de calor forte ou de chuva, com estacionamento amplo e gratuito.",lat:36.541,lng:-4.625,durationLabel:"1–2 h",fit:"INDOOR",mapQuery:"Centro Comercial Miramar, Fuengirola",whatToDo:"Faça as compras variadas de moda e esporte e aproveite o cinema ou a praça de alimentação nas horas de sol mais forte.",kingTip:"Ao contrário dos mercados de rua, abre também aos domingos e feriados na temporada alta; ideal para um dia sem praia.",priceLevel:"€€",hours:{openDays:"Seg–Dom",openHour:"10:00",closeHour:"22:00",note:"Hipermercado e restauração com horários próprios."},links:[{label:"Site oficial",url:"https://www.ccmiramar.es/"}]},{id:"ant_dulces_belen",categoryId:"compras",city:"antequera",name:"Dulces Conventuales de Belén",tagline:"Doçaria conventual no torno das clarissas",description:"No convento de Belén, as monjas clarissas mantêm viva a doçaria conventual de Antequera, vendida pelo tradicional torno giratório à esquerda da fachada da igreja. É o lugar mais célebre para o bienmesabe antequerano, além de mantecados, polvorones, roscos de aceite, magdalenas e o bolo de Santa Clara. Uma compra doce e discreta, feita sem ver quem atende, como manda a clausura.",lat:37.0188,lng:-4.5557,durationLabel:"15–30 min",fit:"ANY",mapQuery:"Convento de Belén, Calle Belén, Antequera",whatToDo:"Toque a campainha do torno e peça o bienmesabe, especialidade da casa; no fim do ano acrescente mantecados e polvorones caseiros.",kingTip:"Compra-se pelo torno giratório, sem contato direto com as freiras; leve trocado e evite o horário da sesta, quando fecha.",priceLevel:"€",hours:{openDays:"Seg–Sex",openHour:"09:30",closeHour:"18:30",note:"Pausa aproximada das 13h30 às 15h30; horário ampliado no Natal."}},{id:"ben_castillo_colomares",categoryId:"cultura",city:"marbella",name:"Castillo de Colomares",tagline:"Um castelo-monumento a Cristóvão Colombo",description:"Erguido entre 1987 e 1994 por um médico apaixonado pela história, é um exuberante monumento-castelo dedicado a Cristóvão Colombo e ao descobrimento da América. Mistura estilos gótico, românico, mudéjar e bizantino num labirinto de torres, arcos e escadarias sobre a serra de Benalmádena. Guarda ainda a menor igreja do mundo, com pouco mais de um metro quadrado. As vistas para o Mediterrâneo são deslumbrantes.",whatToDo:["Suba pelas torres e passarelas em busca dos mirantes sobre o mar","Procure a capela minúscula, citada como a menor igreja do mundo","Decifre os símbolos das três caravelas espalhados pela pedra"],kingTip:"É todo a céu aberto e sobe bastante; vá logo na abertura, às 10h, para fugir do sol forte de julho. Fica em Benalmádena Pueblo, longe da praia.",priceLevel:"~€2,50",lat:36.5966,lng:-4.5726,durationLabel:"1h–1h15",fit:"CLEAR_SKY",hours:{openDays:"Qua–Dom (fecha Seg e Ter)",openHour:10,closeHour:21,note:"Verão: qua–dom 10h–14h e 17h–21h. Inverno: qua–dom 10h–18h. Fecha segundas e terças."},mapQuery:"Castillo Monumento Colomares, Finca la Carraca, Benalmádena Pueblo",links:[{label:"Turismo de Benalmádena",url:"https://www.benalmadena.es/"}]},{id:"fgr_castillo_sohail",categoryId:"cultura",city:"marbella",name:"Castillo Sohail",tagline:"Fortaleza à beira-mar em Fuengirola",description:"Castelo de origem árabe do século X, reconstruído no período nazari e depois pelos cristãos, plantado numa colina sobre a foz do rio Fuengirola e o Mediterrâneo. Suas muralhas e torres são hoje totalmente visitáveis, com passeios pelo adarve e vistas amplas da costa. No verão, a esplanada recebe mercado medieval, concertos e festivais. A entrada é gratuita.",whatToDo:["Percorra o caminho de ronda no alto das muralhas","Contemple a foz do rio e a praia de Fuengirola lá do topo","Confira a agenda de concertos e do mercado medieval no verão"],kingTip:"Entrada gratuita. É exposto ao sol; prefira o fim da tarde, quando refresca e a luz sobre a costa fica linda. Há estacionamento vigiado ao lado.",priceLevel:"Grátis",lat:36.5311,lng:-4.6246,durationLabel:"45min–1h",fit:"CLEAR_SKY",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:10,closeHour:18,note:"Ter–sex 10h–14h; sáb, dom e feriados 10h–18h. Fecha às segundas (salvo feriados). Entrada gratuita."},mapQuery:"Castillo Sohail, Fuengirola, Málaga",history:"Ergueu-se por volta do ano 956 sobre um assentamento fenício e romano. Disputado por muçulmanos e cristãos, viu passar as tropas dos Reis Católicos e, séculos depois, as batalhas napoleônicas antes de virar palco cultural.",links:[{label:"Site oficial",url:"https://www.castillosohail.es/"}]},{id:"mrb_museo_grabado",categoryId:"cultura",city:"marbella",name:"Museo del Grabado Español Contemporáneo",tagline:"Gravura espanhola no casco antigo de Marbella",description:"Único museu da Espanha dedicado à gravura contemporânea, reúne mais de quatro mil obras com nomes como Picasso, Miró, Tàpies e Chillida. Ocupa o Hospital Bazán, elegante edifício renascentista do século XVI no casco histórico caiado de Marbella. Salas frescas e íntimas fazem dele uma pausa cultural entre as ruelas floridas do centro.",whatToDo:["Reconheça gravuras dos grandes mestres espanhóis do século XX","Aprecie a arquitetura gótico-mudéjar do antigo Hospital Bazán","Saia para o labirinto de becos brancos e pátios do casco antigo"],kingTip:"Fica no coração do casco antigo de Marbella; encaixe entre a Plaza de los Naranjos e um café. Abre também à noite de quarta a sexta, ótimo para fugir do calor.",priceLevel:"~€4 (est.)",lat:36.5101,lng:-4.8829,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Seg–Dom (varia por turno)",openHour:10,closeHour:22,note:"Manhãs: seg–sex 10h–14h; sáb e dom 11h–14h. Tardes: qua, qui e sex 17h–22h. Última entrada 20 min antes."},mapQuery:"Museo del Grabado Español Contemporáneo, Calle Hospital Bazán, Marbella",links:[{label:"Site oficial",url:"https://www.mgec.es/"}]},{id:"mrb_museo_ralli",categoryId:"cultura",city:"marbella",name:"Museo Ralli Marbella",tagline:"Arte latino-americana e surrealista, grátis",description:"Um dos cinco museus Ralli do mundo, guarda uma das mais importantes coleções de arte contemporânea latino-americana da Europa, ao lado de obras europeias e surrealistas com nomes como Dalí e Chagall. O edifício amplo e luminoso fica na urbanização Coral Beach, entre Marbella e Puerto Banús, a poucos metros do mar. A entrada é sempre gratuita.",whatToDo:["Percorra as salas de surrealismo e arte latino-americana","Descubra esculturas espalhadas pelos jardins do museu","Combine com um passeio pelo paseo marítimo ali ao lado"],kingTip:"Entrada gratuita e climatizado. Fecha aos domingos e segundas e fica entre Marbella e Puerto Banús; chegue de carro ou táxi.",priceLevel:"Grátis",lat:36.4936,lng:-4.9527,durationLabel:"1h–1h30",fit:"INDOOR",hours:{openDays:"Ter–Sáb (fecha Dom e Seg)",openHour:10,closeHour:17,note:"Ter–sex 10h–17h; sáb 10h–16h. Fecha domingos e segundas. Entrada gratuita."},mapQuery:"Museo Ralli Marbella, Urbanización Coral Beach, Marbella",links:[{label:"Site oficial",url:"https://museoralli.es/"}]},{id:"ben_museo_precolombino",categoryId:"cultura",city:"marbella",name:"Museo Precolombino Felipe Orlando",tagline:"Arte pré-colombina em Benalmádena Pueblo",description:"Coleção reunida pelo artista e humanista cubano Felipe Orlando, com cerca de mil e quinhentas peças de culturas pré-colombianas da América, de cerâmicas a figuras rituais. Ocupa um espaço tranquilo na Plaza de las Tres Culturas, no charmoso Benalmádena Pueblo. A entrada é gratuita e o acervo dá um mergulho raro na América antiga, longe do bulício da praia.",whatToDo:["Observe as cerâmicas e figuras rituais das culturas pré-colombianas","Aprenda sobre a trajetória do artista Felipe Orlando","Passeie depois pelas ruelas caiadas de Benalmádena Pueblo"],kingTip:"Entrada gratuita. Está no pueblo, na parte alta; combine com o Castillo de Colomares, que fica pertinho. Fecha às segundas e terças.",priceLevel:"Grátis",lat:36.5967,lng:-4.5709,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Qua–Dom (fecha Seg e Ter)",openHour:9,closeHour:19,note:"Qua–sáb 9h30–13h30 e 17h–19h; dom e feriados 10h–14h. Fecha segundas e terças. Entrada gratuita."},mapQuery:"Museo de Arte Precolombino Felipe Orlando, Plaza de las Tres Culturas, Benalmádena Pueblo",links:[{label:"Turismo de Benalmádena",url:"https://www.benalmadena.es/"}]},{id:"mlg_mimma",categoryId:"cultura",city:"malaga",name:"Museo Interactivo de la Música (MIMMA)",tagline:"Toque os instrumentos num palácio do século XVIII",description:'Museu interativo com centenas de instrumentos de todas as épocas e cantos do mundo, sob o lema "por favor, toque". Muitas peças podem ser experimentadas em salas dedicadas, o que encanta adultos e crianças. Ocupa o Palácio do Conde de las Navas, casarão do século XVIII na Calle Beatas, no centro histórico de Málaga.',whatToDo:["Toque os instrumentos liberados nas salas interativas","Percorra a coleção de instrumentos de várias culturas e séculos","Aprecie o pátio e a arquitetura do palácio setecentista"],kingTip:"Ideal para quem viaja com crianças e nos dias de calor: é coberto, climatizado e prático. Fica a poucos minutos da Catedral.",priceLevel:"~€4 (est.)",lat:36.7236,lng:-4.4213,durationLabel:"1h–1h30",fit:"INDOOR",hours:{openDays:"Todos os dias",openHour:10,closeHour:19,note:"Inverno (7/set–24/jun): seg 10h–16h, ter–dom 10h–19h. Verão (25/jun–6/set): seg 10h30–16h, ter–dom 10h30–19h30."},mapQuery:"MIMMA Museo Interactivo de la Música, Calle Beatas 15, Málaga",links:[{label:"Site oficial",url:"https://www.musicaenaccion.com/"}]},{id:"grn_casa_de_los_tiros",categoryId:"cultura",city:"granada",name:"Museo Casa de los Tiros",tagline:"Palacete renascentista com teto de heróis",description:"Casa-fortaleza do século XVI no bairro do Realejo, com fachada de pedra ornada por esculturas e arcabuzes que dão nome ao lugar. Abriga o museu de história de Granada, com pintura, gravuras e objetos que contam a cidade dos séculos XIX e XX. Sua joia é a Cuadra Dorada, salão com um extraordinário teto de madeira policromada e retratos de reis e heróis.",whatToDo:["Admire o teto policromado e os retratos da Cuadra Dorada","Veja gravuras e fotografias antigas da Granada romântica","Repare na fachada com as figuras e os arcabuzes de pedra"],kingTip:"Gratuito para cidadãos da UE (leve documento). Fica no Realejo, ótimo para intercalar com uma volta pelo bairro judeu.",priceLevel:"Grátis (UE)",lat:37.1745,lng:-3.5945,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:9,closeHour:21,note:"Inverno (16/set–15/jun): ter–sáb 9h–21h, dom e feriados 9h–15h. Verão (16/jun–15/set): ter–dom e feriados 9h–15h. Fecha às segundas."},mapQuery:"Museo Casa de los Tiros, Calle Pavaneras 19, Granada",links:[{label:"Site oficial (Museos de Andalucía)",url:"https://www.museosdeandalucia.es/web/museocasadelostirosdegranada"}]},{id:"grn_hospital_real",categoryId:"cultura",city:"granada",name:"Hospital Real de Granada",tagline:"Joia renascentista dos Reis Católicos",description:"Grandioso edifício iniciado pelos Reis Católicos no início do século XVI, um dos marcos do Renascimento espanhol, hoje sede da reitoria e da biblioteca da Universidade de Granada. Impressiona pela fachada plateresca de janelas lavradas e por quatro pátios simétricos em planta de cruz. O acesso aos pátios e às exposições costuma ser livre, num respiro sereno perto do centro.",whatToDo:["Contemple a fachada plateresca com os emblemas dos fundadores","Passeie pelos quatro pátios renascentistas do interior","Espie o salão nobre e as mostras temporárias, quando abertas"],kingTip:"Por ser edifício universitário, o acesso aos pátios costuma ser gratuito em dias úteis; confirme se há exposição em cartaz. Fica junto à estação de ônibus e ao Albaicín.",priceLevel:"Grátis (pátios)",lat:37.184,lng:-3.6017,durationLabel:"30–45min",fit:"CLEAR_SKY",hours:{openDays:"Seg–Sex (dias úteis)",openHour:9,closeHour:20,note:"Acesso a pátios e exposições em geral seg–sex em horário universitário. Fins de semana e agosto podem ter acesso restrito; confirme antes."},mapQuery:"Hospital Real, Avenida del Hospicio, Granada",history:"Fundado em 1504 por ordem de Isabel e Fernando para acolher doentes e peregrinos, levou mais de um século para ser concluído. Passou por usos diversos até ser cedido, em 1971, à Universidade de Granada.",links:[{label:"Universidad de Granada",url:"https://patrimonio.ugr.es/bien-inmueble/610/"}]},{id:"crd_julio_romero_de_torres",categoryId:"cultura",city:"cordoba",name:"Museo Julio Romero de Torres",tagline:"A alma cordobesa em retratos sensuais",description:'Dedicado ao pintor cordobês Julio Romero de Torres (1874–1930), reúne suas obras mais célebres, com as morenas melancólicas e simbólicas que fizeram sua fama. Ocupa a antiga casa da família, na pitoresca Plaza del Potro citada por Cervantes, ao lado do Museu de Belas Artes. Salas íntimas e frescas guardam telas como "La chiquita piconera".',whatToDo:['Encontre "La chiquita piconera" e outras obras-símbolo do pintor',"Entenda o simbolismo andaluz por trás dos retratos femininos","Combine com o Museu de Belas Artes, na mesma praça"],kingTip:"Fica na Plaza del Potro, coladinho ao Museu de Belas Artes; visite os dois juntos. No verão abre só de manhã, das 10h às 17h.",priceLevel:"~€4,50 (est.)",lat:37.8812,lng:-4.7747,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:10,closeHour:20,note:"Verão (16/jun–15/set): ter–dom e feriados 10h–17h. Inverno: ter–sáb 10h–20h30, dom e feriados 10h–17h. Fecha às segundas."},mapQuery:"Museo Julio Romero de Torres, Plaza del Potro, Córdoba",links:[{label:"Turismo de Córdoba",url:"https://www.turismodecordoba.org/museo-julio-romero-de-torres"}]},{id:"crd_casa_de_sefarad",categoryId:"cultura",city:"cordoba",name:"Casa de Sefarad",tagline:"A memória sefardita no coração da Judería",description:"Centro cultural instalado numa casa do século XIV, de frente para a Sinagoga, dedicado à história, à música e às tradições dos judeus sefarditas. Nove salas percorrem a vida na Judería, as mulheres de Al-Andalus, a Inquisição e a música sefardita, entre pátios e alcovas. É uma parada íntima e envolvente no coração do bairro judeu de Córdoba.",whatToDo:["Percorra as nove salas sobre a vida e a cultura sefardita","Descubra a sala dedicada às mulheres de Al-Andalus","Confira a agenda de concertos de música sefardita ao vivo"],kingTip:"Fica em frente à Sinagoga, na Calle Judíos; junte os dois numa só caminhada à sombra das ruelas. Abre todos os dias, das 11h às 18h.",priceLevel:"~€5 (est.)",lat:37.8794,lng:-4.7838,durationLabel:"45min–1h",fit:"INDOOR",hours:{openDays:"Ter–Dom (fecha Seg)",openHour:11,closeHour:18,note:"Terça a domingo 11h–18h. Fecha às segundas. Confira no site os concertos de música sefardita."},mapQuery:"Casa de Sefarad, Calle Judíos esquina Averroes, Córdoba",links:[{label:"Site oficial",url:"https://lacasadesefarad.com/"}]},{id:"mlg_el_tintero",categoryId:"gastronomia",city:"malaga",name:"El Tintero",tagline:"O chiringuito da subasta na praia de El Palo",description:"Instituição malaguenha na ponta leste da praia de El Dedo, no bairro pescador de El Palo. Aqui não há cardápio: os garçons saem da cozinha aos gritos, leiloando à viva voz os pratos de peixe frito e marisco recém-feitos, e você levanta a mão para ficar com o que passar. No fim, contam-se os pratos vazios para fechar a conta. Barulhento, rápido e divertidíssimo, é o mais autêntico sabor da cultura de praia local.",lat:36.7178,lng:-4.3559,durationLabel:"almoço 1h30",fit:"CLEAR_SKY",mapQuery:"El Tintero II, Avenida Salvador Allende 340, El Palo, Málaga",whatToDo:"Sente-se na esplanada de frente para o mar e vá levantando a mão conforme passam os pratos de fritura, chopitos e espetos; deixe a conta por conta dos pratos vazios.",kingTip:"Não se reserva e não há carta: chegue cedo no almoço de verão e fique atento ao garçom que passa gritando o prato que você quer. Só dinheiro em algumas mesas: leve trocado.",priceLevel:"€€",hours:{openDays:"Seg-Dom",openHour:"12:30",closeHour:"23:30",note:"Horário amplo em temporada; almoço é o auge da subasta"},history:"Nascido como merendero de praia em El Palo, o Tintero transformou o leilão de pratos numa tradição malaguenha única, hoje repetida por gerações de famílias aos fins de semana."},{id:"mlg_balausta",categoryId:"gastronomia",city:"malaga",name:"Balausta",tagline:"Recomendado Michelin no pátio do Palacio Solecio",description:"Restaurante gastronômico recomendado pela Guia Michelin, instalado no pátio envidraçado do Hotel Palacio Solecio, um palácio andaluz do século XVIII no coração de Málaga. A partir de 2026 passou à direção do chef Dani Carnero (uma estrela Michelin no Kaleja), com uma proposta contemporânea e de partilha que homenageia o receituário tradicional malaguenho. Cenário elegante para uma refeição de autor no centro histórico.",lat:36.7223,lng:-4.4188,durationLabel:"almoço/jantar 2h",fit:"ANY",mapQuery:"Restaurante Balausta, Hotel Palacio Solecio, Calle Granada 61, Málaga",whatToDo:"Peça os pratos de partilha da nova etapa de Dani Carnero e reserve mesa no pátio envidraçado do palácio; combine com harmonização de vinhos andaluzes.",kingTip:"É a cozinha de autor de Dani Carnero em formato mais relaxado que o Kaleja. Sala pequena dentro do hotel: reserve com antecedência para o jantar de verão.",priceLevel:"€€€€",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://palaciosolecio.com/restaurante-balausta/"}],history:"O restaurante do Palacio Solecio teve o selo de José Carlos García e, em janeiro de 2026, passou às mãos de Dani Carnero, que assumiu a direção gastronômica com uma leitura contemporânea da tradição malaguenha.",image:"mlg_balausta.jpg"},{id:"mlg_oleo",categoryId:"gastronomia",city:"malaga",name:"Óleo",tagline:"Cozinha mediterrânea e sushi bar no Soho",description:"Casa dos chefs Sergio del Río e Rui Da Mata no bairro do Soho de Málaga, junto ao Centro de Arte Contemporáneo. Une a tradição malaguenha com um toque de autor e um sushi bar de qualidade, num conceito de fusão mediterrânea e asiática pouco comum na cidade. Ambiente moderno e descontraído, ideal para quem quer variar do peixe frito clássico.",lat:36.7133,lng:-4.4239,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"Óleo Restaurante, Calle Casas de Campos 4, Soho, Málaga",whatToDo:"Combine pratos de autor de raiz mediterrânea com uma seleção do sushi bar de Rui; ótimo para partilhar antes ou depois de visitar o CAC, ao lado.",kingTip:"A fusão mediterrânea-asiática e o sushi são o diferencial da casa. Bairro do Soho movimentado: reserve para o jantar de fim de semana.",priceLevel:"€€€",hours:{openDays:"Ter-Dom",openHour:"13:00",closeHour:"23:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://www.oleorestaurante.es/"}],history:"Aberto junto ao CAC, o Óleo firmou-se como um dos endereços de fusão mais populares de Málaga, cruzando a cozinha malaguenha de Sergio del Río com o sushi de Rui Da Mata."},{id:"mlg_la_reserva_12",categoryId:"gastronomia",city:"malaga",name:"La Reserva 12",tagline:"Arrozes e produto no centro histórico",description:"Restaurante tradicional andaluz na Calle Bolsa, a poucos passos da Calle Larios e da catedral de Málaga. Cozinha de produto com boas frituras, ovos rotos, carnes vermelhas na brasa e, sobretudo, arrozes bem executados, tudo apoiado numa adega ampla de rótulos nacionais e internacionais. Tem esplanada na rua pedonal, perfeita para uma refeição no coração da cidade.",lat:36.7196,lng:-4.4207,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"La Reserva 12, Calle Bolsa 12, Málaga",whatToDo:"Peça um arroz e uma carne vermelha na brasa para partilhar e escolha um vinho da adega; em dia de sol, sente-se na esplanada da Calle Bolsa.",kingTip:"Os arrozes e a seleção de vinhos são o forte. Localização central e muito procurada: reserve a esplanada para o almoço.",priceLevel:"€€€",hours:{openDays:"Seg-Dom",openHour:"13:00",closeHour:"23:30",note:"Aberto todos os dias em temporada; confirme"},links:[{label:"Reserva (TheFork)",url:"https://www.thefork.es/restaurante/la-reserva-12-r842582"}],history:"A poucos metros da Calle Larios, La Reserva 12 consolidou-se como uma parada segura de cozinha andaluza de produto e boa adega no centro histórico de Málaga."},{id:"mrb_espeto_torremolinos",categoryId:"gastronomia",city:"marbella",name:"Chiringuito El Espeto (Torremolinos)",tagline:"Espetos de sardinha na Playa Bajondillo",description:"Chiringuito clássico à beira-mar na Playa Bajondillo, em Torremolinos, no coração da Costa del Sol Central. Especialista no espeto de sardinha assado na barca de lenha à moda malaguenha, além de fritura variada e peixe fresco do dia com os pés quase na areia. O ícone acessível para provar o ritual do espeto num dia de sol.",lat:36.6208,lng:-4.4957,durationLabel:"almoço 1h30",fit:"CLEAR_SKY",mapQuery:"Chiringuito El Espeto Playa, Paseo de los Álamos, Playa Bajondillo, Torremolinos",whatToDo:"Peça o espeto de sardinhas assado na lenha e fritura malaguenha; sente-se na esplanada de frente para o Mediterrâneo ao meio-dia.",kingTip:"O espeto de sardinha assado na barca de lenha é a razão da visita. Chiringuito muito concorrido no verão: vá cedo no almoço para pegar mesa na areia.",priceLevel:"€€",hours:{openDays:"Seg-Dom",openHour:"12:00",closeHour:"23:00",note:"Sazonal e sujeito ao tempo; almoço é o forte"},history:"Na longa praia de Torremolinos, o espeto de sardinha na barca de lenha é uma herança dos antigos merenderos malaguenhos, mantida viva pelos chiringuitos do Bajondillo."},{id:"mrb_casanis",categoryId:"gastronomia",city:"marbella",name:"Casanis Bistrot",tagline:"Bistrô franco-belga no casco antigo",description:"Bistrô mediterrâneo com influências francesas e belgas no casco antigo de Marbella, sob a cozinha criativa do chef Fabian Cangas. Reinterpreta a gastronomia francesa com produto de proximidade, numa sala acolhedora numa das ruas mais bonitas do centro histórico. Um contraponto europeu e romântico aos formatos andaluzes da cidade.",lat:36.5108,lng:-4.8846,durationLabel:"jantar 1h30-2h",fit:"ANY",mapQuery:"Casanis Bistrot, Calle Ancha 8, Casco Antiguo, Marbella",whatToDo:"Vá de menu com pratos franco-belgas reinterpretados e reserve mesa no charmoso casco antigo; ambiente intimista, ideal para uma noite a dois.",kingTip:"Cozinha francesa criativa rara na zona. Casa pequena no centro histórico: reserve com antecedência, sobretudo aos fins de semana de verão.",priceLevel:"€€€",hours:{openDays:"Seg-Sáb",openHour:"19:00",closeHour:"23:30",note:"Serve sobretudo ao jantar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://casanisbistrot.com/"}],history:"O Casanis tornou-se um dos endereços mais queridos do casco antigo de Marbella, defendendo a cozinha franco-belga numa cidade dominada pela tradição andaluza e pelo luxo internacional."},{id:"mrb_santiago",categoryId:"gastronomia",city:"marbella",name:"Restaurante Santiago",tagline:"O templo do peixe e marisco de Marbella",description:"Clássico marisqueiro de Marbella no Paseo Marítimo, com origem na primeira barraca de praia da cidade nos anos 1950 e casa própria desde 1973. Referência absoluta em peixe e marisco fresco da lonja, servido com o rigor de uma casa histórica reaberta em 2024 sob a direção de Santiago Domínguez. A mesa de sempre para comer o melhor do mar em Marbella.",lat:36.5064,lng:-4.8828,durationLabel:"almoço/jantar 1h30-2h",fit:"ANY",mapQuery:"Restaurante Santiago, Paseo Marítimo esquina Gregorio Marañón 8, Marbella",whatToDo:"Peça o peixe do dia ao peso e uma seleção de marisco fresco; deixe o garçom sugerir a lonja do dia e sente-se de frente para o mar.",kingTip:"Peça o peixe fresco ao peso, a especialidade histórica da casa. Instituição muito procurada: reserve para o almoço de domingo.",priceLevel:"€€€€",hours:{openDays:"Seg-Dom",openHour:"13:00",closeHour:"23:30",note:"Aberto todos os dias em temporada; confirme"},links:[{label:"Site oficial",url:"https://marbella.costasur.com/sites/santiago/en/index.html"}],history:"Fundado a partir da primeira barraca de praia de Marbella nos anos 1950, o Santiago mudou-se para o Paseo Marítimo em 1973 e reabriu em 2024, mantendo o estatuto de grande casa de peixe e marisco da cidade."},{id:"nrj_oliva",categoryId:"gastronomia",city:"axarquia",name:"Oliva",tagline:"Recomendado Michelin na Plaza de España de Nerja",description:"Restaurante recomendado pela Guia Michelin desde 2016, na Plaza de España de Nerja, tocado pelo casal Carlos (cozinha) e Kim (sala). Cozinha contemporânea de raiz mediterrânea com produto de temporada, entre uma carta sazonal e um menu-degustação de autor, servida numa sala elegante com terraço agradável. A alternativa refinada ao clássico Sollun na Axarquía.",lat:36.7461,lng:-3.8767,durationLabel:"jantar 2h",fit:"ANY",mapQuery:"Restaurante Oliva, Plaza de España, Nerja",whatToDo:"Opte pelo menu-degustação sazonal ou pela carta mediterrânea; peça mesa no terraço e combine com um passeio pelo Balcón de Europa, ao lado.",kingTip:"Recomendado Michelin ano após ano, com sala reduzida numa vila que lota em julho: reserve o jantar com antecedência.",priceLevel:"€€€",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Site oficial e reserva",url:"https://www.restauranteoliva.com/"},{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/nerja/restaurant/oliva-1195827"}],history:"Aberto por Carlos e Kim, o Oliva mudou-se em 2021 para a Plaza de España e mantém desde 2016 a recomendação da Guia Michelin, sendo uma das mesas de autor de referência da costa de Nerja."},{id:"grn_cala",categoryId:"gastronomia",city:"granada",name:"Cala",tagline:"Recomendado Michelin, quatro mesas de autor",description:"Casa de autor recomendada pela Guia Michelin do chef Samuel Hernández, na zona do Forum, perto do Parque de las Ciencias de Granada. Apenas quatro mesas para uma cozinha íntima que funde tradições francesas, portuguesas e espanholas com o produto andaluz de temporada. Menu-degustação único que muda com a estação, num interior contemporâneo e minucioso.",lat:37.1587,lng:-3.6038,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Restaurante Cala, Calle José Luis Pérez Pujadas, Granada",whatToDo:"Vá de menu-degustação único com harmonização de vinhos; a sala minúscula favorece a conversa com o chef, prato a prato.",kingTip:"Só quatro mesas: das reservas mais difíceis de Granada. Reserve com semanas de antecedência para o jantar de verão.",priceLevel:"~€75/pessoa (est.)",hours:{openDays:"Mié-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/granada/restaurant/cala1154913"},{label:"Reserva (TheFork)",url:"https://www.thefork.es/restaurante/cala-r752405"}],history:"Samuel Hernández, de formação francesa, abriu o Cala como um projeto íntimo de quatro mesas na zona do Forum, cruzando as suas raízes europeias com o produto de temporada granadino."},{id:"crd_garum_21",categoryId:"gastronomia",city:"cordoba",name:"Garum 2.1",tagline:"Bib Gourmand bistronômico na Judería",description:"Tapas bar bistronômico com Bib Gourmand da Guia Michelin, de gestão familiar, na Judería de Córdoba, com um troço de muralha romana à vista dentro da sala. Visão contemporânea do receituário cordovês com excelente relação qualidade-preço, famoso pelo salmorejo de amontillado, o polvo defumado e o rabo de touro. Uma das melhores mesas informais da cidade.",lat:37.8843,lng:-4.7817,durationLabel:"almoço/jantar 1h30",fit:"ANY",mapQuery:"Garum 2.1, Calle San Fernando 122, Córdoba",whatToDo:"Peça o salmorejo de amontillado (melhor tapa de Córdoba num concurso) e o rabo de touro; formato de partilha, ótimo para provar vários pratos.",kingTip:"O salmorejo de amontillado é a assinatura premiada da casa. Bib Gourmand pequeno e muito procurado: reserve para o jantar.",priceLevel:"€€€",hours:{openDays:"Mar-Dom",openHour:"13:00",closeHour:"23:00",note:"Dias podem variar; confirme na reserva"},links:[{label:"Site oficial",url:"https://www.garum2punto1.com/"},{label:"Guia Michelin",url:"https://guide.michelin.com/be/nl/andalucia/cordoba/restaurant/garum-2-1"}],history:"De gestão familiar, o Garum 2.1 renova ano após ano o Bib Gourmand da Guia Michelin com a sua releitura bistronômica da cozinha cordovesa, na Judería e sobre restos de muralha romana."},{id:"crd_terra_olea",categoryId:"gastronomia",city:"cordoba",name:"Terra Olea",tagline:"Bib Gourmand em torno da azeitona",description:"Restaurante com Bib Gourmand da Guia Michelin no bairro de Arruzafilla, a noroeste de Córdoba, com sala luminosa e cozinha à vista. Cozinha contemporânea assente no produto local e nos pequenos produtores cordoveses, articulada em dois menus-degustação, Flos e Cibarium, que homenageiam a azeitona e a sua importância histórica. Ótima relação qualidade-preço fora do circuito estrelado.",lat:37.8928,lng:-4.8058,durationLabel:"almoço/jantar 2h",fit:"ANY",mapQuery:"Terra Olea, Calle Rigoberta Menchú 2, Córdoba",whatToDo:"Escolha um dos menus-degustação (Flos ou Cibarium), centrados na azeitona e no produto local; peça harmonização com azeites e vinhos da terra.",kingTip:"Bib Gourmand com menus-degustação a preço justo. Fica fora do centro: vale o táxi curto e a reserva antecipada.",priceLevel:"~€45/pessoa (est.)",hours:{openDays:"Mar-Sáb",openHour:"13:30",closeHour:"22:30",note:"Dias podem variar; confirme na reserva"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/cordoba/restaurant/terra-olea-1194951"}],history:"No bairro de Arruzafilla, o Terra Olea construiu a sua identidade em torno da azeitona e do produto cordovês, renovando o Bib Gourmand da Guia Michelin com uma cozinha contemporânea acessível."},{id:"grn_realejo_campo_principe",categoryId:"granada",city:"granada",name:"Realejo e Campo del Príncipe",tagline:"A antiga judiaria e sua praça de tapas",description:"O Realejo é o antigo bairro judeu de Granada, um dédalo de ladeiras, cármenes e muros grafitados pelo artista El Niño de las Pinturas. Seu coração é o Campo del Príncipe, largo aberto em 1497 para as bodas do príncipe Juan, hoje cercado de esplanadas de tapas e presidido pelo Cristo de los Favores, crucifixo de jaspe de 1640. Bairro boêmio, autêntico e menos turístico que o Albaicín.",lat:37.17331,lng:-3.59211,durationLabel:"1–2 h a pé",fit:"ANY",mapQuery:"Campo del Principe, Realejo, Granada",kingTip:"Sente-se numa esplanada do Campo del Príncipe ao entardecer para as tapas gratuitas que acompanham a bebida — tradição que em Granada ainda se cumpre à risca. Suba depois pela Cuesta de los Molinos rumo ao Carmen de los Mártires.",priceLevel:"Gratuito (consumo à parte)",history:"Chamado Garnata al-Yahud (Granada dos Judeus) na época nazarí, foi rebatizado Realejo após a conquista cristã; o Campo del Príncipe, aberto sobre um antigo cemitério muçulmano, ganhou o Cristo de los Favores em 1640, ainda mais venerado após a peste de 1679-1682."},{id:"grn_basilica_angustias",categoryId:"granada",city:"granada",name:"Basílica de las Angustias",tagline:"O santuário da padroeira de Granada",description:"Na arborizada Carrera de la Virgen ergue-se a basílica barroca da Virgen de las Angustias, padroeira da cidade e da província desde a ratificação papal de 1887. Concluída em 1671, guarda no camarín do altar-mor a imagem quinhentista da Virgem, envolta em um esplendor churrigueresco de talha dourada, mármores coloridos e prata. É o coração devocional dos granadinos.",lat:37.16988,lng:-3.59711,durationLabel:"20–30 min",fit:"INDOOR",mapQuery:"Basilica de las Angustias, Granada",kingTip:"Fica na Carrera de la Virgen, alameda ideal para caminhar até a Fuente de las Batallas e o centro. Fecha nas horas de culto; visite pela manhã, fora dos horários de missa.",priceLevel:"Gratuito",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"13:30",note:"Reabre à tarde; fecha durante missas. Grande devoção em setembro, mês da padroeira."},links:[{label:"Site oficial",url:"https://www.basilicadelasangustias.org"}],history:"Nasceu de uma ermida do início do século XVI dedicada às santas Úrsula e Susana; o templo barroco atual foi concluído em 1671 e Leão XIII confirmou em 1887 o patronato da Virgen de las Angustias sobre Granada."},{id:"grn_palacio_cordova",categoryId:"granada",city:"granada",name:"Palacio de los Córdova",tagline:"Jardins com vista da Alhambra no fim do Darro",description:"No arranque da Cuesta del Chapiz, onde o Paseo de los Tristes encontra o Sacromonte, este casarão do século XVI de fachada renascentista se cerca de jardins, hortas e uma torre. Hoje abriga o Arquivo Municipal, mas o que encanta são os jardins escalonados e gratuitos, com fontes, pomares e uma das vistas mais tranquilas da Alhambra suspensa em frente.",lat:37.17982,lng:-3.58715,durationLabel:"30–40 min",fit:"ANY",mapQuery:"Palacio de los Cordova, Granada",kingTip:"A entrada aos jardins é gratuita e quase sempre deserta — um oásis à sombra no fim do Paseo de los Tristes, antes de subir ao Sacromonte. Suba até a base da torre para a melhor vista da Alhambra.",priceLevel:"Gratuito",hours:{openDays:"Seg a sex",openHour:"09:00",closeHour:"14:00",note:"Horário do Arquivo Municipal; jardins acessíveis em horário de expediente."},links:[{label:"Turismo Granada",url:"https://turismo.granada.org/es/areas-tematicas/bodas-palacios/palacio-cordova"}],history:"Construído entre 1530 e 1592 na Placeta de las Descalzas, foi desmontado e remontado pedra a pedra em 1960 na Cuesta del Chapiz; desde 1984 sedia o Arquivo Municipal de Granada."},{id:"grn_mirador_carvajales",categoryId:"granada",city:"granada",name:"Mirador de la Placeta de Carvajales",tagline:"A Alhambra de pertinho, sem multidão",description:"Escondido no baixo Albaicín, entre a Cuesta de San Gregorio e a Calle San Juan de los Reyes, este pequeno miradouro oferece uma das visões mais íntimas da Alhambra. Daqui a Torre de la Vela e a Alcazaba erguem-se logo à frente sobre o morro da Sabika, com as torres dos Palácios Nazaríes ao fundo. Silencioso e quase secreto, ao contrário do lotado San Nicolás.",lat:37.17893,lng:-3.59425,durationLabel:"15–20 min",fit:"CLEAR_SKY",mapQuery:"Mirador Placeta de los Carvajales, Granada",kingTip:"Vá ao fim da tarde: a luz dourada bate de frente na Alhambra e há bancos para sentar em paz. Fica muito perto da Plaza Nueva, subindo poucos metros — não confunda com o San Nicolás.",priceLevel:"Gratuito",history:"Antiga horta da família nobre dos Carvajales, influente em Granada nos séculos XV e XVI; ganhou traçado de praça pública nas reformas urbanas do Albaicín no século XIX."},{id:"crd_cristo_faroles",categoryId:"cordoba",city:"cordoba",name:"Cristo de los Faroles",tagline:"A imagem mais cordobesa: um Cristo e oito lanternas",description:"Na sóbria Plaza de Capuchinos, de paredes caiadas de branco, ergue-se o crucifixo barroco esculpido por Juan Navarro León em 1794, iluminado por oito lanternas de ferro forjado que lhe deram o apelido. O contraste do Cristo escuro sobre a cal ofuscante faz desta uma das estampas mais recolhidas e fotografadas de Córdoba, sobretudo à noite.",lat:37.88817,lng:-4.77759,durationLabel:"15–20 min",fit:"CLEAR_SKY",mapQuery:"Cristo de los Faroles, Plaza de Capuchinos, Cordoba",kingTip:"Venha depois do anoitecer, quando as lanternas acesas dramatizam o Cristo contra o branco — a foto clássica. De dia, a praça calçada com pedra original fica em silêncio quase total.",priceLevel:"Gratuito",history:"Erguido em 1794 por encomenda do frei capuchinho Diego José de Cádiz e obra do escultor Juan Navarro León, chama-se oficialmente Cristo de la Expiración y del Perdón; o povo o rebatizou pelas oito lanternas que o cercam."},{id:"crd_plaza_tendillas",categoryId:"cordoba",city:"cordoba",name:"Plaza de las Tendillas",tagline:"O coração moderno de Córdoba",description:"A grande praça central de Córdoba, ponto de encontro e marco-zero da cidade moderna. No meio ergue-se a estátua equestre do Gran Capitán, Gonzalo Fernández de Córdoba, obra de Mateo Inurria de 1923. Seu relógio toca as horas com acordes de guitarra flamenca gravados. Cercada de cafés e lojas, é a fronteira entre a Córdoba antiga e a comercial.",lat:37.88451,lng:-4.77956,durationLabel:"15–20 min",fit:"CLEAR_SKY",mapQuery:"Plaza de las Tendillas, Cordoba",kingTip:"Fique atento ao relógio no alto: em vez de badaladas, marca as horas com toques de guitarra flamenca. É o melhor ponto de partida para descer à Judería e à Mesquita-Catedral a pé.",priceLevel:"Gratuito",history:"De origem no século XIV, quando abrigava as casas dos comendadores de Calatrava e pequenas 'tendillas' (lojinhas) que lhe deram o nome; ganhou a feição atual na grande reforma urbana de 1925-1930, com o Gran Capitán transferido ao centro em 1927."},{id:"crd_iglesia_san_lorenzo",categoryId:"cordoba",city:"cordoba",name:"Iglesia de San Lorenzo",tagline:"A joia gótico-mudéjar das igrejas fernandinas",description:"Uma das igrejas fernandinas erguidas após a Reconquista de Fernando III, no fim do século XIII, e talvez a mais bela do grupo. Distingue-se por um raro pórtico de três arcos diante da entrada e por um grande rosetão gótico-mudéjar, um dos melhores da época. Guarda afrescos do século XIV e uma torre-campanário desenhada por Hernán Ruiz II em 1555.",lat:37.88856,lng:-4.76889,durationLabel:"20–30 min",fit:"INDOOR",mapQuery:"Iglesia de San Lorenzo, Cordoba",kingTip:"Fica no bairro de San Lorenzo, longe das rotas turísticas — combine com a Torre de la Malmuerta e a Plaza de Capuchinos numa caminhada pela Córdoba autêntica dos bairros do norte.",priceLevel:"Gratuito ou simbólico",history:"Construída entre cerca de 1244 e 1300 sobre uma antiga mesquita, é uma das igrejas fernandinas do reinado de Fernando III, o Santo; a torre é de Hernán Ruiz II (1555) e o restauro de 1963 recuperou seu aspecto gótico-mudéjar original."},{id:"crd_puerta_almodovar",categoryId:"cordoba",city:"cordoba",name:"Puerta de Almodóvar",tagline:"A porta árabe da muralha, guardada por Séneca",description:"A única porta de origem árabe que Córdoba conserva, encaixada num dos melhores trechos preservados da muralha medieval, ao lado da Judería. Reconstruída no século XIV sobre a porta andalusí Bab al-Chawz, é ladeada por torreões e por uma estátua de bronze do filósofo cordobês Séneca. Dela parte a estreita Calle Judíos, coração do bairro judeu.",lat:37.88283,lng:-4.7862,durationLabel:"15–20 min",fit:"CLEAR_SKY",mapQuery:"Puerta de Almodovar, Cordoba",kingTip:"Atravesse a porta e siga pela Calle Judíos até a Sinagoga e o Zoco — é a entrada mais atmosférica da Judería. O trecho de muralha ao longo da Calle Cairuán, com sua alberca, rende ótimas fotos ao entardecer.",priceLevel:"Gratuito",history:"Conhecida como Bab al-Chawz (Porta da Nogueira) na época muçulmana, remonta à Córdoba andalusí e foi reconstruída no século XIV; a estátua de Séneca, de Amadeo Ruiz Olmos, foi inaugurada em 1965 no XIX centenário da morte do filósofo."},{id:"ant_iglesia_san_juan_de_dios",categoryId:"antequera",city:"antequera",name:"Iglesia de San Juan de Dios",tagline:"Uma joia do barroco andaluz em azul e branco",description:"Na rua Infante Don Fernando, esta igreja da Ordem Hospitaleira foi iniciada em 1696 por Melchor de Aguirre e é um dos interiores barrocos mais delicados da Andaluzia. De planta em cruz latina e cúpula sobre pendentes, encanta pela decoração em estuque branco ondulante com detalhes azuis, entremeada de motivos vegetais e animais. A portada é de calcário vermelho do Torcal.",lat:37.02044,lng:-4.56397,durationLabel:"20–30 min",fit:"INDOOR",mapQuery:"Iglesia de San Juan de Dios, Antequera",kingTip:"Aberta ao público de forma permanente desde 2013 — refúgio fresco e pouco visitado sobre a artéria principal. Repare que a pedra do templo veio das ruínas romanas de Singilia Barba.",priceLevel:"Gratuito ou simbólico",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/iglesia-san-juan-de-dios/"}],history:"A Ordem Hospitaleira chegou a Antequera na segunda metade do século XVII; a igreja começou em 1696 sob projeto de Melchor de Aguirre e foi bendita em 1716, com hospital e convento concluídos só no fim do século XVIII. É Bem de Interesse Cultural desde 2005."},{id:"ant_mirador_torcal_ventanillas",categoryId:"antequera",city:"antequera",name:"El Torcal — Mirador de las Ventanillas",tagline:"Um labirinto kárstico com vista até a África",description:"A poucos passos do centro de visitantes Torcal Alto, este miradouro se abre sobre um dos paisagens kársticas mais espetaculares da Europa: torres de calcário de 150 milhões de anos esculpidas pela erosão em formas surreais. Do balcão descortina-se Villanueva de la Concepción, o vale do Campanillas, Málaga e, em dias limpos, a linha da costa africana. Trilhas sinalizadas partem dali.",lat:36.9581,lng:-4.5436,durationLabel:"1,5–2 h (com trilha)",fit:"CLEAR_SKY",mapQuery:"Centro de Visitantes Torcal Alto, Antequera",whatToDo:"Comece no centro de visitantes, admire a vista do Mirador de las Ventanillas e percorra a Rota Verde (1,5 km) entre os pilares de calcário.",kingTip:"No verão, o acesso de carro à parte alta é restrito e há lançadeira a partir do posto inferior — chegue cedo. Leve água e calçado firme; a rocha é escorregadia. A serra fica bem mais fresca que Antequera lá embaixo.",priceLevel:"Gratuito (lançadeira/estacionamento à parte)",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/activity/el-torcal-de-antequera/"},{label:"Torcal de Antequera",url:"https://www.torcaldeantequera.com"}],history:"Paraje Natural desde 1989 e parte do sítio Patrimônio Mundial dos Dólmenes de Antequera desde 2016, o Torcal formou-se a partir de sedimentos marinhos do Jurássico, erguidos e depois moldados pela dissolução da chuva ao longo de milhões de anos."},{id:"ant_plaza_coso_viejo",categoryId:"antequera",city:"antequera",name:"Plaza del Coso Viejo",tagline:"O largo senhorial no coração de Antequera",description:"No coração do casco histórico, esta praça empedrada nasceu no século XVI como ampliação da Plaza de San Sebastián e foi antigo mercado e palco de touradas. Preside-a o Palácio de Nájera, casa senhorial setecentista que abriga o museu da cidade, com a estátua equestre do Infante Don Fernando, conquistador de Antequera em 1410, e a Fonte dos Quatro Elementos.",lat:37.01645,lng:-4.55789,durationLabel:"20–30 min",fit:"ANY",mapQuery:"Plaza del Coso Viejo, Antequera",kingTip:"É o ponto de partida natural para subir a cidade alta: daqui pegue a Cuesta de Zapateros rumo ao Arco de los Gigantes e à Colegiata. As esplanadas à sombra convidam a uma pausa antes da ladeira.",priceLevel:"Gratuito",links:[{label:"Turismo Antequera",url:"https://turismo.antequera.es/puntos-de-interes/plaza-coso-viejo/"}],history:"Surgida no século XVI como ampliação da Plaza de San Sebastián e antes chamada Plaza de las Verduras pelos mercados que abrigava; passou a Coso Viejo por acolher festas e touradas, e hoje reúne o Palácio de Nájera e o monumento ao Infante Don Fernando."},{id:"mlg_ac_palacio",categoryId:"hospedagem",city:"malaga",name:"AC Málaga Palacio",tagline:"4★ com rooftop de piscina sobre a Catedral",description:"Torre clássica na Cortina del Muelle, entre a Catedral e o porto, com quartos amplos e vista para o Mediterrâneo ou para a cidade antiga. O trunfo é o rooftop no último andar, com piscina, bar e panorama frontal para a torre da Catedral. Central, confortável e com ótimo custo-benefício para a categoria.",whatToDo:["rooftop com piscina","bar panorâmico","a 2 min da Catedral"],kingTip:"Suba ao terraço ao entardecer; a vista da Catedral iluminada dali é a melhor da cidade num hotel deste preço.",lat:36.7178,lng:-4.4177,durationLabel:"estadia",fit:"ANY",priceLevel:"~€170–290/noite (est., jul)",mapQuery:"AC Hotel Málaga Palacio",links:[{label:"Site oficial",url:"https://www.marriott.com/en-us/hotels/agpap-ac-hotel-malaga-palacio/overview/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=AC+Hotel+Malaga+Palacio"}],image:"mlg_ac_palacio.jpg"},{id:"mlg_vincci_posada_patio",categoryId:"hospedagem",city:"malaga",name:"Vincci Selección Posada del Patio",tagline:"5★ com muralha romana no lobby",description:"Boutique 5★ no Pasillo Santa Isabel, à beira do rio Guadalmedina e a passos do Mercado de Atarazanas. Um vestígio da muralha árabe-romana atravessa o átrio sob piso de vidro, num diálogo raro entre ruína e design. Elegante e tranquilo, na borda oeste do centro histórico.",whatToDo:["muralha histórica no átrio","spa e terraço","a 5 min do Mercado de Atarazanas"],kingTip:"Peça um quarto nos andares altos com vista para a cidade; os inferiores dão para a rua movimentada do pasillo.",lat:36.7186,lng:-4.4255,durationLabel:"estadia",fit:"ANY",priceLevel:"~€200–340/noite (est., jul)",mapQuery:"Vincci Selección Posada del Patio, Málaga",links:[{label:"Site oficial",url:"https://www.vinccihoteles.com/hoteles/espana/malaga/vincci-seleccion-posada-del-patio"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Vincci+Posada+del+Patio+Malaga"}]},{id:"mlg_room_mate_larios",categoryId:"hospedagem",city:"malaga",name:"Room Mate Larios",tagline:"Design art déco na esquina da Larios",description:"Hotel de design instalado num edifício art déco na própria Calle Marqués de Larios, a artéria nobre de Málaga. Quartos com estilo e um rooftop terraço com vista para a rua elegante e os telhados do centro. Impossível ficar mais no coração comercial e de tapas da cidade.",whatToDo:["rooftop","na própria Calle Larios","a 4 min da Catedral"],kingTip:"A localização é imbatível, mas peça quarto afastado da fachada: a Larios fica cheia e barulhenta até tarde no verão.",lat:36.7183,lng:-4.4206,durationLabel:"estadia",fit:"ANY",priceLevel:"~€180–310/noite (est., jul)",mapQuery:"Room Mate Larios, Málaga",links:[{label:"Site oficial",url:"https://room-matehotels.com/en/larios/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Room+Mate+Larios+Malaga"}]},{id:"mlg_barcelo_malaga",categoryId:"hospedagem",city:"malaga",name:"Barceló Málaga",tagline:"4★ de design colado à estação AVE",description:"Hotel de design conectado à estação María Zambrano (trem de alta velocidade), com um lobby marcante e um escorregador que desce ao térreo. Prático para quem chega de AVE de Madri, Córdoba ou Sevilha e quer emendar a cidade. Fica a poucos minutos de táxi do centro histórico.",whatToDo:["ligado à estação AVE","fitness e bar","a 10 min do centro histórico"],kingTip:"Ideal como primeira ou última noite se você viaja de trem; escolha quarto nas faces altas para fugir do ruído dos trilhos.",lat:36.7118,lng:-4.4318,durationLabel:"estadia",fit:"ANY",priceLevel:"~€130–230/noite (est., jul)",mapQuery:"Barceló Málaga",links:[{label:"Site oficial",url:"https://www.barcelo.com/pt-br/barcelo-malaga/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Barcelo+Malaga"}],image:"mlg_barcelo_malaga.jpg"},{id:"mrb_higueron_curio",categoryId:"hospedagem",city:"marbella",name:"Higuerón Hotel Curio by Hilton (Fuengirola)",tagline:"Resort de vista mar na Reserva del Higuerón",description:"Grande resort da Curio Collection by Hilton no alto da Reserva del Higuerón, entre Benalmádena e Fuengirola, com vista panorâmica para o Mediterrâneo. Múltiplas piscinas, spa Nammu, ginásios e teleférico/shuttle até o beach club à beira-mar. Ótima base familiar na Costa del Sol central.",whatToDo:["piscinas com vista mar","spa Nammu","beach club próprio"],kingTip:"Reserve quarto 'sea view' nos andares altos; o resort fica na encosta, então use o shuttle para descer à praia.",lat:36.5268,lng:-4.6268,durationLabel:"estadia",fit:"ANY",priceLevel:"~€220–420/noite (est., jul)",mapQuery:"Higuerón Hotel Málaga Curio Collection by Hilton",links:[{label:"Site oficial",url:"https://www.higueronhotel.com/en/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Higueron+Hotel+Curio+Hilton+Fuengirola"}]},{id:"mrb_vincci_aleysa_benalmadena",categoryId:"hospedagem",city:"marbella",name:"Vincci Selección Aleysa Benalmádena",tagline:"Boutique 5★ à beira-mar em Benalmádena",description:"Pequeno hotel boutique 5★ de frente para a praia de Benalmádena Costa, com estilo mediterrâneo luminoso e ambiente sereno. Piscina, spa e um restaurante voltado ao mar, a poucos passos do passeio marítimo. Refinado e tranquilo, no coração da Costa del Sol central.",whatToDo:["piscina de frente para o mar","spa","passeio marítimo na porta"],kingTip:"Peça quarto com terraço e vista mar; a diferença compensa pela varanda sobre a praia e o café da manhã ao ar livre.",lat:36.5936,lng:-4.5166,durationLabel:"estadia",fit:"ANY",priceLevel:"~€200–360/noite (est., jul)",mapQuery:"Vincci Selección Aleysa Benalmádena",links:[{label:"Site oficial",url:"https://www.vinccihoteles.com/hoteles/espana/benalmadena/vincci-seleccion-aleysa-hotel-boutique-spa"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Vincci+Aleysa+Benalmadena"}]},{id:"mrb_fuerte_marbella",categoryId:"hospedagem",city:"marbella",name:"Hotel Fuerte Marbella",tagline:"Beira-mar colado ao centro antigo",description:"Clássico de frente para a praia de La Fontanilla, num jardim subtropical entre o Paseo Marítimo e o casco antiguo de Marbella. Piscinas, spa e acesso direto à areia, com a vantagem rara de estar a poucos minutos a pé das praças e vielas históricas. Familiar, arborizado e muito bem situado.",whatToDo:["praia na porta","piscinas e spa","a 5 min do centro antigo"],kingTip:"É o único grande hotel de praia de Marbella colado ao casco antiguo: peça quarto vista mar e faça o centro histórico a pé.",lat:36.5085,lng:-4.883,durationLabel:"estadia",fit:"ANY",priceLevel:"~€230–420/noite (est., jul)",mapQuery:"Hotel Fuerte Marbella",links:[{label:"Site oficial",url:"https://www.fuertehoteles.com/en/hotels/hotel-fuerte-marbella/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hotel+Fuerte+Marbella"}]},{id:"mrb_los_monteros",categoryId:"hospedagem",city:"marbella",name:"Los Monteros Marbella",tagline:"Grande-dame 5★ entre pinheiros e mar",description:"Um dos resorts históricos de Marbella, a leste da cidade, cercado de jardins e pinhais, com o célebre beach club La Cabane na areia. Piscinas, tênis, spa e um ar de clube clássico e discreto. Elegância à moda antiga, longe do burburinho de Puerto Banús.",whatToDo:["beach club La Cabane","piscinas e tênis","spa"],kingTip:"Fica a leste, mais calmo: bom para quem quer sossego. Reserve almoço no La Cabane, o beach club é o coração social do hotel.",lat:36.4983,lng:-4.8442,durationLabel:"estadia",fit:"ANY",priceLevel:"~€300–560/noite (est., jul)",mapQuery:"Los Monteros Marbella",links:[{label:"Site oficial",url:"https://www.monteros.com/en/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Los+Monteros+Marbella"}]},{id:"mrb_amare_beach",categoryId:"hospedagem",city:"marbella",name:"Amàre Beach Hotel Marbella",tagline:"Adults-only de rooftop no Paseo Marítimo",description:"Hotel só para adultos no Paseo Marítimo de Marbella, com pegada moderna e social. Rooftop com piscina, bar e vista para o mar, além de beach club próprio na areia. Para casais e amigos que querem praia, drinques e vibe descontraída a pé do centro.",whatToDo:["rooftop com piscina","beach club","passeio marítimo na porta"],kingTip:"Adults-only (16+): não é para famílias com crianças. O rooftop Belvue ao pôr do sol é o programa da casa.",lat:36.5057,lng:-4.8996,durationLabel:"estadia",fit:"ANY",priceLevel:"~€240–440/noite (est., jul)",mapQuery:"Amàre Beach Hotel Marbella",links:[{label:"Site oficial",url:"https://www.amarehotels.com/en/amare-beach-hotel-marbella/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Amare+Beach+Hotel+Marbella"}]},{id:"mrb_flats_costa_central",categoryId:"hospedagem",city:"marbella",name:"Flats na Costa Central (Torremolinos/Benalmádena/Fuengirola)",tagline:"Apartamentos de praia na Costa del Sol",description:"Aluguel de temporada nos balneários centrais da Costa del Sol: Torremolinos, Benalmádena e Fuengirola. Apartamentos à beira-mar, muitos com piscina de condomínio e varanda sobre o Mediterrâneo, bem servidos de trem de cercanías até Málaga. Prático e econômico para famílias e estadas longas de praia.",whatToDo:["cozinha própria","piscina de condomínio","trem direto a Málaga"],kingTip:"Escolha algo perto de uma estação do Cercanías C-1 (Benalmádena-Arroyo, Torremolinos ou Fuengirola) para ir e voltar de Málaga sem carro.",lat:36.5988,lng:-4.539,durationLabel:"estadia",fit:"ANY",priceLevel:"~€100–220/noite (est., jul)",mapQuery:"Benalmádena Costa, Málaga, Spain",links:[{label:"Buscar no Airbnb (Benalmádena)",url:"https://www.airbnb.com.br/s/Benalm%C3%A1dena--Spain/homes"},{label:"Buscar no Airbnb (Fuengirola)",url:"https://www.airbnb.com.br/s/Fuengirola--Spain/homes"}]},{id:"grn_aurea_washington_irving",categoryId:"hospedagem",city:"granada",name:"Áurea Washington Irving",tagline:"Histórico no caminho da Alhambra",description:"Hotel histórico no Paseo del Generalife, na subida arborizada rumo à Alhambra, herdeiro do clássico Washington Irving que hospedou viajantes desde o séc. XIX. Reformado com conforto contemporâneo, fica a poucos passos da bilheteria do monumento. Base cômoda para chegar cedo à Alhambra, antes das multidões.",whatToDo:["a 5 min da entrada da Alhambra","terraço","no bosque do Generalife"],kingTip:"A localização paga sozinha: durma aqui para ser dos primeiros a entrar na Alhambra sem depender de táxi na subida.",lat:37.1747,lng:-3.5893,durationLabel:"estadia",fit:"ANY",priceLevel:"~€180–320/noite (est., jul)",mapQuery:"Áurea Washington Irving, Granada",links:[{label:"Site oficial",url:"https://www.eurostarshotels.com/aurea-washington-irving.html"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Aurea+Washington+Irving+Granada"}]},{id:"grn_ac_santa_paula",categoryId:"hospedagem",city:"granada",name:"AC Palacio de Santa Paula",tagline:"Convento-palácio 5★ na Gran Vía",description:"Luxo 5★ da Autograph Collection num conjunto que reúne convento do séc. XVI, casas mouriscas e fachada senhorial na Gran Vía de Colón. Claustro ajardinado, biblioteca-restaurante El Claustro e spa, no centro comercial de Granada. Histórico e elegante, a poucos minutos da Catedral e da Capela Real.",whatToDo:["claustro histórico","spa","a 5 min da Catedral"],kingTip:"Peça um quarto voltado ao claustro interno; são mais silenciosos que os da Gran Vía, avenida de tráfego constante.",lat:37.1782,lng:-3.5987,durationLabel:"estadia",fit:"ANY",priceLevel:"~€230–390/noite (est., jul)",mapQuery:"AC Palacio de Santa Paula, Granada",links:[{label:"Site oficial",url:"https://www.marriott.com/en-us/hotels/grxak-ac-hotel-palacio-de-santa-paula/overview/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=AC+Palacio+de+Santa+Paula+Granada"}]},{id:"grn_palacio_santa_ines",categoryId:"hospedagem",city:"granada",name:"Palacio de Santa Inés",tagline:"Casa-palácio do séc. XVI no Albaicín",description:"Pequeno hotel numa casa senhorial renascentista da Carrera del Darro, no sopé do Albaicín, com pátio de colunas e afrescos atribuídos à escola de Rafael. Poucos quartos, muito charme e um terraço com vista para a Alhambra. Atmosfera íntima e histórica, dentro do bairro mouro.",whatToDo:["pátio renascentista","terraço com vista da Alhambra","na Carrera del Darro"],kingTip:"Reserve os quartos superiores com vista da Alhambra; o hotel é pequeno e essas unidades esgotam primeiro no verão.",lat:37.1769,lng:-3.592,durationLabel:"estadia",fit:"ANY",priceLevel:"~€150–260/noite (est., jul)",mapQuery:"Palacio de Santa Inés, Granada",links:[{label:"Site oficial",url:"https://www.palaciosantaines.com/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Palacio+de+Santa+Ines+Granada"}]},{id:"rnd_catalonia_ronda",categoryId:"hospedagem",city:"ronda",name:"Catalonia Ronda",tagline:"4★ com rooftop e vista do campo bravo",description:"Hotel moderno junto à Plaza de Toros e à Alameda del Tajo, com spa e um rooftop de piscina com vista panorâmica para a serrania e o vale. Confortável e bem equipado, num raro exemplo de hotel novo dentro do casco de Ronda. Ótimo para famílias que querem piscina e localização central.",whatToDo:["rooftop com piscina panorâmica","spa","a 3 min da Plaza de Toros"],kingTip:"Suba ao rooftop ao fim do dia: a vista aberta para a serrania rondeña é a melhor surpresa da casa.",lat:36.7443,lng:-5.1646,durationLabel:"estadia",fit:"ANY",priceLevel:"~€150–260/noite (est., jul)",mapQuery:"Catalonia Ronda",links:[{label:"Site oficial",url:"https://www.cataloniahotels.com/en/hotel/catalonia-ronda"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Catalonia+Ronda"}]},{id:"rnd_san_gabriel",categoryId:"hospedagem",city:"ronda",name:"Hotel San Gabriel",tagline:"Casa-museu de família no casco antigo",description:"Charmoso hotel familiar numa mansão de 1736 no casco antiguo de Ronda, cheia de antiguidades, uma escadaria senhorial e até uma minissala de cinema com poltronas de teatro. Quartos únicos e um pátio acolhedor, a passos da Casa del Rey Moro e da Puente Nuevo. Autêntico, pessoal e cheio de história.",whatToDo:["pátio e salões de antiguidades","biblioteca e sala de cinema","a 4 min da Puente Nuevo"],kingTip:"Cada quarto é diferente; peça um dos maiores do andar nobre e tome o café da manhã no pátio histórico.",lat:36.7398,lng:-5.1656,durationLabel:"estadia",fit:"ANY",priceLevel:"~€110–180/noite (est., jul)",mapQuery:"Hotel San Gabriel, Ronda",links:[{label:"Site oficial",url:"https://www.hotelsangabriel.com/en/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hotel+San+Gabriel+Ronda"}]},{id:"nrj_carabeo_boutique",categoryId:"hospedagem",city:"axarquia",name:"Hotel Carabeo (boutique) Nerja",tagline:"Boutique à beira da falésia em Nerja",description:"Pequeno hotel boutique de estilo inglês na Calle Carabeo, sobre a falésia da zona antiga de Nerja, cheio de antiguidades e obras de arte. Jardim escalonado com piscina descendo até um mirante sobre o mar e acesso próximo às calas. Íntimo, romântico e a passos do Balcón de Europa.",whatToDo:["jardim com piscina sobre o mar","restaurante 34","a 5 min do Balcón de Europa"],kingTip:"Poucos quartos e muito procurado: reserve cedo e peça um com terraço e vista mar sobre o jardim em socalcos.",lat:36.7456,lng:-3.8728,durationLabel:"estadia",fit:"ANY",priceLevel:"~€150–260/noite (est., jul)",mapQuery:"Hotel Carabeo, Nerja",links:[{label:"Site oficial",url:"https://www.hotelcarabeo.com/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hotel+Carabeo+Nerja"}]},{id:"crd_hospes_bailio",categoryId:"hospedagem",city:"cordoba",name:"Hospes Palacio del Bailío",tagline:"Palácio 5★ com ruínas romanas sob o spa",description:"Palácio dos séculos XVI-XVIII no centro histórico de Córdoba, com uma sucessão de pátios andaluzes, jardins e piscina. O spa se assenta sobre ruínas de uma casa romana, visíveis sob piso de vidro no restaurante. Um dos endereços mais belos da cidade, entre a Judería e a Plaza de Colón.",whatToDo:["pátios e jardins","spa sobre ruínas romanas","piscina"],kingTip:"Peça um quarto que dê para os pátios ajardinados; são o coração do palácio e ficam frescos até no calor de julho.",lat:37.8878,lng:-4.7768,durationLabel:"estadia",fit:"ANY",priceLevel:"~€230–400/noite (est., jul)",mapQuery:"Hospes Palacio del Bailío, Córdoba",links:[{label:"Site oficial",url:"https://www.hospes.com/cordoba-palacio-bailio/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hospes+Palacio+del+Bailio+Cordoba"}]},{id:"crd_eurostars_palace",categoryId:"hospedagem",city:"cordoba",name:"Eurostars Palace Córdoba",tagline:"4★ moderno com rooftop no Paseo da Vitória",description:"Hotel contemporâneo no Paseo de la Victoria, na borda oeste do centro, com quartos amplos e um rooftop de piscina e bar com vista para a cidade. Prático, confortável e a uma caminhada plana até a Mesquita-Catedral e a Judería. Boa opção para quem prefere estrutura moderna à intimidade dos boutiques.",whatToDo:["rooftop com piscina","a 10 min da Mesquita-Catedral","estrutura moderna"],kingTip:"O rooftop abre no verão e é o ponto alto: vá ao anoitecer. Fica pertinho da estação AVE, cômodo para chegadas de trem.",lat:37.8832,lng:-4.7856,durationLabel:"estadia",fit:"ANY",priceLevel:"~€130–230/noite (est., jul)",mapQuery:"Eurostars Palace, Córdoba",links:[{label:"Site oficial",url:"https://www.eurostarshotels.com/eurostars-palace.html"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Eurostars+Palace+Cordoba"}]},{id:"mrb_teleferico_benalmadena",categoryId:"natureza",city:"marbella",name:"Teleférico de Benalmádena (Monte Calamorro)",tagline:"Bondinho ao cume de 771 m sobre a costa",description:"Teleférico que sobe em 15 minutos da Explanada do Tívoli, em Arroyo de la Miel, até o alto do Monte Calamorro, na Sierra de Mijas. Lá em cima abrem-se trilhas curtas de monte mediterrâneo e miradouros que alcançam de Málaga a Gibraltar e, em dias limpos, o Rif marroquino. No terraço há sessões de voo livre de aves de rapina em pleno horizonte da baía.",lat:36.599,lng:-4.5488,durationLabel:"2–3 h",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Teleférico Benalmádena, Explanada del Tívoli, Arroyo de la Miel",kingTip:"O teleférico fecha com vento forte e o cume fica bem mais fresco e ventoso que a costa: leve um casaco leve mesmo em julho, suba na primeira hora pela luz e confira antes se há voo de aves rapaces no dia.",priceLevel:"€€€",hours:{openDays:"Todos os dias (verão)",openHour:"10:00",closeHour:"19:00",note:"Horário do verão costuma esticar até o fim da tarde; confirme no site, pois muda por temporada e pode fechar por vento."},links:[{label:"Site oficial",url:"https://www.telefericobenalmadena.com"}]},{id:"mrb_bioparc_fuengirola",categoryId:"natureza",city:"marbella",name:"Bioparc Fuengirola",tagline:"Zoo de imersão em plena selva urbana",description:"Parque de nova geração no centro de Fuengirola, onde os animais vivem em recriações fiéis de selvas de Madagascar, África Equatorial, Sudeste Asiático e Indo-Pacífico, sem grades à vista. Passarelas cruzam a vegetação densa junto a gorilas, tigres, lêmures e crocodilos, com forte trabalho de conservação de espécies ameaçadas. Um dos zoológicos mais premiados da Europa, ótimo para famílias.",lat:36.5373,lng:-4.6274,durationLabel:"3–4 h",fit:"ANY",mapQuery:"Bioparc Fuengirola, Calle Camilo José Cela 6, Fuengirola",kingTip:"A vegetação densa dá bastante sombra, o que ajuda no calor, mas ainda assim vá na abertura às 10h para ver os animais ativos antes do meio-dia; fica a 600 m da estação de trem de Fuengirola.",priceLevel:"€€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"20:00",note:"Abre todo o dia às 10h; o fechamento estica no verão (até 20h em maio–agosto). Confirme o horário do dia no site."},links:[{label:"Site oficial",url:"https://www.bioparcfuengirola.es"}]},{id:"mrb_selwo_aventura",categoryId:"natureza",city:"marbella",name:"Selwo Aventura (Estepona)",tagline:"Safári a pé e de veículo entre serras",description:"Grande parque de aventura na serra de Estepona onde mais de 2.000 animais de três continentes vivem em vastos recintos que imitam a savana e a floresta. Percorre-se a pé e em veículos 4x4 tipo safári, com girafas, rinocerontes, leões, elefantes e uma reserva de aves. Tem tirolesas, pontes tibetanas e experiências de tratador para quem quer mais adrenalina.",lat:36.4456,lng:-5.0078,durationLabel:"meio dia",fit:"CLEAR_SKY",mapQuery:"Selwo Aventura, A-7 km 162.5, Estepona",kingTip:"O terreno é aberto e serrano, com pouca sombra e muita subida: vá cedo, leve boné, protetor e água, e reserve o passeio de 4x4 e a tirolesa online para não pegar fila no calor.",priceLevel:"€€€",hours:{openDays:"Todos os dias (verão)",openHour:"10:00",closeHour:"18:00",note:"Abre às 10h; horário e dias podem variar fora do verão. Confirme no site antes de ir."},links:[{label:"Site oficial",url:"https://www.selwo.es"}]},{id:"mrb_selwo_marina",categoryId:"natureza",city:"marbella",name:"Selwo Marina (Delfinário de Benalmádena)",tagline:"Golfinhos, pinguins e selva tropical",description:"Parque marinho junto ao Parque de la Paloma, em Benalmádena Costa, com o único delfinário da Andaluzia e uma grande pinguineira antártica com aves de várias espécies. Há ainda uma cúpula de selva tropical amazônica, répteis, aves exóticas e apresentações educativas de golfinhos e leões-marinhos ao longo do dia. Compacto e sombreado, funciona bem mesmo com tempo instável.",lat:36.5951,lng:-4.5339,durationLabel:"2–3 h",fit:"ANY",mapQuery:"Selwo Marina, Parque de la Paloma, Benalmádena",kingTip:"Chegue cedo e cheque o quadro de horários logo na entrada para encaixar as apresentações de golfinhos e pinguins sem correria; boa opção de dia nublado ou muito quente, por ter áreas cobertas e climatizadas.",priceLevel:"€€€",hours:{openDays:"Todos os dias (verão)",openHour:"10:00",closeHour:"18:00",note:"Abre às 10h no verão; dias e horários variam por temporada. Confirme no site."},links:[{label:"Site oficial",url:"https://www.selwomarina.es"}]},{id:"mrb_sea_life_benalmadena",categoryId:"natureza",city:"marbella",name:"Sea Life Benalmádena",tagline:"Aquário com túnel e tanque de tubarões",description:"Aquário à beira do glamouroso Puerto Marina de Benalmádena, com dezenas de tanques que recriam do Mediterrâneo aos mares tropicais. O ponto alto é o túnel submerso que atravessa o oceânico, com tubarões, raias e tartarugas passando por cima da cabeça. Espaço interativo com poças de toque, cavalos-marinhos e trabalho de resgate de tartarugas marinhas.",lat:36.5966,lng:-4.5164,durationLabel:"1,5–2 h",fit:"ANY",mapQuery:"Sea Life Benalmádena, Puerto Marina",kingTip:"Totalmente coberto e climatizado, é o refúgio ideal nas horas de sol mais forte ou em dia de vento; emende com um passeio pelo Puerto Marina e reserve online para poupar até 20% e evitar fila.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"19:00",note:"Última entrada cerca de 1h antes do fechamento; horário estica no verão. Confirme no site."},links:[{label:"Site oficial",url:"https://www.visitsealife.com/benalmadena"}]},{id:"mrb_cocodrilos_park",categoryId:"natureza",city:"marbella",name:"Cocodrilos Park (Torremolinos)",tagline:"Centenas de crocodilos a 15 min do centro",description:"Parque de conservação em Torremolinos dedicado aos crocodilos, com centenas de exemplares de várias espécies, do anão africano ao imponente crocodilo-do-nilo. Percursos passam por lagos e viveiros até o veterano Big Daddy, um dos maiores da Europa, além de tartarugas e répteis num museu temático. Visitas guiadas mostram alimentação e o trabalho de criação.",lat:36.6262,lng:-4.5057,durationLabel:"1,5–2 h",fit:"ANY",mapQuery:"Cocodrilos Park, Calle Cuba 14, Torremolinos",kingTip:"Compacto e com boa parte à sombra e coberta, é uma parada rápida e boa até com tempo instável; confira o horário da alimentação dos crocodilos, o momento mais movimentado da visita, e há estacionamento próprio grátis.",priceLevel:"€€",hours:{openDays:"Todos os dias (verão)",openHour:"10:00",closeHour:"18:00",note:"Jul–ago costuma abrir 10:00–18:00; nos demais meses fecha mais cedo. Confirme no site."},links:[{label:"Site oficial",url:"https://www.cocodrilospark.com"}]},{id:"mlg_embalse_guadalhorce",categoryId:"natureza",city:"malaga",name:"Embalse Conde de Guadalhorce (Lagos de El Chorro)",tagline:"Espelhos turquesa aos pés do Caminito del Rey",description:"Conjunto de represas de água turquesa encaixadas na paisagem cársica de Ardales, junto à entrada do Caminito del Rey. Miradouros como o Luis Morales revelam os lagos entre pinheiros e paredões, e nas margens dá para nadar, alugar caiaque e pedalinho ou fazer um roteiro guiado de remo. Restaurantes rústicos à beira-d'água completam um dia de natureza no interior de Málaga.",lat:36.9184,lng:-4.7888,durationLabel:"2–4 h",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Mirador Embalse Conde de Guadalhorce, Ardales",kingTip:"Água refrescante e ótima para caiaque no calor, mas as margens têm pouca sombra: leve chapéu, protetor e água, e combine com o Caminito del Rey, logo ali, reservando o caiaque com antecedência na alta temporada.",priceLevel:"€",links:[{label:"Diputación de Málaga",url:"https://www.malaga.es/es/laprovincia/naturaleza/lis_cd-17018/pantano-conde-guadalhorce"}]},{id:"mrb_parque_paloma",categoryId:"natureza",city:"marbella",name:"Parque de la Paloma (Benalmádena)",tagline:"Parque enorme com animais soltos e lago",description:"Um dos maiores parques urbanos da Costa del Sol, com mais de 200.000 m² de gramados, trilhas e um grande lago central em Benalmádena Costa. Coelhos, galinhas, pavões, patos e até um pônei circulam soltos entre os visitantes, para alegria das crianças. Tem área de piquenique, playground, cafeteria e fica a poucos passos da praia de Santa Ana.",lat:36.5966,lng:-4.5361,durationLabel:"1–2 h",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Parque de la Paloma, Benalmádena Costa",kingTip:"Entrada gratuita e muita sombra de árvores: perfeito para o fim da tarde com crianças, levando pão ou ração própria para os animais soltos, e emendando com um banho na praia de Santa Ana ao lado.",priceLevel:"€"},{id:"mrb_los_reales_bermeja",categoryId:"natureza",city:"marbella",name:"Los Reales de Sierra Bermeja (Estepona)",tagline:"Pinsapar sobre peridotita a 1.452 m",description:"Paraje natural sobre Estepona coroado pelo Pico de Los Reales, com 1.452 metros o ponto mais alto de toda a linha costeira da Península. A serra de rocha vermelha de peridotita abriga um dos raros bosques relictos de pinsapo, o abeto-espanhol. Do Mirador Salvador Guerrero, a 380 m do estacionamento, a vista varre da baía de Marbella ao Estreito e, em dias limpos, à África.",lat:36.487,lng:-5.1585,durationLabel:"2–4 h",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Mirador Salvador Guerrero, Los Reales de Sierra Bermeja, Estepona",kingTip:"A altitude deixa o ar bem mais fresco e ventoso que a costa, alívio perfeito no calor; a estrada de acesso é estreita e sinuosa, então suba com calma pela manhã e confira antes se não há fechamento por risco de incêndio no verão.",priceLevel:"€",links:[{label:"Estepona Natural",url:"https://www.estepona-natural.es"}]},{id:"rnd_garganta_verde",categoryId:"natureza",city:"ronda",name:"Garganta Verde (Zahara de la Sierra)",tagline:"Cânion de 100 m com colônia de grifos",description:"Desfiladeiro espetacular escavado pelo arroio Bocaleones no Parque Natural Sierra de Grazalema, a oeste de Ronda. As paredes verticais de até 100 metros abrigam uma das maiores colônias de grifos da Andaluzia, que planam sobre o abismo. No fundo do cânion escondem-se a Ermita de la Garganta, uma gruta de formações calcárias, num dos trekkings mais impressionantes da região.",lat:36.8203,lng:-5.3838,durationLabel:"2–3 h",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Sendero Garganta Verde, Zahara de la Sierra",kingTip:"Atenção: a descida completa ao cânion exige autorização gratuita (pelo centro de visitantes de El Bosque) e fica fechada de 1º de junho a 15 de outubro por risco de incêndio, justo no verão; nesse período só se chega ao primeiro miradouro dos grifos. Confirme antes e vá cedo.",priceLevel:"€",links:[{label:"Cádiz Turismo",url:"https://www.cadizturismo.com/rutas/sendero-garganta-verde"}]},{id:"mrb_carihuela",categoryId:"praias",city:"marbella",name:"Playa de la Carihuela",tagline:"O reino dos espetos em Torremolinos",description:"A praia mais castiça de Torremolinos, no antigo bairro de pescadores da Carihuela, com mais de dois quilômetros de areia colada a Benalmádena. É um dos melhores lugares da Costa del Sol para comer espeto de sardinha, com uma fileira de chiringuitos históricos onde o peixe assa na brasa à vista de todos. Passeio marítimo pedonal, ambiente familiar e vida de bairro andaluz.",lat:36.6072,lng:-4.5049,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de la Carihuela, Torremolinos",kingTip:"Reserve o almoço num chiringuito da Carihuela e peça o espeto de sardinha assado na barca de brasa: é aqui que muitos malaguenhos juram estar o melhor da costa.",whereToEat:"Chiringuitos clássicos da orla da Carihuela, como El Roqueo e La Chana, especialistas em peixe fresco e frituras."},{id:"mrb_bajondillo",categoryId:"praias",city:"marbella",name:"Playa del Bajondillo",tagline:"A praia central de Torremolinos",description:"A praia mais central e movimentada de Torremolinos, um extenso areal urbano logo abaixo do centro histórico. Larga e com todos os serviços, é prática para um banho sem sair da cidade, com palmeiras, passeio marítimo e chiringuitos ao longo de toda a orla. Um elevador público na Praça Panorama poupa a descida pela íngreme Cuesta del Tajo.",lat:36.6183,lng:-4.4966,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa El Bajondillo, Torremolinos",kingTip:"Para evitar a ladeira, use o elevador gratuito da Praça Panorama, que desce direto do centro à areia."},{id:"mrb_malapesquera",categoryId:"praias",city:"marbella",name:"Playa de Malapesquera",tagline:"Areia escura ao lado do Puerto Marina",description:"Praia urbana de areia escura em Benalmádena Costa, a poucos passos do vistoso Puerto Marina e do castelo de Bil-Bil. Bem equipada e animada, é boa base para um dia de praia combinado com um passeio pela marina, suas lojas e restaurantes. Ondas moderadas e todos os serviços à mão, muito frequentada no verão.",lat:36.5958,lng:-4.5195,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Malapesquera, Benalmádena"},{id:"mrb_santa_ana",categoryId:"praias",city:"marbella",name:"Playa de Santa Ana",tagline:"Águas calmas junto ao Puerto Marina",description:"Praia protegida e de águas rasas em Benalmádena Costa, praticamente uma extensão da orla que sai do Puerto Marina. O fundo suave e o mar tranquilo fazem dela uma das mais indicadas para famílias com crianças, com Bandeira Azul e serviços completos. Ao lado ficam o Sea Life e a badalada vida noturna da marina.",lat:36.5983,lng:-4.5128,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Santa Ana, Benalmádena"},{id:"mrb_fuente_salud",categoryId:"praias",city:"marbella",name:"Playa de Fuente de la Salud",tagline:"A fonte que corre para o mar",description:"A praia mais a leste de Benalmádena, na fronteira com Torremolinos, deve o nome a uma nascente natural que deságua no mar e a que se atribuíam propriedades curativas. É um areal tranquilo e familiar, com passeio arborizado de palmeiras e boa oferta de chiringuitos. Ambiente calmo apesar de central, ideal para um dia sem agito.",lat:36.6018,lng:-4.5058,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa Fuente de la Salud, Benalmádena"},{id:"mrb_los_boliches",categoryId:"praias",city:"marbella",name:"Playa de Los Boliches",tagline:"A longa orla de Fuengirola",description:"Trecho central da imensa praia de Fuengirola, no bairro de Los Boliches, parte de um areal contínuo de vários quilômetros. Areia fina e escura, mar calmo e um passeio marítimo interminável cheio de chiringuitos, sorveterias e esplanadas. Fácil de alcançar de trem pela linha de cercanias que liga a Málaga capital.",lat:36.5378,lng:-4.615,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Los Boliches, Fuengirola",kingTip:"Chegue de trem: a estação Los Boliches da linha C-1 de Cercanías deixa você a poucos minutos a pé da areia, sem dor de cabeça com estacionamento."},{id:"mrb_castillo_sohail",categoryId:"praias",city:"marbella",name:"Playa del Castillo",tagline:"Areia sob o castelo de Sohail",description:"Praia larga de areia dourada aos pés do castelo de Sohail, na foz do rio Fuengirola, no extremo sul da cidade. O ambiente é mais desafogado que o do centro, e a fortaleza de origem muçulmana no alto da colina rende as melhores vistas da orla. Palco tradicional das moragas, as noitadas de fogueira na areia com barcas de peixe.",lat:36.534,lng:-4.6268,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa del Castillo, Fuengirola",kingTip:"Suba ao castelo de Sohail no fim da tarde: a muralha no alto da colina emoldura o pôr do sol sobre toda a Costa del Sol."},{id:"mrb_bajadilla",categoryId:"praias",city:"marbella",name:"Playa de la Bajadilla",tagline:"Praia de bairro no coração de Marbella",description:"Praia urbana e popular junto ao antigo porto pesqueiro de Marbella, a leste do centro histórico. Mar calmo e fundo raso a tornam segura e familiar, com um passeio marítimo bem servido de bares e restaurantes. Aqui se come o peixe recém-desembarcado do porto vizinho, longe do brilho de Puerto Banús.",lat:36.5078,lng:-4.8785,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de la Bajadilla, Marbella",whereToEat:"Marisquerias junto ao porto pesqueiro da Bajadilla, com peixe e frutos do mar do dia."},{id:"mrb_siroko_beach",categoryId:"praias",city:"marbella",name:"Siroko Beach",tagline:"Beach club descalço na Marbella leste",description:"Beach club de espírito mediterrâneo e descontraído numa praia com dunas na zona de Costabella, no leste de Marbella, a poucos minutos de Puerto Banús. Arquitetura de madeira natural, tons claros e um clima barefoot combinam com cozinha mediterrânea de peixe, arrozes e grelhados. Música ao vivo e DJs ao fim da tarde, sem o exagero dos clubes mais festivos.",lat:36.5015,lng:-4.8318,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Siroko Beach, Marbella",priceLevel:"€€€",links:[{label:"Site oficial do Siroko Beach",url:"https://sirokobeach.com/"}]},{id:"mrb_nao_pool_club",categoryId:"praias",city:"marbella",name:"Naô Pool Club",tagline:"Piscina e cabanas perto de Puerto Banús",description:"Pool club elegante em Nueva Andalucía, a poucos minutos de Puerto Banús, cercado de vegetação e voltado para o dia à beira da piscina. Espreguiçadeiras, cabanas privadas, coquetéis e cozinha internacional montam o cenário, com DJs e festas de piscina no verão. Escolha para quem quer o glamour de Marbella com estrutura de resort.",lat:36.489,lng:-4.9535,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Naô Pool Club, Marbella",priceLevel:"€€€€",links:[{label:"Site oficial do Naô Pool Club",url:"https://naopoolclub.com/"}]},{id:"mrb_purobeach",categoryId:"praias",city:"marbella",name:"Purobeach Marbella",tagline:"Oásis chill-out com vista para Gibraltar",description:"Um dos beach clubs mais elegantes da Costa del Sol, dentro do complexo Laguna Village, na praia El Padrón entre Puerto Banús e Estepona. Ambiente relaxado com boa música, piscina, spa e cozinha internacional de inspiração global, com vistas que alcançam Gibraltar e o Atlas marroquino nos dias claros. Reabriu renovado em 2024 sob nova gestão.",lat:36.4389,lng:-5.1015,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Purobeach Marbella, Laguna Village",priceLevel:"€€€€",links:[{label:"Site oficial do Purobeach",url:"https://www.purobeach.com/en/"}]},{id:"mlg_casa_lola",categoryId:"tapas",city:"malaga",name:"Casa Lola",tagline:"Tapas malaguenhas na Calle Granada",description:"Taberna de azulejos e barris aberta na movimentada Calle Granada, coração da rota de tapeo do centro histórico. A casa que inaugurou o grupo serve uma carta larga de tapas e montaditos clássicos a preços honestos, com vermute de torneira e um vaivém constante de gente no balcão. Colorida, animada e sempre cheia, é parada certa para começar a noite.",lat:36.72206,lng:-4.41904,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Casa Lola, Calle Granada 46, Málaga",kingTip:"Peça o pincho de tortilla cremosa e o vermute de torneira, a dupla que os malaguenhos repetem no aperitivo.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Costuma lotar no fim da tarde; há outras casas do grupo pela cidade (Strachan e porto)."},links:[{label:"Site oficial",url:"https://grupocasalola.com"}],image:"mlg_casa_lola.jpg"},{id:"mlg_el_yerno",categoryId:"tapas",city:"malaga",name:"Bodega El Yerno",tagline:"Marisco fresco no Mercado de Atarazanas",description:"Barra de mariscos encravada dentro do Mercado Central de Atarazanas, o belo mercado de ferro e vitral do centro. A família compra o pescado do dia ali mesmo e serve boquerones, gambas, chocos e atum vermelho fritos ou grelhados na hora, regados a vinho de Málaga. Come-se em pé, no balcão, no burburinho do mercado. Ganhou em 2025 o prêmio de melhor boquerón frito da cidade.",lat:36.71841,lng:-4.42406,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bar Marisquería El Yerno, Mercado de Atarazanas, Málaga",kingTip:"Peça os boquerones fritos premiados e uma taça de moscatel seco, direto no balcão do mercado.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"16:00",note:"Segue o horário do mercado; fecha à tarde e aos domingos. Melhor pela manhã e no aperitivo do meio-dia."},image:"mlg_el_yerno.jpg"},{id:"mlg_barra_zapata",categoryId:"tapas",city:"malaga",name:"La Barra de Zapata",tagline:"Tapas criativas de fusão no centro",description:"Bar de tapas pequeno e familiar junto à Plaza de la Constitución, com poucas mesas altas de barril na calçada. A cozinha cruza raiz andaluza com pinceladas latinas, italianas e asiáticas em porções de apresentação cuidada, com um carpaccio de fama local. O atendimento explica cada prato com calma, o que combina com um jantar sem pressa.",lat:36.72018,lng:-4.42089,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"La Barra de Zapata, Calle Salinas 10, Málaga",kingTip:"Peça o carpaccio da casa, a tapa que consagrou o balcão, acompanhado de uma taça de tinto.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"23:30",note:"Espaço pequeno; reserve nos fins de semana. Confirme o dia de descanso na baixa temporada."}},{id:"mlg_gorki",categoryId:"tapas",city:"malaga",name:"Gorki",tagline:"Vinhos e tapas gourmet na Strachan",description:"Casa de vinhos e tapas nascida em 1992 como loja gourmet na central Calle Strachan, a passos da Calle Larios. Equilibra taberna mediterrânea e bistrô refinado, com tapas espertas de produto fresco e uma carta de vinhos extensa. Tem terraço agradável para ver o vaivém do centro com um copo na mão.",lat:36.71963,lng:-4.42095,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Gorki, Calle Strachan 6, Málaga",kingTip:"Peça uma tábua de queijos e ibéricos com um vinho da carta, o forte da casa desde os tempos de loja gourmet.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Terraço disputado nos fins de semana; há uma segunda casa no porto (Muelle Uno)."},links:[{label:"Site oficial",url:"https://www.grupogorki.es"}]},{id:"cor_bodega_guzman",categoryId:"tapas",city:"cordoba",name:"Bodega Guzmán",tagline:"Fino do tonel na Judería cordovesa",description:"Bodega centenária escondida na Calle Judíos, no coração da Judería, a poucos passos da Sinagoga. Quase nada mudou desde que abriu: cartazes de touros, cabeças de toro na parede e enormes tonéis de onde saem o fino Amargoso e o oloroso da Sierra de Montilla, servidos direto do barril a preço de bairro. Tapas simples e baratas acompanham o vinho num ambiente sem concessões ao turismo.",lat:37.88036,lng:-4.78367,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bodega Guzmán, Calle Judíos 7, Córdoba",kingTip:"Peça um fino Amargoso do tonel com berinjelas em conserva ou chorizo ao vinho, a experiência mais autêntica da Judería.",priceLevel:"€",hours:{openDays:"Sex–Qua",openHour:"12:30",closeHour:"16:00",note:"Reabre à noite (20h–00h); fecha às quintas e à tarde entre serviços. Só dinheiro em muitas ocasiões."}},{id:"cor_sociedad_plateros",categoryId:"tapas",city:"cordoba",name:"Sociedad de Plateros María Auxiliadora",tagline:"Bacalhau e pátio cordovês desde 1868",description:"Taberna histórica do bairro de San Lorenzo, aberta em 1868 e tocada por gerações da mesma sociedade de artesãos. Em torno de um belo pátio andaluz de colunas, serve mais de trinta pratos de bacalhau que lhe valeram o apelido de La Posada del Bacalao, além de salmorejo, rabo de toro e flamenquines. Longe das rotas mais concorridas, é um clássico dos cordoveses.",lat:37.88913,lng:-4.76754,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Sociedad de Plateros María Auxiliadora, Calle María Auxiliadora 25, Córdoba",kingTip:"Peça o bacalhau em qualquer versão da casa e o salmorejo cordovês, sentado no pátio de colunas.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"23:30",note:"Fecha à tarde entre serviços; oferece opções sem glúten e vegetarianas. Confirme o descanso semanal."},links:[{label:"Site oficial",url:"https://www.sociedadplateros.com"}]},{id:"grn_taberna_la_tana",categoryId:"tapas",city:"granada",name:"Taberna La Tana",tagline:"Melhor bar de vinhos, no Realejo",description:"Taberna minúscula do bairro Realejo, fundada em 1993 e tocada pelo sommelier Jesús González, com as paredes forradas de garrafas do chão ao teto. Eleita melhor bar de vinhos da Espanha em 2020, mantém viva a tapa gratuita de Granada, aqui pareada a taças de vinho escolhidas a dedo e boas tábuas de queijos e embutidos. Íntima e calorosa, é ponto de peregrinação de quem gosta de vinho.",lat:37.17275,lng:-3.59609,durationLabel:"45 min–1,5 h",fit:"ANY",mapQuery:"Taberna La Tana, Placeta del Agua 3, Realejo, Granada",kingTip:"Peça uma taça e deixe o dono sugerir a tapa que combina; em Granada ela vem grátis com a bebida.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:30",closeHour:"23:30",note:"Espaço muito pequeno; costuma lotar à noite. Fecha à tarde entre serviços."},links:[{label:"Site oficial",url:"https://www.tabernalatana.com"}]},{id:"grn_bar_aliatar",categoryId:"tapas",city:"granada",name:"Bar Aliatar",tagline:"Caracoles e tapa grátis no Albaicín",description:"Bar de bairro na recolhida Plaza Aliatar, no alto do Albaicín, o quarteirão mouro de ruelas caiadas tombado pela UNESCO. Antiga parada de arrieiros, mantém o ritual granadino da tapa gratuita a cada bebida e é famoso pelos caracoles em caldo picante servidos na temporada. Terraço na praça e clientela local dão o tom despretensioso.",lat:37.18279,lng:-3.59132,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bar Aliatar, Plaza Aliatar 4, Albaicín, Granada",kingTip:"A tapa vem grátis com a bebida; no verão peça os caracoles em caldo picante, a especialidade da casa.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"23:30",note:"Os caracoles são sazonais (fim da primavera e verão); a subida ao Albaicín é íngreme."}},{id:"mrb_balcon_virgen",categoryId:"tapas",city:"marbella",name:"El Balcón de la Virgen",tagline:"Peixe frito sob a buganvília",description:"Taberna de 1978 num casarão dos séculos XVI–XVII no casco antigo de Marbella, a passos da Plaza de los Naranjos. A fachada some sob uma buganvília gigante e um balcão com capela da Virgem dá nome à casa. A cozinha mediterrânea brilha nas frituras de peixe fresco da Costa del Sol e nas carnes na brasa, servidas no ambiente caiado e florido da cidade velha.",lat:36.51098,lng:-4.88507,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"El Balcón de la Virgen, Calle Remedios 2, Marbella",kingTip:"Peça o pescaíto frito em azeite bem quente, a especialidade da casa, à sombra da buganvília.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:30",closeHour:"23:30",note:"Muito procurado no verão; as mesas sob a buganvília são as mais disputadas."},links:[{label:"Site oficial",url:"https://www.elbalcondelavirgen.com"}]},{id:"mrb_taberna_pintxo_fuengirola",categoryId:"tapas",city:"marbella",name:"La Taberna del Pintxo",tagline:"Pintxos bascos à beira-mar",description:"Taberna de conceito basco no centro de Fuengirola, pertinho do paseo marítimo, onde os pintxos desfilam no balcão espetados em fatias de pão. Serve-se à moda de San Sebastián: pega-se o que apetece e paga-se pelo número de palitos ao final, entre versões frias e quentes. Informal e divertido, funciona bem em grupo e para provar muitas coisas de uma vez.",lat:36.54038,lng:-4.62408,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"La Taberna del Pintxo, Calle Hermanos Pinzón, Fuengirola",kingTip:"Guarde os palitos: a conta sai pelo número de pintxos consumidos; peça também os quentes na hora.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"23:30",note:"Na Costa del Sol central (Fuengirola); enche na hora do aperitivo. Há casas do mesmo conceito em Marbella."}},{id:"mrb_bodega_quitapenas_torremolinos",categoryId:"tapas",city:"marbella",name:"Bodega Quitapenas (Torremolinos)",tagline:"Bodega de 1961 junto ao mar",description:"Bodega histórica na Cuesta del Tajo, a ladeira que desce ao mar em Torremolinos, aberta desde 1961. Barris de moscatel e uma barra farta de pescado servem pescaíto frito, polvo, tortillitas de camarão e conservas, no melhor estilo da tapa marinha malaguenha. Ambiente popular e de solera, a caminho da praia do Bajondillo.",lat:36.62206,lng:-4.49692,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bodega Quitapenas, Cuesta del Tajo 3, Torremolinos",kingTip:"Peça o pescaíto frito com uma taça do moscatel da casa, o Quitapenas, descendo para o Bajondillo.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"11:00",closeHour:"23:00",note:"Na Costa del Sol central (Torremolinos); a ladeira leva direto à praia do Bajondillo."}},{id:"trm_casco_cuesta_tajo",categoryId:"marbella",city:"marbella",name:"Casco Antiguo & Cuesta del Tajo de Torremolinos",tagline:"A ladeira histórica até o mar",description:"Poucos imaginam que a badalada Torremolinos guarda um casco antigo. Da Plaza Costa del Sol, a Calle San Miguel puxa o passeio pedonal até a Cuesta del Tajo, ladeira empedrada de casas caiadas que desce em degraus rumo à praia de El Bajondillo. É o Torremolinos anterior ao turismo de massa, com pátios floridos e a Torre de Pimentel guardando a memória mourisca.",lat:36.6205,lng:-4.4988,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Cuesta del Tajo, Torremolinos",kingTip:"Desça a Cuesta del Tajo até o fim: a ladeira termina no calçadão de El Bajondillo, com vista aberta para o mar e boas paradas de peixe frito.",priceLevel:"Gratuito (passeio)"},{id:"trm_pueblo_blanco",categoryId:"marbella",city:"marbella",name:"Pueblo Blanco de Torremolinos",tagline:"O recanto andaluz escondido no centro",description:"Um beco-praça cenográfico logo ao lado da Cuesta del Tajo, recriando um pueblo blanco em miniatura: cal imaculada, arcos, vasos azuis e trepadeiras concentrados num pátio íntimo. É a fotografia mais andaluza que Torremolinos oferece, a poucos passos do burburinho da Calle San Miguel. Parada curta, ideal para emendar com o casco antigo.",lat:36.6198,lng:-4.4972,durationLabel:"15–20 min",fit:"ANY",mapQuery:"Pueblo Blanco, Torremolinos",priceLevel:"Gratuito"},{id:"bnm_pueblo",categoryId:"marbella",city:"marbella",name:"Benalmádena Pueblo",tagline:"O casco branco no alto da montanha",description:"Enquanto a costa de Benalmádena ferve de turismo, o pueblo original resiste no alto da serra, com ruas caiadas, cantos floridos e a Plaza de España como coração. Dos miradouros do casco, como a Plaza de la Mezquita, abre-se um panorama que vai da baía inteira até Fuengirola. É o contraponto tranquilo e autêntico à agitação do litoral.",lat:36.5985,lng:-4.5697,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Benalmádena Pueblo",kingTip:"Suba de carro e estacione no alto: as ruas do casco são íngremes, e é dos miradouros do topo que sai a melhor vista da costa.",priceLevel:"Gratuito (passeio)"},{id:"bnm_estupa",categoryId:"marbella",city:"marbella",name:"Estupa de la Iluminación",tagline:"A maior estupa budista do Ocidente",description:"Erguida em 2003, esta estupa budista de 33 metros é a maior do mundo ocidental, plantada numa colina de Benalmádena com vista para o mar. O interior guarda uma sala de meditação decorada com murais e um grande Buda dourado, aberta ao público e gratuita. O contraste entre a arquitetura tibetana e a paisagem mediterrânea rende um dos passeios mais insólitos da costa.",lat:36.5882,lng:-4.5812,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Estupa de la Iluminación, Benalmádena",kingTip:"Vá ao fim da tarde: a luz dourada realça a estupa branca e a esplanada em frente vira mirante sobre toda a baía.",priceLevel:"Gratuito",hours:{note:"Ter–Dom ~10:00–14:00 e 16:00–20:00 (verão); seg fechado; confirmar"}},{id:"fgr_plaza_constitucion",categoryId:"marbella",city:"marbella",name:"Plaza de la Constitución de Fuengirola",tagline:"O coração pedonal da cidade velha",description:"A praça-mãe de Fuengirola, ladeada pela Igreja de Nuestra Señora del Rosario e por casarios brancos com esplanadas, é o ponto de encontro do casco antigo. Palmeiras, fonte central e um vaivém constante de vizinhos e turistas dão o tom mediterrâneo; das vielas ao redor partem as ruas de tapas mais animadas. É a base natural para conhecer a Fuengirola de sempre, longe dos arranha-céus da praia.",lat:36.5397,lng:-4.6252,durationLabel:"45 min – 1 h",fit:"ANY",mapQuery:"Plaza de la Constitución, Fuengirola",priceLevel:"Gratuito (passeio)"},{id:"fgr_paseo_maritimo",categoryId:"marbella",city:"marbella",name:"Paseo Marítimo Rey de España",tagline:"Sete quilômetros de calçadão à beira-mar",description:"Um dos calçadões mais longos da Andaluzia, o Paseo Marítimo Rey de España estende-se por cerca de 7 km ao longo de toda a orla de Fuengirola, ladeado de palmeiras, esculturas, praças e esplanadas. É onde a cidade caminha, pedala e vê o pôr do sol, ligando o Castillo Sohail ao porto num percurso plano e contínuo. Passeio urbano à beira-mar, ideal ao amanhecer ou no fim da tarde.",lat:36.5375,lng:-4.623,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Paseo Marítimo Rey de España, Fuengirola",priceLevel:"Gratuito"},{id:"mrb_jardines_muralla_mijas",categoryId:"marbella",city:"marbella",name:"Jardines de la Muralla & Mirador de Mijas",tagline:"Os terraços floridos sobre o Mediterrâneo",description:"Escalonados sobre os restos da antiga muralha árabe de Mijas, estes jardins de canteiros floridos, fontes e pérgulas culminam num mirante que se debruça sobre toda a Costa del Sol. Em dias claros a vista alcança de Fuengirola a Gibraltar e, ao longe, a costa africana. É o melhor ponto panorâmico da vila branca, a poucos passos da Plaza de Toros oval.",lat:36.596,lng:-4.6378,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"Jardines de la Muralla, Mijas Pueblo",kingTip:"Reserve o mirante para um dia sem bruma: só com o céu limpo a linha da costa africana aparece no horizonte.",priceLevel:"Gratuito"},{id:"axq_comares",categoryId:"axarquia",city:"axarquia",name:"Comares",tagline:"O balcão da Axarquía no alto da serra",description:'Empoleirada a mais de 700 metros no topo de um morro, Comares é apelidada de "balcón de la Axarquía" pela vista de 360º que domina toda a comarca até o mar. O casco de origem andalusí é um labirinto de becos brancos que se sobe seguindo pegadas de cerâmica cravadas no chão, a Ruta de la Villa, até os restos do antigo castelo e a igreja de la Encarnación. Uma das vilas mais espetaculares e menos visitadas do leste da província.',lat:36.8378,lng:-4.236,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",mapQuery:"Comares, Málaga",kingTip:"Siga as pegadas de cerâmica no chão: elas traçam a Ruta de la Villa pelos becos até o mirante do castelo, o ponto mais alto e panorâmico.",priceLevel:"Gratuito"},{id:"axq_canillas_aceituno",categoryId:"axarquia",city:"axarquia",name:"Canillas de Aceituno",tagline:"Vila branca na saia da Maroma",description:"Encravada na encosta sul da Sierra de Tejeda, aos pés do pico La Maroma, Canillas de Aceituno conserva um casco mourisco de ruas íngremes e a Casa de los Diezmos, com portal mudéjar. É porta de entrada para uma das rotas mais famosas da comarca, a Ruta de la Cueva de la Fájara, e terra do embutido de morcilla celebrado em festa própria. Ambiente serrano autêntico, com o vale e o mar ao fundo.",lat:36.8763,lng:-4.0533,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Canillas de Aceituno, Málaga",kingTip:"Reserve energia para as ruas: o desnível é forte. Deixe o carro na parte baixa e suba a pé até a igreja para a melhor vista da serra.",priceLevel:"Gratuito"},{id:"axq_alcaucin_zalia",categoryId:"axarquia",city:"axarquia",name:"Alcaucín & Castillo de Zalia",tagline:"As ruínas árabes no portão da serra",description:"A vila branca de Alcaucín, de fontes e ruas floridas, guarda no seu termo uma das ruínas mais lendárias da Axarquía: o Castillo de Zalia, fortaleza árabe erguida sobre uma povoação anterior, no desfiladeiro que abre caminho para o Boquete de Zafarraya. Restam muralhas e torres semiderruídas num promontório de vistas amplas sobre o vale. Sítio histórico e cenário de mil lendas mouras.",lat:36.9039,lng:-4.143,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Castillo de Zalia, Alcaucín",kingTip:"As ruínas ficam fora do casco, junto à A-402; combine a parada com uma volta pela vila de Alcaucín e suas fontes.",priceLevel:"Gratuito"},{id:"axq_cutar",categoryId:"axarquia",city:"axarquia",name:"Cútar",tagline:"Vila moura da rota da passa e do vinho",description:"Pequeno povoado de origem andalusí sobre o vale do rio Cútar, com um casco de becos brancos que quase não mudou desde o tempo mourisco. Guarda a Fuente Árabe medieval e a igreja da Encarnación, e é parada da Ruta Mudéjar e da Ruta de la Pasa, ligada à uva moscatel seca ao sol. No mês da passa, em setembro, a vila revive as tradições de colheita.",lat:36.831,lng:-4.2288,durationLabel:"45 min – 1 h",fit:"ANY",mapQuery:"Cútar, Málaga",priceLevel:"Gratuito"},{id:"axq_macharaviaya",categoryId:"axarquia",city:"axarquia",name:"Macharaviaya",tagline:"A pequena vila dos Gálvez",description:'Diminuta e tranquila, Macharaviaya teve um passado grandioso no século XVIII graças à família Gálvez, cujo membro Bernardo foi governador da Luisiana e ajudou na independência dos Estados Unidos. Do apogeu restam a monumental igreja de San Jacinto, o panteão familiar e o traçado nobre que rendeu o apelido de "pequeno El Escorial". Vila de becos brancos e silêncio, cercada de olivais e vinhas.',lat:36.7597,lng:-4.2108,durationLabel:"45 min – 1 h",fit:"ANY",mapQuery:"Macharaviaya, Málaga",kingTip:"A ligação histórica com os EUA é levada a sério: em anos ímpares, a vila encena a Batalha de Pensacola em festa própria.",priceLevel:"Gratuito"},{id:"axq_canillas_albaida",categoryId:"axarquia",city:"axarquia",name:"Canillas de Albaida",tagline:"Casario branco no portal da Almijara",description:"Vizinha de Cómpeta e igualmente debruçada sobre a Sierra de Almijara, Canillas de Albaida é um casco caiado de ruas estreitas coroado pela igreja de la Expectación e pela pitoresca ermita de San Antón, na entrada da vila. É um dos acessos ao Parque Natural das Sierras Tejeda, Almijara y Alhama, com trilhas e um antigo lavadouro. Menos visitada que a vizinha, guarda o ritmo pausado das aldeias do vinho.",lat:36.8422,lng:-3.977,durationLabel:"45 min – 1 h",fit:"ANY",mapQuery:"Canillas de Albaida, Málaga",kingTip:"Combine no mesmo roteiro com Cómpeta, a 2 km, e com o alminar de Árchez: as três ficam encadeadas pela estrada do vale.",priceLevel:"Gratuito"},{id:"cdz_catedral",categoryId:"cadiz",city:"cadiz",name:"Catedral de Cádiz",tagline:"A catedral dourada de frente para o Atlântico",description:'Erguida ao longo de mais de um século, a "Catedral Nueva" mistura barroco e neoclássico e é coroada por uma cúpula de telhas amarelas que reluz sobre a cidade e o mar. O interior guarda a cripta onde repousa o compositor Manuel de Falla, e a subida à Torre del Reloj abre um dos melhores panoramas do casco antigo. Fica na Plaza de la Catedral, coração da Cádiz monumental.',lat:36.5296,lng:-6.2985,durationLabel:"1–1,5 h",fit:"INDOOR",mapQuery:"Catedral de Cádiz",kingTip:"Pague o ingresso da Torre del Reloj: do alto se vê a cúpula amarela e o casario branco emoldurados pelo Atlântico dos dois lados.",priceLevel:"€€ (entrada com torre)",links:[{label:"Catedral de Cádiz – site oficial",url:"https://catedraldecadiz.com/"}]},{id:"cdz_torre_tavira",categoryId:"cadiz",city:"cadiz",name:"Torre Tavira & Câmara Escura",tagline:"A torre-vigia com a câmara escura da cidade",description:"A mais alta das antigas torres-vigia de Cádiz, a 45 metros sobre o nível do mar, foi ponto de observação dos navios no auge do comércio com as Américas. Hoje abriga uma câmara escura que projeta imagens ao vivo da cidade em tempo real numa tela côncava, guiada por um narrador. Do terraço, vê-se todo o labirinto de torres-miradouro que marcam o casco antigo.",lat:36.5306,lng:-6.2971,durationLabel:"45 min – 1 h",fit:"INDOOR",mapQuery:"Torre Tavira, Cádiz",kingTip:"As sessões da câmara escura têm horário marcado e lotam: chegue cedo e reserve a sessão antes de subir ao terraço.",priceLevel:"€€",links:[{label:"Torre Tavira – site oficial",url:"https://www.torretavira.com/"}]},{id:"cdz_barrio_populo",categoryId:"cadiz",city:"cadiz",name:"Barrio del Pópulo",tagline:"O núcleo medieval mais antigo da cidade",description:"O Pópulo é o bairro mais antigo de Cádiz, o único que conserva o traçado medieval dentro dos antigos muros, com três arcos que sobreviveram das portas da cidade. Entre becos estreitos afloram o Teatro Romano, escondido sob as casas, e a Casa del Obispo, além de esplanadas animadas ao redor da catedral. É o coração histórico da cidade, ideal de se percorrer a pé sem pressa.",lat:36.5292,lng:-6.2955,durationLabel:"1 h",fit:"ANY",mapQuery:"Barrio del Pópulo, Cádiz",kingTip:"Entre pelo Arco de la Rosa, junto à catedral, e procure a entrada do Teatro Romano: a visita às ruínas é gratuita.",priceLevel:"Gratuito (passeio)"},{id:"cdz_caleta_san_sebastian",categoryId:"cadiz",city:"cadiz",name:"La Caleta & Castillo de San Sebastián",tagline:"A praia enseada entre dois castelos",description:"Encaixada entre os castelos de Santa Catalina e San Sebastián, La Caleta é a praia urbana mais fotogênica de Cádiz, uma pequena enseada de areia dourada com o balneário modernista La Palma ao centro. Do castelo de San Sebastián, alcançado por um longo molhe sobre o mar, descortina-se toda a baía e o casario. É cenário de filmes e o ponto mais celebrado para o pôr do sol atlântico da cidade.",lat:36.529,lng:-6.3053,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Playa de La Caleta, Cádiz",kingTip:"Percorra o molhe até o Castillo de San Sebastián ao entardecer: é dali, com o mar dos dois lados, que sai o melhor pôr do sol da cidade.",priceLevel:"Gratuito"},{id:"cdz_playa_victoria",categoryId:"cadiz",city:"cadiz",name:"Playa de la Victoria",tagline:"O extenso areal urbano da cidade nova",description:"Estendendo-se por cerca de 3 km ao longo da Cádiz moderna, a Playa de la Victoria é uma das melhores praias urbanas da Espanha, de areia fina e clara e águas atlânticas abertas. Bem estruturada, com calçadão, chiringuitos e serviços, é onde a cidade toma sol e joga futebol de praia. O vento e a maré mais fortes que os do Mediterrâneo dão o tom autenticamente atlântico do banho.",lat:36.5093,lng:-6.2657,durationLabel:"2–3 h",fit:"CLEAR_SKY",mapQuery:"Playa de la Victoria, Cádiz",kingTip:"Fica na cidade nova, longe do casco antigo: vá de ônibus ou táxi e emende com um almoço de pescado num chiringuito do calçadão.",priceLevel:"Gratuito"},{id:"jrz_alcazar",categoryId:"cadiz",city:"cadiz",name:"Alcázar de Jerez",tagline:"A fortaleza almóada com câmara escura",description:"Fortaleza-palácio do século XII erguida pelos almóadas, o Alcázar de Jerez é um dos exemplos mais bem conservados da arquitetura militar islâmica da Andaluzia. Dentro das muralhas guardam-se uma mesquita convertida em capela, banhos árabes, jardins perfumados e um moinho de azeite. A torre octogonal abriga outra câmara escura, com vistas em tempo real sobre a colegiata e os telhados de Jerez.",lat:36.6789,lng:-6.1409,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Alcázar de Jerez de la Frontera",kingTip:"O ingresso pode incluir a câmara escura da torre: confira os horários das sessões na bilheteria ao entrar.",priceLevel:"€€"},{id:"jrz_bodega_tio_pepe",categoryId:"cadiz",city:"cadiz",name:"Bodegas Tío Pepe (González Byass)",tagline:"As catedrais do vinho onde nasce o xerez",description:'No coração de Jerez, as históricas Bodegas González Byass abrigam a marca Tío Pepe, ícone mundial do fino. A visita guiada percorre as "catedrais do vinho", naves altíssimas de barris empilhados assinados por celebridades, o famoso trenzinho entre as adegas e a degustação de xerez direto do tonel. É a forma mais completa de entender a criança do vinho fortificado que só existe neste triângulo.',lat:36.6798,lng:-6.1428,durationLabel:"1,5–2 h",fit:"INDOOR",mapQuery:"Bodegas Tío Pepe, Jerez de la Frontera",kingTip:"Reserve a visita com degustação online e escolha a sessão em português ou espanhol: as guiadas incluem prova de vários tipos de xerez.",priceLevel:"€€–€€€",links:[{label:"Bodegas Tío Pepe – visitas",url:"https://www.bodegastiopepe.com/"}]},{id:"jrz_real_escuela_ecuestre",categoryId:"cadiz",city:"cadiz",name:"Real Escuela Andaluza del Arte Ecuestre",tagline:"O balé equestre dos cavalos que dançam",description:'Instituição de fama mundial, a Real Escuela é onde se preserva a arte do cavalo andaluz de pura raça espanhola. O espetáculo "Cómo bailan los caballos andaluces" leva cavalos e cavaleiros a uma coreografia de doma clássica ao som de música espanhola, num picadeiro palaciano. Nos dias sem show, visitam-se os treinos, as cavalariças, a guarnição de arreios e os jardins da fundação.',lat:36.6873,lng:-6.1362,durationLabel:"2–2,5 h",fit:"INDOOR",mapQuery:"Real Escuela Andaluza del Arte Ecuestre, Jerez",kingTip:"O espetáculo com os cavalos dançantes é só em dias marcados (em geral terças e quintas): confira o calendário e reserve com antecedência.",priceLevel:"€€–€€€",links:[{label:"Real Escuela – site oficial",url:"https://www.realescuela.org/"}]},{id:"trf_casco_puerta_jerez",categoryId:"cadiz",city:"cadiz",name:"Casco Antiguo & Puerta de Jerez de Tarifa",tagline:"A vila murada onde dois mares se encontram",description:"Tarifa é o ponto continental mais ao sul da Europa, e seu casco antigo mourisco de ruas estreitas e caiadas se entra pela monumental Puerta de Jerez, único acesso que resta das antigas muralhas. Dentro, becos floridos, a igreja de San Mateo e um clima de kitesurf e ventos convivem com a herança medieval. A cidade olha ao mesmo tempo para o Atlântico e o Mediterrâneo, com a costa africana no horizonte.",lat:36.0128,lng:-5.6063,durationLabel:"1,5–2 h",fit:"ANY",mapQuery:"Puerta de Jerez, Tarifa",kingTip:"Entre pela Puerta de Jerez e siga até o Mirador del Estrecho, na muralha: em dias claros a costa de Marrocos aparece nítida do outro lado.",priceLevel:"Gratuito (passeio)"},{id:"trf_bolonia_baelo_claudia",categoryId:"cadiz",city:"cadiz",name:"Playa de Bolonia & Baelo Claudia",tagline:"Ruínas romanas ao pé de uma duna gigante",description:"Uma das praias mais espetaculares do sul, Bolonia combina areal virgem, águas transparentes e uma enorme duna de areia branca, monumento natural, que se pode subir. Ao lado, o conjunto arqueológico de Baelo Claudia preserva uma cidade romana quase completa — fórum, basílica, teatro e as fábricas de garum — de frente para o mar. Natureza e história num dos cenários mais fotogênicos da província de Cádiz.",lat:36.0897,lng:-5.7745,durationLabel:"2–3 h",fit:"CLEAR_SKY",mapQuery:"Conjunto Arqueológico Baelo Claudia, Bolonia",kingTip:"A entrada em Baelo Claudia é gratuita para cidadãos da UE; para brasileiros costuma ser paga e barata. Leve água: não há sombra entre as ruínas.",priceLevel:"€ (sítio); praia gratuita",links:[{label:"Conjunto Arqueológico Baelo Claudia",url:"https://www.juntadeandalucia.es/cultura/enclaves/conjunto-arqueologico-baelo-claudia"}]},{id:"trf_isla_palomas",categoryId:"cadiz",city:"cadiz",name:"Isla de las Palomas",tagline:"O ponto mais ao sul da Europa continental",description:"Ligada a Tarifa por um istmo artificial, a Isla de las Palomas marca o extremo sul do continente europeu, exatamente onde o Atlântico e o Mediterrâneo se tocam. O istmo separa duas praias, e uma placa assinala a divisa simbólica dos dois mares. A ilha em si é recinto militar de acesso restrito, mas o passeio pelo istmo e o marco geográfico rendem a foto obrigatória de Tarifa.",lat:36.0024,lng:-5.6086,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Isla de las Palomas, Tarifa",kingTip:"Caminhe pelo istmo até a placa que separa Atlântico e Mediterrâneo: a ilha fortificada não se visita, mas o marco dos dois mares é livre.",priceLevel:"Gratuito"},{id:"vejer_frontera",categoryId:"cadiz",city:"cadiz",name:"Vejer de la Frontera",tagline:"A vila branca no alto da colina",description:"Considerada uma das vilas mais bonitas da Espanha, Vejer se agarra a uma colina numa massa compacta de casas caiadas, coroada por muralhas e por um castelo mourisco. Seu labirinto de becos, arcos e pátios andaluzes esconde miradouros que se abrem sobre a campina de La Janda até o mar. O casco preserva a Judería, a igreja gótico-mudéjar do Salvador e um ambiente pausado de doçarias e restaurantes de charme.",lat:36.2517,lng:-5.9663,durationLabel:"2–3 h",fit:"ANY",mapQuery:"Vejer de la Frontera, Cádiz",kingTip:"Estacione fora das muralhas e suba a pé: o casco é íngreme e de ruas estreitíssimas. Procure os miradouros da Cobijada para as melhores vistas.",priceLevel:"Gratuito (passeio)"},{id:"puerto_santa_maria",categoryId:"cadiz",city:"cadiz",name:"El Puerto de Santa María",tagline:"A cidade das adegas e do castelo templário",description:"Do outro lado da baía de Cádiz, El Puerto de Santa María foi porto das Índias e terra de adegas centenárias, entre elas a icônica Osborne, do touro-símbolo. O Castillo de San Marcos, fortaleza-igreja de origem medieval, e a Plaza de Toros monumental dividem o roteiro com o barrio das bodegas e as marisquerías da Ribera del Marisco. Chega-se de Cádiz pelo tradicional catamarã ou vapor que cruza a baía.",lat:36.5983,lng:-6.2331,durationLabel:"2–3 h",fit:"ANY",mapQuery:"Castillo de San Marcos, El Puerto de Santa María",kingTip:"Vá de Cádiz no catamarã da baía: são cerca de 30 minutos de travessia e desembarca-se a poucos passos do centro e das bodegas.",priceLevel:"Gratuito (passeio); adegas €€"},{id:"sanlucar_barrameda",categoryId:"cadiz",city:"cadiz",name:"Sanlúcar de Barrameda",tagline:"A manzanilla e as corridas na praia",description:"Na foz do Guadalquivir, de frente para o parque de Doñana, Sanlúcar é a pátria da manzanilla, o xerez seco que só amadurece neste ar salino. O Barrio Alto guarda o palácio dos duques de Medina Sidonia e bodegas históricas, enquanto a Bajo de Guía enfileira marisquerías célebres pelos langostinos. No verão, a praia recebe as tradicionais corridas de cavalos, patrimônio único da cidade.",lat:36.7785,lng:-6.353,durationLabel:"2–3 h",fit:"ANY",mapQuery:"Sanlúcar de Barrameda, Cádiz",kingTip:"Almoce langostinos na Bajo de Guía com vista para Doñana e prove a manzanilla local: o vinho combina de propósito com o marisco da foz.",priceLevel:"Gratuito (passeio); adegas €€"},{id:"gib_upper_rock",categoryId:"gibraltar",city:"gibraltar",name:"Upper Rock Nature Reserve",tagline:"O coração selvagem do Rochedo",description:"A reserva natural que ocupa o alto do Rochedo reúne quase todas as atrações icônicas de Gibraltar num só bilhete: cavernas, túneis, o castelo mouro, miradouros e os famosos macacos. Trilhas e estradinhas ligam os pontos entre penhascos calcários com vista para dois continentes. É o passeio-âncora de qualquer bate-volta ao território britânico.",lat:36.135,lng:-5.345,durationLabel:"3–4 h",fit:"CLEAR_SKY",mapQuery:"Upper Rock Nature Reserve, Gibraltar",kingTip:"Leve o passaporte: cruzar a fronteira do Reino Unido é obrigatório, e a pé você atravessa a própria pista do aeroporto. O bilhete único da reserva já cobre gruta, túneis e castelo, então compre uma vez e aproveite tudo.",priceLevel:"£19 adulto (estimativa; bilhete único da reserva)",hours:{note:"Verão (mai–set) ~9:30–19:00; confirmar no acesso"},links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/upper-rock-nature-reserve"}]},{id:"gib_apes_den",categoryId:"gibraltar",city:"gibraltar",name:"Apes' Den & Macacos de Berbéria",tagline:"Os únicos macacos selvagens da Europa",description:"Gibraltar é o único lugar da Europa onde vivem macacos em liberdade: cerca de 230 macacos-de-berbéria habitam o Rochedo, e o Apes' Den é o ponto clássico para vê-los de perto. Ágeis e curiosos, transitam entre muretas e turistas sem qualquer cerca. Um encontro divertido, mas que pede respeito à distância.",lat:36.1339,lng:-5.3475,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Apes' Den, Gibraltar",kingTip:"Nunca alimente nem mostre comida: os macacos abrem mochilas e sacolas em segundos, e alimentá-los dá multa. Guarde óculos, celular e lanches antes de chegar perto.",priceLevel:"Incluído no bilhete da reserva",links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/apes-den-barbary-macaques"}]},{id:"gib_st_michaels_cave",categoryId:"gibraltar",city:"gibraltar",name:"St. Michael's Cave",tagline:"A catedral de estalactites do Rochedo",description:"Esta gruta calcária no interior do Rochedo impressiona pelo salão principal, tomado por estalactites e estalagmites e iluminado por um espetáculo de luzes coloridas. Usado como auditório de concertos desde os anos 1950, o espaço tem acústica notável e é a atração fechada mais visitada de Gibraltar. Refúgio perfeito quando o tempo fecha lá fora.",lat:36.1246,lng:-5.3436,durationLabel:"45 min",fit:"INDOOR",mapQuery:"St. Michael's Cave, Gibraltar",kingTip:"Como é abrigada e fresca, deixe a gruta para as horas de mais calor ou de céu nublado, aproveitando os miradouros ao ar livre quando o sol estiver aberto.",priceLevel:"Incluído no bilhete da reserva",hours:{note:"Verão ~9:30–19:00 (via reserva); confirmar"},links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/st-michaels-cave"}]},{id:"gib_europa_point",categoryId:"gibraltar",city:"gibraltar",name:"Europa Point",tagline:"A ponta sul, com a África no horizonte",description:"No extremo meridional de Gibraltar, o Estreito estreita-se a apenas 14 km e, em dias claros, revela em detalhe as montanhas do Rif marroquino do outro lado do mar. O promontório reúne o farol da Trinity House, a mesquita Ibrahim-al-Ibrahim e uma esplanada aberta ao vento onde Mediterrâneo e Atlântico se encontram. Um dos panoramas mais dramáticos do território.",lat:36.1088,lng:-5.3435,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Europa Point, Gibraltar",kingTip:"Vá num dia limpo e sem bruma: é a diferença entre ver a costa africana nitidamente ou apenas uma linha no horizonte. De manhã cedo o ar costuma estar mais transparente.",priceLevel:"Gratuito (acesso livre)",links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/europa-point"}]},{id:"gib_great_siege_tunnels",categoryId:"gibraltar",city:"gibraltar",name:"Great Siege Tunnels",tagline:"A fortaleza escavada dentro da rocha",description:"Escavados na rocha viva durante o Grande Cerco de 1779–1783, com pouco mais que pólvora e ferramentas simples, estes túneis foram cravados para posicionar canhões contra as tropas franco-espanholas. Percorrer as galerias com aberturas voltadas para o norte é uma aula de engenharia militar e um dos capítulos mais fascinantes da história de Gibraltar. Fresco e abrigado o ano todo.",lat:36.1452,lng:-5.345,durationLabel:"45 min",fit:"INDOOR",mapQuery:"Great Siege Tunnels, Gibraltar",kingTip:"Das seteiras dos canhões abre-se uma vista rasante sobre o istmo e o aeroporto: bom lugar para entender, de cima, por que a pista corta a única estrada de acesso ao território.",priceLevel:"Incluído no bilhete da reserva",links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/great-siege-tunnels"}]},{id:"gib_moorish_castle",categoryId:"gibraltar",city:"gibraltar",name:"Castelo Mouro (Moorish Castle)",tagline:"A Torre da Homenagem sobre a cidade",description:"Erguido a partir do século XII, o Castelo Mouro domina a encosta norte com sua imponente Torre da Homenagem, ainda marcada por impactos de antigos cercos. É a mais antiga estrutura mourisca visível de Gibraltar e um dos símbolos do território. Da muralha, a vista alcança a baía, o istmo e a Espanha logo ali.",lat:36.1443,lng:-5.3513,durationLabel:"30–40 min",fit:"ANY",mapQuery:"Moorish Castle, Gibraltar",kingTip:"Combine com os Great Siege Tunnels: ambos ficam na encosta norte da reserva e se visitam na mesma subida, sem retorno até o centro.",priceLevel:"Incluído no bilhete da reserva",links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/moorish-castle"}]},{id:"gib_main_street",categoryId:"gibraltar",city:"gibraltar",name:"Main Street",tagline:"Compras duty-free entre cabines vermelhas",description:"A artéria comercial de Gibraltar é um pedaço de Reino Unido no Mediterrâneo: pubs, cabines telefônicas vermelhas, fachadas georgianas e lojas isentas de impostos que atraem quem busca perfumes, eletrônicos, tabaco e bebidas a preços vantajosos. A Casemates Square, numa ponta, concentra restaurantes e mesas ao ar livre. Passeio ideal para começar ou fechar o dia.",lat:36.1408,lng:-5.3535,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Main Street, Gibraltar",kingTip:"As lojas são duty-free, mas a moeda oficial é a libra (£); o euro é aceito, só que o câmbio no balcão costuma ser pior. Pague em libra ou no cartão para não perder na conversão.",priceLevel:"Variável (£/GBP; compras isentas de imposto)",hours:{note:"Lojas geralmente seg–sáb ~10:00–19:00; domingos reduzido; confirmar"},links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/shopping"}]},{id:"gib_skywalk",categoryId:"gibraltar",city:"gibraltar",name:"Skywalk Gibraltar",tagline:"Piso de vidro a 340 metros de altura",description:"Encravada no alto do Rochedo, esta plataforma de vidro projeta o visitante sobre o vazio a 340 metros acima do mar, com vista de 360 graus que alcança Espanha, o Estreito e a África em dias claros. Construída sobre uma antiga posição militar, é uma das atrações mais recentes e vertiginosas do território. Emoção garantida para quem não teme altura.",lat:36.1288,lng:-5.3448,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"Skywalk Gibraltar",kingTip:"Vá cedo, antes dos ônibus de excursão: a plataforma é compacta e, cheia, fica difícil conseguir a foto sobre o vidro com a paisagem limpa ao fundo.",priceLevel:"Incluído no bilhete da reserva",links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/skywalk"}]},{id:"gib_ohara_battery",categoryId:"gibraltar",city:"gibraltar",name:"O'Hara's Battery",tagline:"O ponto mais alto do Rochedo",description:"No cume de Gibraltar, a 426 metros, esta bateria de artilharia guarda um enorme canhão que outrora defendia o Estreito. É o ponto mais alto acessível do Rochedo, com panorama absoluto sobre a cidade, a baía, o Mediterrâneo e o Atlântico ao mesmo tempo. Vista de tirar o fôlego, literalmente, dado o vento constante no topo.",lat:36.1238,lng:-5.3429,durationLabel:"30 min",fit:"CLEAR_SKY",mapQuery:"O'Hara's Battery, Gibraltar",kingTip:"Leve corta-vento mesmo no verão: no cume o vento é forte e a temperatura cai bastante em relação ao nível do mar.",priceLevel:"Incluído no bilhete da reserva",links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/oharas-battery"}]},{id:"gib_windsor_bridge",categoryId:"gibraltar",city:"gibraltar",name:"Windsor Suspension Bridge",tagline:"A ponte suspensa sobre a ravina",description:"Esta passarela suspensa de 71 metros cruza uma profunda ravina no flanco do Rochedo, oferecendo uma travessia balançante com vista para a baía e a costa espanhola. Rodeada de vegetação mediterrânea, integra o circuito de trilhas da reserva e liga-se facilmente ao Skywalk. Curta, mas memorável para quem gosta de emoção com paisagem.",lat:36.1298,lng:-5.3458,durationLabel:"15–20 min",fit:"CLEAR_SKY",mapQuery:"Windsor Suspension Bridge, Gibraltar",kingTip:"Emende com o Skywalk, a poucos minutos de caminhada: os dois ficam no mesmo trecho da encosta oeste e rendem as melhores fotos com a baía ao fundo.",priceLevel:"Incluído no bilhete da reserva",links:[{label:"Visit Gibraltar (oficial)",url:"https://www.visitgibraltar.gi/see-and-do/windsor-bridge"}]},{id:"gib_alameda_gardens",categoryId:"gibraltar",city:"gibraltar",name:"Alameda Botanic Gardens",tagline:"O jardim botânico junto ao centro",description:"Desenhados em 1816 e ligados historicamente aos Kew Gardens de Londres, os Jardins Botânicos da Alameda são um oásis de espécies mediterrâneas e subtropicais a poucos passos do centro. Caminhos sombreados, esculturas e miradouros fazem dele uma pausa tranquila e gratuita, longe das filas das atrações do alto. Bom para descansar as pernas entre um passeio e outro.",lat:36.1358,lng:-5.3502,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Gibraltar Botanic Gardens, The Alameda",kingTip:"Fica na parte baixa, perto da estação inferior do teleférico e do centro: encaixa bem no fim do dia, antes de voltar à fronteira, sem precisar subir o Rochedo de novo.",priceLevel:"Gratuito (entrada livre)",hours:{note:"Diariamente ~8:00 ao anoitecer; confirmar"},links:[{label:"The Alameda (oficial)",url:"https://www.gibraltargardens.gi/"}]},{id:"mlg_ac_palacio_atico",categoryId:"tapas",city:"malaga",name:"Ático — AC Hotel Málaga Palacio",tagline:"rooftop mais alto, vista do porto",description:"No 15º andar do histórico AC Hotel Málaga Palacio, este é o rooftop mais alto da cidade, com vista de 360° sobre a catedral, o porto e o Mediterrâneo. À noite, o terraço com piscina vira palco de coquetéis de autor e música ambiente, num dos pores do sol mais concorridos de Málaga. Ambiente elegante e adulto, ideal para abrir a noite com calma.",lat:36.719173,lng:-4.419542,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"Ático Rooftop AC Hotel Málaga Palacio, Calle Cortina del Muelle 1, Málaga",kingTip:"Suba antes do pôr do sol e peça um gin-tônica de autor no parapeito voltado para a catedral; nos fins de semana vale reservar mesa.",priceLevel:"€€€ (coquetel ~€14 est.)",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"01:00",note:"Aberto ao público, não só a hóspedes. Horários encurtam fora da alta temporada; confirme na hora."}},{id:"mlg_the_top_molina_lario",categoryId:"tapas",city:"malaga",name:"The Top — Molina Lario",tagline:"coquetéis frente à catedral",description:"Rooftop do elegante Hotel Molina Lario, a poucos passos da catedral, com terraço no alto e vista aberta sobre a Manquita, o porto e os telhados do centro. A casa é conhecida pelos coquetéis criativos, cheios de texturas e aromas, servidos com tapas finas e música ao vivo em noites selecionadas. Um clássico sofisticado para brindar com a catedral iluminada ao fundo.",lat:36.719151,lng:-4.42021,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"The Top Rooftop, Hotel Molina Lario, Calle Molina Lario 22, Málaga",kingTip:"Peça um coquetel de autor da carta e garanta lugar no lado voltado para a catedral, o melhor ângulo da casa.",priceLevel:"€€€ (coquetel ~€14 est.)",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"01:00",note:"Terraço disputado ao entardecer; reserve nos fins de semana. Confirme os horários na baixa temporada."},links:[{label:"Hotel Molina Lario",url:"https://www.cataloniahotels.com/en/hotel/catalonia-molina-lario"}]},{id:"mlg_batik_terraza_alcazaba",categoryId:"tapas",city:"malaga",name:"Batik — Terraza de Alcazaba",tagline:"rooftop com vista da Alcazaba",description:"No último andar do Alcazaba Premium Hotel, na Calle Alcazabilla, o terraço chill-out do Batik tem uma das melhores vistas panorâmicas da Alcazaba, do Teatro Romano e do castelo de Gibralfaro. Dividido em dois níveis, serve coquetéis preparados por bartenders e petiscos mediterrâneos num clima descontraído e sofisticado. É o ponto certo para prolongar a noite com um dos cenários mais bonitos do centro histórico.",lat:36.722263,lng:-4.417045,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"Batik Terraza de Alcazaba, Calle Alcazabilla 12, Málaga",kingTip:"Peça um coquetel e fique no nível superior voltado para a Alcazaba iluminada; o pôr do sol sobre a fortaleza é o momento a não perder.",priceLevel:"€€€ (coquetel ~€13 est.)",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"00:00",note:"Terraço pequeno e muito procurado; reserve no verão. Horários variam com a estação."},links:[{label:"Hotel Alcazaba Premium",url:"https://www.hotelalcazabapremium.com/en/malaga-restaurant/"}]},{id:"mlg_terraza_larios",categoryId:"tapas",city:"malaga",name:"La Terraza de Larios",tagline:"rooftop no topo da Calle Larios",description:"No alto do Hotel Larios, na famosa Calle Marqués de Larios, este rooftop estiloso tem bar de mosaico, teto retrátil e vista para a catedral e os telhados do centro. Coquetéis bem executados, som ambiente e um público animado fazem dele uma das varandas mais glamourosas de Málaga. O teto móvel garante o programa em qualquer época do ano.",lat:36.720658,lng:-4.42186,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"La Terraza de Larios, Calle Marqués de Larios 2, Málaga",kingTip:"Entre pela recepção do hotel na Calle Larios e suba de elevador; peça a mesa junto ao parapeito com vista para a catedral.",priceLevel:"€€€ (coquetel ~€14 est.)",hours:{openDays:"Todos os dias",openHour:"14:00",closeHour:"02:00",note:"Fecha mais cedo de domingo a quinta (por volta de 00:30–01:00). Aberto ao público, walk-ins bem-vindos."}},{id:"mlg_the_pharmacy_speakeasy",categoryId:"tapas",city:"malaga",name:"The Pharmacy — Speakeasy",tagline:"coctelería de autor semiescondida",description:"Speakeasy semiescondido no centro de Málaga, com estética de botica antiga e uma carta de coquetéis de autor organizada como um herbário, cheia de destilados botânicos e criações fora do comum. Premiado como uma das melhores coctelerías novas da Espanha no concurso World Class, é um espaço íntimo, com jazz de fundo e mixologia levada a sério. Não aceita reservas: chega-se e espera-se por um lugar no balcão.",lat:36.721019,lng:-4.424886,durationLabel:"a noite",fit:"ANY",mapQuery:"Speakeasy The Pharmacy, Calle García Briz 3, Málaga",kingTip:"Deixe o bartender guiar pela carta-herbário em vez de escolher às cegas; chegue cedo, pois não há reservas e enche rápido.",priceLevel:"€€€ (coquetel ~€12 est.)",hours:{openDays:"Todos os dias",openHour:"18:00",closeHour:"02:00",note:"Não aceita reservas. Espaço pequeno e intimista; confirme o dia de descanso na baixa temporada."},links:[{label:"Site oficial",url:"https://www.thepharmacy.es"}]},{id:"mrb_la_suite_puente_romano",categoryId:"tapas",city:"marbella",name:"La Suite — Puente Romano",tagline:"sala icônica da Milha de Ouro",description:"Sala noturna íntima dentro do resort Puente Romano, na Milha de Ouro, com decoração que cruza loft de Manhattan e estilo Marbella. Uma das baladas mais exclusivas da cidade, reúne um público seleto com programação de DJs internacionais, código de vestimenta apertado e serviço de mesa impecável. Abre depois da meia-noite e é reduto histórico da noite chic marbellí.",lat:36.503664,lng:-4.925582,durationLabel:"a noite",fit:"ANY",mapQuery:"La Suite Club, Puente Romano Beach Resort, Bulevar Príncipe Alfonso von Hohenlohe, Marbella",kingTip:"Reserve mesa com serviço de garrafa com antecedência e respeite o dress code (nada de bermuda ou chinelo); a casa costuma abrir só depois da meia-noite.",priceLevel:"€€€",hours:{openDays:"Qui–Sáb",openHour:"00:00",closeHour:"06:00",note:"Programação concentrada de quinta a sábado e no verão; funcionamento sazonal. Confirme a agenda antes de ir."},links:[{label:"Puente Romano",url:"https://www.puenteromano.com"}]},{id:"mrb_olivia_valere",categoryId:"tapas",city:"marbella",name:"Olivia Valère",tagline:"sala-mito com jardins mouros",description:"Instituição da noite marbellí desde os anos 1990, num cenário deslumbrante inspirado num palácio de estilo mouro, com pátios, jardins e fontes na estrada de Istán. Referência de badalação da Costa del Sol, mistura restaurante, lounge e balada com DJs e público internacional cosmopolita. É a sala-mito onde a alta temporada de Marbella atinge o auge.",lat:36.505062,lng:-4.940957,durationLabel:"a noite",fit:"ANY",mapQuery:"Olivia Valère, Carretera de Istán Km 0.8, Marbella",kingTip:"Fica fora do centro, na estrada de Istán: vá de táxi. Para garantir entrada nas noites cheias de agosto, reserve mesa antecipadamente.",priceLevel:"€€€",hours:{openDays:"Qua–Dom",openHour:"00:00",closeHour:"06:00",note:"Auge no verão; funcionamento sazonal e agenda variável. Dress code exigente; confirme a programação da semana."},links:[{label:"Site oficial",url:"https://olivia-valere.com"}]},{id:"mrb_nikki_beach",categoryId:"tapas",city:"marbella",name:"Nikki Beach Marbella",tagline:"beach club chic ao anoitecer",description:"Beach club de luxo em Elviria, à beira-mar, com piscina, camas VIP, restaurante ao ar livre e o icônico bar octogonal ao centro. Aberto desde 2003, é famoso pelas festas temáticas, do champanhe à lua cheia, que embalam a tarde e deslizam para a noite com DJs e clima de festa. Um dos endereços mais exclusivos (e caros) da Costa del Sol.",lat:36.489687,lng:-4.773009,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"Nikki Beach Marbella, Playa Hotel Don Carlos, Elviria, Marbella",kingTip:"O forte é a virada tarde-noite: reserve cama ou mesa e mire nos dias de festa temática, quando a casa ferve com DJ.",priceLevel:"€€€ (coquetel ~€18 est.)",hours:{openDays:"Todos os dias (temporada)",openHour:"11:00",closeHour:"00:00",note:"Fica em Elviria, a leste do centro de Marbella. Opera na temporada (primavera–outono); confirme calendário e eventos."}},{id:"mrb_belvue_amare",categoryId:"tapas",city:"marbella",name:"Belvue Rooftop — Amàre Beach",tagline:"rooftop com coquetéis de Diego Cabrera",description:"No 9º andar do Amàre Beach Hotel (só adultos), no paseo marítimo de Marbella, este rooftop tem vista de 360° sobre o mar e a serra, alcançando Gibraltar e a África em dias claros. A carta de coquetéis assinada pelo premiado mixólogo Diego Cabrera é o grande trunfo, com DJs residentes e shows ao vivo à noite. Do drink romântico ao pôr do sol à balada animada, é dos rooftops mais refinados da cidade.",lat:36.508237,lng:-4.881168,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"Belvue Rooftop Bar, Amàre Beach Hotel Marbella, Av. Severo Ochoa, Marbella",kingTip:"Peça um dos coquetéis de assinatura de Diego Cabrera ao entardecer; hotel só para adultos, ótimo para uma noite sem pressa a dois.",priceLevel:"€€€ (coquetel ~€16 est.)",hours:{openDays:"Todos os dias (temporada)",openHour:"13:00",closeHour:"01:00",note:"No centro de Marbella, junto à praia. Funciona na temporada; horários e agenda de DJ variam. Confirme antes."},links:[{label:"Site oficial",url:"https://www.amarehotels.com/amare-marbella/belvue-rooftop-bar/"}]},{id:"grn_b_heaven_carmen",categoryId:"tapas",city:"granada",name:"B-Heaven — Barceló Carmen",tagline:"rooftop com a Alhambra ao fundo",description:"Rooftop amplo e elegante no alto do hotel Barceló Carmen, com vista de 360° sobre Granada, a Sierra Nevada e a Torre de la Vela da Alhambra. À noite, vira lounge de coquetéis com a Alhambra iluminada no horizonte, gastronomia de forno a carvão e programação de música ao vivo e shows de flamenco em dias fixos. Um dos melhores mirantes da cidade para brindar depois do pôr do sol.",lat:37.17052,lng:-3.598312,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"B-Heaven, Barceló Carmen Granada, Acera del Darro 62, Granada",kingTip:"Vá ao anoitecer para ver a Alhambra ganhar tons alaranjados; peça um coquetel e confira a agenda (flamenco às quartas, música ao vivo em outras noites).",priceLevel:"€€€ (coquetel ~€13 est.)",hours:{openDays:"Todos os dias (temporada)",openHour:"12:00",closeHour:"00:00",note:"Terraço sazonal, mais ativo de primavera a outono. Aberto ao público; confirme horários e programação."},links:[{label:"Site oficial",url:"https://bheavengranada.com"}]},{id:"sev_terraza_eme",categoryId:"tapas",city:"sevilla",name:"La Terraza del EME",tagline:"rooftop coladinho na Giralda",description:"Rooftop sofisticado no alto do EME Catedral Hotel, no bairro de Santa Cruz, a poucos metros da catedral e com a Giralda praticamente ao alcance da mão. Distribuído em dois níveis de decoração moderna, oferece coquetéis icônicos assinados por Javier de las Muelas (Dry Martini) e petiscos num ambiente urbano e vibrante. É dos rooftops mais deslumbrantes de Sevilha para brindar com a Giralda iluminada.",lat:37.386865,lng:-5.992736,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"La Terraza del EME, EME Catedral Hotel, Calle Alemanes 27, Sevilla",kingTip:"Peça um dos coquetéis de assinatura de Javier de las Muelas e garanta lugar no parapeito de frente para a Giralda; enche muito ao pôr do sol.",priceLevel:"€€€ (coquetel ~€15 est.)",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"02:00",note:"Muito procurado ao entardecer; considere reservar. Horários encurtam fora da alta temporada."},links:[{label:"Site oficial",url:"https://www.laterrazadeleme.com"}]},{id:"sev_terraza_dona_maria",categoryId:"tapas",city:"sevilla",name:"Terraza Doña María",tagline:"a vista mais frontal da Giralda",description:"Terraço do histórico Hotel Doña María, em Santa Cruz, com vários níveis, piscina e o ângulo mais frontal e próximo da Giralda em toda Sevilha. De atmosfera clássica e charmosa, é o lugar perfeito para um aperitivo ou um drink ao entardecer, envolvido pela silhueta iluminada da torre. Menos badalado que os rooftops de hotel de design, ganha no cenário puro.",lat:37.386395,lng:-5.99161,durationLabel:"a noite",fit:"CLEAR_SKY",mapQuery:"Terraza Doña María, Hotel Doña María, Calle Don Remondo 19, Sevilla",kingTip:"Chegue perto do pôr do sol para pegar mesa de frente para a Giralda; o drink ali é mais sobre a vista do que sobre a coctelaria.",priceLevel:"€€€ (coquetel ~€13 est.)",hours:{openDays:"Todos os dias (temporada)",openHour:"17:00",closeHour:"00:00",note:"Terraço sazonal (primavera–outono) e dependente do tempo. Confirme abertura antes de subir."},links:[{label:"Site oficial",url:"https://www.terrazadonamaria.es"}]},{id:"svq_abantal",categoryId:"gastronomia",city:"sevilla",name:"Abantal",tagline:"Estrela Michelin, alta cozinha sevillana",description:"A única mesa do centro de Sevilha a manter estrela Michelin ininterrupta desde 2009, sob o chef Julio Fernández Quintero. A cozinha parte da despensa andaluza e das receitas da região para construir menus-degustação de traço contemporâneo e sazonal, com profundo trabalho de vinhos de Jerez. Sala sóbria e serviço preciso fazem dela o endereço de referência para uma noite de fine dining na cidade.",lat:37.38793,lng:-5.98371,durationLabel:"2,5–3 h",fit:"ANY",mapQuery:"Restaurante Abantal, Calle Alcalde José de la Bandera 7, Sevilla",kingTip:"Só funciona com menu-degustação e reserva antecipada; peça o pareamento de vinhos de Jerez, a grande especialidade da casa.",priceLevel:"€€€€",hours:{openDays:"Ter–Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha à tarde entre serviços e descansa dom/seg. Reserva obrigatória; confirme horários na alta temporada."},links:[{label:"Abantal – site oficial e reservas",url:"https://abantalrestaurante.es/"}]},{id:"svq_canabota",categoryId:"gastronomia",city:"sevilla",name:"Cañabota",tagline:"Estrela Michelin do mar, produto ao natural",description:"Estrela Michelin desde 2022, a Cañabota fez fama tratando peixe e marisco do Atlântico andaluz com respeito quase absoluto ao produto: brasa, sal e pouco mais. Tem ambiente de gastro-bar, com peixaria e cozinha abertas à vista, e trabalha só proteína do mar — não há carne na carta. Ao lado, a informal La Barra de Cañabota serve a mesma matéria-prima em preparos simples e diretos.",lat:37.39343,lng:-5.99363,durationLabel:"2–2,5 h",fit:"ANY",mapQuery:"Cañabota, Calle Orfila 1, Sevilla",kingTip:"Sem reserva, tente a barra da La Barra de Cañabota (Orfila 5); para o menu-degustação completo, reserve o restaurante principal com antecedência.",priceLevel:"€€€–€€€€",hours:{openDays:"Ter–Sáb",openHour:"13:30",closeHour:"23:00",note:"Fecha à tarde entre serviços e descansa dom/seg. Só peixe e marisco; confirme na reserva."},links:[{label:"Cañabota – site oficial e reservas",url:"https://canabota.es/"}]},{id:"svq_ispal",categoryId:"gastronomia",city:"sevilla",name:"Ispal",tagline:"Recomendado Michelin, 100% sevillano",description:'Recomendado pela Guia Michelin, o Ispal faz da província de Sevilha o seu único território: cada ingrediente principal vem da terra sevillana, sob o selo "ADN Sevilla" do chef executivo. A proposta resgata receitas tradicionais — arroces de marisma, gaspachos, guisos — em versão elegante e atual, com menus-degustação e uma carta cuidada. Fica na Plaza de San Sebastián, junto ao Prado, num ambiente contemporâneo.',lat:37.38151,lng:-5.98658,durationLabel:"2–2,5 h",fit:"ANY",mapQuery:"Restaurante Ispal, Plaza de San Sebastián 1, Sevilla",kingTip:'Não é estrelado, mas entrega alta cozinha por preço mais amável: o menu "100% Sevilla" é a porta de entrada perfeita à despensa local.',priceLevel:"€€€",hours:{openDays:"Ter–Sáb",openHour:"13:30",closeHour:"23:00",note:"Fecha à tarde entre serviços e descansa dom/seg. Confirme dias e menus na reserva."},links:[{label:"Ispal – site oficial e reservas",url:"https://restauranteispal.com/"}]},{id:"svq_rinconcillo",categoryId:"tapas",city:"sevilla",name:"El Rinconcillo",tagline:"A taberna mais antiga de Sevilha, desde 1670",description:"Aberta em 1670, é a taberna mais antiga de Sevilha e uma das mais veneráveis da Espanha, ainda tocada pela mesma família há gerações. O balcão de mogno onde o garçom anota a conta a giz sobre a madeira, as prateleiras de garrafas antigas e os azulejos guardam intacto o rito do tapeo sevillano. Espinacas con garbanzos, croquetes e ibéricos regados a fino são o cânone da casa.",lat:37.39334,lng:-5.98829,durationLabel:"45 min–1,5 h",fit:"ANY",mapQuery:"El Rinconcillo, Calle Gerona 40, Sevilla",kingTip:"Peça as espinacas con garbanzos e um fino; a conta é somada a giz na barra de madeira, como há séculos.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"13:00",closeHour:"01:30",note:"Costuma descansar às quartas em baixa temporada e enche muito à noite; confirme o dia de folga."},links:[{label:"El Rinconcillo – site oficial",url:"https://www.elrinconcillo.es/"}]},{id:"svq_las_teresas",categoryId:"tapas",city:"sevilla",name:"Las Teresas",tagline:"Jamón de Jabugo na barra de Santa Cruz",description:"Bar histórico do bairro de Santa Cruz, com origem no século XIX, de barra estreita em L pintada de vermelho e presuntos pendurados no teto. É um dos melhores endereços da cidade para o jamón ibérico de bellota de Jabugo, cortado à faca, ao lado das clássicas espinacas con garbanzos e de bons guisos. O corredor de mesinhas na viela caiada é um dos cenários mais fotogênicos do tapeo sevillano.",lat:37.38598,lng:-5.98932,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bar Las Teresas, Calle Santa Teresa 2, Sevilla",kingTip:"Peça uma tábua de jamón de Jabugo cortado à faca com um fino; as mesinhas da viela são disputadas, mas a barra rende mais conversa.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"00:00",note:"No coração turístico de Santa Cruz; costuma lotar no meio-dia e no fim da tarde."},links:[{label:"Las Teresas – site oficial",url:"http://www.lasteresas.es/"}]},{id:"svq_eslava",categoryId:"tapas",city:"sevilla",name:"Eslava",tagline:"Tapas premiadas junto a San Lorenzo",description:'Culto entre sevillanos e viajantes, o Eslava fica no bairro de San Lorenzo e é referência da tapa moderna desde 1988. A cozinha andaluza com técnica renovada rendeu prêmios famosos, como o "huevo sobre bizcocho de boletus" com redução de vinho de Jerez, campeão da melhor tapa da cidade. Barra sempre cheia e sala nos fundos para quem prefere sentar; vale a espera.',lat:37.39755,lng:-5.99692,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Bar Eslava, Calle Eslava 3, Sevilla",kingTip:"Peça o ovo sobre bolo de boletus com redução de Jerez, a tapa que ganhou prêmios; não aceita reserva na barra, chegue cedo.",priceLevel:"€€",hours:{openDays:"Ter–Dom",openHour:"12:30",closeHour:"23:30",note:"Descansa às segundas e fecha à tarde entre serviços; a barra não reserva e forma fila."}},{id:"svq_el_comercio",categoryId:"cafe",city:"sevilla",name:"Bar El Comercio",tagline:"Churros clássicos de Sevilha desde 1904",description:"Aberto em 1904 e ainda tocado pela família fundadora, é a churrería mais querida do centro de Sevilha. Serve os churros grossos em roda, fritos na hora e acompanhados de chocolate espesso ou café, ao balcão ou nas mesinhas de azulejo. Diferentemente da maioria, mantém a fritura o dia todo, o que o torna parada certa também no fim da tarde, entre os becos da Alfalfa.",lat:37.39081,lng:-5.99236,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Bar El Comercio, Calle Lineros 9, Sevilla",kingTip:"Peça churros com chocolate quente no café da manhã; aqui, ao contrário de quase toda a Espanha, também se fritam churros à tarde.",priceLevel:"€",hours:{openDays:"Seg–Sáb",openHour:"07:30",closeHour:"21:00",note:"Costuma fechar aos domingos e no meio da tarde; melhor no café da manhã ou na merienda."}},{id:"cdz_aponiente",categoryId:"gastronomia",city:"cadiz",name:"Aponiente",tagline:"Três estrelas Michelin, o Chef do Mar",description:'Instalado num antigo moinho de maré junto às salinas de El Puerto de Santa María, o Aponiente de Ángel León é a primeira mesa da Andaluzia a conquistar três estrelas Michelin. O "Chef do Mar" transforma o menu num laboratório do oceano: embutidos marinhos, plâncton, bioluminescência, peixes de descarte e sal marinho conduzem uma experiência de vanguarda ligada à sustentabilidade. É destino gastronômico de primeira grandeza, a cerca de meia hora de Cádiz.',lat:36.60334,lng:-6.21669,durationLabel:"3–3,5 h",fit:"ANY",mapQuery:"Aponiente, El Puerto de Santa María, Cádiz",kingTip:"As datas esgotam com meses de antecedência: reserve assim que a agenda abrir. Fica em El Puerto de Santa María, não em Cádiz capital — programe o deslocamento.",priceLevel:"€€€€",hours:{openDays:"Ter–Sáb",openHour:"13:30",closeHour:"22:00",note:"Temporada costuma ir da primavera ao fim do outono, com fechamento no inverno. Só menu-degustação e reserva antecipada."},links:[{label:"Aponiente – site oficial e reservas",url:"https://www.aponiente.com/"}]},{id:"cdz_lu_cocina_alma",categoryId:"gastronomia",city:"cadiz",name:"LÚ Cocina y Alma",tagline:"Duas estrelas Michelin em Jerez",description:'Em Jerez, o chef Juanlu Fernández aplica técnica francesa clássica a ingredientes andaluzes de estação, elevando pratos humildes gaditanos a obras refinadas — um estilo que ele chama de "vanguarda de retaguarda", hoje com duas estrelas Michelin. A cozinha ocupa o centro da sala, e os comensais quase se sentam à mesa do chef, entre uma cenografia inspirada em Alice no País das Maravilhas. Dois menus-degustação, Duende e Duxo, conduzem a experiência.',lat:36.68814,lng:-6.13449,durationLabel:"2,5–3 h",fit:"ANY",mapQuery:"LÚ Cocina y Alma, Calle Zaragoza 2, Jerez de la Frontera",kingTip:"Fica em Jerez, ideal de emendar com uma visita às bodegas de xerez no mesmo dia; reserve o menu com boa antecedência.",priceLevel:"€€€€",hours:{openDays:"Ter–Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha à tarde entre serviços e descansa dom/seg. Só menu-degustação e reserva antecipada."},links:[{label:"Universo LÚ – site oficial e reservas",url:"https://universolu.com/restaurantes/"}]},{id:"cdz_codigo_de_barra",categoryId:"gastronomia",city:"cadiz",name:"Código de Barra",tagline:"A primeira estrela Michelin de Cádiz capital",description:"Pequena mesa no casco antigo, foi o primeiro restaurante de Cádiz capital a ganhar estrela Michelin, sob o chef neerlandês León Griffioen e Paqui Márquez. Os menus-degustação narram a história gastronômica da cidade a partir de um olhar contemporâneo, com pratos como tortilla de camarones, babeta de choco e crocante de cañaílla. Ambiente minimalista e cozinha à vista, a poucos passos da Torre Tavira.",lat:36.53373,lng:-6.29547,durationLabel:"2–2,5 h",fit:"ANY",mapQuery:"Código de Barra, Calle San Francisco 7, Cádiz",kingTip:"É intimista e lota rápido: reserve com antecedência e escolha o menu mais longo para a viagem completa pela cozinha gaditana.",priceLevel:"€€€",hours:{openDays:"Ter–Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha à tarde entre serviços e descansa dom/seg. Poucas mesas; reserva recomendada."},links:[{label:"Código de Barra – site oficial",url:"https://restaurantecodigodebarracadiz.com/"}]},{id:"cdz_casa_manteca",categoryId:"tapas",city:"cadiz",name:"Taberna Casa Manteca",tagline:"Chicharrones e solera no bairro La Viña",description:'Fundada em 1953 por José "Pepe El Manteca", é a taberna mais emblemática do bairro carnavalesco de La Viña, um antigo armazém que virou templo do tapeo gaditano. As paredes cobertas de cartazes de toureiros e do Carnaval emolduram o balcão de onde saem os famosos chicharrones de Chiclana e o atum em conserva servidos sobre papel kraft. Autêntica e sem concessões, é uma imersão na Cádiz mais popular.',lat:36.53005,lng:-6.30359,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Taberna Casa Manteca, Corralón de los Carros 66, Cádiz",kingTip:"Peça os chicharrones especiales com um fino da Baía; servidos no papel, comem-se em pé, no melhor estilo de La Viña.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Costuma fechar à tarde entre serviços; enche muito à noite e nas datas do Carnaval."}},{id:"cdz_el_faro",categoryId:"tapas",city:"cadiz",name:"El Faro de Cádiz",tagline:"Tortillitas de camarão desde 1964",description:"Casa familiar aberta em 1964 por Gonzalo Córdoba no bairro de La Viña, marco do renascimento da cozinha gaditana. A barra da frente é uma das mais célebres de Cádiz para tapear pescado — as tortillitas de camarones aqui são referência —, enquanto as salas ao fundo servem carta e menus mais elaborados de peixe fresco. Duas experiências no mesmo endereço, da tapa clássica ao almoço com toalha.",lat:36.52858,lng:-6.30382,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"El Faro de Cádiz, Calle San Félix 15, Cádiz",kingTip:"Fique na barra e peça as tortillitas de camarones, finas e crocantes; é a versão que virou padrão-ouro da cidade.",priceLevel:"€€–€€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"A barra de tapas e o restaurante têm ritmos distintos; para a sala, reserve na alta temporada."},links:[{label:"El Faro de Cádiz – site oficial",url:"https://www.elfarodecadiz.com/"}]},{id:"cdz_cafe_la_marina",categoryId:"cafe",city:"cadiz",name:"Café-Bar La Marina",tagline:"Churros e café na Plaza de las Flores",description:"Clássico café-bar gaditano na colorida Plaza de las Flores (Plaza Topete), entre o casario e o Mercado Central. De manhã serve o café da manhã de churros e tostadas com azeite ao balcão ou nas mesinhas da praça florida; ao meio-dia, vira ponto de pescaíto frito. É o lugar para viver o vaivém matinal da cidade com um café con leche e churros diante das bancas de flores.",lat:36.53099,lng:-6.29733,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Café-Bar La Marina, Plaza de las Flores, Cádiz",kingTip:"Sente-se na esplanada da Plaza de las Flores para o café da manhã de churros; ao meio-dia, o mesmo balcão vira parada de pescaíto frito.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"08:00",closeHour:"20:00",note:"Melhor no café da manhã e no aperitivo do meio-dia; a esplanada na praça é o lugar mais disputado."}},{id:"svq_catedral_giralda",categoryId:"sevilla",city:"sevilla",name:"Catedral de Sevilla e Giralda",tagline:"A maior catedral gótica do mundo",description:"Erguida sobre a antiga mesquita almóada, é a maior catedral gótica do planeta e guarda o túmulo de Cristóvão Colombo, sustentado por quatro alegorias dos reinos de Espanha. Sua nave central sobe a 42 metros e o retábulo-mor dourado é o maior do mundo. Ao lado, a Giralda — antigo minarete do século XII coroado por um campanário renascentista — se sobe por 35 rampas, sem degraus.",lat:37.38614,lng:-5.99263,durationLabel:"1,5–2 h",fit:"INDOOR",mapQuery:"Catedral de Sevilla, Sevilla",kingTip:"Compre o ingresso online com horário marcado e vá logo na abertura, às 10h30 — a Giralda esquenta e lota ao meio-dia. O mesmo bilhete dá acesso à Igreja do Salvador, que você pode visitar noutro momento sem nova fila.",priceLevel:"€€ (cerca de 13€; Giralda incluída)",hours:{openDays:"Todos os dias",openHour:"10:30",closeHour:"18:00",note:"Domingos abre mais tarde; horários de culto alteram o acesso. Confirme no site."},links:[{label:"Site oficial e ingressos",url:"https://www.catedraldesevilla.es"}],history:"Construída entre 1401 e 1528 sobre a mesquita aljama almóada, cujo pátio das abluções sobrevive como o Patio de los Naranjos; a Giralda, minarete de 1198, ganhou o corpo de sinos e o cata-vento El Giraldillo em 1568. É Patrimônio Mundial desde 1987."},{id:"svq_real_alcazar",categoryId:"sevilla",city:"sevilla",name:"Real Alcázar",tagline:"O palácio real em uso mais antigo da Europa",description:"Um deslumbrante conjunto de palácios de mil anos onde o mudéjar, o gótico e o renascentista se sobrepõem em pátios, azulejos e tetos de madeira lavrada. O Palácio de Pedro I, com o Patio de las Doncellas, é o ápice da arte mudéjar; ao redor estendem-se jardins de laranjeiras, fontes e o labirinto. Cenário de Game of Thrones, segue sendo residência oficial da família real em Sevilha.",lat:37.38316,lng:-5.99106,durationLabel:"2–3 h",fit:"INDOOR",mapQuery:"Real Alcazar de Sevilla, Sevilla",kingTip:"Reserve online com dias de antecedência: os ingressos por franja horária esgotam, sobretudo no verão. Entre às 9h30 na abertura e refugie-se nos jardins e no fresco Salón de Embajadores nas horas de mais calor.",priceLevel:"€€ (cerca de 14,50€)",hours:{openDays:"Todos os dias",openHour:"09:30",closeHour:"19:00",note:"Fecha 1 e 6 de jan, Sexta-Feira Santa e 25 dez. Última entrada 1 h antes."},links:[{label:"Site oficial e ingressos",url:"https://www.alcazarsevilla.org"}],history:"Iniciado como fortaleza omíada no século X, foi ampliado pelos almóadas e reconstruído como palácio mudéjar por Pedro I de Castela a partir de 1364, com sucessivas intervenções até o século XIX. É Patrimônio Mundial desde 1987 e residência real desde então."},{id:"svq_plaza_espana",categoryId:"sevilla",city:"sevilla",name:"Plaza de España",tagline:"O grande semicírculo de azulejos e canais",description:"Joia da Exposição Ibero-Americana de 1929, é um monumental semicírculo de 200 metros que abraça um canal navegável cruzado por quatro pontes de cerâmica. Ao longo da base, 48 bancos de azulejo representam cada província espanhola em ordem alfabética. Mistura regionalismo, art déco e ecos mudéjares e renascentistas; serviu de cenário a Star Wars e Lawrence da Arábia.",lat:37.37727,lng:-5.98716,durationLabel:"45 min – 1 h",fit:"CLEAR_SKY",mapQuery:"Plaza de Espana, Sevilla",kingTip:"Vá bem cedo ou no fim da tarde: ao meio-dia o sol bate em cheio na praça aberta e não há sombra. Procure o banco 'Málaga' entre os 48 azulejos para a foto de casa. Alugar um barquinho no canal dura só uns minutos e vale pelas fotos.",priceLevel:"Gratuito (barcos à parte)",history:"Projetada por Aníbal González para a Exposição Ibero-Americana de 1929, foi concebida como abraço simbólico de Espanha às suas antigas colônias, com as pontes representando os quatro reinos históricos da península; hoje abriga sedes de órgãos públicos."},{id:"svq_barrio_santa_cruz",categoryId:"sevilla",city:"sevilla",name:"Barrio de Santa Cruz",tagline:"O labirinto branco da antiga judiaria",description:"A antiga judiaria de Sevilha é um emaranhado de vielas estreitas, casas caiadas de branco, pátios floridos e pracinhas com laranjeiras, encravado entre a Catedral e o Alcázar. Ruas como a Calle Agua e a lendária Calleja del Beso, largos como a Plaza de Doña Elvira e a Plaza de Santa Cruz condensam o imaginário mais romântico da cidade. Some-se as sombras e o frescor dos becos.",lat:37.38509,lng:-5.9901,durationLabel:"1–2 h a pé",fit:"ANY",mapQuery:"Barrio de Santa Cruz, Sevilla",kingTip:"Perca-se de propósito pelas vielas na hora da sesta, quando os becos ficam vazios e frescos. Espie os pátios abertos e busque a Plaza de Doña Elvira à sombra dos laranjais — um dos recantos mais fotogênicos e tranquilos do bairro.",priceLevel:"Gratuito",history:"Foi a judiaria de Sevilha desde a conquista cristã de 1248 até o pogrom de 1391, que a esvaziou; o traçado atual, de ruas propositalmente estreitas para dar sombra e frescor, foi remodelado e romantizado nas reformas urbanas do início do século XX."},{id:"svq_setas_metropol",categoryId:"sevilla",city:"sevilla",name:"Metropol Parasol — Las Setas",tagline:"O maior monumento de madeira do mundo",description:"Apelidada de 'Las Setas' (os cogumelos), esta ondulante estrutura de madeira de 2011, projetada por Jürgen Mayer, cobre a Plaza de la Encarnación e é a maior obra de madeira do mundo. No térreo, o Antiquarium exibe ruínas romanas e islâmicas descobertas na obra. No alto, uma passarela sinuosa oferece uma das melhores vistas panorâmicas de Sevilha, num contraste ousado com o casco antigo.",lat:37.39335,lng:-5.99213,durationLabel:"45 min – 1 h",fit:"CLEAR_SKY",mapQuery:"Setas de Sevilla, Plaza de la Encarnacion, Sevilla",kingTip:"Suba ao mirante ao pôr do sol: a passarela pega a Giralda e a Catedral recortadas na luz dourada, e o ingresso costuma dar direito a uma bebida no bar do topo. Compre online para evitar a fila do elevador.",priceLevel:"€ (mirante cerca de 15€ com consumo)",hours:{openDays:"Todos os dias",openHour:"09:30",closeHour:"00:00",note:"Mirante aberto até tarde; o Antiquarium tem horário próprio. Confirme no site."},links:[{label:"Site oficial e ingressos",url:"https://www.setasdesevilla.com"}],history:"Inaugurada em 2011 após um projeto de Jürgen Mayer vencedor de concurso de 2004, ergueu-se sobre o antigo mercado da Encarnación; as escavações revelaram um bairro romano e almóada, hoje preservado no Antiquarium sob a praça."},{id:"svq_triana_puente_isabel",categoryId:"sevilla",city:"sevilla",name:"Triana e Puente de Isabel II",tagline:"O bairro marinheiro do outro lado do rio",description:"Do outro lado do Guadalquivir, Triana é o berço do flamenco, da cerâmica e dos marinheiros que partiram para as Américas. A Puente de Isabel II, de 1852 e a mais antiga ponte de ferro conservada da Espanha, leva ao Mercado de Triana, à Capilla del Carmen e à Calle Betis, cuja fileira de casas coloridas se reflete no rio. Ateliês de azulejos mantêm viva a tradição oleira do bairro.",lat:37.38468,lng:-6.00191,durationLabel:"1,5–2 h a pé",fit:"ANY",mapQuery:"Puente de Isabel II, Triana, Sevilla",kingTip:"Cruze a ponte no fim da tarde e caminhe pela Calle Betis com o rio à direita: é a vista clássica da Torre del Oro e da Giralda ao pôr do sol, do lado de Triana. O Mercado de Triana esconde o Castillo de San Jorge, sede da Inquisição, no subsolo.",priceLevel:"Gratuito",history:"Bairro extramuros desde a época romana, Triana foi lar de oleiros, ceramistas e navegadores dos séculos XV-XVI; a Puente de Isabel II, também chamada Puente de Triana, foi inaugurada em 1852 inspirada na parisiense do Carrousel, substituindo a antiga ponte de barcas almóada."},{id:"svq_torre_del_oro",categoryId:"sevilla",city:"sevilla",name:"Torre del Oro",tagline:"A torre albarrã à beira do Guadalquivir",description:"Sentinela dodecagonal do século XIII à margem do Guadalquivir, integrava a muralha almóada e controlava o acesso fluvial ao porto de Sevilha. Deve o nome ao brilho dourado que a luz arrancava de seus antigos revestimentos. Hoje abriga um pequeno Museu Naval, e seu terraço superior oferece uma vista aberta do rio, de Triana e da Plaza de Toros logo ao lado.",lat:37.38263,lng:-5.99631,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Torre del Oro, Sevilla",kingTip:"É uma das visitas mais baratas da cidade e às segundas costuma ser gratuita. Suba ao terraço para a vista do rio, mas o melhor mesmo é fotografá-la de fora, do lado de Triana, com o Guadalquivir em primeiro plano ao entardecer.",priceLevel:"€ (cerca de 3€; segundas grátis)",hours:{openDays:"Todos os dias",openHour:"09:30",closeHour:"18:45",note:"Fins de semana com horário reduzido; confirme antes de ir."},history:"Erguida por volta de 1220-1221 pelos almóadas como torre albarrã da muralha, fechava com uma corrente sobre o rio a passagem de navios inimigos; serviu de prisão e capela e, desde 1944, abriga o Museu Marítimo da Marinha espanhola."},{id:"svq_plaza_toros_maestranza",categoryId:"sevilla",city:"sevilla",name:"Plaza de Toros de la Maestranza",tagline:"A praça de touros mais antiga do país",description:"Considerada a mais monumental praça de touros da Espanha, sua construção arrastou-se de 1749 a 1881, o que lhe deu a forma ovalada irregular e a fachada barroca branca e ocre da Puerta del Príncipe. A visita guiada percorre a arena, os curros, a capela dos toureiros e o museu taurino, com trajes, cartazes e obras de Goya. Um marco histórico e arquitetônico à beira do rio, para além da tourada.",lat:37.38636,lng:-5.99862,durationLabel:"1 h (visita guiada)",fit:"INDOOR",mapQuery:"Plaza de Toros de la Real Maestranza, Sevilla",kingTip:"A visita guiada com o museu roda em espanhol e inglês a cada 30 minutos e é interessante mesmo para quem não liga para touradas — pela arquitetura e pelas telas de Goya. Evite os dias de corrida (domingos da primavera), quando a visita não abre.",priceLevel:"€€ (visita guiada cerca de 12€)",hours:{openDays:"Todos os dias",openHour:"09:30",closeHour:"21:00",note:"Em dias de espetáculo o horário de visita muda ou é suspenso. Confirme no site."},links:[{label:"Site oficial",url:"https://www.realmaestranza.com"}],history:"A Real Maestranza de Caballería de Sevilha começou a levantá-la em 1749 substituindo uma praça de madeira; a obra prolongou-se até 1881, resultando no formato oval assimétrico. É a mais antiga praça de touros monumental da Espanha ainda em uso."},{id:"svq_archivo_de_indias",categoryId:"sevilla",city:"sevilla",name:"Archivo General de Indias",tagline:"A memória documental de todo um império",description:"Instalado na antiga Lonja de Mercaderes, sereno edifício renascentista de Juan de Herrera junto à Catedral, guarda o mais completo arquivo da administração espanhola nas Américas e Filipinas: 43 mil legajos e 80 milhões de páginas, do diário de bordo de Colombo aos mapas do Novo Mundo. A entrada é gratuita e permite ver a monumental escadaria de mármore e as salas com exposições rotativas.",lat:37.38455,lng:-5.99268,durationLabel:"30–45 min",fit:"INDOOR",mapQuery:"Archivo General de Indias, Sevilla",kingTip:"Entrada livre e a poucos passos da Catedral e do Alcázar — um refúgio fresco e climatizado, quase vazio, para as horas de mais calor. Suba a escadaria de jaspe e veja as vitrines com documentos originais dos descobrimentos.",priceLevel:"Gratuito",hours:{openDays:"Ter a dom",openHour:"09:30",closeHour:"17:00",note:"Domingos e feriados só de manhã; fecha às segundas. Confirme no site."},links:[{label:"Cultura — Archivo de Indias",url:"https://www.cultura.gob.es/archivos/mc/agi/portada.html"}],history:"O edifício, obra de Juan de Herrera concluída em 1598 como bolsa de comércio, passou a arquivo em 1785 por ordem de Carlos III, que reuniu ali a documentação colonial antes dispersa. Integra o conjunto Patrimônio Mundial de Sevilha desde 1987."},{id:"svq_basilica_macarena",categoryId:"sevilla",city:"sevilla",name:"Basílica de la Macarena",tagline:"O templo da Virgem mais amada de Sevilha",description:"No bairro popular da Macarena, esta basílica de meados do século XX guarda a Esperanza Macarena, a imagem mariana mais venerada de Sevilha, obra anônima do século XVII de rosto lacrimoso e cinco lágrimas de cristal. Coberta de mantos bordados a ouro e joias, é o centro emocional da Semana Santa sevilhana. Ao lado ergue-se o melhor trecho conservado da muralha almóada, com o Arco da Macarena.",lat:37.40119,lng:-5.98903,durationLabel:"30–45 min",fit:"INDOOR",mapQuery:"Basilica de la Macarena, Sevilla",kingTip:"Combine a visita com o trecho de muralha almóada e o Arco da Macarena, logo em frente — o melhor lençol de muralha árabe da cidade. O tesouro da Virgem, com mantos e o manto de tabaco, tem entrada à parte e vale a pena.",priceLevel:"Gratuito (museu do tesouro à parte)",hours:{openDays:"Todos os dias",openHour:"09:00",closeHour:"19:00",note:"Fecha ao meio-dia; horários de culto alteram o acesso. Confirme no site."},links:[{label:"Site oficial",url:"https://www.hermandaddelamacarena.es"}],history:"A basílica atual foi construída entre 1941 e 1949 para abrigar a imagem, antes venerada na paróquia de San Gil; a Esperanza Macarena, atribuída a fins do século XVII, tornou-se símbolo da cidade e é levada em procissão na madrugada da Sexta-Feira Santa."},{id:"svq_casa_de_pilatos",categoryId:"sevilla",city:"sevilla",name:"Casa de Pilatos",tagline:"Palácio-jardim mudéjar e renascentista",description:"O mais belo palácio senhorial de Sevilha, residência dos duques de Medinaceli, funde o mudéjar, o gótico e o renascimento italiano numa harmonia rara. Seu pátio principal reúne azulejos, estuques mudéjares e uma coleção de estátuas clássicas e bustos de imperadores romanos. Jardins com fontes e loggias completam o conjunto, cujo nome evoca a suposta casa de Pilatos em Jerusalém.",lat:37.38953,lng:-5.98745,durationLabel:"1–1,5 h",fit:"INDOOR",mapQuery:"Casa de Pilatos, Sevilla",kingTip:"Menos disputada que o Alcázar e igualmente deslumbrante — ótima alternativa se os ingressos do Alcázar esgotaram. O andar térreo pode ser visitado por conta própria; o andar nobre, ainda habitado, só com visita guiada, que sai de tempos em tempos.",priceLevel:"€€ (cerca de 12€ térreo; 15€ com andar nobre)",hours:{openDays:"Todos os dias",openHour:"09:00",closeHour:"18:00",note:"Última entrada 1 h antes; horário pode estender no verão. Confirme no site."},links:[{label:"Fundación Medinaceli",url:"https://www.fundacionmedinaceli.org/monumentos/pilatos/"}],history:"Iniciado no fim do século XV por Pedro Enríquez e sua mulher Catalina de Ribera, foi transformado após a peregrinação de Fadrique Enríquez a Jerusalém em 1519, que inspirou o nome e a devoção do Via-Crúcis; é sede da Fundación Casa de Medinaceli."},{id:"svq_palacio_las_duenas",categoryId:"sevilla",city:"sevilla",name:"Palacio de las Dueñas",tagline:"A casa sevilhana da duquesa de Alba",description:"Residência sevilhana da Casa de Alba e casa natal do poeta Antonio Machado, cujo pai era administrador da propriedade. Este palácio dos séculos XV-XVI mistura gótico-mudéjar e renascentista em torno de pátios com laranjeiras, buganvílias e fontes. Aberto ao público desde 2016, revela salões repletos de arte, tapeçarias e objetos pessoais da célebre duquesa Cayetana, num ambiente ainda muito habitado.",lat:37.39468,lng:-5.99,durationLabel:"45 min – 1 h",fit:"INDOOR",mapQuery:"Palacio de las Duenas, Sevilla",kingTip:"Menos turístico e delicioso de percorrer com o audioguia incluído, que conta as histórias da duquesa Cayetana de Alba. Os pátios floridos rendem fotos lindas e ficam à sombra — respiro fresco entre a Macarena e o centro. Feche 'Las Setas' na mesma caminhada.",priceLevel:"€€ (cerca de 12€, audioguia incluído)",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"18:00",note:"Verão pode ter horário estendido; fecha em eventos privados. Confirme no site."},links:[{label:"Site oficial",url:"https://www.lasduenas.es"}],history:"Documentado desde o século XV e ampliado pelos Ribera e depois pela Casa de Alba, deve o nome ao extinto convento de Santa María de las Dueñas; ali nasceu Antonio Machado em 1875, e foi lar predileto de Cayetana Fitz-James Stuart, 18.ª duquesa de Alba."},{id:"svq_plaza_nueva_ayuntamiento",categoryId:"sevilla",city:"sevilla",name:"Plaza Nueva e Ayuntamiento",tagline:"O salão urbano no coração de Sevilha",description:"Ampla praça ajardinada com palmeiras e o monumento equestre a Fernando III, o Santo, é o marco-zero da Sevilha moderna e ponto de partida dos bondes. Fecha-a a leste a fachada plateresca do Ayuntamiento, joia do renascimento espanhol lavrada em pedra por Diego de Riaño no século XVI, com medalhões, grutescos e emblemas mitológicos. Dali arranca a movimentada rua comercial Sierpes.",lat:37.38914,lng:-5.99553,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"Plaza Nueva, Sevilla",kingTip:"Rodeie o Ayuntamiento até a Plaza de San Francisco para ver a fachada plateresca mais rica, esculpida em detalhe. Daqui a Calle Sierpes leva, à sombra de toldos no verão, direto às lojas e ao centro histórico.",priceLevel:"Gratuito",history:"A praça abriu-se em 1852 sobre o solar do convento de San Francisco, demolido pela desamortização; o Ayuntamiento, obra plateresca de Diego de Riaño iniciada em 1527, foi ampliado com fachada neoclássica sobre a Plaza Nueva no século XIX."},{id:"mlg_jose_carlos_garcia",categoryId:"gastronomia",city:"malaga",name:"José Carlos García",tagline:"A estrela Michelin do porto de Málaga",description:"Uma estrela Michelin e o único estrelado da cidade de Málaga, no Muelle Uno com vista para os iates. Cozinha malaguenha contemporânea e criativa em dois menus-degustação que evoluem com a estação. Ambiente elegante e informal, jardins verticais e luz mediterrânea.",lat:36.7163,lng:-4.4162,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Restaurante José Carlos García, Plaza de la Capilla 1, Málaga",whatToDo:"Escolha o menu-degustação longo e deixe a harmonização de vinhos por conta da casa; peça mesa voltada para o Muelle Uno.",kingTip:"Prato-assinatura ao redor do peixe do dia da lota de Málaga. RESERVE COM 2-3 MESES DE ANTECEDÊNCIA: em julho, alta temporada, os estrelados esgotam meses antes.",priceLevel:"~€165/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"23:00",note:"Fecha domingo e segunda; confirme no site"},links:[{label:"Site oficial e reserva",url:"https://www.restaurantejcg.com"},{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/malaga/restaurant/jose-carlos-garcia"}],history:"Aberto por José Carlos García, malaguenho de nascimento e herdeiro do histórico Café de París da família, é referência da alta cozinha andaluza há mais de uma década."},{id:"mlg_kaleja",categoryId:"gastronomia",city:"malaga",name:"Kaleja",tagline:"Guisos de autor com uma estrela Michelin",description:"Uma estrela Michelin do chef Dani Carnero, no centro histórico de Málaga. Reinventa o guiso e o receituário andaluz de raiz com técnica de alta cozinha, memória e produto local. Menu-degustação intenso e caseiro em sala íntima.",lat:36.7211,lng:-4.4193,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Restaurante Kaleja, Calle Marqués 1, Málaga",whatToDo:"Vá de menu-degustação completo; a cozinha de colher (guisos e caldos) é o coração da casa.",kingTip:"Prove os guisos de autor, a assinatura de Carnero. Sala pequena e muito procurada: RESERVE COM MESES DE ANTECEDÊNCIA, sobretudo em julho.",priceLevel:"~€110/pessoa (est.)",hours:{openDays:"Qua-Dom",openHour:"13:30",closeHour:"23:00",note:"Dias podem variar; confirme na reserva"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/malaga/restaurant/kaleja"}],history:"Dani Carnero consolidou aqui a linguagem que já ensaiara em La Cosmopolita, elevando o guiso malaguenho ao patamar Michelin."},{id:"mlg_ta_kumi",categoryId:"gastronomia",city:"malaga",name:"TA-KUMI",tagline:"Japonês de culto frente à Alcazaba",description:"Um dos japoneses mais respeitados da Andaluzia, unindo os chefs Toshio Tsutsui e Álvaro Arbeloa. Sushi e cozinha nipônica com produto local e excelente relação qualidade-preço, junto à Alcazaba. Barra de sushi e terraço com vista para a fortaleza.",lat:36.7224,lng:-4.4136,durationLabel:"jantar 1h30-2h",fit:"CLEAR_SKY",mapQuery:"Restaurante Ta-Kumi, Calle Mundo Nuevo 4, Málaga",whatToDo:"Sente-se à barra de sushi para ver o corte ao vivo; em noite limpa, peça mesa no terraço voltado à Alcazaba.",kingTip:"Deixe-se levar pelo omakase do dia. Terraço disputado no verão: reserve com antecedência e peça expressamente mesa com vista.",priceLevel:"€€€",hours:{openDays:"Ter-Dom",openHour:"13:30",closeHour:"23:30",note:"Costuma fechar segunda; confirme"},links:[{label:"Site oficial e reserva",url:"https://www.restaurantetakumi.com"}],history:'O nome funde as iniciais dos dois cozinheiros com "kumi", artesão-mestre em japonês, resumindo a filosofia da casa.'},{id:"rnd_bardal",categoryId:"gastronomia",city:"ronda",name:"Bardal",tagline:"Duas estrelas Michelin no coração de Ronda",description:"Duas estrelas Michelin do chef Benito Gómez, revalidadas na guia 2026. Cozinha de autor que exalta o produto da serra de Ronda com criatividade e coerência, em menus-degustação de peregrinação gourmet. No espaço onde antes brilhou o histórico Tragabuches.",lat:36.7427,lng:-5.1662,durationLabel:"almoço/jantar 3h",fit:"ANY",mapQuery:"Restaurante Bardal, Calle José Aparicio 1, Ronda",whatToDo:"Reserve o menu-degustação longo com harmonização; combine com a visita ao Puente Nuevo, a poucos passos.",kingTip:"Duas estrelas em tempo recorde: das mesas mais cobiçadas da Andaluzia. RESERVE COM 2-3 MESES DE ANTECEDÊNCIA, imprescindível em julho.",priceLevel:"~€190/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha domingo e segunda; confirme no site"},links:[{label:"Site oficial e reserva",url:"https://www.restaurantebardal.com"},{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/ronda/restaurant/bardal"}],history:"Benito Gómez, catalão de Argentona, abriu o Tragatá em 2006 e dez anos depois inaugurou o Bardal, hoje uma das quatro casas de Málaga com duas estrelas."},{id:"rnd_tragata",categoryId:"gastronomia",city:"ronda",name:"Tragatá",tagline:"O tapas-bar canalha de Benito Gómez",description:"A casa informal do mesmo chef do Bardal, Benito Gómez, listada no Guia Michelin. Tapas de autor a preço sensato, com técnica de duas estrelas em formato descontraído. A melhor porta de entrada à cozinha de Ronda sem menu-degustação.",lat:36.7438,lng:-5.1655,durationLabel:"almoço/jantar 1-2h",fit:"ANY",mapQuery:"Tragatá, Calle Nueva 4, Ronda",whatToDo:"Peça várias tapas para partilhar; ideal para quem não conseguiu mesa no Bardal.",kingTip:"Prove o sanduíche de pastrami e as croquetes, clássicos da casa. Não aceita reservas para grupos pequenos em alguns horários: chegue cedo no verão.",priceLevel:"€€€",hours:{openDays:"Ter-Sáb",openHour:"13:00",closeHour:"23:00",note:"Dias podem variar; confirme"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/ronda/restaurant/tragata"}],history:"Foi o primeiro projeto de Benito Gómez em Ronda, em 2006, antes do salto que o levaria às duas estrelas do Bardal."},{id:"mrb_skina",categoryId:"gastronomia",city:"marbella",name:"Skina",tagline:"Duas estrelas Michelin no casco antigo",description:"Duas estrelas Michelin numa das ruas estreitas do centro histórico de Marbella. Alta cozinha andaluza de produto excepcional e adega de referência, num dos menores e mais íntimos biestrelados da Espanha. Serviço de gala em espaço minúsculo.",lat:36.5101,lng:-4.8853,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Restaurante Skina, Calle Aduar 12, Marbella",whatToDo:"Confie no menu-degustação e explore a carta de vinhos, uma das joias da casa, com o sommelier.",kingTip:"Pouquíssimas mesas: é dos jantares mais difíceis de conseguir na Costa del Sol. RESERVE COM MESES DE ANTECEDÊNCIA para julho.",priceLevel:"~€220/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha domingo e segunda; confirme no site"},links:[{label:"Site oficial e reserva",url:"https://www.restauranteskina.com"},{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/marbella/restaurant/skina"}],history:"Escondido nas vielas caiadas do casco antigo, tornou-se símbolo da ascensão gastronômica de Marbella."},{id:"mrb_messina",categoryId:"gastronomia",city:"marbella",name:"Messina",tagline:"Uma estrela Michelin de fusão criativa",description:"Uma estrela Michelin do chef ítalo-argentino Mauricio Giovanini. Cozinha de autor que cruza técnica de vanguarda com produtos andaluzes e acentos latino-americanos e asiáticos. Menus-degustação surpreendentes junto ao paseo marítimo.",lat:36.5069,lng:-4.8799,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Restaurante Messina, Avenida Severo Ochoa 12, Marbella",whatToDo:"Peça o menu-degustação mais longo para captar a amplitude criativa de Giovanini.",kingTip:"Cozinha de vanguarda muito pessoal, uma das mais interessantes de Marbella. Reserve com antecedência, especialmente na alta temporada de julho.",priceLevel:"~€150/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha domingo e segunda; confirme"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/marbella/restaurant/messina"}],history:"Mauricio Giovanini construiu no Messina uma das trajetórias criativas mais longevas e respeitadas da Costa del Sol."},{id:"mrb_back",categoryId:"gastronomia",city:"marbella",name:"Back",tagline:"Estrela Michelin de técnica e diversão",description:"Uma estrela Michelin (desde 2023) dos chefs David Olivas e Fabián Villar, no centro de Marbella. Alta cozinha que une precisão técnica a surpresa e um toque lúdico em cada prato. Menus-degustação de perfil jovem e vibrante.",lat:36.5093,lng:-4.8933,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Restaurante Back, Calle Pablo Casals 8, Marbella",whatToDo:"Vá de menu-degustação e deixe-se surpreender pela sequência; ótimo para quem busca cozinha criativa sem formalidade excessiva.",kingTip:"David Olivas, de Úbeda, aposta em técnica com humor. Sala pequena: reserve com semanas a meses de antecedência para julho.",priceLevel:"~€120/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha domingo e segunda; confirme no site"},links:[{label:"Site oficial e reserva",url:"https://backrestaurante.com"},{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/marbella/restaurant/back"}],history:"Conquistou a primeira estrela em novembro de 2023, colocando a dupla Olivas-Villar no mapa da alta cozinha da Costa del Sol."},{id:"mrb_lena",categoryId:"gastronomia",city:"marbella",name:"Leña Marbella",tagline:"O asador global de Dani García",description:"Asador de autor do chef Dani García (ex-três estrelas Michelin) no resort Puente Romano. Brasa, cortes de carne selecionados e técnica aprendida pelo mundo, num dos espaços mais cenográficos de Marbella, premiado pelo design. Ícone da alta gastronomia de grelha da Costa del Sol.",lat:36.4996,lng:-4.9185,durationLabel:"jantar 2h",fit:"ANY",mapQuery:"Leña Marbella, Puente Romano, Bulevar Príncipe Alfonso de Hohenlohe, Marbella",whatToDo:"Peça os grandes cortes maturados na brasa; explore os coquetéis de autor do bar antes de sentar.",kingTip:"Prato-assinatura na carne maturada ao carvão. Casa muito procurada por famosos no verão: reserve com antecedência e vá arrumado (dress code).",priceLevel:"€€€€",hours:{openDays:"Seg-Dom",openHour:"13:00",closeHour:"00:00",note:"Aberto todos os dias em temporada; confirme"},links:[{label:"Site oficial e reserva",url:"https://lenarestaurants.com/es/marbella/"}],history:"Depois de devolver as três estrelas do seu restaurante epônimo, Dani García reinventou-se com formatos como o Leña, eleito um dos restaurantes mais bonitos do mundo em 2021."},{id:"mrb_nobu",categoryId:"gastronomia",city:"marbella",name:"Nobu Marbella",tagline:"O nipo-peruano de culto do Puente Romano",description:"Filial da célebre marca de Nobu Matsuhisa, no Nobu Hotel dentro do Puente Romano. Cozinha nipo-peruana com os clássicos globais da casa e produto local, em ambiente sofisticado e animado. Referência do jantar de luxo em Marbella.",lat:36.4993,lng:-4.9177,durationLabel:"jantar 2h",fit:"ANY",mapQuery:"Nobu Marbella, Puente Romano Beach Resort, Marbella",whatToDo:"Peça os clássicos black cod miso e o tiradito; reserve pela plataforma para garantir horário de jantar.",kingTip:"Ambiente adults-only e com dress code. Prato-assinatura no bacalhau negro ao missô. Reserve 6-8 semanas antes para julho, o pico da temporada.",priceLevel:"€€€€",hours:{openDays:"Seg-Dom",openHour:"19:00",closeHour:"00:00",note:"Jantar; horários e terraço variam por temporada"},links:[{label:"Site oficial",url:"https://www.puenteromano.com/dining-drinks/nobu/"},{label:"Reserva",url:"https://www.sevenrooms.com/reservations/nobupuenteromano"}],history:"Aberto em 2017 no Nobu Hotel Marbella, trouxe à Costa del Sol a assinatura nipo-peruana criada por Nobu Matsuhisa e Robert De Niro."},{id:"grn_farala",categoryId:"gastronomia",city:"granada",name:"Faralá",tagline:"A primeira estrela Michelin de Granada",description:"Uma estrela Michelin da chef Cristina Jiménez, a primeira concedida à cidade de Granada, na guia 2026. Alta cozinha de produto local em preparos precisos e diretos, aos pés da Alhambra, na subida da Cuesta de Gomérez. Espaço que combina gastronomia, arte e programação de flamenco.",lat:37.1758,lng:-3.592,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Faralá, Cuesta de Gomérez 11, Granada",whatToDo:"Combine o menu-degustação com o El Quejío Wine Bar da casa; ideal antes ou depois da visita à Alhambra.",kingTip:"Estrela recém-conquistada e muita procura: RESERVE COM MESES DE ANTECEDÊNCIA. Pergunte pela programação de flamenco ao reservar.",priceLevel:"~€110/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"23:00",note:"Dias e horários podem variar; confirme na reserva"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/es/es/andalucia/granada/restaurante/farala"}],history:"Com Cristina Jiménez, de 33 anos, Granada conquistou em 2026 a sua primeira estrela Michelin, na porta dos jardins da Alhambra."},{id:"crd_noor",categoryId:"gastronomia",city:"cordoba",name:"Noor",tagline:"Três estrelas Michelin ao sabor de Al-Andalus",description:"Três estrelas Michelin do chef Paco Morales, no bairro do Cañero, longe do centro turístico. Uma viagem à cozinha de Al-Andalus reconstruída com técnica de vanguarda e ingredientes históricos. Um dos poucos triestrelados da Andaluzia e experiência gastronômica de destino.",lat:37.8759,lng:-4.7548,durationLabel:"jantar 3h+",fit:"ANY",mapQuery:"Noor Restaurant, Calle Pablo Ruiz Picasso 8, Córdoba",whatToDo:"Reserve o menu-degustação com harmonização; reserve a noite inteira para a experiência completa de imersão andalusí.",kingTip:"Um dos triestrelados mais difíceis da Espanha e com temporada limitada. RESERVE ASSIM QUE ABRIREM AS DATAS, com vários meses de antecedência.",priceLevel:"~€250/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Temporada limitada; confirme período de abertura e dias"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/cordoba/restaurant/noor"}],history:"Paco Morales dedicou Noor a recriar a cozinha do califado de Córdoba, subindo de uma a três estrelas até se tornar templo da gastronomia andalusí."},{id:"crd_choco",categoryId:"gastronomia",city:"cordoba",name:"Choco",tagline:"A estrela Michelin de bairro de Kisko García",description:"Uma estrela Michelin do chef Kisko García, no bairro onde cresceu, em Córdoba. Cozinha criativa enraizada no produto do Valle de los Pedroches, em dois menus-degustação que celebram a memória local. Casa próxima e pessoal, contraponto perfeito ao Noor.",lat:37.8828,lng:-4.7647,durationLabel:"jantar 2-3h",fit:"ANY",mapQuery:"Choco Restaurante, Calle Compositor Serrano Lucena 14, Córdoba",whatToDo:"Escolha entre os menus Barrio Antiguo e Kisko García; peça sugestão de harmonização à casa.",kingTip:"Estrela consolidada e sala reduzida. Reserve com antecedência; em julho, a demanda de Córdoba se concentra nos poucos estrelados.",priceLevel:"~€120/pessoa (est.)",hours:{openDays:"Ter-Sáb",openHour:"13:30",closeHour:"22:30",note:"Fecha domingo e segunda; confirme"},links:[{label:"Guia Michelin",url:"https://guide.michelin.com/us/en/andalucia/cordoba/restaurant/choco"}],history:"Kisko García transformou o restaurante de família num estrelado, mantendo o vínculo com o bairro e o campo cordovês."},{id:"mlg_los_marinos_jose",categoryId:"gastronomia",city:"malaga",name:"Los Marinos José",tagline:"O chiringuito premium do espeto e do marisco",description:"O chiringuito mais celebrado da Costa del Sol, à beira-mar em Fuengirola, frente à praia de Carvajal. Peixe e marisco de lota do dia e o clássico espeto de sardinha assado na barca de lenha, com qualidade de joalheria marinha. O contraponto descontraído — porém premium — aos estrelados.",lat:36.5388,lng:-4.606,durationLabel:"almoço 1h30-2h",fit:"CLEAR_SKY",mapQuery:"Los Marinos José, Paseo Marítimo Rey de España 161, Fuengirola",whatToDo:"Peça o espeto de sardinha e deixe o garçom sugerir o marisco fresco do dia; almoço à beira-mar de frente para a praia.",kingTip:"Espeto de sardinha na brasa é obrigatório. Não estrelado, mas dos mais disputados: reserve com antecedência e prefira o almoço; fecha domingo e segunda.",priceLevel:"€€€",hours:{openDays:"Ter-Sáb",openHour:"13:00",closeHour:"22:30",note:"Fecha domingo e segunda; serve almoço e jantar"},links:[{label:"Site oficial e reserva",url:"https://www.marinosjose.com"},{label:"Guia Michelin",url:"https://guide.michelin.com/en/andalucia/fuengirola/restaurant/los-marinos-jose"}],history:"Aberto há mais de quarenta anos pelos irmãos Sánchez, passou de humilde chiringuito a referência nacional do peixe fresco e do espeto."},{id:"grn_alhambra_palacios_nazaries",categoryId:"granada",city:"granada",name:"Alhambra — Palácios Nazaríes",tagline:"A joia moura da Espanha, imperdível",description:"O conjunto palaciano dos sultões nazaríes é o auge da arte islâmica no Ocidente. Estuques rendados, azulejos geométricos e o Pátio dos Leões deixam qualquer visitante sem palavras. É a atração mais visitada da Espanha.",lat:37.1774,lng:-3.5896,durationLabel:"3–4 h para todo o recinto",fit:"ANY",mapQuery:"Palacios Nazaries, Alhambra, Granada",whatToDo:"Percorra os Palácios Nazaríes, o Alcazaba (fortaleza) e o Palácio de Carlos V no mesmo bilhete geral.",kingTip:"ATENÇÃO: o ingresso geral com data/hora esgota MESES antes — compre assim que abrir a venda. A entrada aos Palácios Nazaríes tem horário marcado IMPRETERÍVEL (tolerância de ~30 min); se perder o horário, perde o acesso ao palácio. Em julho, reserve a primeira sessão da manhã ou a última da tarde para fugir do calor e da multidão.",priceLevel:"€€ (geral ~18 €, estimativa)",hours:{openDays:"Todos os dias",openHour:"08:30",closeHour:"20:00",note:"Visita noturna aos Palácios em dias selecionados; horário dos Nazaríes é fixo no bilhete."},links:[{label:"Site oficial / ingressos",url:"https://tickets.alhambra-patronato.es"},{label:"Patronato de la Alhambra",url:"https://www.alhambra-patronato.es"}],history:"Erguida a partir do século XIII pela dinastia nazarí, foi o último reduto muçulmano da Península até 1492, quando os Reis Católicos tomaram Granada."},{id:"grn_generalife",categoryId:"granada",city:"granada",name:"Generalife",tagline:"Os jardins de recreio dos sultões",description:"A residência de veraneio dos reis nazaríes, com jardins escalonados, fontes e o célebre Pátio da Acequia. É um oásis de água corrente e cheiro de murta, com vistas privilegiadas sobre a Alhambra.",lat:37.1785,lng:-3.5842,durationLabel:"45–60 min",fit:"CLEAR_SKY",mapQuery:"Generalife, Alhambra, Granada",kingTip:"Já está incluso no ingresso geral da Alhambra — não precisa comprar à parte. Deixe para o fim do percurso, quando a luz baixa realça as flores.",priceLevel:"Incluso no bilhete geral",links:[{label:"Ingressos oficiais",url:"https://tickets.alhambra-patronato.es"}]},{id:"grn_mirador_san_nicolas",categoryId:"granada",city:"granada",name:"Mirador de San Nicolás",tagline:"O pôr do sol mais famoso sobre a Alhambra",description:"Do alto do Albaicín, este terraço oferece a vista postal de Granada: a Alhambra inteira recortada contra a Serra Nevada. Ao entardecer, músicos de rua e viajantes se reúnem para ver o palácio pegar fogo de dourado.",lat:37.1809,lng:-3.5924,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Mirador de San Nicolas, Granada",kingTip:"Chegue 40 min antes do pôr do sol para garantir lugar no muro. Em julho o sol se põe por volta das 21h30 — o calor já cedeu e a luz fica perfeita.",priceLevel:"Gratuito"},{id:"grn_albaicin",categoryId:"granada",city:"granada",name:"Albaicín",tagline:"O labirinto mouro, Patrimônio da Humanidade",description:"O antigo bairro muçulmano é um dédalo de ruas de pedra, casas caiadas, cármenes (casas com jardim murado) e placinhas escondidas. Perder-se aqui é o programa — cada esquina revela um arco, uma buganvília ou uma vista nova da Alhambra.",lat:37.1817,lng:-3.5936,durationLabel:"1,5–2 h a pé",fit:"ANY",mapQuery:"Albaicin, Granada",kingTip:"Suba de teleférico não existe: são ladeiras íngremes. Use calçado firme e faça o passeio de manhã ou no fim da tarde para escapar do sol de julho.",priceLevel:"Gratuito",history:"Núcleo urbano de origem zirí e nazarí, mantém o traçado medieval intacto e foi declarado Patrimônio da Humanidade pela UNESCO em 1994."},{id:"grn_sacromonte",categoryId:"granada",city:"granada",name:"Sacromonte",tagline:"Cuevas brancas e flamenco cigano",description:"O bairro das cavernas escavadas na encosta é o berço do flamenco zambra granadino. À noite, as cuevas viram tablaos íntimos onde se dança a poucos palmos do público. De dia, o Mirador do Sacromonte rivaliza com o de San Nicolás.",lat:37.1852,lng:-3.5812,durationLabel:"Noite: 1,5–2 h de espetáculo",fit:"ANY",mapQuery:"Sacromonte, Granada",whatToDo:"Assista a uma zambra numa cueva histórica e visite o Museo Cuevas del Sacromonte para entender o modo de vida das cavernas.",kingTip:"Reserve o tablao com antecedência e prefira as casas tradicionais (Los Tarantos, Venta El Gallo, Cuevas Los Tarantos) à zona turística. Vá de táxi à noite — a subida é longa e mal iluminada.",priceLevel:"€€–€€€ (espetáculo com bebida, estimativa)"},{id:"grn_catedral_capilla_real",categoryId:"granada",city:"granada",name:"Catedral de Granada & Capilla Real",tagline:"Renascimento monumental e o túmulo dos Reis Católicos",description:"A catedral renascentista impressiona pela nave branca e dourada de proporções colossais. Ao lado, a Capilla Real guarda os túmulos de Isabel de Castela e Fernando de Aragão, os monarcas que unificaram a Espanha.",lat:37.1765,lng:-3.5993,durationLabel:"1–1,5 h para as duas",fit:"INDOOR",mapQuery:"Catedral de Granada, Granada",kingTip:"Ótimo refúgio do calor do meio-dia. A Capilla Real é bilhete separado da Catedral e não permite fotos na cripta real — respeite a regra.",priceLevel:"€ (cada uma ~6 €, estimativa)",hours:{openDays:"Seg a sáb; domingo horário reduzido",openHour:"10:00",closeHour:"18:15",note:"Fecha em horários de culto; confira no site."},links:[{label:"Catedral de Granada",url:"https://catedraldegranada.com"},{label:"Capilla Real de Granada",url:"https://capillarealgranada.com"}],history:"Iniciada em 1523 sobre a antiga mesquita maior, é obra-prima de Diego de Siloé; a Capilla Real, gótica, foi concluída em 1521 para sepultar os Reis Católicos."},{id:"grn_alcaiceria",categoryId:"granada",city:"granada",name:"Alcaicería",tagline:"O antigo bazar de seda mourisco",description:"Uma trama de vielas estreitas junto à catedral, reconstituição do souk nazarí onde se comerciava seda. Hoje reúne lojinhas de especiarias, lâmpadas, cerâmica e artesanato árabe — colorido e perfumado.",lat:37.1755,lng:-3.5989,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Alcaiceria, Granada",kingTip:"Pechinche com bom humor e compare preços entre as bancas. É central e coberto — bom para uma pausa fresca à tarde.",priceLevel:"Gratuito (compras à parte)"},{id:"grn_carmen_de_los_martires",categoryId:"granada",city:"granada",name:"Carmen de los Mártires",tagline:"Jardins românticos e pavões livres",description:"Um carmen palaciano nas encostas da Alhambra, com jardins franceses, lagos, grutas e pavões que passeiam soltos. É um recanto tranquilo e pouco lotado, com vistas amplas sobre a cidade e a vega.",lat:37.172,lng:-3.5872,durationLabel:"45–60 min",fit:"CLEAR_SKY",mapQuery:"Carmen de los Martires, Granada",kingTip:"Entrada gratuita e quase sempre vazia — segredo bem guardado a poucos passos da Alhambra. Vá no fim da tarde, quando o calor afrouxa.",priceLevel:"Gratuito",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"20:00",note:"Horário de verão mais amplo; entrada gratuita."}},{id:"grn_monasterio_cartuja",categoryId:"granada",city:"granada",name:"Monasterio de la Cartuja",tagline:"O barroco levado ao delírio",description:"Este mosteiro cartuxo abriga uma das sacristias barrocas mais exuberantes da Espanha, com mármores policromados, talha dourada e trompe-l'oeil que confundem o olhar. Um exagero decorativo que impressiona pela ousadia.",lat:37.1934,lng:-3.6042,durationLabel:"45 min",fit:"INDOOR",mapQuery:"Monasterio de la Cartuja, Granada",kingTip:"Fica afastado do centro (táxi ou ônibus). Vale o desvio para quem ama o barroco — e é fresco por dentro no auge do calor.",priceLevel:"€ (~5 €, estimativa)",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"19:00",note:"Horário reduzido no inverno."}},{id:"crd_mezquita_catedral",categoryId:"cordoba",city:"cordoba",name:"Mesquita-Catedral de Córdoba",tagline:"A floresta de arcos vermelhos e brancos",description:"O monumento máximo de Córdoba: um bosque de 856 colunas e arcos bicolores erguido como grande mesquita omíada, com uma catedral renascentista brotando do centro. A fusão de duas civilizações num só espaço é comovente e única no mundo.",lat:37.879,lng:-4.7794,durationLabel:"1,5–2 h",fit:"INDOOR",mapQuery:"Mezquita-Catedral de Cordoba",whatToDo:"Percorra o mihrab dourado, a floresta de colunas e suba à torre-campanário (antigo alminar) para a vista.",kingTip:"De segunda a sábado, das 8h30 às 9h30, a entrada ao templo é GRATUITA (sem grupos) — chegue cedo e aproveite o interior quase vazio e fresco antes do calor de julho. A subida à torre é bilhete à parte e com horário marcado.",priceLevel:"€€ (~13 €, estimativa; torre à parte)",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"19:00",note:"Domingo com horário reduzido; janela gratuita seg–sáb 08:30–09:30."},links:[{label:"Site oficial / ingressos",url:"https://mezquita-catedraldecordoba.es"}],history:"Erguida a partir de 785 pelo emir Abderramão I sobre uma basílica visigótica, foi ampliada por séculos; após 1236 foi consagrada catedral, ganhando a nave cristã no século XVI."},{id:"crd_juderia",categoryId:"cordoba",city:"cordoba",name:"Judería",tagline:"O bairro judeu de becos caiados",description:"O antigo bairro judaico é uma teia de vielas brancas, pátios floridos e a pequena Sinagoga do século XIV, uma das três medievais preservadas na Espanha. Aqui também estão a Calleja de las Flores e o Zoco artesanal.",lat:37.8788,lng:-4.782,durationLabel:"1–1,5 h a pé",fit:"ANY",mapQuery:"Juderia de Cordoba",whatToDo:"Visite a Sinagoga, espie pátios abertos e fotografe a Calleja de las Flores emoldurando a torre da Mesquita.",kingTip:"As vielas estreitas guardam sombra — bom refúgio ao meio-dia. Vá cedo para fotografar a Calleja de las Flores sem multidão.",priceLevel:"Gratuito (Sinagoga simbólica)",history:"Habitado por judeus até a expulsão de 1492, o bairro preserva o traçado medieval e foi parte do centro histórico declarado Patrimônio da Humanidade em 1994."},{id:"crd_alcazar_reyes_cristianos",categoryId:"cordoba",city:"cordoba",name:"Alcázar de los Reyes Cristianos",tagline:"Fortaleza real e jardins de água",description:"Palácio-fortaleza dos monarcas cristãos, com torres, mosaicos romanos e salões abobadados. O ponto alto são os jardins escalonados: fileiras de tanques, repuxos, ciprestes e laranjeiras que se estendem sob o sol andaluz.",lat:37.8765,lng:-4.7817,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Alcazar de los Reyes Cristianos, Cordoba",kingTip:"Os jardins não têm sombra — visite logo na abertura ou no fim da tarde. Foi daqui que Colombo foi recebido pelos Reis Católicos antes da viagem de 1492.",priceLevel:"€ (~5 €, estimativa)",hours:{openDays:"Ter a dom (fecha segunda)",openHour:"08:15",closeHour:"20:00",note:"Horário de verão amplo; entrada reduzida às quintas em alguns períodos."}},{id:"crd_puente_romano_calahorra",categoryId:"cordoba",city:"cordoba",name:"Puente Romano & Torre de la Calahorra",tagline:"A ponte milenar sobre o Guadalquivir",description:"A ponte romana de dezesseis arcos cruza o Guadalquivir desde a época imperial, servindo de cartão-postal ao entardecer. Na outra margem, a Torre de la Calahorra, fortaleza islâmica, abriga um museu sobre a convivência das três culturas.",lat:37.8759,lng:-4.7778,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Puente Romano de Cordoba",kingTip:"Atravesse a pé ao pôr do sol para a melhor foto da Mesquita refletida no rio. A torre oferece vista do alto da cidade histórica.",priceLevel:"Ponte gratuita; torre ~4,50 € (estimativa)",history:"De origem romana (século I a.C.), a ponte foi muitas vezes reconstruída; a Calahorra é fortificação de raiz islâmica, ampliada no período cristão."},{id:"crd_palacio_de_viana",categoryId:"cordoba",city:"cordoba",name:"Palacio de Viana",tagline:"Doze pátios floridos num só palácio",description:'Conhecido como o "museu dos pátios", este palácio renascentista reúne doze pátios ajardinados e um jardim, cada um com caráter próprio — de fontes mudéjares a laranjeiras e buganvílias. É a essência da tradição cordobesa dos patios.',lat:37.8907,lng:-4.7745,durationLabel:"1 h",fit:"CLEAR_SKY",mapQuery:"Palacio de Viana, Cordoba",whatToDo:"Faça o circuito dos doze pátios; opcionalmente some a visita guiada aos aposentos do palácio.",kingTip:"Se não pegar o Festival de los Patios (maio), este é o jeito de ver os pátios cordobeses o ano todo. Vá de manhã, quando as plantas são regadas e o ar fica fresco.",priceLevel:"€ (pátios ~8 €; combinado com palácio ~12 €, estimativa)",hours:{openDays:"Ter a dom (fecha segunda)",openHour:"10:00",closeHour:"15:00",note:"No verão fecha à tarde pelo calor; confira horário atualizado."},links:[{label:"Site oficial",url:"https://www.palaciodeviana.com"}]},{id:"crd_plaza_de_la_corredera",categoryId:"cordoba",city:"cordoba",name:"Plaza de la Corredera",tagline:"A grande praça porticada castelhana",description:"Única praça maior retangular fechada da Andaluzia, ao estilo das plazas mayores castelhanas. Suas fachadas vermelhas com arcadas abrigam bares e um mercado; à noite, as mesas se enchem e a praça vira ponto de encontro.",lat:37.8836,lng:-4.7742,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Plaza de la Corredera, Cordoba",kingTip:"Sente-se numa esplanada sob os arcos para um vermute ao entardecer. Pela manhã há mercado no interior — bom para provar produtos locais.",priceLevel:"Gratuito (consumo à parte)",history:"Construída no fim do século XVII, serviu de praça de touros, mercado e palco de festas públicas ao longo dos séculos."},{id:"mlg_gran_hotel_miramar",categoryId:"hospedagem",city:"malaga",name:"Gran Hotel Miramar GL",tagline:"5★GL belle époque à beira-mar",description:"Palácio de 1926 restaurado como o único 5★ Gran Lujo de Málaga, no Paseo de Reding, entre o centro e a praia da Malagueta. Átrio senhorial com cúpula de vitral, spa e restaurante de alta gastronomia. É a hospedagem mais grand da cidade, com serviço à altura.",whatToDo:["spa","jantar de alta cozinha","a 10 min a pé da Catedral"],kingTip:"Peça um quarto de frente para o mar (sea view); os dos fundos olham para a colina de Gibralfaro.",lat:36.7205,lng:-4.409,durationLabel:"estadia",fit:"ANY",priceLevel:"~€350–600/noite (est., jul)",mapQuery:"Gran Hotel Miramar GL, Málaga",links:[{label:"Site oficial",url:"https://www.granhotelmiramarmalaga.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Gran+Hotel+Miramar+GL+Malaga"}]},{id:"mlg_palacio_solecio",categoryId:"hospedagem",city:"malaga",name:"Palacio Solecio",tagline:"Palacete do séc. XVIII no coração histórico",description:"Boutique 5★ instalado num palacete setecentista na Calle Granada, a passos da Catedral e do Museu Picasso. Pátio andaluz, décor sóbrio e o restaurante Balausta, do chef José Carlos García. Perfeito para quem quer dormir dentro do centro histórico com elegância.",whatToDo:["restaurante Balausta","a 3 min do Museu Picasso"],kingTip:"Melhor base para explorar o centro a pé; reserve os quartos com varanda sobre o pátio.",lat:36.7223,lng:-4.4188,durationLabel:"estadia",fit:"ANY",priceLevel:"~€230–380/noite (est., jul)",mapQuery:"Palacio Solecio, Málaga",links:[{label:"Site oficial",url:"https://www.palaciosolecio.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Palacio+Solecio+Malaga"}]},{id:"mlg_only_you",categoryId:"hospedagem",city:"malaga",name:"Only YOU Hotel Málaga",tagline:"5★ de design no edifício La Equitativa",description:"Aberto no icônico prédio La Equitativa, junto à Calle Larios, une design contemporâneo e vibe social. O ponto alto é o rooftop Lolita, com piscina, redes e bar de vista panorâmica sobre a cidade. Para quem gosta de hotel moderno, animado e supercentral.",whatToDo:["rooftop","piscina panorâmica","a 5 min da Catedral"],kingTip:"Suba ao Lolita Skyview no fim da tarde; o pôr do sol sobre os telhados é o melhor momento.",lat:36.717,lng:-4.4202,durationLabel:"estadia",fit:"ANY",priceLevel:"~€260–430/noite (est., jul)",mapQuery:"Only YOU Hotel Málaga",links:[{label:"Site oficial",url:"https://www.onlyyouhotels.com/en/hotels/only-you-hotel-malaga/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Only+YOU+Hotel+Malaga"}]},{id:"mlg_molina_lario",categoryId:"hospedagem",city:"malaga",name:"Hotel Molina Lario",tagline:"4★ com rooftop de frente para a Catedral",description:"Clássico bem-localizado a menos de 100 m da Catedral, entre o centro e o porto de Muelle Uno. Quartos amplos e confortáveis e um terraço com piscina e vista para a torre da Catedral. Ótimo custo-benefício para uma base central sem exageros.",whatToDo:["rooftop","piscina","a 2 min da Catedral"],kingTip:"O terraço com piscina abre no verão; vá ao anoitecer para ver a Catedral iluminada.",lat:36.7188,lng:-4.4193,durationLabel:"estadia",fit:"ANY",priceLevel:"~€180–300/noite (est., jul)",mapQuery:"Hotel Molina Lario, Málaga",links:[{label:"Site oficial",url:"https://www.hotelmolinalario.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hotel+Molina+Lario+Malaga"}]},{id:"mlg_parador_gibralfaro",categoryId:"hospedagem",city:"malaga",name:"Parador de Málaga Gibralfaro",tagline:"A melhor vista da cidade, no monte",description:"Parador junto ao castelo de Gibralfaro, no alto do monte, com a vista mais espetacular de Málaga: a cidade, a Plaza de Toros e o Mediterrâneo aos pés. Prédio simples e acolhedor, com terraço e piscina. Vale pela paisagem, não pela proximidade do centro.",whatToDo:["mirante panorâmico","piscina","junto ao Castelo de Gibralfaro"],kingTip:"Reserve mesa no terraço ao entardecer; a vista da praça de touros e do porto é a foto de Málaga.",lat:36.7237,lng:-4.4103,durationLabel:"estadia",fit:"ANY",priceLevel:"~€190–320/noite (est., jul)",mapQuery:"Parador de Málaga Gibralfaro",links:[{label:"Site oficial",url:"https://www.parador.es/es/paradores/parador-de-malaga-gibralfaro"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Parador+de+Malaga+Gibralfaro"}]},{id:"mlg_flats_centro_historico",categoryId:"hospedagem",city:"malaga",name:"Flats no Centro Histórico",tagline:"Apartamentos entre Larios e a Catedral",description:"Alternativa aos hotéis: apartamentos e flats de temporada no coração de Málaga, entre a Calle Larios, a Catedral e o Soho. Bom para famílias ou estadas mais longas, com cozinha e mais espaço. Ideal para viver a cidade a pé, com mercados e tapas na porta.",whatToDo:["cozinha própria","a pé por todo o centro"],kingTip:"Prefira endereços a leste da Larios (Catedral/Alcazaba); evite térreos na zona de bares pelo ruído noturno.",lat:36.7196,lng:-4.42,durationLabel:"estadia",fit:"ANY",priceLevel:"~€120–260/noite (est., jul)",mapQuery:"Centro Histórico, Málaga",links:[{label:"Buscar no Airbnb",url:"https://www.airbnb.com.br/s/M%C3%A1laga--Spain/homes"}]},{id:"nrj_parador_nerja",categoryId:"hospedagem",city:"axarquia",name:"Parador de Nerja",tagline:"Sobre a falésia, com elevador à praia",description:"Parador debruçado na falésia de Nerja, com jardins, piscina e acesso próprio de elevador à praia de Burriana. Quartos tranquilos e amplos, muitos com varanda para o mar. Base perfeita para explorar o Balcón de Europa, as calas e a Axarquía.",whatToDo:["piscina de frente para o mar","elevador à praia de Burriana","a 10 min do Balcón de Europa"],kingTip:"Peça quarto com terraço e vista mar; a diferença de preço compensa pelo nascer do sol sobre a água.",lat:36.7418,lng:-3.8695,durationLabel:"estadia",fit:"ANY",priceLevel:"~€200–330/noite (est., jul)",mapQuery:"Parador de Nerja",links:[{label:"Site oficial",url:"https://www.parador.es/es/paradores/parador-de-nerja"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Parador+de+Nerja"}]},{id:"nrj_posada_morisca",categoryId:"hospedagem",city:"axarquia",name:"La Posada Morisca",tagline:"Boutique rústico nas serras de Frigiliana",description:"Pequeno hotel boutique de 12 quartos no campo, à beira do Parque Natural Sierra de Tejeda, a poucos minutos de Frigiliana. Casinhas de estilo mourisco com terraço, lareira e vista para o mar e a serra. Refúgio íntimo, silencioso e cheio de charme andaluz.",whatToDo:["piscina","terraços com vista serra e mar","a 20 min a pé de Frigiliana"],kingTip:"Reserve com carro; a vila mais bonita da região fica logo abaixo e o café da manhã no terraço é imperdível.",lat:36.793,lng:-3.913,durationLabel:"estadia",fit:"ANY",priceLevel:"~€150–240/noite (est., jul)",mapQuery:"La Posada Morisca, Frigiliana",links:[{label:"Site oficial",url:"https://www.laposadamorisca.com/en/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=La+Posada+Morisca+Frigiliana"}]},{id:"nrj_airbnb_frigiliana_nerja",categoryId:"hospedagem",city:"axarquia",name:"Airbnb em Frigiliana / Nerja",tagline:"Casas brancas e flats na Axarquía",description:"Aluguel de temporada nas duas joias da Axarquía: casinhas encaladas no casco antigo de Frigiliana ou flats à beira-mar em Nerja. Boa opção para quem quer autonomia, cozinha e vistas de serra ou praia. Ideal para famílias e estadas de vários dias.",whatToDo:["cozinha própria","vilas brancas e praias"],kingTip:"Em Frigiliana escolha o casco antiguo (mais fotogênico, porém de ladeiras); em Nerja, algo perto do Balcón de Europa.",lat:36.7885,lng:-3.8965,durationLabel:"estadia",fit:"ANY",priceLevel:"~€110–220/noite (est., jul)",mapQuery:"Frigiliana, Spain",links:[{label:"Buscar no Airbnb (Frigiliana)",url:"https://www.airbnb.com.br/s/Frigiliana--Spain/homes"},{label:"Buscar no Airbnb (Nerja)",url:"https://www.airbnb.com.br/s/Nerja--Spain/homes"}]},{id:"ant_parador_antequera",categoryId:"hospedagem",city:"antequera",name:"Parador de Antequera",tagline:"Base serena para o coração de Málaga",description:"Parador tranquilo cercado de jardins, com piscina e vista para a Vega e a Peña de los Enamorados. Prédio de linhas modernas e ambiente calmo, ótimo ponto de partida para os Dólmenes, El Torcal e a estrada até Granada e Córdoba. Confortável e sem alardes.",whatToDo:["piscina","jardins","a 5 min dos Dólmenes"],kingTip:"Antequera é o hub geográfico da região: durma aqui para bater Torcal e dólmenes com calma antes de seguir viagem.",lat:37.0208,lng:-4.5588,durationLabel:"estadia",fit:"ANY",priceLevel:"~€120–200/noite (est., jul)",mapQuery:"Parador de Antequera",links:[{label:"Site oficial",url:"https://www.parador.es/es/paradores/parador-de-antequera"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Parador+de+Antequera"}]},{id:"rnd_fuente_higuera",categoryId:"hospedagem",city:"ronda",name:"La Fuente de la Higuera",tagline:"Casa-de-campo boutique num olival",description:"Refúgio boutique num antigo lagar de azeite entre oliveiras, a poucos minutos de Ronda. Quartos e suítes de décor autoral, piscina serena e jardins com vista para o vale. Atmosfera íntima e adulta, para desacelerar longe do bulício da cidade.",whatToDo:["piscina no olival","spa e sossego","a 10 min de carro de Ronda"],kingTip:"Precisa de carro; peça uma suíte com terraço sobre o vale e jante no restaurante da casa.",lat:36.762,lng:-5.1905,durationLabel:"estadia",fit:"ANY",priceLevel:"~€220–360/noite (est., jul)",mapQuery:"La Fuente de la Higuera, Ronda",links:[{label:"Site oficial",url:"https://www.hotellafuente.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=La+Fuente+de+la+Higuera+Ronda"}]},{id:"rnd_parador_ronda",categoryId:"hospedagem",city:"ronda",name:"Parador de Ronda",tagline:"Sobre o Tajo, ao lado da Puente Nuevo",description:"Instalado na antiga Casa Consistorial, à borda do desfiladeiro do Tajo e colado à Puente Nuevo. Terraço e piscina suspensos sobre o abismo, com vista de tirar o fôlego. É o endereço mais icônico de Ronda, no ponto exato dos cartões-postais.",whatToDo:["piscina sobre o desfiladeiro","vista da Puente Nuevo","no centro histórico"],kingTip:"Reserve quarto com vista para o Tajo; a piscina à beira do precipício é o auge da estada.",lat:36.7418,lng:-5.1663,durationLabel:"estadia",fit:"ANY",priceLevel:"~€200–340/noite (est., jul)",mapQuery:"Parador de Ronda",links:[{label:"Site oficial",url:"https://www.parador.es/es/paradores/parador-de-ronda"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Parador+de+Ronda"}]},{id:"rnd_montelirio",categoryId:"hospedagem",city:"ronda",name:"Hotel Montelirio",tagline:"Palacete boutique na borda do Tajo",description:"Boutique 4★ num palácio do séc. XVII na Calle Tenorio, debruçado sobre o desfiladeiro. Terraço, piscina e restaurante Albacara com vista vertiginosa para o vale. Elegante e intimista, a poucos passos da Puente Nuevo.",whatToDo:["terraço panorâmico","piscina sobre o vale","a 2 min da Puente Nuevo"],kingTip:"Os quartos 'con vistas' valem cada euro; jante no Albacara ao pôr do sol sobre o Tajo.",lat:36.7414,lng:-5.1673,durationLabel:"estadia",fit:"ANY",priceLevel:"~€180–300/noite (est., jul)",mapQuery:"Hotel Montelirio, Ronda",links:[{label:"Site oficial",url:"https://www.hotelmontelirio.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hotel+Montelirio+Ronda"}]},{id:"mrb_puente_romano",categoryId:"hospedagem",city:"marbella",name:"Puente Romano Beach Resort",tagline:"Resort-vila 5★GL na Milha de Ouro",description:"Ícone da Costa del Sol: um resort em forma de vila andaluza ajardinada, à beira-mar na Golden Mile. Reúne praia, spa, clube de tênis, piscinas e a badalada praça de restaurantes de assinatura. Sofisticado, familiar e social ao mesmo tempo.",whatToDo:["spa","praia e piscinas","restaurantes de assinatura"],kingTip:"Entre Marbella e Puerto Banús; a Sala de restaurantes fica lotada no verão, reserve jantar com antecedência.",lat:36.4906,lng:-4.949,durationLabel:"estadia",fit:"ANY",priceLevel:"~€500–900/noite (est., jul)",mapQuery:"Puente Romano Beach Resort, Marbella",links:[{label:"Site oficial",url:"https://www.puenteromano.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Puente+Romano+Beach+Resort+Marbella"}]},{id:"mrb_marbella_club",categoryId:"hospedagem",city:"marbella",name:"Marbella Club Hotel",tagline:"O clube lendário da Golden Mile",description:"Hotel-jardim fundado em 1954 pelo príncipe Alfonso von Hohenlohe, berço da lenda glamourosa de Marbella. Bangalôs entre jardins tropicais, praia privativa, spa e um serviço de discreção total. Clássico atemporal para quem busca elegância à moda antiga.",whatToDo:["spa","praia privativa","jardins históricos"],kingTip:"As villas com piscina privativa são o topo; peça mesa no beach club ao almoço.",lat:36.4922,lng:-4.954,durationLabel:"estadia",fit:"ANY",priceLevel:"~€450–850/noite (est., jul)",mapQuery:"Marbella Club Hotel",links:[{label:"Site oficial",url:"https://www.marbellaclub.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Marbella+Club+Hotel"}]},{id:"mrb_nobu_marbella",categoryId:"hospedagem",city:"marbella",name:"Nobu Hotel Marbella",tagline:"Design japonês dentro do Puente Romano",description:"Ala boutique dentro do Puente Romano, com o estilo minimalista Nobu e o célebre restaurante japonês-peruano na casa. Quartos serenos, acesso a todo o resort e vibe cosmopolita. Para quem quer o burburinho da Golden Mile com um refúgio de design.",whatToDo:["restaurante Nobu","acesso ao resort Puente Romano","spa"],kingTip:"Reserve o omakase no Nobu com bastante antecedência no verão; hóspedes têm prioridade.",lat:36.4909,lng:-4.9483,durationLabel:"estadia",fit:"ANY",priceLevel:"~€480–850/noite (est., jul)",mapQuery:"Nobu Hotel Marbella",links:[{label:"Site oficial",url:"https://marbella.nobuhotels.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Nobu+Hotel+Marbella"}]},{id:"mrb_airbnb_puerto_banus",categoryId:"hospedagem",city:"marbella",name:"Airbnb em Puerto Banús",tagline:"Flats à beira da marina glamourosa",description:"Apartamentos e flats de temporada em Puerto Banús, junto à marina de iates, boutiques de luxo e vida noturna. Muitos com piscina de condomínio e a poucos metros da praia. Ideal para quem quer autonomia no epicentro chique de Marbella.",whatToDo:["marina e beach clubs","piscina de condomínio","compras de grife"],kingTip:"Prefira condomínios com piscina e vaga; no verão o trânsito e o estacionamento em Banús são caóticos.",lat:36.488,lng:-4.953,durationLabel:"estadia",fit:"ANY",priceLevel:"~€180–400/noite (est., jul)",mapQuery:"Puerto Banús, Marbella, Spain",links:[{label:"Buscar no Airbnb",url:"https://www.airbnb.com.br/s/Puerto-Ban%C3%BAs--Marbella--Spain/homes"}]},{id:"grn_parador_granada",categoryId:"hospedagem",city:"granada",name:"Parador de Granada",tagline:"Dentro do recinto da Alhambra",description:"O parador mais cobiçado da Espanha: um convento do séc. XV dentro dos muros da Alhambra, sobre os jardins do Generalife. Dormir aqui é ter o monumento aos pés, antes e depois das multidões. Histórico, íntimo e absolutamente irrepetível.",whatToDo:["dentro da Alhambra","jardins do Generalife","terraço com vista"],kingTip:"Reserve com MESES de antecedência; poucos quartos e demanda altíssima. Peça vista para os jardins.",lat:37.1767,lng:-3.5847,durationLabel:"estadia",fit:"ANY",priceLevel:"~€380–600/noite (est., jul)",mapQuery:"Parador de Granada",links:[{label:"Site oficial",url:"https://www.parador.es/es/paradores/parador-de-granada"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Parador+de+Granada"}]},{id:"grn_hospes_patos",categoryId:"hospedagem",city:"granada",name:"Hospes Palacio de los Patos",tagline:"Palácio senhorial 5★ com spa",description:"Palacete do séc. XIX tombado, no centro de Granada, unido a um anexo contemporâneo de mármore. Spa árabe, jardim interno e o restaurante Senzone. Luxo urbano e tranquilo, a poucos minutos a pé da Catedral e do centro comercial.",whatToDo:["spa árabe","restaurante Senzone","a 10 min da Catedral"],kingTip:"Os quartos do palácio histórico têm pé-direito alto e mais alma que os do anexo moderno.",lat:37.1707,lng:-3.602,durationLabel:"estadia",fit:"ANY",priceLevel:"~€250–420/noite (est., jul)",mapQuery:"Hospes Palacio de los Patos, Granada",links:[{label:"Site oficial",url:"https://www.hospes.com/palacio-patos/"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hospes+Palacio+de+los+Patos+Granada"}]},{id:"grn_casa_1800",categoryId:"hospedagem",city:"granada",name:"Hotel Casa 1800 Granada",tagline:"Boutique no Albaicín, aos pés da Alhambra",description:"Casa senhorial restaurada no bairro do Albaicín, com pátio de colunas e décor clássico acolhedor. Alguns quartos e o terraço têm vista frontal para a Alhambra iluminada. Charme, localização e romance a poucos passos da Carrera del Darro.",whatToDo:["terraço com vista da Alhambra","a 3 min da Carrera del Darro"],kingTip:"Vale muito o upgrade para um quarto 'vistas Alhambra'; o terraço serve chá da tarde grátis aos hóspedes.",lat:37.1765,lng:-3.5935,durationLabel:"estadia",fit:"ANY",priceLevel:"~€200–340/noite (est., jul)",mapQuery:"Hotel Casa 1800 Granada",links:[{label:"Site oficial",url:"https://www.hotelcasa1800granada.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Hotel+Casa+1800+Granada"}]},{id:"grn_airbnb_albaicin",categoryId:"hospedagem",city:"granada",name:"Airbnb no Albaicín",tagline:"Carmens e casas com vista da Alhambra",description:"Aluguel de temporada no Albaicín, o bairro mouro de ruelas de pedra tombado pela UNESCO. Os cobiçados 'carmens' têm pátio, jardim e terraço com vista frontal para a Alhambra. Experiência íntima e cheia de atmosfera, difícil de igualar em hotel.",whatToDo:["terraços com vista da Alhambra","ruelas do bairro mouro","perto do Mirador de San Nicolás"],kingTip:"Confirme se o imóvel tem 'vistas a la Alhambra' real; e prepare-se para ladeiras íngremes e táxis limitados.",lat:37.18,lng:-3.592,durationLabel:"estadia",fit:"ANY",priceLevel:"~€130–280/noite (est., jul)",mapQuery:"Albaicín, Granada, Spain",links:[{label:"Buscar no Airbnb",url:"https://www.airbnb.com.br/s/Albaic%C3%ADn--Granada--Spain/homes"}]},{id:"crd_balcon_cordoba",categoryId:"hospedagem",city:"cordoba",name:"Balcón de Córdoba",tagline:"Boutique íntimo colado à Mesquita",description:"Pequeno hotel boutique numa casa senhorial da Judería, a metros da Mesquita-Catedral. Pátios andaluzes com peças arqueológicas, terraço com vista para os telhados e um serviço atento e discreto. Refúgio silencioso no coração da Córdoba antiga.",whatToDo:["terraço com vista da Mesquita","pátios da Judería","a 2 min da Mesquita-Catedral"],kingTip:"Poucos quartos e muito procurado: reserve cedo. Suba ao terraço ao anoitecer, quando os sinos ecoam pela Judería.",lat:37.8792,lng:-4.7793,durationLabel:"estadia",fit:"ANY",priceLevel:"~€200–340/noite (est., jul)",mapQuery:"Balcón de Córdoba, Córdoba",links:[{label:"Site oficial",url:"https://www.balcondecordoba.com"},{label:"Reservar (Booking)",url:"https://www.booking.com/searchresults.pt-br.html?ss=Balcon+de+Cordoba"}]},{id:"mlg_alcazaba",categoryId:"malaga",city:"malaga",name:"Alcazaba de Málaga",tagline:"A fortaleza mourisca sobre a cidade",description:"Palácio-fortaleza do século XI, uma das cidadelas muçulmanas mais bem conservadas da Espanha. Sobe-se por rampas em ziguezague entre pátios, arcos de ferradura, fontes e jardins que emolduram vistas do porto. É o coração histórico de Málaga, colado ao Teatro Romano.",lat:36.7213,lng:-4.416,durationLabel:"1-2h",fit:"CLEAR_SKY",mapQuery:"Alcazaba de Málaga, Spain",whatToDo:["Subir pelas rampas defensivas até o Palácio Nazarí e seus pátios","Fotografar o porto e a Catedral a partir das muralhas altas","Comprar o bilhete combinado com o Castillo de Gibralfaro"],kingTip:"Vá logo às 9h, na abertura: em julho o sol bate forte nas rampas sem sombra e o pátio superior esvazia cedo. O combinado Alcazaba + Gibralfaro sai mais barato que os dois avulsos.",priceLevel:"~€3,50 (est.) | combinado com Gibralfaro ~€5,50 (est.)",hours:{openDays:[1,2,3,4,5,6,7],openHour:9,closeHour:20,note:"Horário de verão (abr-out). Domingo grátis a partir das 14h. Fechada 24, 25 e 31/dez e 1/jan."},links:[{label:"Visita Málaga (oficial)",url:"https://visita.malaga.eu/en/what-to-see-and-do/culture/historic-monuments/monuments/alcazaba-p103555"}],history:"Erguida a partir de 1057 sobre restos fenícios e romanos, foi residência dos governadores muçulmanos e último reduto na reconquista cristã de 1487.",image:"mlg_alcazaba.jpg"},{id:"mlg_gibralfaro",categoryId:"malaga",city:"malaga",name:"Castillo de Gibralfaro",tagline:"O melhor mirante de Málaga",description:"Castelo do século XIV no alto do monte que domina a cidade, ligado à Alcazaba por uma muralha. O prêmio é o caminho de ronda: um circuito completo pelas ameias com vista de 360° sobre a baía, a praça de touros e os telhados do centro. Vale mais pela paisagem do que pelo interior.",lat:36.7233,lng:-4.4108,durationLabel:"1h",fit:"CLEAR_SKY",mapQuery:"Castillo de Gibralfaro, Málaga, Spain",whatToDo:["Percorrer o caminho de ronda pelas muralhas com vistas panorâmicas","Ver a arena da Malagueta lá embaixo, moldura perfeita para foto","Visitar o pequeno centro de interpretação do castelo"],kingTip:"A subida a pé pela ladeira é bonita mas exige fôlego e não tem sombra; em pleno julho, pegue o ônibus 35 na Alameda ou um táxi para subir e desça caminhando no fim da tarde, com luz dourada.",priceLevel:"~€3,50 (est.) | combinado com Alcazaba ~€5,50 (est.)",hours:{openDays:[1,2,3,4,5,6,7],openHour:9,closeHour:20,note:"Horário de verão (abr-out). Domingo grátis a partir das 14h."},links:[{label:"Visita Málaga (oficial)",url:"https://visita.malaga.eu/en/what-to-see-and-do/culture/historic-monuments/monuments/gibralfaro-castle-p103556"}],history:"Construído por Yusuf I de Granada no século XIV para abrigar tropas e proteger a Alcazaba, resistiu a um longo cerco antes de cair em 1487.",image:"mlg_gibralfaro.jpg"},{id:"mlg_catedral",categoryId:"malaga",city:"malaga",name:"Catedral de Málaga (La Manquita)",tagline:"A dama de uma torre só",description:"Catedral renascentista monumental, apelidada de La Manquita (a maneta) porque a torre sul nunca foi concluída. O interior impressiona pela altura das naves, pela sillería do coro e por um dos maiores órgãos históricos da Espanha. Atenção: a célebre visita às cubiertas (telhados) segue fechada por obras de restauração previstas até o fim de 2027.",lat:36.7196,lng:-4.4197,durationLabel:"45min-1h",fit:"INDOOR",mapQuery:"Catedral de Málaga, Spain",whatToDo:["Admirar as naves góticas-renascentistas e a cúpula","Ver a sillería do coro esculpida por Pedro de Mena","Dar a volta pela fachada e pelo Patio de los Naranjos"],kingTip:"A visita às cubiertas está suspensa até por volta do fim de 2027 pela restauração do telhado; não conte com ela em julho. Como refúgio do calor, o interior fresco é um dos melhores da cidade no meio da tarde.",priceLevel:"~€10 (est.) interior + museu",hours:{openDays:[1,2,3,4,5,6],openHour:10,closeHour:18,note:"Domingos e feriados abre à tarde. Cubiertas (telhados) fechadas por obras até ~fim de 2027."},links:[{label:"Catedral de Málaga (oficial)",url:"https://malagacatedral.com/"}],history:"Iniciada em 1528 sobre a antiga mesquita e concluída em grande parte no século XVIII, com dinheiro que, segundo a lenda, teria ido para a segunda torre e acabou desviado para outras causas.",image:"mlg_catedral.jpg"},{id:"mlg_teatro_romano",categoryId:"malaga",city:"malaga",name:"Teatro Romano de Málaga",tagline:"Roma ao pé da fortaleza mourisca",description:"Teatro romano do século I a.C., redescoberto em 1951, encravado na encosta logo abaixo da Alcazaba. Reúne dois mil anos de história numa só imagem: a bancada romana e, acima, a muralha muçulmana. A entrada é gratuita e há um pequeno centro de interpretação na base.",lat:36.7213,lng:-4.4152,durationLabel:"30min",fit:"ANY",mapQuery:"Teatro Romano de Málaga, Spain",whatToDo:["Ver a cávea romana com a Alcazaba emoldurada ao fundo","Passar pelo centro de interpretação envidraçado na entrada","Combinar com a subida à Alcazaba, que fica ao lado"],kingTip:"É de graça e rápido: encaixe antes de subir à Alcazaba. À noite fica iluminado e a Calle Alcazabilla ao lado concentra bons bares de tapas.",priceLevel:"Grátis",hours:{openDays:[2,3,4,5,6,7],openHour:10,closeHour:18,note:"Fechado às segundas. Entrada gratuita."},links:[{label:"Visita Málaga (oficial)",url:"https://visita.malaga.eu/en/what-to-see-and-do/culture/historic-monuments/monuments/teatro-romano-p103562"}],history:"Ativo do século I a.C. ao III d.C., foi depois saqueado pelos muçulmanos para erguer a Alcazaba; permaneceu enterrado até 1951, sob uma antiga Casa de Cultura."},{id:"mlg_muelle_uno_palmeral",categoryId:"malaga",city:"malaga",name:"Muelle Uno e Palmeral de las Sorpresas",tagline:"O passeio à beira do porto",description:"A frente marítima renovada de Málaga: o Muelle Uno reúne lojas, restaurantes e o cubo de vidro colorido do Centre Pompidou, enquanto o Palmeral de las Sorpresas é uma alameda de pérgola ondulada e centenas de palmeiras. Juntos formam o melhor passeio a pé entre o centro e o mar.",lat:36.7156,lng:-4.4165,durationLabel:"1-2h",fit:"CLEAR_SKY",mapQuery:"Muelle Uno, Málaga, Spain",whatToDo:["Caminhar do Palmeral até a ponta do Muelle Uno com vista para o farol","Fotografar o cubo colorido do Centre Pompidou","Parar num terraço à beira-mar ao pôr do sol"],kingTip:"Deixe para o fim da tarde: a pérgola do Palmeral dá sombra e a brisa do mar torna o calor de julho suportável. O domingo tem feirinha de artesanato ao longo do cais.",priceLevel:"Grátis (passeio)",links:[{label:"Muelle Uno (oficial)",url:"https://www.muelleuno.com/"}],history:"O antigo porto industrial foi reurbanizado entre 2011 e 2013, devolvendo à cidade uma orla que estava fechada ao público havia décadas."},{id:"mlg_soho_maus",categoryId:"malaga",city:"malaga",name:"Soho e arte urbana MAUS",tagline:"Galeria a céu aberto de Málaga",description:"Bairro entre a Alameda e o porto reinventado como Barrio de las Artes. O projeto MAUS (Málaga Arte Urbano Soho) trouxe murais monumentais de nomes globais do street art, como OBEY (Shepard Fairey) e D*Face, além de galerias e cafés independentes. É um museu ao ar livre para percorrer sem pressa.",lat:36.7139,lng:-4.4231,durationLabel:"1h",fit:"ANY",mapQuery:"Soho Málaga Barrio de las Artes, Spain",whatToDo:["Ver 'Paz y Libertad' de OBEY e 'The Pilot' de D*Face, na lateral do CAC","Caçar murais de Belin, ROA e Dal East pelas ruas do bairro","Fazer uma pausa num café ou galeria independente"],kingTip:"Os dois grandes murais de OBEY e D*Face ficam na Calle Comandante Benítez, 14, atrás do CAC Málaga: comece por ali. Ruas estreitas dão sombra, então funciona bem no meio do dia.",priceLevel:"Grátis",links:[{label:"Rota de grafite no Soho (oficial)",url:"https://visita.malaga.eu/en/what-to-see-and-do/blog/graffiti-route-a-stroll-through-soho-malaga-barrio-de-las-artes-p1640"}],history:"O projeto MAUS nasceu em 2013 como iniciativa vizinhal apoiada pela prefeitura para regenerar um bairro degradado através da arte urbana."},{id:"mlg_calle_larios",categoryId:"malaga",city:"malaga",name:"Calle Marqués de Larios",tagline:"O corso de mármore da cidade",description:"A grande avenida comercial de Málaga, calçada em mármore claro e ladeada por fachadas de inspiração chicaguense. É a espinha dorsal do centro pedonal, sempre animada, ligando a Plaza de la Constitución à Alameda Principal. O ponto de encontro para passear, comprar e observar a cidade.",lat:36.7186,lng:-4.4207,durationLabel:"30-45min",fit:"ANY",mapQuery:"Calle Marqués de Larios, Málaga, Spain",whatToDo:["Descer a rua até a Plaza de la Constitución e a fonte de Génova","Entrar nas travessas para tapas e lojas históricas","Ver a rua ao anoitecer, quando esfria e enche de gente"],kingTip:"O mármore reflete o sol e ferve ao meio-dia; é uma rua para o começo da manhã ou depois das 20h, quando vira palco do passeio local. Na época de festas, ganha toldos e iluminação artística sobre a cabeça.",priceLevel:"Grátis (passeio)",history:"Inaugurada em 1891 e batizada em homenagem ao marquês de Larios, foi rasgada no traçado do centro medieval como símbolo da Málaga industrial e burguesa.",image:"mlg_calle_larios.jpg"},{id:"mlg_plaza_merced",categoryId:"malaga",city:"malaga",name:"Plaza de la Merced",tagline:"A praça de Picasso",description:"Uma das praças mais vivas do centro, com um obelisco central e fileiras de plátanos que dão sombra. Numa esquina fica a casa natal de Pablo Picasso, hoje museu-fundação. Cercada de esplanadas, é ponto de encontro dia e noite, entre o centro histórico e o bairro de Lagunillas.",lat:36.7234,lng:-4.4175,durationLabel:"30min",fit:"ANY",mapQuery:"Plaza de la Merced, Málaga, Spain",whatToDo:["Ver a fachada da Casa Natal de Picasso na esquina norte","Sentar numa esplanada à sombra dos plátanos","Usar a praça como porta de entrada para Lagunillas"],kingTip:"Sente-se no lado sombreado no fim da tarde e observe o vaivém local; as esplanadas aqui são mais autênticas (e baratas) que as da Calle Larios.",priceLevel:"Grátis (praça)",history:"Antigo mercado e palco de execuções e comícios, ganhou em 1881 o obelisco ao general Torrijos, fuzilado na praia de Málaga com seus companheiros em 1831."},{id:"mlg_lagunillas",categoryId:"malaga",city:"malaga",name:"Barrio de Lagunillas",tagline:"O bairro que virou mural",description:"Bairro popular e boêmio logo acima da Plaza de la Merced, conhecido pela sua explosão de arte de rua com forte carga social e poética. Menos polido que o Soho e mais espontâneo, é onde vizinhos e artistas transformaram fachadas descascadas em galeria viva. Um passeio para quem quer a Málaga fora do roteiro.",lat:36.7268,lng:-4.416,durationLabel:"45min",fit:"ANY",mapQuery:"Calle Lagunillas, Málaga, Spain",whatToDo:["Perder-se pelas ruas caçando murais e mensagens poéticas nas paredes","Comparar o tom mais cru daqui com o street art do Soho","Tomar algo num bar de bairro autêntico"],kingTip:"Suba logo depois de conhecer a Plaza de la Merced, é ali ao lado. Como é bairro residencial e vivo, seja discreto com a câmera e prefira a manhã, quando o sol ainda não castiga as ruas estreitas.",priceLevel:"Grátis",history:"Bairro histórico de tradição operária e cigana, tornou-se nos anos 2010 um foco de arte urbana reivindicativa contra a especulação imobiliária.",image:"mlg_lagunillas.jpg"},{id:"mlg_farola_malagueta",categoryId:"malaga",city:"malaga",name:"La Farola e Paseo de la Malagueta",tagline:"O farol e o calçadão do mar",description:"La Farola, o farol oitocentista que é símbolo de Málaga, marca o início do calçadão que corre ao longo da praia da Malagueta. É o passeio marítimo clássico da cidade: palmeiras, esplanadas e a areia urbana mais central, a poucos passos do porto e do centro histórico.",lat:36.7133,lng:-4.4142,durationLabel:"45min-1h",fit:"CLEAR_SKY",mapQuery:"La Farola de Málaga, Spain",whatToDo:["Fotografar La Farola, um dos poucos faróis 'femininos' com nome próprio","Caminhar pelo Paseo Marítimo até a Playa de la Malagueta","Provar espeto de sardinhas num chiringuito à beira da areia"],kingTip:"Em julho a Malagueta lota; venha de manhã cedo para o calçadão vazio ou ao pôr do sol. O espeto de sardinhas assado na brasa dos chiringuitos é o ritual imperdível da orla.",priceLevel:"Grátis (passeio)",history:"Construído em 1817, o farol resistiu a terremotos e à Guerra Civil e deu nome a todo o bairro marítimo que cresceu ao seu redor."},{id:"mlg_playa_malagueta",categoryId:"praias",city:"malaga",name:"Playa de la Malagueta",tagline:"A praia urbana de Málaga, a pé do centro",description:'A praia-cartão da cidade, areia escura importada e o letreiro branco "Malagueta" para a foto obrigatória. Está a dez minutos a pé do centro histórico e do porto, com chiringuitos, duchas e espreguiçadeiras enfileiradas. É a escolha prática para emendar manhã de cultura com tarde de mar.',lat:36.7174,lng:-4.411,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de la Malagueta, Málaga",whatToDo:['Foto no letreiro branco "Malagueta"',"Alugar espreguiçadeira e guarda-sol na areia","Caminhar até o porto e o Muelle Uno ao entardecer"],kingTip:"No verão a areia lota cedo: pague a espreguiçadeira do chiringuito (uns €5–7) e garanta sombra sem disputar lugar.",whereToEat:"Chiringuito com espeto de sardinhas assado na barca à beira-mar — o clássico de Málaga.",hours:{note:"Praia pública, acesso livre; chiringuitos ~11h–23h no verão"}},{id:"mlg_playa_pedregalejo",categoryId:"praias",city:"malaga",name:"Playa de Pedregalejo",tagline:"A fileira de chiringuitos e espetos",description:"O antigo bairro de pescadores virou o corredor gastronômico da praia de Málaga: uma calçada de casinhas baixas com chiringuito atrás de chiringuito, cada um com sua barca de espetos fumegando na areia. Pequenas enseadas protegidas por espigões deixam a água mais calma. É onde o malaguenho almoça de pé no domingo.",lat:36.7189,lng:-4.3822,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Pedregalejo, Málaga",whatToDo:["Almoçar espetos de sardinha assados na lenha","Passear pela calçada de casas de pescador","Banho nas calas protegidas pelos espigões"],kingTip:"O espeto de sardinhas se come com a mão, de cima para baixo, e sem talher — peça uma cerveja bem gelada para acompanhar.",whereToEat:"Qualquer chiringuito da fileira serve o espeto; os mais tradicionais ficam na ponta leste, rumo a El Palo."},{id:"mlg_playa_caleta",categoryId:"praias",city:"malaga",name:"Playa de la Caleta",tagline:"A praia tranquila da orla urbana",description:"Trecho mais tranquilo e residencial do litoral urbano, entre a movimentada Malagueta e os espetos de Pedregalejo. Areia larga, calçadão arborizado e um ar mais familiar, sem o aperto do centro. Boa base para quem quer mar sem multidão a poucos minutos do coração de Málaga.",lat:36.7181,lng:-4.403,durationLabel:"algumas horas",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de la Caleta, Málaga",kingTip:"Vá a pé pelo calçadão desde a Malagueta: são 15 minutos à sombra das palmeiras e você escolhe o pedaço menos cheio."},{id:"mlg_banos_del_carmen",categoryId:"praias",city:"malaga",name:"Baños del Carmen",tagline:"Balneário histórico de 1918 à beira-mar",description:"Antigo balneário de 1918, com pergolado, eucaliptos centenários e uma esplanada debruçada sobre o Mediterrâneo. Mais lugar de pôr do sol e vermute do que de banho: o charme está na varanda histórica sobre as rochas e nas mesas ao ar livre. Um dos cantos mais fotogênicos e boêmios da orla.",lat:36.7183,lng:-4.3903,durationLabel:"fim de tarde",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Baños del Carmen, Málaga",kingTip:"Chegue no fim da tarde para o sol descendo atrás das palmeiras — é o melhor drink com vista de Málaga, e não custa o preço de um beach club.",whereToEat:"O próprio restaurante/chiringuito do Balneario, na esplanada sobre as rochas.",image:"mlg_banos_del_carmen.jpg"},{id:"nrj_playa_burriana",categoryId:"praias",city:"axarquia",name:"Playa de Burriana",tagline:"A praia mais completa de Nerja",description:"A grande praia de Nerja: quase 800 metros de areia dourada, águas calmas e a estrutura mais completa da Axarquía, com esportes aquáticos, caiaques e uma fileira de chiringuitos. É o cartão-postal do leste de Málaga e casa do lendário Ayo, com sua paella à lenha servida ao ar livre.",lat:36.7383,lng:-3.872,durationLabel:"diária inteira",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de Burriana, Nerja",whatToDo:["Alugar caiaque ou stand-up para as calas de Maro","Almoçar a paella à lenha do Ayo","Passar o dia com espreguiçadeira e guarda-sol"],kingTip:"No Ayo a paella à lenha tem repetição à vontade (barra livre de arroz por preço fixo) — chegue antes das 14h, que a fila cresce rápido no verão.",whereToEat:"Chiringuito Ayo, na ponta leste da praia: paella feita na lenha desde 1969, uma instituição de Nerja."},{id:"nrj_playa_maro",categoryId:"praias",city:"axarquia",name:"Playa de Maro",tagline:"Cala virgem sob paredões verdes",description:"A joia natural do leste: uma enseada de água cristalina turquesa cercada por falésias cobertas de vegetação, dentro do paraje protegido dos Acantilados de Maro-Cerro Gordo. Areia grossa, poucos serviços e uma cascata caindo na areia. Cala abrigada do vento, perfeita para snorkel e para chegar de caiaque desde Burriana.",lat:36.749,lng:-3.834,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Maro, Nerja",whatToDo:["Snorkel nas águas cristalinas da cala","Chegar de caiaque contornando as falésias","Ver a cascata que cai direto na areia"],kingTip:"A descida a pé até a cala é íngreme e o estacionamento é minúsculo: chegue cedo, leve água e sombra, porque há pouquíssima estrutura."},{id:"nrj_playa_calahonda",categoryId:"praias",city:"axarquia",name:"Playa de Calahonda",tagline:"A caleta escondida sob o Balcón de Europa",description:"Pequena enseada de barcos de pescadores encravada bem abaixo do Balcón de Europa, no coração de Nerja. Cercada por casinhas brancas e rochas, é a praia mais pitoresca e central da vila, protegida do vento e de água tranquila. Desce-se por uma ladeira estreita a partir do mirante.",lat:36.744,lng:-3.877,durationLabel:"algumas horas",fit:"CLEAR_SKY",windSensitive:!1,mapQuery:"Playa de Calahonda, Nerja",kingTip:"Emende com o Balcón de Europa logo acima: banho de manhã na caleta e, ao descer o calor, o mirante para o pôr do sol.",whereToEat:"Chiringuitos de peixe fresco na própria enseada, entre os barcos varados na areia."},{id:"mrb_playa_fontanilla",categoryId:"praias",city:"marbella",name:"Playa de la Fontanilla",tagline:"A melhor praia da cidade de Marbella",description:"A praia urbana mais bem cuidada de Marbella, colada ao casco antigo: areia larga e dourada, bandeira azul e uma fileira de chiringuitos badalados. Estrutura completa e clima descontraído-chique, ideal para emendar com um passeio pelo centro florido. Ponto de partida perfeito para conhecer a Costa del Sol pelo lado oeste.",lat:36.5075,lng:-4.893,durationLabel:"meia diária",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Playa de la Fontanilla, Marbella",kingTip:"Reserve espreguiçadeira num dos chiringuitos da Fontanilla no início da manhã; ao meio-dia as primeiras filas à beira d'água já estão tomadas.",whereToEat:"Chiringuitos de peixe e arroz na própria praia, com espeto e frituras andaluzas."},{id:"mrb_puente_romano_beach_club",categoryId:"praias",city:"marbella",name:"Puente Romano Beach Club",tagline:"Beach club 5 estrelas na Milla de Oro",description:"O beach club do lendário resort Puente Romano, na Milla de Oro entre Marbella e Puerto Banús. Piscina infinita, redes de teca sobre a areia e cozinha mediterrânea de alto nível (o Sea Grill à beira-mar). É o refúgio de praia mais elegante da Costa del Sol, com serviço impecável e clientela internacional.",lat:36.4906,lng:-4.925,durationLabel:"diária inteira",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Puente Romano Beach Resort, Marbella",priceLevel:"~€100+/pessoa com hamaca e almoço (est.)",kingTip:"Reserve a hamaca (bali bed) com antecedência pela recepção do resort; no verão as redes de primeira fila esgotam dias antes.",whereToEat:"Sea Grill, o restaurante de peixe do próprio Puente Romano, pé na areia.",links:[{label:"Puente Romano (site oficial)",url:"https://www.puenteromano.com/"}]},{id:"mrb_ocean_club",categoryId:"praias",city:"marbella",name:"Ocean Club Marbella",tagline:"Pool party glamourosa junto a Puerto Banús",description:"Um dos beach clubs mais famosos de Marbella, ao lado de Puerto Banús, em Nueva Andalucía. Grande piscina cercada de camas balinesas, brunch de champanhe e festas de dia lendárias no verão. Ambiente jovem, badalado e visto, para quem quer o lado glamouroso e festeiro da Costa del Sol.",lat:36.4854,lng:-4.959,durationLabel:"diária inteira",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Ocean Club Marbella, Nueva Andalucía",priceLevel:"~€75–120 mín. consumo por cama (est.)",kingTip:"As reservas pré-pagas valem até as 16h; garanta a cama pelo site com antecedência nos fins de semana de julho, que lotam.",links:[{label:"Ocean Club (reservas)",url:"https://oceanclub.es/"}]},{id:"mrb_trocadero_arena",categoryId:"praias",city:"marbella",name:"Trocadero Arena",tagline:"Beach club chic pé na areia em Río Real",description:"O beach club à beira-mar da praia de Río Real, a leste de Marbella, do grupo Trocadero. Estética boho-chic assinada por Lorenzo Queipo de Llano, hamacas na areia, bar de sushi, coquetéis e DJ ao entardecer. Mais intimista e sofisticado que os clubes de festa, com uma das melhores cozinhas de praia da região.",lat:36.5013,lng:-4.8478,durationLabel:"diária inteira",fit:"CLEAR_SKY",windSensitive:!0,mapQuery:"Trocadero Arena, Río Real, Marbella",priceLevel:"~€60–100/pessoa com almoço e hamaca (est.)",kingTip:"Reserve mesa para o almoço tardio e fique para o pôr do sol com música: é o programa de dia inteiro mais elegante e menos frenético de Marbella.",hours:{note:"Aberto diariamente, ~10h–01h"},links:[{label:"Trocadero Arena (oficial)",url:"https://grupotrocadero.com/en/trocadero-arena-marbella/"}]},{id:"mlg_el_pimpi",categoryId:"tapas",city:"malaga",name:"El Pimpi",tagline:"A bodega-templo de Málaga, entre tonéis e história",description:"Instalada num casarão do século XVIII ao lado do Teatro Romano e da Alcazaba, é a bodega mais icônica da cidade. Tonéis pintados assinados por celebridades, pátios frescos e uma carta que casa vinho doce local com tapas andaluzas. Ambiente vibrante e cenográfico, ideal para a primeira noite.",lat:36.72123,lng:-4.41758,durationLabel:"1–2 h",fit:"ANY",mapQuery:"El Pimpi, Calle Granada 62, Málaga",whatToDo:"Peça um copo de Málaga Dulce direto do tonel e uma tábua de embutidos ibéricos no pátio.",kingTip:"No verão, reserve a mesa do pátio interior ou do terraço com vista para a Alcazaba; sem reserva a espera é longa.",priceLevel:"€€€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"00:00",note:"Cozinha contínua; picos no almoço e após as 21h."},links:[{label:"Site oficial",url:"https://www.elpimpi.com"}],history:"Aberta nos anos 1970 no antigo Palacio de Buenavista, virou símbolo cultural de Málaga; o ator Antonio Banderas é sócio da casa."},{id:"mlg_antigua_casa_guardia",categoryId:"tapas",city:"malaga",name:"Antigua Casa de Guardia",tagline:"O vinho doce de Málaga do tonel, desde 1840",description:"A taberna mais antiga da cidade, de pé desde 1840, com tonéis alinhados atrás de um balcão de madeira gasta. Não há mesas: bebe-se em pé enquanto o garçom anota a conta a giz no próprio balcão. Museu vivo do Moscatel e do Pedro Ximénez malaguenhos.",lat:36.71743,lng:-4.42227,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Antigua Casa de Guardia, Alameda Principal 18, Málaga",whatToDo:"Prove a sequência Seco Añejo, Pajarete e Pedro Ximénez servida direto dos tonéis, com gambas cozidas ao lado.",kingTip:"A conta é rabiscada a giz no balcão diante de você; peça de dois em dois copos para sentir a curva de doçura.",priceLevel:"€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"22:00",note:"Domingos fechado; horário reduzido em feriados."},links:[{label:"Site oficial",url:"https://antiguacasadeguardia.com"}],history:"Fundada por José de la Guardia em 1840, é a bodega mais antiga de Málaga ligada à Denominação de Origem local.",image:"mlg_antigua_casa_guardia.jpg"},{id:"mlg_los_patios_de_beatas",categoryId:"tapas",city:"malaga",name:"Los Patios de Beatas",tagline:"Vinoteca premium em dois casarões restaurados",description:"Duas casas dos séculos XVIII e XIX unidas por pátios interiores, a 50 metros do Museu Picasso. Adega com centenas de referências de toda a Espanha e serviço por taça em copos Riedel, acompanhado de cozinha andaluza atualizada. A escolha refinada para quem leva vinho a sério.",lat:36.7227,lng:-4.42035,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Los Patios de Beatas, Calle Beatas 43, Málaga",whatToDo:"Peça uma degustação de vinhos de Málaga por taça com harmonização do sommelier.",kingTip:"Sente-se no pátio coberto e envidraçado, climatizado, o refúgio ideal no calor de julho.",priceLevel:"€€€",hours:{openDays:"Todos os dias",openHour:"12:30",closeHour:"00:00",note:"Reserva recomendada nas noites de fim de semana."},links:[{label:"Site oficial",url:"https://lospatiosdebeatas.com"}]},{id:"mlg_la_tranca",categoryId:"tapas",city:"malaga",name:"La Tranca",tagline:"Vermute, vinil e vinho doce no compasso local",description:"Bar minúsculo e cultuado da Calle Carretería, onde o vermute de torneira e o Moscatel correm ao som de discos de vinil e boleros. Paredes cobertas de azulejos e recortes, atmosfera cordial e conta anotada no balcão. Uma imersão despretensiosa na vida noturna malaguenha.",lat:36.7246,lng:-4.4233,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"La Tranca, Calle Carretería 93, Málaga",whatToDo:"Peça um vermute de torneira e uma tapa de conservas, e fique de pé na calçada como os locais.",kingTip:"Lota depois das 21h; chegue no fim da tarde para pegar um canto no balcão.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"12:00",closeHour:"02:00",note:"Espaço pequeno; a maioria bebe em pé na rua."}},{id:"grn_bodegas_castaneda",categoryId:"tapas",city:"granada",name:"Bodegas Castañeda",tagline:"Tapa grátis e calicasas na esquina da Calle Elvira",description:"Taberna clássica pertinho da Plaza Nueva, decorada com barris, presuntos pendurados e mármore antigo. Fiel à tradição de Granada, cada bebida vem com tapa gratuita, e o vermute de casa e as tábuas de embutidos são lendários. Ambiente ruidoso, autêntico e sempre cheio.",lat:37.1764,lng:-3.5956,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Bodegas Castañeda, Calle Almireceros 1, Granada",whatToDo:"Peça uma cerveja ou vermute e receba a tapa surpresa da casa; encare uma tábua de queijos e ibéricos.",kingTip:"Em Granada a tapa é grátis com a bebida e melhora a cada rodada; peça devagar e deixe a cozinha surpreender.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"11:30",closeHour:"00:00",note:"Cozinha contínua; enche na hora do aperitivo e à noite."}},{id:"mlg_casa_aranda",categoryId:"cafe",city:"malaga",name:"Casa Aranda",tagline:"Churros com chocolate desde 1932",description:"A churrería por excelência de Málaga, ocupando várias esquinas de um beco próprio junto ao Mercado de Atarazanas. Churros finos e alongados fritos na hora, mergulhados em chocolate espesso, servidos por garçons de gravata desde 1932. Ritual matinal indispensável na cidade.",lat:36.71888,lng:-4.42155,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Casa Aranda, Calle Herrería del Rey 2, Málaga",whatToDo:"Peça uma ração de churros com uma xícara de chocolate quente para mergulhar.",kingTip:"Vá logo cedo, antes das 10h; no calor, prefira o café con leche gelado ao chocolate.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"08:00",closeHour:"20:15",note:"Fecha à tarde entre turnos; domingos abre só à tarde."},links:[{label:"Site oficial",url:"http://www.casa-aranda.net"}],history:"Aberta em 1932, é a churrería histórica de Málaga, símbolo do café da manhã tradicional malaguenho.",image:"mlg_casa_aranda.jpg"},{id:"mlg_santa_coffee_soho",categoryId:"cafe",city:"malaga",name:"Santa Coffee Soho",tagline:"Torrefação de especialidade no bairro Soho",description:"Café de especialidade e microtorrefação no artístico bairro Soho, entre murais urbanos. Grãos torrados no próprio laboratório e métodos filtrados feitos com precisão, além de doces e opções veganas. Parada obrigatória para quem busca o melhor espresso da cidade.",lat:36.71618,lng:-4.4226,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Santa Coffee Soho, Calle Tomás Heredia 5, Málaga",whatToDo:"Prove um filtrado V60 do lote em destaque e leve um pacote de grãos torrados na casa.",kingTip:"No calor, peça o cold brew da casa; o espaço interno é pequeno e bem climatizado.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"08:30",closeHour:"20:00",note:"Horário pode encurtar aos domingos."},links:[{label:"Site oficial",url:"https://santacoffee.es"}]},{id:"mlg_casa_mira",categoryId:"cafe",city:"malaga",name:"Casa Mira",tagline:"Sorvetes artesanais e turrón desde 1890",description:"Heladería-turronería histórica na elegante Calle Larios, de origem alicantina e aberta em Málaga desde o fim do século XIX. Sorvetes cremosos, horchata gelada e turrón artesanal servidos há gerações. O antídoto perfeito para o calor de julho no centro comercial.",lat:36.7193,lng:-4.4206,durationLabel:"20–30 min",fit:"ANY",mapQuery:"Casa Mira, Calle Marqués de Larios 5, Málaga",whatToDo:"Peça uma bola de turrón de Jijona ou uma horchata bem gelada para caminhar pela Larios.",kingTip:"Nos dias mais quentes, a horchata com fartón supera o sorvete para se refrescar de verdade.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"23:00",note:"Fecha mais tarde nas noites quentes de verão."},history:"Casa de tradição turronera com mais de um século de história, referência do doce artesanal no centro de Málaga.",image:"mlg_casa_mira.jpg"},{id:"grn_lopez_mezquita",categoryId:"cafe",city:"granada",name:"Pastelería López-Mezquita",tagline:"Doçaria histórica de Granada desde 1862",description:"Confeitaria familiar fundada em 1862, na atual loja da Calle Reyes Católicos desde 1905, a poucos passos da catedral. Vitrines de piononos, felipes, palmeras de chocolate e o célebre napolitana. Balcão de mármore e serviço clássico que atravessou gerações.",lat:37.1749,lng:-3.5992,durationLabel:"20–30 min",fit:"ANY",mapQuery:"Pastelería López-Mezquita, Calle Reyes Católicos 39, Granada",whatToDo:"Leve uma caixa de piononos e prove a napolitana de chocolate quentinha.",kingTip:"Peça os doces batizados de 'apperley', criados a partir de um quadro deixado pelo pintor inglês em 1925.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"09:00",closeHour:"21:00",note:"Horário pode variar em feriados locais."},history:"Fundada em 1862 pelo casal Cristóbal López e Dolores Mezquita, é uma das confeitarias mais emblemáticas de Granada."},{id:"mlg_mercado_atarazanas",categoryId:"compras",city:"malaga",name:"Mercado Central de Atarazanas",tagline:"Mercado coberto do século XIX com vitral monumental",description:"Ergue-se sobre um antigo estaleiro nazari, guardando um portal de mármore original e um vitral colorido que retrata marcos de Málaga. Bancas transbordam de peixe do dia, presuntos, azeites e frutas, com barras de tapas no meio do burburinho. Coração gastronômico da cidade.",lat:36.7176,lng:-4.4232,durationLabel:"45 min–1 h",fit:"INDOOR",mapQuery:"Mercado Central de Atarazanas, Calle Atarazanas 10, Málaga",whatToDo:"Circule pelas bancas de peixe e pare numa barra interna para comer boquerones fritos e uma taça de vinho.",kingTip:"Vá pela manhã, antes das 13h; às segundas a seção de peixe fica fechada.",priceLevel:"€€",hours:{openDays:"Seg–Sáb",openHour:"08:00",closeHour:"14:00",note:"Domingos fechado; peixaria fecha às segundas."},links:[{label:"Mercados de Málaga",url:"https://mercados.malagacomercio.es/mercados/mercado-de-atarazanas/"}],history:"Construído no século XIX pelo arquiteto Joaquín de Rucoba sobre o antigo estaleiro árabe; restaurado entre 2008 e 2010."},{id:"mlg_alfajar",categoryId:"compras",city:"malaga",name:"Alfajar",tagline:"Cerâmica andaluza autoral ao lado da catedral",description:"Loja-referência de cerâmica criativa instalada no barroco Palacio de Zea-Salvatierra, colado à catedral. Peças artesanais de ceramistas andaluzes, de azulejos a louça de mesa, com desenho contemporâneo e cores mediterrâneas. Negócio familiar desde 1992, ideal para uma lembrança de valor.",lat:36.7203,lng:-4.4189,durationLabel:"20–40 min",fit:"ANY",mapQuery:"Alfajar Cerámica, Calle Císter 1, Málaga",whatToDo:"Escolha uma peça assinada por ceramistas locais; eles orientam sobre embalagem para viagem.",kingTip:"Peça o embrulho reforçado para levar a cerâmica na bagagem de mão sem risco.",priceLevel:"€€€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"20:30",note:"Horário pode reduzir aos domingos."},links:[{label:"Site oficial",url:"https://alfajar.es"}],image:"mlg_alfajar.jpg"},{id:"mrb_el_corte_ingles_banus",categoryId:"compras",city:"marbella",name:"El Corte Inglés Puerto Banús",tagline:"Grifes de luxo na Milla de Oro de Marbella",description:"A grande loja de departamentos de luxo de Puerto Banús, na Milla de Oro entre Marbella e a marina. Reúne dezenas de grifes internacionais, gastronomia gourmet e um serviço de personal shopping exclusivo. Base natural para explorar as boutiques de Cartier a Dior à beira do porto.",lat:36.4887,lng:-4.9525,durationLabel:"1–2 h",fit:"ANY",mapQuery:"El Corte Inglés Puerto Banús, Marbella",whatToDo:"Combine a loja com um passeio pela marina de Puerto Banús e suas vitrines de alta-costura.",kingTip:"Peça o serviço de personal shopper 'Suite Xquisit' para atendimento reservado e climatizado.",priceLevel:"€€€€",hours:{openDays:"Seg–Sáb",openHour:"10:00",closeHour:"22:00",note:"Domingos e feriados com horário especial."},links:[{label:"Site oficial",url:"https://www.elcorteingles.es/centroscomerciales/es/eci/centros/centro-comercial-puerto-banus"}]},{id:"ant_caminito_del_rey",categoryId:"natureza",city:"antequera",name:"Caminito del Rey",tagline:"Passarela suspensa no desfiladeiro dos Gaitanes",description:"Trilha lendária em passadiços de madeira colados à parede do desfiladeiro dos Gaitanes, cem metros acima do rio Guadalhorce. Percurso linear de cerca de 3 km (7,7 km com os acessos), de sentido único e mão obrigatória de norte a sul. Um dos passeios mais espetaculares da Espanha.",lat:36.91464,lng:-4.80761,durationLabel:"3–4 h (com acessos)",fit:"CLEAR_SKY",mapQuery:"Caminito del Rey, acceso norte, Ardales",whatToDo:"Reserve o horário com antecedência, retire capacete no acesso norte e faça o percurso de norte a sul.",kingTip:"Julho é escaldante e sem sombra: leve 1,5 L de água por pessoa, chapéu e protetor, e escolha o primeiro horário da manhã. Ingressos esgotam com semanas de antecedência.",priceLevel:"€€",hours:{openDays:"Ter–Dom",openHour:"09:30",closeHour:"15:00",note:"Fecha às segundas e em dias de vento forte; entrada só com horário reservado."},links:[{label:"Ingressos oficiais",url:"https://www.caminitodelrey.info"}],history:"Construído em 1901–1905 para operários da hidrelétrica e inaugurado pelo rei Alfonso XIII em 1921; reaberto restaurado em 2015."},{id:"ant_el_torcal",categoryId:"natureza",city:"antequera",name:"El Torcal de Antequera",tagline:"Labirinto de rochas cársticas moldadas pelo mar",description:"Paisagem cársica única, com torres de calcário esculpidas por milhões de anos em formas surreais, a mais de 1.300 metros de altitude. Trilhas circulares sinalizadas cruzam o labirinto de pedra habitado por cabras-monteses. Centro de visitantes com mirante e observatório astronômico.",lat:36.95324,lng:-4.5446,durationLabel:"2–3 h",fit:"CLEAR_SKY",mapQuery:"Centro de Visitantes Torcal Alto, Antequera",whatToDo:"Faça a Ruta Verde (1,5 km) ou a Amarilla (3 km) a partir do centro de visitantes Torcal Alto.",kingTip:"No verão o acesso ao parking alto é restrito e há lanzadera paga; chegue cedo, leve água e evite o meio-dia, quando a pedra irradia calor.",priceLevel:"€",hours:{openDays:"Todos os dias",openHour:"10:00",closeHour:"19:00",note:"Abr–out até 19h; entrada ao parque gratuita, estacionamento com lanzadera na alta temporada."},links:[{label:"Site oficial",url:"https://www.torcaldeantequera.com"}]},{id:"axq_cuevas_de_nerja",categoryId:"natureza",city:"axarquia",name:"Cuevas de Nerja",tagline:"Catedral subterrânea de estalactites em Maro",description:"Sistema de cavernas de quase 5 km próximo a Maro, com salas monumentais e a maior coluna estalagmítica do mundo, com 32 metros. O percurso turístico revela galerias iluminadas com pinturas rupestres e temperatura amena o ano todo. Fresco e abrigado, refúgio perfeito nos dias de calor.",lat:36.76167,lng:-3.84583,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Cueva de Nerja, Maro, Nerja",whatToDo:"Reserve horário online e percorra as galerias iluminadas até a grande coluna central.",kingTip:"A gruta é coberta e fresca (uns 20°C), mas o acesso e a fila são ao ar livre; compre o ingresso com hora marcada para pular a espera no sol.",priceLevel:"€€",hours:{openDays:"Todos os dias",openHour:"09:30",closeHour:"16:30",note:"Horário ampliado no verão; entrada por sessão com hora marcada."},links:[{label:"Ingressos oficiais",url:"https://cuevadenerja.es"}],history:"Redescoberta em 12 de janeiro de 1959 por cinco jovens que entraram pela fenda de La Mina; aberta ao público em 1960."},{id:"mlg_jardin_la_concepcion",categoryId:"natureza",city:"malaga",name:"Jardín Botánico-Histórico La Concepción",tagline:"Selva subtropical romântica aos pés de Málaga",description:"Um dos poucos jardins subtropicais da Europa continental, criado no século XIX por um casal apaixonado por botânica. Palmeiras centenárias, cascatas, pérgola de glicínias e mirantes sobre a cidade compõem um passeio à sombra densa. Oásis verde a poucos minutos do centro.",lat:36.7549,lng:-4.4098,durationLabel:"1,5–2 h",fit:"CLEAR_SKY",mapQuery:"Jardín Botánico La Concepción, Málaga",whatToDo:"Siga a rota principal até a pérgola de glicínias e o mirante com vista para Málaga.",kingTip:"A copa das árvores dá sombra generosa, mas leve água e vá pela manhã; às segundas o jardim fecha.",priceLevel:"€",hours:{openDays:"Ter–Dom",openHour:"09:30",closeHour:"20:30",note:"Abr–set até 20:30; fechado às segundas."},links:[{label:"Site oficial",url:"https://laconcepcion.malaga.eu"}],history:"Criado em meados do século XIX pelos marqueses de Casa Loring; hoje é Bem de Interesse Cultural e jardim histórico municipal."},{id:"axq_playa_de_maro",categoryId:"natureza",city:"axarquia",name:"Playa de Maro e Acantilados de Maro-Cerro Gordo",tagline:"Enseadas turquesa sob falésias protegidas",description:"Praia de seixos e água cristalina encaixada num paraje natural de 12 km de falésias entre Málaga e Granada. Cachoeira que cai sobre a areia, fundo marinho protegido e enseadas selvagens acessíveis por trilhas. Paisagem virgem, das mais bonitas da costa andaluza.",lat:36.75375,lng:-3.83396,durationLabel:"2–4 h",fit:"CLEAR_SKY",mapQuery:"Playa de Maro, Nerja",whatToDo:"Desça a trilha até a praia, mergulhe nas águas transparentes e explore as calas vizinhas de caiaque.",kingTip:"O estacionamento (30–40 vagas) lota antes das 9h30 em julho; chegue cedo ou use a lanzadera paga, e leve água, pois há pouca sombra.",priceLevel:"€",links:[{label:"Visita Nerja",url:"https://visita.nerja.es"}],history:"Paraje Natural desde 1989, o Acantilados de Maro-Cerro Gordo protege 384 hectares, 80% deles de superfície marinha."},{id:"nrj_balcon_de_europa",categoryId:"axarquia",city:"axarquia",name:"Balcón de Europa",tagline:"O mirante-símbolo de Nerja sobre o mar",description:"Terraço palmeirado suspenso sobre o Mediterrâneo, no coração de Nerja. Erguido sobre uma antiga fortaleza, oferece vista aberta para as enseadas e a Serra de Almijara. É o ponto de encontro da vila e o melhor cartão-postal da Costa del Sol oriental.",lat:36.7452,lng:-3.8767,durationLabel:"20–40 min",fit:"CLEAR_SKY",mapQuery:"Balcón de Europa, Nerja",whatToDo:"Caminhe até a ponta do balcão ao amanhecer, antes do calor e das multidões; desça depois às calas laterais.",kingTip:"Chegue antes das 9h ou perto do pôr do sol: a luz rasante sobre o mar rende as melhores fotos e o terraço fica quase vazio.",priceLevel:"Gratuito",history:"Ocupa o antigo baluarte de uma bateria costeira do século XVI; o nome atual foi popularizado após a visita de Afonso XII em 1885."},{id:"nrj_frigiliana_casco_antiguo",categoryId:"axarquia",city:"axarquia",name:"Casco Antiguo de Frigiliana",tagline:"O labirinto mourisco do Barribarto",description:"Um dos povoados brancos mais bem preservados da Andaluzia. O bairro alto (Barribarto) mantém o traçado mouro de ruas íngremes e sinuosas, calçadas de seixos, cal imaculada e portas em azul. Painéis de cerâmica narram a história mudéjar da vila pelas esquinas.",lat:36.7947,lng:-3.8958,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Barribarto, Frigiliana",whatToDo:"Perca-se a pé pelas vielas do Barribarto, siga os painéis de azulejos e suba até os miradouros do topo da vila.",kingTip:"Estacione na parte baixa e suba a pé: as ruas do casco antigo são estreitas demais para carro e a subida é a essência do passeio.",priceLevel:"Gratuito",history:"O traçado atual remonta ao período andalusí; Frigiliana foi um dos últimos redutos mouriscos, palco da revolta de 1569 no vizinho Peñón."},{id:"nrj_iglesia_el_salvador",categoryId:"axarquia",city:"axarquia",name:"Iglesia de El Salvador",tagline:"A igreja barroca junto ao Balcón",description:"Templo do século XVII a poucos passos do Balcón de Europa, em estilo barroco com traços mudéjares. A fachada branca e a torre sóbria dominam a praça central de Nerja. Interior de uma só nave, com teto de madeira e um mural contemporâneo da Anunciação.",lat:36.7455,lng:-3.8779,durationLabel:"15–20 min",fit:"ANY",mapQuery:"Iglesia de El Salvador, Nerja",priceLevel:"Gratuito (contribuição sugerida)",history:"Construída em 1697 em estilo barroco-mudéjar; é a igreja matriz de Nerja e centro da vida devocional da vila."},{id:"nrj_ingenio_mirador_frigiliana",categoryId:"axarquia",city:"axarquia",name:"El Ingenio & Mirador de Frigiliana",tagline:"A última fábrica de mel de cana da Europa",description:"Casarão senhorial do século XVI que abriga a única fábrica de miel de caña ainda em funcionamento na Europa. Ao lado, o mirador abre para o vale do rio Higuerón e a linha do mar ao fundo. Passado industrial e panorama num só ponto do casco antigo.",lat:36.794,lng:-3.8968,durationLabel:"20–30 min",fit:"CLEAR_SKY",mapQuery:"El Ingenio Frigiliana",whatToDo:"Aprecie o vale a partir do mirador ao lado do Ingenio e leve um pote de mel de cana como lembrança local.",kingTip:"O edifício não abre à visita, mas a esquina do mirador ao lado rende a foto clássica de Frigiliana com o mar ao fundo.",priceLevel:"Gratuito (exterior)",history:"O Ingenio ocupa o antigo Palácio dos Condes de Frigiliana; sua produção de mel de cana remonta ao século XVIII e é a última de seu tipo no continente."},{id:"ant_alcazaba",categoryId:"antequera",city:"antequera",name:"Alcazaba de Antequera",tagline:"A fortaleza mourisca no alto da cidade",description:"Cidadela do século XIV que coroa o cerro de Antequera. Muralhas, a Torre del Homenaje e os jardins altos abrem para uma vista de 360° sobre a vega, a Real Colegiata vizinha e o perfil da Peña de los Enamorados. Uma das fortificações nasridas mais imponentes do interior andaluz.",lat:37.0202,lng:-4.5606,durationLabel:"1–1,5 h",fit:"CLEAR_SKY",mapQuery:"Alcazaba de Antequera",kingTip:"Combine o ingresso com a Colegiata de Santa María, ao lado, e suba à Torre del Homenaje para o melhor enquadramento da Peña.",priceLevel:"€€ (ingresso conjunto ~€6, estimativa)",hours:"Aberta diariamente; conferir horário de verão no site oficial",links:[{label:"Turismo de Antequera",url:"https://www.antequera.es/antequera/turismo/"}],history:"Erguida sobre bases romanas e islâmicas no século XIV, foi conquistada pelas tropas cristãs em 1410, abrindo caminho para a tomada de Granada."},{id:"ant_colegiata_santa_maria",categoryId:"antequera",city:"antequera",name:"Real Colegiata de Santa María",tagline:"A fachada renascentista junto à Alcazaba",description:"Templo do século XVI considerado um marco do Renascimento andaluz, com fachada-retábulo em pedra e interior de três naves sobre colunas jônicas. Fica na praça alta, ao lado da Alcazaba, com a Peña de los Enamorados ao fundo. Hoje também abriga espaço expositivo sobre a história da cidade.",lat:37.0197,lng:-4.561,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Real Colegiata de Santa María la Mayor, Antequera",priceLevel:"€€ (ingresso conjunto com a Alcazaba, estimativa)",history:"Construída entre 1514 e 1550, foi um dos primeiros templos renascentistas da Espanha e sede de uma cátedra de gramática e latinidade."},{id:"ant_conjunto_dolmenico",categoryId:"antequera",city:"antequera",name:"Conjunto Dolménico (Menga e Viera)",tagline:"Megálitos de 6.000 anos, Patrimônio UNESCO",description:"Os dólmenes de Menga e Viera formam um dos maiores conjuntos megalíticos da Europa, Patrimônio Mundial da UNESCO. Menga impressiona pelas lajes ciclópicas de dezenas de toneladas e pelo alinhamento com a Peña de los Enamorados. Câmaras funerárias neolíticas de engenharia surpreendente.",lat:37.0246,lng:-4.546,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Dólmenes de Antequera",kingTip:"Entre no dólmen de Menga e observe a abertura alinhada à Peña de los Enamorados no horizonte: um dos poucos megálitos do mundo orientado para um marco natural.",priceLevel:"Gratuito",hours:"Terça a domingo; fechado às segundas. Conferir horário de verão.",links:[{label:"Sítio dos Dólmenes (Junta de Andalucía)",url:"https://www.juntadeandalucia.es/organismos/culturaydeporte/areas/cultura/bienes-culturales/patrimonio-mundial/paginas/dolmenes-antequera.html"}],history:"Construídos por volta de 3.800–3.600 a.C.; o Sítio dos Dólmenes de Antequera foi inscrito na UNESCO em 2016."},{id:"ant_pena_de_los_enamorados",categoryId:"antequera",city:"antequera",name:"Mirante da Peña de los Enamorados",tagline:"O 'rosto do índio' que domina a vega",description:"Monte calcário de perfil humano deitado, símbolo natural de Antequera, envolto na lenda trágica de dois amantes mouro e cristão. Visto dos miradouros da cidade e da estrada, seu contorno domina toda a planície. Referência visual dos dólmenes e da paisagem antequerana.",lat:37.047,lng:-4.509,durationLabel:"15–20 min (mirante)",fit:"CLEAR_SKY",mapQuery:"Peña de los Enamorados, Antequera",kingTip:"Para a foto, procure o mirador junto aos dólmenes ou a saída norte da cidade: o perfil de rosto só se forma de determinados ângulos.",priceLevel:"Gratuito",history:"A lenda medieval conta que dois amantes de fés opostas se lançaram do alto para não serem separados, dando nome à montanha."},{id:"mrb_casco_antiguo",categoryId:"marbella",city:"marbella",name:"Casco Antiguo & Plaza de los Naranjos",tagline:"O centro histórico branco de Marbella",description:"Emaranhado de ruas caiadas, gerânios e boutiques que contrasta com o glamour da costa. No coração está a Plaza de los Naranjos, praça renascentista do século XV com laranjeiras, a fonte central e a Casa Consistorial. O lado autêntico e sombreado de Marbella.",lat:36.5108,lng:-4.8855,durationLabel:"1–1,5 h",fit:"ANY",mapQuery:"Plaza de los Naranjos, Marbella",whatToDo:"Vagueie pelas vielas do casco antigo, faça uma pausa à sombra das laranjeiras da praça e observe a Ermita de Santiago.",kingTip:"Visite no fim da tarde, quando as fachadas brancas ganham luz dourada e as ruas ficam mais frescas que o calçadão da praia.",priceLevel:"Gratuito",history:"A Plaza de los Naranjos foi traçada após a conquista cristã de 1485, reunindo edifícios civis, religiosos e a antiga sede do concelho."},{id:"mrb_puerto_banus",categoryId:"marbella",city:"marbella",name:"Puerto Banús",tagline:"A marina do luxo da Costa del Sol",description:"Marina de iates icônica inaugurada em 1970, vitrine de superiates, esportivos e grifes internacionais. O passeio à beira das docas mistem observação de embarcações, arquitetura andaluza branca e a vida noturna mais badalada da região. Cenário obrigatório do glamour marbellí.",lat:36.4878,lng:-4.9527,durationLabel:"1–2 h",fit:"ANY",mapQuery:"Puerto Banús, Marbella",whatToDo:"Passeie pelas docas admirando os iates, veja a escultura 'Rinoceronte alado' de Dalí e explore as galerias de grifes.",kingTip:"Vá ao entardecer: os iates acendem as luzes, o calor cede e o desfile de carros e barcos fica no auge.",priceLevel:"Gratuito (passeio)",history:"Idealizado pelo empresário José Banús e inaugurado em 1970 com uma festa que reuniu a jet set internacional, tornou-se símbolo do turismo de luxo espanhol."},{id:"mrb_avenida_del_mar",categoryId:"marbella",city:"marbella",name:"Avenida del Mar (esculturas de Dalí)",tagline:"O corredor de bronzes de Salvador Dalí",description:"Alameda arborizada que liga o casco antigo ao Paseo Marítimo, ladeada por dez esculturas em bronze de Salvador Dalí ao ar livre. Figuras surrealistas alongadas, como o 'Homem-relógio' e a 'Vênus com gavetas', pontuam o passeio até o mar. Museu a céu aberto no centro de Marbella.",lat:36.5075,lng:-4.8835,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Avenida del Mar, Marbella",whatToDo:"Percorra a alameda de ponta a ponta, identificando cada uma das dez esculturas de Dalí até desembocar no calçadão.",kingTip:"Faça o trajeto do casco antigo em direção ao mar: você termina o passeio no Paseo Marítimo com a praia à frente.",priceLevel:"Gratuito",history:"As dez esculturas de bronze de Dalí foram instaladas na avenida em 2003, integrando arte surrealista ao urbanismo do centro."},{id:"mrb_puerto_deportivo",categoryId:"marbella",city:"marbella",name:"Puerto Deportivo de Marbella",tagline:"A marina animada junto ao centro",description:"Porto esportivo a poucos passos do centro histórico, mais descontraído que Puerto Banús. Reúne veleiros, barcos de pesca e uma faixa de bares e terraços à beira-d'água. Bom ponto de partida para passeios de barco pela costa e para ver o pôr do sol sobre o Mediterrâneo.",lat:36.5033,lng:-4.8792,durationLabel:"30–60 min",fit:"ANY",mapQuery:"Puerto Deportivo de Marbella",priceLevel:"Gratuito (passeio)",history:"Inaugurado nos anos 1970, é a marina de recreio mais próxima do centro de Marbella e base de excursões marítimas locais."},{id:"rnd_puente_nuevo",categoryId:"ronda",city:"ronda",name:"Puente Nuevo & Mirador del Tajo",tagline:"A ponte suspensa sobre o abismo de Ronda",description:"O monumento-símbolo de Ronda: ponte de pedra do século XVIII que salta os 120 metros da garganta do Tajo, unindo a cidade velha à nova. Dos miradouros laterais, a vista mergulha no desfiladeiro e se abre para a serra. Uma das imagens mais icônicas da Andaluzia.",lat:36.7413,lng:-5.166,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Puente Nuevo, Ronda",whatToDo:"Atravesse a ponte e desça pelos miradouros laterais (lado do Jardín de Cuenca) para vê-la de baixo e de perfil.",kingTip:"A foto clássica com a ponte inteira sobre o abismo é do lado sul, a partir do caminho do Mirador de Aldehuela ou dos Jardines de Cuenca, do outro lado do Tajo.",priceLevel:"Gratuito (ponte); centro de interpretação €€ estimativa",history:"Concluída em 1793 após décadas de obras sobre o Tajo, a câmara interna sobre o arco já serviu de prisão e centro de interpretação."},{id:"rnd_plaza_de_toros",categoryId:"ronda",city:"ronda",name:"Plaza de Toros (Real Maestranza)",tagline:"Uma das arenas mais antigas da Espanha",description:"Arena de estilo neoclássico inaugurada em 1785, berço da tourada moderna a pé e uma das mais monumentais do país. O anel de pedra com dupla galeria de arcos, o museu taurino e a cavalariça contam a história da Real Maestranza de Caballería. Visita mesmo sem eventos.",lat:36.7435,lng:-5.167,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Plaza de Toros de Ronda",priceLevel:"€€ (ingresso ~€9, estimativa)",hours:"Aberta diariamente; horário ampliado no verão",links:[{label:"Real Maestranza de Ronda",url:"https://www.rmcr.org/"}],history:"Inaugurada em 1785 pela Real Maestranza de Caballería, é considerada um dos marcos da tauromaquia rondeña e da escola de Pedro Romero."},{id:"rnd_banos_arabes",categoryId:"ronda",city:"ronda",name:"Baños Árabes",tagline:"Os banhos mouros mais bem conservados da Espanha",description:"Complexo termal de fins do século XIII, no antigo bairro curtidor junto ao arroio das Culebras. Salas fria, morna e quente com abóbadas perfuradas por lucernas em forma de estrela e um engenhoso sistema hidráulico visível. Os banhos árabes mais bem preservados da Península Ibérica.",lat:36.7392,lng:-5.1638,durationLabel:"30–45 min",fit:"ANY",mapQuery:"Baños Árabes de Ronda",kingTip:"Vá no início da manhã, quando o sol entra pelas lucernas em estrela e projeta pontos de luz sobre as abóbadas.",priceLevel:"€ (ingresso ~€4,50, estimativa)",history:"Construídos no período nasrida, entre os séculos XIII e XIV, aproveitavam a água do arroio para alimentar as salas termais de tradição islâmica."},{id:"rnd_casa_del_rey_moro",categoryId:"ronda",city:"ronda",name:"Casa del Rey Moro & Jardines de Cuenca",tagline:"A mina d'água secreta descendo ao Tajo",description:"Conjunto que reúne uma casa senhorial, jardins em terraços desenhados por Forestier e a célebre Mina de Agua: uma escadaria escavada na rocha que desce mais de 200 degraus até o rio, no fundo da garganta. Descida vertiginosa com vistas únicas do abismo por dentro.",lat:36.7403,lng:-5.1642,durationLabel:"45 min–1 h",fit:"ANY",mapQuery:"Casa del Rey Moro, Ronda",whatToDo:"Desça a Mina de Agua até o leito do Tajo e, do outro lado, aprecie a ponte a partir dos Jardines de Cuenca.",kingTip:"Use calçado firme: os degraus da mina são úmidos e irregulares. A recompensa é ver o Tajo do fundo, onde poucos chegam.",priceLevel:"€€ (ingresso ~€8, estimativa)",history:"A mina foi escavada no século XIV para garantir água à cidade em cerco; os jardins foram redesenhados por Jean-Claude Forestier no início do século XX."},{id:"rnd_palacio_de_mondragon",categoryId:"ronda",city:"ronda",name:"Palacio de Mondragón",tagline:"O palácio mudéjar com pátios e mirante",description:"Residência palaciana de origem islâmica, reformada após a Reconquista, com pátios mudéjares, artesanados, azulejos e um jardim suspenso sobre o Tajo. Abriga o museu municipal e um dos miradouros mais serenos da cidade, voltado para a serra e o vale do rio.",lat:36.74,lng:-5.1658,durationLabel:"30–45 min",fit:"CLEAR_SKY",mapQuery:"Palacio de Mondragón, Ronda",kingTip:"Atravesse os pátios até o jardim dos fundos: o mirante sobre a serra é um dos cantos mais tranquilos e fotogênicos de Ronda.",priceLevel:"€ (ingresso ~€4, estimativa)",history:"Erguido no período nasrida e reformado no século XVI, teria hospedado os monarcas católicos após a conquista de Ronda em 1485."},{id:"rnd_alameda_del_tajo",categoryId:"ronda",city:"ronda",name:"Alameda del Tajo",tagline:"O jardim-balcão sobre o precipício",description:"Alameda arborizada do início do século XIX, com alamedas de plátanos, coretos e bancos de ferro que terminam em varandas debruçadas sobre o penhasco. Do balcão, a vista se estende pela serrania e pelo vale, num dos passeios mais elegantes e sombreados de Ronda.",lat:36.7458,lng:-5.1668,durationLabel:"20–40 min",fit:"CLEAR_SKY",mapQuery:"Alameda del Tajo, Ronda",kingTip:"Vá até as varandas de ferro no fim do parque: parecem suspensas no vazio e enquadram a serra ao pôr do sol.",priceLevel:"Gratuito",history:"Inaugurada em 1806, foi concebida como passeio público ajardinado no bordo do desfiladeiro, então uma novidade urbanística para a cidade."}],s={},l={weatherLat:36.7213,weatherLng:-4.4214,timezone:"Europe/Madrid",startDate:"2027-07-01",endDate:"2027-07-10"},t=[{id:"malaga",title:"Málaga capital",emoji:"🏛️",summary:'A cidade natal de Picasso à beira do Mediterrâneo: Alcazaba, Gibralfaro, a catedral "Manquita", o porto e o boêmio Soho. É a base da viagem.',gradient:["#B5651D","#E0A458"],image:"malaga.jpg"},{id:"axarquia",title:"Nerja & Axarquía",emoji:"🌅",summary:"A costa a leste: Nerja e o Balcón de Europa, a vila branca de Frigiliana, as grutas e as praias de Maro. Luz de cartão-postal.",gradient:["#1B6E8E","#5FB0C0"],image:"axarquia.jpg"},{id:"antequera",title:"Antequera & El Torcal",emoji:"🪨",summary:"O coração geográfico da Andaluzia: dólmens milenares, o mar de rochas de El Torcal e o vertiginoso Caminito del Rey em El Chorro.",gradient:["#7A5C3B","#C0A06A"],image:"antequera.jpg"},{id:"ronda",title:"Ronda & Serranía",emoji:"⛰️",summary:"A cidade rasgada por um abismo: o Puente Nuevo sobre o Tajo, a praça de touros mais antiga e o vinho da Serranía. Dá vontade de dormir lá.",gradient:["#6B3A2B","#B57A5A"],image:"ronda.jpg"},{id:"marbella",title:"Marbella & Costa del Sol",emoji:"🏖️",summary:"O oeste glamouroso: casco antiguo florido, a Milla de Oro, Puerto Banús e os beach clubs. Onde a Costa del Sol veste gala.",gradient:["#1E6E5A","#6FB89A"],image:"marbella.jpg"},{id:"granada",title:"Granada & Alhambra",emoji:"🏯",summary:"A joia nazari: a Alhambra e o Generalife, o Albaicín, o pôr do sol do Mirador San Nicolás e as cuevas do Sacromonte. Vale dormir.",gradient:["#8A2E4E","#C77A9A"],image:"granada.jpg"},{id:"cordoba",title:"Córdoba",emoji:"🕌",summary:"A grande alternativa de bate-volta: a Mesquita-Catedral, a Judería e os pátios floridos. Chega-se de AVE em ~1h de Málaga.",gradient:["#6A4C93","#A084C7"],image:"cordoba.jpg"},{id:"sevilla",title:"Sevilla",emoji:"🌇",summary:"A capital andaluza: a catedral e a Giralda, o Real Alcázar, a Plaza de España e Triana. ~2h40 de AVE — bate-volta puxado ou uma noite.",gradient:["#B5372A","#E0894A"],image:"sevilla.jpg"},{id:"cadiz",title:"Cádiz & província",emoji:"⚓",summary:"O sul atlântico: a milenar Cádiz, o xerez de Jerez, o vento de Tarifa e a vila branca de Vejer. Ar de oceano, do outro lado da montanha.",gradient:["#1C6E86","#5FB2C4"],image:"cadiz.jpg"},{id:"gibraltar",title:"Gibraltar",emoji:"🐒",summary:"O Rochedo britânico na ponta da Espanha: os macacos, a St. Michael’s Cave, o Skywalk e a Main Street duty-free. Leve o passaporte.",gradient:["#565A62","#9AA0AA"],image:"gibraltar.jpg"},{id:"gastronomia",title:"Restaurantes & Michelin",emoji:"🍽️",summary:"Da estrela de José Carlos García aos dois sóis de Bardal, passando por tabernas históricas e chiringuitos de espeto. Reserve os premiados cedo.",gradient:["#9A2617","#D96C4A"],image:"gastronomia.jpg"},{id:"praias",title:"Praias & chiringuitos",emoji:"🏝️",summary:"La Malagueta na cidade, os espetos de Pedregalejo, as calas de Maro e os beach clubs de Marbella. O Mediterrâneo em julho.",gradient:["#0E7CA0","#5FC5D6"],image:"praias.jpg"},{id:"tapas",title:"Tapas, vinhos & bares",emoji:"🍷",summary:"El Pimpi, o vinho doce de Málaga direto do tonel, o vermut e a coquetelaria. A vida acontece de tapa em tapa, ao entardecer.",gradient:["#7A2A4A","#B56A8A"],image:"tapas.jpg"},{id:"cultura",title:"Museus & monumentos",emoji:"🎨",summary:"Picasso onde ele nasceu, o Thyssen, o Pompidou, o Museo Ruso e a Alhambra. Ótimo para as horas de mais calor (tudo com ar).",gradient:["#5B4C93","#9A84C7"],image:"cultura.jpg"},{id:"natureza",title:"Natureza & aventura",emoji:"🌿",summary:"O Caminito del Rey pendurado no desfiladeiro, o mar de rochas de El Torcal, as grutas de Nerja e os jardins de La Concepción.",gradient:["#2A7E4E","#6FB88A"],image:"natureza.jpg"},{id:"cafe",title:"Cafés & doces",emoji:"☕",summary:"Churros com chocolate na Casa Aranda, o café de especialidade do Soho e o gelato para o calor. A pausa doce entre passeios.",gradient:["#6B4A2B","#B98E5E"],image:"cafe.jpg"},{id:"compras",title:"Compras & mercados",emoji:"🛍️",summary:"O Mercado de Atarazanas, a Calle Larios, artesanato andaluz e cerâmica. Do peixe fresco às marcas na Milla de Oro.",gradient:["#B5651D","#E0A458"],image:"compras.jpg"},{id:"hospedagem",title:"Onde ficar — hotéis & flats",emoji:"🛏️",summary:'Hotéis-boutique, 5 estrelas à beira-mar e flats/Airbnb selecionados por zona. Compare, reserve por fora e registre em "Minhas reservas".',gradient:["#37607A","#7FA8C0"],image:"hospedagem.jpg"}],i=[{id:"malaga",label:"Málaga",emoji:"🏛️"},{id:"axarquia",label:"Nerja & Axarquía",emoji:"🌅"},{id:"antequera",label:"Antequera",emoji:"🪨"},{id:"ronda",label:"Ronda",emoji:"⛰️"},{id:"marbella",label:"Marbella",emoji:"🏖️"},{id:"granada",label:"Granada",emoji:"🏯"},{id:"cordoba",label:"Córdoba",emoji:"🕌"},{id:"sevilla",label:"Sevilla",emoji:"🌇"},{id:"cadiz",label:"Cádiz & província",emoji:"⚓"},{id:"gibraltar",label:"Gibraltar",emoji:"🐒"}],c=a=>i.some(e=>e.id===a),m=a=>i.find(e=>e.id===a),d=[],r=[...d,...n].map(a=>a.links||!s[a.name]?a:{...a,links:s[a.name]}),u=a=>t.find(e=>e.id===a),p=a=>r.filter(e=>e.categoryId===a),g=a=>r.find(e=>e.id===a),b=(a,e)=>r.filter(o=>o.categoryId===a&&o.city===e),h=a=>i.filter(e=>r.some(o=>o.categoryId===a&&o.city===e.id));export{g as a,r as b,b as c,p as d,t as e,u as f,i as g,h,m as i,c as j,l as t};
